import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Piano di sviluppo Clarae notanda — da Specifications.md v1.1 al rilascio 1.0","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md"}'),d={name:"roadmap.md"};function c(n,e,r,l,s,p){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="piano-di-sviluppo-clarae-notanda-—-da-specifications-md-v1-1-al-rilascio-1-0" tabindex="-1">Piano di sviluppo Clarae notanda — da <code>Specifications.md</code> v1.1 al rilascio 1.0 <a class="header-anchor" href="#piano-di-sviluppo-clarae-notanda-—-da-specifications-md-v1-1-al-rilascio-1-0" aria-label="Permalink to &quot;Piano di sviluppo Clarae notanda — da `Specifications.md` v1.1 al rilascio 1.0&quot;">​</a></h1><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Il repository contiene solo <code>Specifications.md</code> (v1.1, 23/10/2026) e <code>CLAUDE.md</code>. Lo spec definisce architettura, vincoli (V-01…V-10), decisioni (D-01…D-08), schema DB, API, protocollo di sync, E2EE e layout del monorepo, oltre a una roadmap per milestone (Appendice B) senza scomposizione in task. Questo piano trasforma la roadmap in un piano eseguibile: per ogni milestone M0–M7 definisce work package (WP), task concreti con file e ordine, criteri di uscita e verifica. Il piano è pensato per un singolo sviluppatore affiancato da Claude Code; dove due WP sono indipendenti lo segnalo come parallelizzabile (worktree/agent).</p><p>Regole ereditate da <code>CLAUDE.md</code>: non modificare <code>Specifications.md</code> in automatico (le deviazioni si propongono come ADR in <code>docs/adr/</code> e l&#39;utente aggiorna lo spec); nessun commit/push senza richiesta esplicita.</p><hr><h2 id="_1-decisioni-di-piano-vincolanti-per-l-esecuzione" tabindex="-1">1. Decisioni di piano (vincolanti per l&#39;esecuzione) <a class="header-anchor" href="#_1-decisioni-di-piano-vincolanti-per-l-esecuzione" aria-label="Permalink to &quot;1. Decisioni di piano (vincolanti per l&#39;esecuzione)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tema</th><th>Scelta</th><th>Note</th></tr></thead><tbody><tr><td>Module path Go</td><td>Path locale <code>clarae</code> (moduli <code>clarae/apps/desktop</code>, <code>clarae/services/cloud</code>, <code>clarae/shared</code>) in <code>go.work</code></td><td>Host non ancora deciso. Il rename futuro è un <code>find/sed</code> sugli import + <code>go.mod</code>; task <strong>M0-00</strong> lo prevede con <code>task rename-module NEW=…</code>.</td></tr><tr><td>Go</td><td>1.27 (sqlc 1.31 e buf 1.75 richiedono ≥ 1.26; il toolchain si scarica via <code>GOTOOLCHAIN=auto</code>)</td><td>Tutti i tool (<code>oapi-codegen</code>, <code>sqlc</code>, <code>goose</code>, <code>buf</code>, <code>golangci-lint</code>, <code>govulncheck</code>, <code>protoc-gen-go*</code>) sono pinnati con <code>tool</code> directive in un modulo separato <code>tools/go.mod</code> <strong>fuori da <code>go.work</code></strong> (installazione con <code>task tools</code> → <code>GOWORK=off go install tool</code>), così il loro albero di dipendenze non entra nei moduli applicativi.</td></tr><tr><td>Wails</td><td>v2.17.0 (<code>apps/desktop/go.mod</code>; era 2.12.0 all&#39;avvio del piano) — D-07</td><td><code>OnUrlOpen</code> (Mac) + <code>SingleInstanceLock</code>/<code>OnSecondInstanceLaunch</code> esistono in v2 ≥ 2.10; comportamento &quot;URL verso istanza già attiva su macOS&quot; da verificare nello <strong>SPIKE-01</strong>. Il passaggio a v3 è proposto da <a href="./adr/0051-wails-v3.html">ADR-0051</a> (M15, §13-octies), non ancora accettato.</td></tr><tr><td>Node / Yarn</td><td>Node 24 LTS, Yarn 4 (corepack, <code>packageManager</code> bloccato)</td><td>Workspace Yarn: <code>apps/desktop/frontend</code>, <code>web</code>, <code>packages/*</code>.</td></tr><tr><td>React</td><td>19 (verifica peerDeps di <code>@excalidraw/excalidraw</code> 0.18.x nello <strong>SPIKE-03</strong>; fallback React 18.3)</td><td>Vite 6, TypeScript 5 <code>strict</code>, ESLint flat config, Prettier, Vitest, Playwright.</td></tr><tr><td>Stato/query FE</td><td>Zustand + TanStack Query (cache delle chiamate ai binding)</td><td>Spec §4.2 <code>state/</code>.</td></tr><tr><td>Editor</td><td>CodeMirror 6 + <code>@lezer/markdown</code>; reading view <code>unified</code> (remark/rehype) + plugin OFM custom</td><td>KaTeX, Mermaid (<code>securityLevel: strict</code>), DOMPurify.</td></tr><tr><td>Cloud HTTP</td><td><code>chi</code> + <code>oapi-codegen</code> v2 (strict server, chi) ; errori RFC 9457</td><td><code>api/openapi.yaml</code> fonte unica.</td></tr><tr><td>gRPC</td><td><code>buf</code> + <code>protoc-gen-go</code>/<code>protoc-gen-go-grpc</code>; SSE fallback in <code>httpserver</code></td><td>Solo <code>NotifyService</code>.</td></tr><tr><td>DB</td><td>PostgreSQL 17 (compose) — pgx v5, sqlc, goose (migrazioni SQL embedded)</td><td><strong>Deviazione dichiarata dalla roadmap (App. B pone &quot;schema DB&quot; in M0):</strong> lo schema §3.2.2 viene introdotto per migrazioni incrementali per milestone (<code>0001</code> M0, <code>0002</code>–<code>0003</code> M2, <code>0004</code> M4, <code>0005</code> M5), così ogni tabella arriva con il modulo che la usa e i suoi test.</td></tr><tr><td>Storage</td><td>S3 via <code>minio-go</code> (MinIO in dev) + driver filesystem per test unit</td><td>tus 1.0 con <code>tusd/v2</code> (handler embedded, store S3).</td></tr><tr><td>JWT/OIDC</td><td><code>coreos/go-oidc/v3</code> + <code>golang.org/x/oauth2</code> (desktop PKCE e cloud JWKS)</td><td>Keycloak 26.x (26.7 ultima nota) in compose; realm export in <code>deploy/keycloak/realm-clarae.json</code>.</td></tr><tr><td>Keychain</td><td><code>zalando/go-keyring</code></td><td>macOS Keychain / Credential Manager / Secret Service.</td></tr><tr><td>SQLite client</td><td><code>modernc.org/sqlite</code> (FTS5 + <code>trigram</code>): verifica <strong>SPIKE-02</strong></td><td>Migrazioni <code>index.db</code>/<code>sync.db</code>/<code>app.db</code> con goose su <code>database/sql</code>.</td></tr><tr><td>Cripto</td><td><code>crypto/aes</code>, <code>crypto/cipher</code>, <code>x/crypto/argon2</code>, <code>x/crypto/hkdf</code>; browser WebCrypto + <code>hash-wasm</code> (Argon2id)</td><td>Formato §3.8.3; test vector condivisi.</td></tr><tr><td>Diff/merge</td><td><code>sergi/go-diff</code> (diff-match-patch) + diff3 a righe custom in <code>shared/go/merge</code></td><td></td></tr><tr><td>UUID</td><td><code>google/uuid</code> v7</td><td></td></tr><tr><td>Log</td><td><code>zerolog</code> (desktop e cloud), OpenTelemetry SDK + exporter Prometheus/OTLP</td><td></td></tr><tr><td>Lingua</td><td>Codice, commit, log, messaggi API in inglese; <code>docs/</code>, ADR, runbook in italiano; UI via i18n <code>it</code>/<code>en</code></td><td></td></tr><tr><td>CI</td><td>Dal 2026-11-01 nessun servizio di CI: <code>task ci</code> in locale prima di merge e tag; solo <code>release.yml</code> su GitHub (ADR-0036)</td><td></td></tr><tr><td>Nome</td><td>Nome in codice <code>nodus</code> (segnaposto); nome ufficiale <strong>Clarae notanda</strong> (identificatori <code>clarae</code>), rebrand eseguito dopo M7</td><td></td></tr></tbody></table><hr><h2 id="_2-principi-di-esecuzione" tabindex="-1">2. Principi di esecuzione <a class="header-anchor" href="#_2-principi-di-esecuzione" aria-label="Permalink to &quot;2. Principi di esecuzione&quot;">​</a></h2><ol><li><strong>Contract-first.</strong> Ogni endpoint nasce in <code>api/openapi.yaml</code> (e <code>proto/</code>), poi <code>task gen</code>, poi implementazione. I tipi condivisi del protocollo (op, codici errore) vivono in <code>shared/go/syncproto</code> e sono la fonte per OpenAPI (enum) e per il client.</li><li><strong>Vertical slice per WP.</strong> Ogni WP arriva fino a un comportamento osservabile (binding + UI minima, o endpoint + test d&#39;integrazione), non &quot;tutto il backend poi tutta la UI&quot;.</li><li><strong>Gate di qualità per milestone</strong> (bloccanti in <code>task ci</code>, eseguito in locale: ADR-0036): <code>golangci-lint</code>, <code>go test -race</code>, <code>govulncheck</code>, ESLint/tsc, Vitest, conformance Go+TS, integration cloud (testcontainers), build desktop su 3 OS (da M0). Copertura ≥ 80 % su <code>parser</code>, <code>merge</code>, <code>sync</code>, <code>sharing</code> misurata da M2 in poi.</li><li><strong>Spike prima dei WP rischiosi.</strong> Gli spike (§4) sono time-boxed (≤ 1 giorno) e producono un ADR in <code>docs/adr/</code>.</li><li><strong>Deviazioni dallo spec</strong> → ADR + proposta all&#39;utente; lo spec lo aggiorna l&#39;utente. Deviazioni già note in questo piano (ciascuna → ADR): migrazioni DB incrementali; colonna <code>op_id</code> su <code>file_revisions</code> (M2-WP2); tabella <code>config_profile_versions</code> (M5-WP1); endpoint GDPR <code>GET /me/export</code> e <code>DELETE /me</code> (M7-WP2); pacchetti TS aggiuntivi <code>packages/config</code> e runner conformance in <code>shared/conformance/ts/</code> (M0-WP0/WP1).</li><li><strong>Parallelismo.</strong> I WP marcati ∥ possono girare in worktree separati (es. parser Go ∥ editor TS); le interfacce tra i due lati sono fissate prima (binding tipizzati, fixture conformance).</li></ol><hr><h2 id="_3-dipendenze-tra-milestone-e-percorso-critico" tabindex="-1">3. Dipendenze tra milestone e percorso critico <a class="header-anchor" href="#_3-dipendenze-tra-milestone-e-percorso-critico" aria-label="Permalink to &quot;3. Dipendenze tra milestone e percorso critico&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>M0 Fondamenta ─┬─► M1 Core editing ─┬─► M3 Excalidraw+Canvas ─┐</span></span>\n<span class="line"><span>               │                     │                         ├─► M6 P1 residui ─► M7 Hardening ─► 1.0</span></span>\n<span class="line"><span>               └─► M2 Sync ──────────┴─► M4 Sharing+Gruppi ─► M5 Console admin ┘</span></span></code></pre></div><ul><li>M2 <strong>dipende da M1-WP1</strong> (parser frontmatter usato dal merge <code>.md</code> in M2-WP4) e da <strong>M1-WP3</strong> (<code>RenameWithLinkUpdate</code>/<code>file_id</code> usati da <code>detect.go</code> in M2-WP6); il resto di M1 (WP4–WP9, editor/UI) è indipendente da M2 e può procedere in parallelo (∥) con il lato cloud di M2 (WP1–WP3, WP7).</li><li>M3 richiede M1 (embed/editor) e M2 (merge per-id sincronizzato).</li><li>M4 richiede M2 (ACL applicata a changes/commit). M5 richiede M4 (gruppi, config profile) e M2 (export).</li><li>M6 richiede M1 (grafo, bases su indice) e M2 (history con revisioni server).</li><li>Ordine consigliato per un solo sviluppatore: M0 → M1 (WP1–WP4) → M2 → M1 (WP5–WP9) → M3 → M4 → M5 → M6 → M7.</li></ul><hr><h2 id="_4-spike-tecnici-m0-time-boxed-ciascuno-con-adr" tabindex="-1">4. Spike tecnici (M0, time-boxed, ciascuno con ADR) <a class="header-anchor" href="#_4-spike-tecnici-m0-time-boxed-ciascuno-con-adr" aria-label="Permalink to &quot;4. Spike tecnici (M0, time-boxed, ciascuno con ADR)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Domanda</th><th>Esito atteso / fallback</th></tr></thead><tbody><tr><td>SPIKE-01</td><td>Wails v2.12 su macOS: un URL <code>clarae://…</code> con app già aperta arriva a <code>OnUrlOpen</code> o a <code>OnSecondInstanceLaunch</code>? Su Windows (NSIS) e Linux (<code>.desktop</code>) l&#39;URL arriva come argv della seconda istanza?</td><td>ADR-0001 &quot;Consegna URL scheme per OS&quot;. Fallback: loopback resta primario (D-08), scheme solo dove verificato.</td></tr><tr><td>SPIKE-02</td><td><code>modernc.org/sqlite</code>: <code>CREATE VIRTUAL TABLE … USING fts5(…, tokenize=&#39;trigram&#39;)</code> funziona? prestazioni su 50k documenti sintetici?</td><td>ADR-0002. Fallback: tokenizer <code>unicode61</code> + indice LIKE su candidati (degrado documentato).</td></tr><tr><td>SPIKE-03</td><td><code>@excalidraw/excalidraw</code> 0.18.x: peerDeps React, <code>EXCALIDRAW_ASSET_PATH</code> offline nel webview Wails (WKWebView/WebView2/WebKitGTK), bundle size con lazy import</td><td>ADR-0003 &quot;Versione React e strategia asset&quot;.</td></tr><tr><td>SPIKE-04</td><td>Live Preview CodeMirror 6: prototipo con 3 elementi (heading, wikilink, bold) con decorations/widget e &quot;sintassi riappare sulla riga del cursore&quot;</td><td>ADR-0004 &quot;Architettura Live Preview&quot; (pattern di estensione riusato in M1-WP5).</td></tr><tr><td>SPIKE-05</td><td>CSP <code>default-src &#39;self&#39;</code> senza <code>unsafe-eval</code> nel webview Wails: compatibilità con Vite dev server, KaTeX, Mermaid, WASM (<code>wasm-unsafe-eval</code>)</td><td>ADR-0005.</td></tr></tbody></table><hr><h2 id="_5-m0-—-fondamenta-esito-hello-vault-con-login-funzionante" tabindex="-1">5. M0 — Fondamenta (esito: &quot;Hello vault&quot; con login funzionante) <a class="header-anchor" href="#_5-m0-—-fondamenta-esito-hello-vault-con-login-funzionante" aria-label="Permalink to &quot;5. M0 — Fondamenta (esito: &quot;Hello vault&quot; con login funzionante)&quot;">​</a></h2><h3 id="m0-wp0-scaffolding-monorepo" tabindex="-1">M0-WP0 Scaffolding monorepo <a class="header-anchor" href="#m0-wp0-scaffolding-monorepo" aria-label="Permalink to &quot;M0-WP0 Scaffolding monorepo&quot;">​</a></h3><ul><li><code>go.work</code> con i tre moduli; <code>shared/go/go.mod</code> (<code>clarae/shared</code>), <code>apps/desktop/go.mod</code>, <code>services/cloud/go.mod</code>.</li><li><code>package.json</code> radice + <code>workspaces di package.json.yaml</code> (<code>apps/desktop/frontend</code>, <code>web</code>, <code>packages/*</code>); <code>tsconfig.base.json</code>; ESLint flat config + Prettier condivisi in <code>packages/config/</code> (o radice).</li><li><code>Makefile</code> (sostituito da <code>Taskfile.yml</code>, ADR-0032): <code>tools</code>, <code>gen</code>, <code>lint</code>, <code>test</code>, <code>test-integration</code>, <code>conformance</code>, <code>dev-cloud</code>, <code>dev-desktop</code>, <code>build-desktop</code>, <code>build-cloud</code>, <code>rename-module</code>.</li><li><code>.gitignore</code>, <code>.editorconfig</code>, <code>.golangci.yml</code> (con <code>depguard</code> per le regole di modularità §4.3), <code>LICENSE</code> (MIT, deciso).</li><li><code>docs/</code>: <code>docs/adr/0000-template.md</code>, <code>docs/roadmap.md</code> (copia di questo piano, aggiornata a ogni milestone), <code>docs/dev-setup.md</code>.</li><li><code>deploy/docker/compose.dev.yaml</code>: postgres:17, minio + <code>mc</code> bootstrap bucket, keycloak:26.x con import realm, (opzionale) mailpit per le email di Keycloak.</li><li>Aggiornare <code>CLAUDE.md</code> con i comandi reali (sezione &quot;Comandi&quot;).</li></ul><h3 id="m0-wp1-librerie-condivise-base-shared-go" tabindex="-1">M0-WP1 Librerie condivise base (<code>shared/go</code>) <a class="header-anchor" href="#m0-wp1-librerie-condivise-base-shared-go" aria-label="Permalink to &quot;M0-WP1 Librerie condivise base (`shared/go`)&quot;">​</a></h3><ul><li><code>pathrules/</code>: <code>Normalize(path) (string, error)</code> (NFC, <code>/</code>, lunghezze, caratteri vietati, segmenti riservati Windows, <code>.</code>/<code>..</code>), <code>Key(path)</code> (NFC+casefold), <code>IsExcluded(path)</code> (§3.4.2). Test tabellari.</li><li><code>syncproto/</code>: tipi <code>Op</code>, <code>OpKind</code> (<code>create|modify|move|delete|restore|move_prefix</code>), <code>CommitRequest/Response</code>, <code>Change</code>, codici errore (§3.1) come costanti + mapping HTTP status; <code>hashing/</code> SHA-256 streaming con <code>io.Reader</code>.</li><li><code>pathrules</code> gestisce solo pattern/nomi; il rilevamento dei symlink (che richiede il FS) sta in <code>apps/desktop/internal/vault</code>.</li><li><code>shared/conformance/</code>: layout e formato fixture (<code>markdown/&lt;case&gt;.md</code> + <code>&lt;case&gt;.expected.json</code>; <code>crypto/vectors.json</code>), README del formato; runner Go (<code>shared/conformance/go_test.go</code>) e TS (<code>shared/conformance/ts/</code>, pacchetto Yarn eseguito da Vitest). In M0 solo 3 fixture (heading, wikilink, tag) per validare il meccanismo.</li></ul><h3 id="m0-wp2-contratti" tabindex="-1">M0-WP2 Contratti <a class="header-anchor" href="#m0-wp2-contratti" aria-label="Permalink to &quot;M0-WP2 Contratti&quot;">​</a></h3><ul><li><code>api/openapi.yaml</code> v0: <code>/healthz</code>, <code>/readyz</code>, <code>/me</code>, <code>/me/devices</code> (GET/POST/DELETE), <code>/config/effective</code> (stub che ritorna default), schema <code>Problem</code>. Componenti riusabili (<code>Pagination</code>, <code>Error</code>).</li><li><code>api/proto/clarae/v1/notify.proto</code> (testo §3.6), <code>buf.yaml</code>, <code>buf.gen.yaml</code>.</li><li><code>task gen</code>: <code>oapi-codegen</code> → <code>services/cloud/internal/api/{types,server}.gen.go</code>; client TS → <code>packages/api-client/src/gen/</code>; buf → Go in <code>services/cloud/internal/api/grpc/</code> e client gRPC in <code>apps/desktop/internal/sync/transport/pb/</code>; <code>sqlc</code> (da M0-WP3); <code>wails generate module</code> per <code>wailsjs/</code>.</li></ul><h3 id="m0-wp3-cloud-skeleton-services-cloud" tabindex="-1">M0-WP3 Cloud skeleton (<code>services/cloud</code>) <a class="header-anchor" href="#m0-wp3-cloud-skeleton-services-cloud" aria-label="Permalink to &quot;M0-WP3 Cloud skeleton (`services/cloud`)&quot;">​</a></h3><ul><li><code>cmd/clarae-cloud/main.go</code>: flag <code>--role=api|worker|all</code>, config da env (<code>internal/config</code>: <code>DATABASE_URL</code>, <code>S3_*</code>, <code>OIDC_ISSUER</code>, <code>OIDC_AUDIENCE=clarae-api</code>, <code>KC_ADMIN_*</code>, <code>LISTEN_ADDR</code>), graceful shutdown.</li><li><code>internal/db</code>: pool pgx, helper <code>WithTx</code>, goose embedded; migrazione <code>0001_core.sql</code> = <code>citext</code>, <code>users</code>, <code>devices</code>, <code>settings</code>, <code>audit_log</code>; seed in <code>0002_seed_settings.sql</code> (<code>storage.default_quota_bytes</code>, soglie 80/95, <code>history.retention_days</code>, <code>files.max_size_bytes</code>).</li><li><code>internal/db/queries/*.sql</code> + <code>sqlc.yaml</code>.</li><li><code>internal/httpserver</code>: router chi, middleware <code>request-id</code>, <code>recover</code>, <code>logging</code>, <code>otel</code>, <code>ratelimit</code> (token bucket per utente/IP, header <code>RateLimit-*</code>), <code>cors</code> (solo origine Web UI), <code>compress</code> (gzip/br solo su JSON, mai sui blob), helper <code>ETag</code>/<code>If-Match</code> per le risorse modificabili (usato da M2-WP1 e M4-WP2), handler <code>Problem</code> RFC 9457; <code>/healthz</code>, <code>/readyz</code>, <code>/metrics</code>.</li><li><code>internal/auth</code>: verifica JWT via <code>go-oidc</code> (JWKS cache, <code>iss</code>, <code>aud</code>, <code>exp</code>, <code>azp</code>, skew 60 s), estrazione claims, <strong>JIT provisioning</strong> utenti (<code>users</code> upsert su <code>keycloak_sub</code>), controllo <code>users.status</code> con cache 30 s → <code>USER_SUSPENDED</code>; contesto <code>Principal{UserID, Role}</code>.</li><li><code>internal/users</code>: <code>GET /me</code>, dispositivi (<code>POST /me/devices</code> ritorna <code>device_id</code>), quota effettiva (default da <code>settings</code>).</li><li><code>internal/audit</code>, <code>internal/observability</code> (metriche RED, tracing).</li><li><code>internal/grpcserver</code>: <code>NotifyService.Subscribe</code> che per ora invia solo keepalive; interceptor auth.</li><li><code>test/integration</code>: testcontainers PG (+ Keycloak solo per il test di login reale, tag <code>integration</code>); test contratto base (<code>test/contract</code>: validazione risposte contro <code>openapi.yaml</code> con <code>kin-openapi</code>).</li><li><code>Dockerfile</code> multi-stage; <code>deploy/helm/clarae/</code> chart minimo (Deployment api/worker, Service, Ingress, ConfigMap/Secret).</li></ul><h3 id="m0-wp4-keycloak" tabindex="-1">M0-WP4 Keycloak <a class="header-anchor" href="#m0-wp4-keycloak" aria-label="Permalink to &quot;M0-WP4 Keycloak&quot;">​</a></h3><ul><li><code>deploy/keycloak/realm-clarae.json</code>: realm <code>clarae</code>, client <code>clarae-desktop</code> (public, PKCE S256, redirect <code>http://127.0.0.1/*</code> e <code>clarae://auth/callback</code>, scope <code>offline_access</code>), <code>clarae-web</code>, <code>clarae-api</code> (audience mapper), <code>clarae-admin-svc</code> (service account con <code>manage-users</code>,<code>view-users</code>,<code>query-users</code>), realm roles <code>clarae-admin</code>/<code>clarae-user</code>, token 5 min, SSO idle 8 h, refresh rotation, brute-force protection, password policy, WebAuthn/OTP abilitati come opzionali (§3.3.1), utenti di test <code>admin</code>/<code>user1</code>/<code>user2</code>.</li><li>Script <code>deploy/keycloak/dev-seed.sh</code>.</li></ul><h3 id="m0-wp5-desktop-skeleton-apps-desktop" tabindex="-1">M0-WP5 Desktop skeleton (<code>apps/desktop</code>) <a class="header-anchor" href="#m0-wp5-desktop-skeleton-apps-desktop" aria-label="Permalink to &quot;M0-WP5 Desktop skeleton (`apps/desktop`)&quot;">​</a></h3><ul><li><code>wails init -t react-ts</code> poi ristrutturazione secondo §4.2 (<code>internal/…</code>, <code>frontend/src/…</code>), <code>wails.json</code> con <code>info.protocols</code> per <code>clarae</code>.</li><li><code>main.go</code>: finestra singola, <code>SingleInstanceLock{UniqueId, OnSecondInstanceLaunch}</code> con <code>UniqueId</code> derivato dalla directory dati (<code>CLARAE_DATA_DIR</code>/flag <code>--data-dir</code>), così due istanze con dir dati distinte possono coesistere per i test multi-dispositivo (M2); <code>Mac.OnUrlOpen</code>, menu nativo base, assetserver con CSP (SPIKE-05).</li><li><code>internal/app</code>: composizione (costruttori espliciti, niente DI framework), <code>bindings.go</code> (<code>VaultAPI</code>, <code>AuthAPI</code>, <code>SettingsAPI</code> iniziali), <code>events.go</code> (nomi evento come costanti condivise con TS in <code>frontend/src/app/events.ts</code>).</li><li><code>internal/store</code>: apertura <code>app.db</code> (vault recenti, impostazioni app), <code>index.db</code>/<code>sync.db</code> per vault in <code>.clarae/</code>; migrazioni goose embedded.</li><li><code>internal/vault</code>: <code>Manager</code> (vault recenti, apri/crea), <code>FS</code> con <code>ReadFile</code>, <code>WriteAtomic(tmp+fsync+rename)</code>, <code>Rename</code>, <code>Delete→.trash/</code>, guardie path traversal (<code>pathrules</code> + <code>filepath.EvalSymlinks</code> dentro la radice), <code>ListTree</code>.</li><li><code>internal/watcher</code>: fsnotify ricorsivo + debounce 1.5 s + riconciliazione periodica (mtime/size) → evento <code>vault:file-changed</code>.</li><li><code>internal/parser</code> v0: goldmark con estensione wikilink minima + heading + tag; <code>internal/indexer</code> v0: tabella <code>files</code> + <code>headings</code> + <code>links</code> + <code>tags</code> in <code>index.db</code>, scansione all&#39;apertura (serve a M1 e a verificare l&#39;ingranaggio).</li><li><code>internal/platform</code>: parsing URL <code>clarae://open?vault=&amp;file=</code> e <code>clarae://auth/callback</code>, registrazione scheme (Info.plist via <code>build/darwin</code>, NSIS script, <code>.desktop</code> Linux).</li><li><code>internal/telemetry</code>: zerolog su file rotante in dir dati app; crash report <strong>opt-in</strong> (consenso nelle impostazioni, invio rinviato a M7-WP4).</li><li>Frontend testabile fuori dal webview: shim dei binding (<code>frontend/src/test/wails-mock/</code> che implementa <code>window.go.*</code> e <code>runtime</code> con fixture) per far girare l&#39;app in Chromium con Playwright; i test sul webview reale restano manuali (checklist per OS).</li><li>Frontend: <code>app/</code> (shell, tema chiaro/scuro con token CSS, provider), <code>workspace/</code> minimo (una tab), <code>sidebar/</code> file explorer (tree, apri nota), <code>editor/</code> CodeMirror 6 in <strong>Source mode</strong> (solo highlighting markdown base), <code>state/</code> Zustand store vault + TanStack Query sui binding, <code>i18n/</code> (it, en) con i18next, <code>settings/</code> pannello &quot;Generale&quot; (lingua, tema).</li></ul><h3 id="m0-wp6-auth-desktop-end-to-end" tabindex="-1">M0-WP6 Auth desktop end-to-end <a class="header-anchor" href="#m0-wp6-auth-desktop-end-to-end" aria-label="Permalink to &quot;M0-WP6 Auth desktop end-to-end&quot;">​</a></h3><ul><li><code>internal/auth</code>: <code>Login()</code> → PKCE (verifier/challenge S256, <code>state</code>), listener <code>127.0.0.1:0</code>, apertura browser di sistema, callback, scambio token, salvataggio refresh token nel keychain; <code>Refresh()</code> silenzioso con rotation; fallback <code>scheme</code> (D-08) quando listener fallisce o Keycloak risponde <code>invalid_redirect_uri</code> o config forza <code>scheme</code>; <code>Logout()</code>; stato <code>auth:state</code> (<code>signed_out|signing_in|ready|disconnected</code>).</li><li><code>internal/sync/transport</code> v0: client HTTP con bearer + retry/backoff + <code>X-Request-Id</code>; chiamata <code>GET /me</code> e <code>POST /me/devices</code> (registrazione dispositivo con nome host/piattaforma).</li><li>UI: pulsante &quot;Accedi al cloud&quot; nelle impostazioni → profilo mostrato.</li></ul><h3 id="m0-wp7-ci" tabindex="-1">M0-WP7 CI <a class="header-anchor" href="#m0-wp7-ci" aria-label="Permalink to &quot;M0-WP7 CI&quot;">​</a></h3><ul><li><code>.github/workflows/ci.yml</code>: job <code>go</code> (lint, test -race, govulncheck), <code>ts</code> (tsc, eslint, vitest), <code>conformance</code>, <code>cloud-integration</code> (testcontainers), <code>desktop-build</code> matrix (ubuntu-24.04 con <code>webkit2gtk-4.1</code> e <code>wails build -tags webkit2_41</code>, windows, macos); <code>cloud-image</code> (buildx, push solo su tag).</li><li>Cache Go/Yarn; <code>task ci</code> locale equivalente.</li></ul><p><strong>Criteri di uscita M0:</strong> <code>task dev-cloud</code> avvia lo stack (compose) e <code>curl /api/v1/me</code> con token Keycloak risponde; l&#39;app desktop apre una cartella come vault, mostra l&#39;albero, apre/modifica/salva una nota in Source mode (scrittura atomica verificata con test), rileva modifiche esterne; login PKCE loopback funziona su macOS (e in CI build su 3 OS); SPIKE-01, -02, -03, -05 chiusi con ADR (SPIKE-04 apre M1); CI verde.</p><hr><h2 id="_6-m1-—-core-editing-p0-esito-parita-funzionale-p0-offline" tabindex="-1">6. M1 — Core editing (P0) (esito: parità funzionale P0 offline) <a class="header-anchor" href="#_6-m1-—-core-editing-p0-esito-parita-funzionale-p0-offline" aria-label="Permalink to &quot;6. M1 — Core editing (P0) (esito: parità funzionale P0 offline)&quot;">​</a></h2><blockquote><p><strong>Stato (2026-10-24):</strong> WP1–WP9 implementati (ADR-0004). Verificati in CI locale: conformance Go/TS su 69 fixture, vitest, e2e Playwright su mock dei binding. Restano la checklist manuale su webview reale (<code>docs/qa/parita-funzionale-m1.md</code>) e il benchmark di ricerca a 50k note (cache dei candidati).</p></blockquote><h3 id="m1-wp1-parser-ofm-completo-go-∥-con-wp5" tabindex="-1">M1-WP1 Parser OFM completo (Go) ∥ con WP5 <a class="header-anchor" href="#m1-wp1-parser-ofm-completo-go-∥-con-wp5" aria-label="Permalink to &quot;M1-WP1 Parser OFM completo (Go) ∥ con WP5&quot;">​</a></h3><ul><li><code>internal/parser</code>: estensioni goldmark per wikilink (<code>[[Nota]]</code>, alias, <code>#heading</code>, <code>#^block</code>, <code>[[#heading]]</code>), embed <code>![[…]]</code> con parametri (<code>|WxH</code>, <code>#page=</code>), callout (<code>&gt; [!type]±</code> con titolo), highlight <code>==</code>, commento <code>%%</code>, block-id <code>^id</code>, task con stati custom, tag <code>#a/b</code> (regola consueta: no solo cifre), footnote, math <code>$</code>/<code>$$</code> (solo riconoscimento), frontmatter YAML tipizzato (<code>tags</code>, <code>aliases</code>; <code>cssclasses</code> ignorata), tabelle GFM.</li><li>Output: <code>parser.Document{Title, Aliases, Headings[], Links[], Embeds[], Tags[], Properties, Tasks[], BlockIDs[], Footnotes[], WordCount}</code> con posizioni (offset byte e riga).</li><li>Fixture conformance complete (≥ 60 casi) in <code>shared/conformance/markdown/</code>, inclusi casi limite (link in code span/fence, escape, nested callout, tag in URL).</li></ul><h3 id="m1-wp2-indexer-e-index-db" tabindex="-1">M1-WP2 Indexer e index.db <a class="header-anchor" href="#m1-wp2-indexer-e-index-db" aria-label="Permalink to &quot;M1-WP2 Indexer e index.db&quot;">​</a></h3><ul><li>Schema <code>index.db</code> (goose): <code>files(path, mtime, size, hash, kind, title, word_count)</code>, <code>headings</code>, <code>links(src, target_raw, target_resolved, heading, block, alias, pos)</code>, <code>embeds</code>, <code>tags</code>, <code>properties(file, key, type, value_text, value_num, value_date, value_bool)</code>, <code>tasks</code>, <code>block_ids</code>, <code>aliases</code>, <code>fts_content</code> (FTS5 trigram su titolo+corpo), <code>fts_meta</code>.</li><li>Pipeline incrementale: pool worker con backpressure, coalescing rename (stesso hash), re-parse solo file cambiati, evento <code>index:progress</code>; comando &quot;Ricostruisci indice&quot;.</li><li>Indicizzazione file <code>.excalidraw</code>/<code>.canvas</code> rinviata a M3 (hook predisposto in <code>indexer.Register(kind, extractor)</code>).</li></ul><h3 id="m1-wp3-link-backlink-rename-refactoring" tabindex="-1">M1-WP3 Link, backlink, rename refactoring <a class="header-anchor" href="#m1-wp3-link-backlink-rename-refactoring" aria-label="Permalink to &quot;M1-WP3 Link, backlink, rename refactoring&quot;">​</a></h3><ul><li><code>internal/links</code>: risoluzione target (&quot;shortest path&quot; configurabile: shortest/relative/absolute), alias, heading/block; note &quot;fantasma&quot; (non risolte); backlink e &quot;menzioni non collegate&quot; (ricerca del titolo nel FTS); outgoing links.</li><li><code>RenameWithLinkUpdate(from,to)</code>: <code>RenamePlan{AffectedFiles[], Rewrites[]}</code> → anteprima → applicazione transazionale (scrittura atomica di tutti i file, rollback su errore), aggiornamento indice. Test con fixture di vault.</li><li>Binding <code>LinksAPI</code>: <code>Resolve</code>, <code>Backlinks</code>, <code>UnlinkedMentions</code>, <code>Outgoing</code>, <code>PlanRename</code>, <code>ApplyRename</code>.</li></ul><h3 id="m1-wp4-ricerca" tabindex="-1">M1-WP4 Ricerca <a class="header-anchor" href="#m1-wp4-ricerca" aria-label="Permalink to &quot;M1-WP4 Ricerca&quot;">​</a></h3><ul><li><code>internal/search</code>: parser query (§2.4: termini, frasi, <code>OR</code>, <code>-</code>, parentesi, <code>file: path: content: tag: line: block: section: task: task-todo: task-done: [prop:val] match-case: ignore-case: /regex/</code>) → AST → piano (predicati strutturali su tabelle + FTS + post-filtro RE2/co-occorrenza); snippet con evidenziazione; ordinamenti; &quot;spiega termini&quot;.</li><li>Sotto 3 caratteri: scansione lineare sui candidati. Benchmark con dataset sintetico 50k note (<code>tools/vaultgen</code> in <code>apps/desktop/internal/testutil</code>): obiettivo &lt; 200 ms.</li><li>Binding <code>SearchAPI.Query(vaultID, q, opts)</code>.</li></ul><h3 id="m1-wp5-editor-codemirror-6-frontend-∥-con-wp1–wp4" tabindex="-1">M1-WP5 Editor CodeMirror 6 (frontend) ∥ con WP1–WP4 <a class="header-anchor" href="#m1-wp5-editor-codemirror-6-frontend-∥-con-wp1–wp4" aria-label="Permalink to &quot;M1-WP5 Editor CodeMirror 6 (frontend) ∥ con WP1–WP4&quot;">​</a></h3><ul><li><code>editor/</code>: setup (markdown language da <code>@lezer/markdown</code> con estensioni OFM Lezer: wikilink, embed, callout, highlight, comment, block-id, math, tag), tema chiaro/scuro, Source mode e <strong>Live Preview</strong> (ADR-0004): un&#39;estensione per elemento in <code>editor/extensions/</code> rilasciata in quest&#39;ordine: heading, emphasis/strike/highlight, link e wikilink (click con mod), liste e task (checkbox cliccabile), quote e callout (fold), code fence (highlight via Lezer), tabelle (editing assistito), math (KaTeX widget), mermaid (widget con render sandbox), embed (widget che chiede <code>ReadNote</code>/immagine ai binding con guardia anti-ciclo), footnote, frontmatter (vista Properties, WP7), commenti <code>%%</code> nascosti in reading.</li><li>Autocompletamento: <code>[[</code> (note/alias da indice, <code>#</code> heading, <code>^</code> block con generazione id), <code>#</code> tag, proprietà frontmatter; slash <code>/</code> rinviato a M6.</li><li>Comandi editor: auto-pair, continuazione liste/task/quote, indent/outdent, riordino liste, folding heading/liste, multi-cursore, find/replace con regex, selezione rettangolare, toggle formatting.</li><li>Smart paste (URL su selezione, HTML→Markdown via <code>turndown</code>, immagine → salva in allegati + embed), drag&amp;drop file.</li><li>Salvataggio: debounce 500 ms, <code>WriteNote(expectedHash)</code>; su <code>conflict</code> (modifica esterna) banner &quot;ricarica/sovrascrivi&quot;.</li><li>Spellcheck webview, line wrap, larghezza lettura, numeri riga.</li></ul><h3 id="m1-wp6-reading-view-e-rendering" tabindex="-1">M1-WP6 Reading view e rendering <a class="header-anchor" href="#m1-wp6-reading-view-e-rendering" aria-label="Permalink to &quot;M1-WP6 Reading view e rendering&quot;">​</a></h3><ul><li><code>reading/</code>: pipeline unified (<code>remark-parse</code>, <code>remark-gfm</code>, <code>remark-math</code>, plugin OFM custom per wikilink/embed/callout/highlight/comment/block-id/tag, <code>rehype-katex</code>, mermaid lazy, <code>rehype-sanitize</code> + DOMPurify, no <code>&lt;style&gt;</code>/<code>style</code>), TOC, embed ricorsivi (profondità max 5), PDF embed (<code>#page=</code>) via <code>&lt;embed&gt;</code>/pdf.js lazy, audio/video.</li><li>Runner conformance TS: parser remark + Lezer producono lo stesso <code>expected.json</code> delle fixture (link/tag/heading/block/task) → CI.</li><li>Page preview (hover) rinviato a M6.</li></ul><h3 id="m1-wp7-properties-tag-outline-word-count" tabindex="-1">M1-WP7 Properties, tag, outline, word count <a class="header-anchor" href="#m1-wp7-properties-tag-outline-word-count" aria-label="Permalink to &quot;M1-WP7 Properties, tag, outline, word count&quot;">​</a></h3><ul><li><code>internal/properties</code>: schema tipi in <code>.clarae/types.json</code>, validazione/coercizione (<code>text,list,number,checkbox,date,datetime</code>), binding <code>PropertiesAPI</code> (<code>GetTypes</code>, <code>SetType</code>, <code>Update(file, key, value)</code> che riscrive il frontmatter preservando ordine/commenti).</li><li>Frontend: editor Properties tipizzato in cima alla nota, vista Properties nel sidebar; vista Tags (gerarchica, conteggi); Outline; <code>statusbar/</code> word/char count (anche selezione).</li></ul><h3 id="m1-wp8-workspace-navigazione-comandi-impostazioni" tabindex="-1">M1-WP8 Workspace, navigazione, comandi, impostazioni <a class="header-anchor" href="#m1-wp8-workspace-navigazione-comandi-impostazioni" aria-label="Permalink to &quot;M1-WP8 Workspace, navigazione, comandi, impostazioni&quot;">​</a></h3><ul><li><code>workspace/</code>: tab, split orizzontale/verticale, linked panes, sidebar sx/dx, drag tab; persistenza <code>.clarae/workspace.json</code> (non sync); modalità per pannello (source/live/reading) ricordata.</li><li><code>commands/</code>: registro comandi unico (id, titolo i18n, hotkey default, <code>when</code>), command palette, hotkey personalizzabili (<code>.clarae/hotkeys.json</code>), quick switcher (fuzzy su nome/alias/heading con <code>fuse.js</code> o algoritmo custom), vault switcher.</li><li>File explorer completo: crea nota/cartella, rinomina (usa <code>PlanRename</code>), sposta (drag), elimina (cestino di sistema via Wails/<code>.trash/</code> da impostazione), ordina, mostra allegati.</li><li><code>settings/</code>: pannelli Editor, File e link, Aspetto (tema, accento, font, zoom, larghezza), Hotkeys, Lingua; persistenza <code>.clarae/{editor,appearance}.json</code> (per utente, sincronizzabili in M2) + <code>app.db</code> per preferenze app.</li><li>URI <code>clarae://open?vault=&amp;file=</code> funzionante.</li></ul><h3 id="m1-wp9-qualita-m1" tabindex="-1">M1-WP9 Qualità M1 <a class="header-anchor" href="#m1-wp9-qualita-m1" aria-label="Permalink to &quot;M1-WP9 Qualità M1&quot;">​</a></h3><ul><li>Playwright e2e in Chromium con lo shim dei binding (M0-WP5) per: apri vault, crea nota, wikilink + backlink, ricerca, rename con aggiornamento link, cambio modalità; checklist manuale equivalente sul webview reale per OS.</li><li>Benchmark: apertura nota &lt; 150 ms, indice iniziale 50k &lt; 3 min (dataset sintetico), digitazione senza lag su 1 MB (test manuale documentato).</li></ul><p><strong>Criteri di uscita M1:</strong> tutte le righe P0 della matrice §2.2.1 tranne Sync/Excalidraw sono implementate; conformance Go/TS verde su ≥ 60 fixture; un vault di file Markdown ordinari di esempio si apre senza conversioni e i link si risolvono secondo le regole del formato (checklist manuale in <code>docs/qa/parita-funzionale-m1.md</code>).</p><hr><h2 id="_7-m2-—-sync-p0-esito-multi-dispositivo-affidabile-vault-privati-e2ee-e-condivisi" tabindex="-1">7. M2 — Sync (P0) (esito: multi-dispositivo affidabile, vault privati E2EE e condivisi) <a class="header-anchor" href="#_7-m2-—-sync-p0-esito-multi-dispositivo-affidabile-vault-privati-e2ee-e-condivisi" aria-label="Permalink to &quot;7. M2 — Sync (P0) (esito: multi-dispositivo affidabile, vault privati E2EE e condivisi)&quot;">​</a></h2><blockquote><p><strong>Stato: implementata (2026-10-24)</strong> — WP1–WP8 completati; criteri di uscita verificati (e2e a 2 dispositivi in entrambi i tipi di vault, load test p95, test vector Go+TS). Dettagli e deviazioni: <a href="./adr/0009-sync-protocol-details.html">ADR-0009</a>.</p></blockquote><h3 id="m2-wp1-schema-e-moduli-cloud-vault-blob-revisioni" tabindex="-1">M2-WP1 Schema e moduli cloud: vault, blob, revisioni <a class="header-anchor" href="#m2-wp1-schema-e-moduli-cloud-vault-blob-revisioni" aria-label="Permalink to &quot;M2-WP1 Schema e moduli cloud: vault, blob, revisioni&quot;">​</a></h3><ul><li>Migrazione <code>0002_vaults.sql</code>: <code>vaults</code>, <code>vault_key_envelopes</code>, <code>blobs</code>, <code>files</code>, <code>file_revisions</code> + trigger <code>vault_kind_immutable</code>; indici §3.2.2.</li><li><code>internal/vaults</code>: CRUD (<code>POST /vaults</code> con <code>kind</code> e <code>key_envelopes</code> obbligatori per <code>private</code>), rinomina, soft delete (30 gg) e <code>:restore</code>, <code>GET /vaults/{vid}/tree</code> (manifest + <code>as_of_seq</code>), <code>GET /vaults</code> con <code>mounts</code> (vuoto fino a M4).</li><li><code>internal/vaultkeys</code>: <code>GET/PUT /vaults/{vid}/key-envelopes[/{kind}]</code> (owner), validazione formato <code>kdf</code> e lunghezze; mai log del contenuto.</li><li><code>internal/blobs</code>: <code>POST blobs:check</code>, <code>PUT /blobs/{sha256}</code> (≤ 32 MB, ricalcolo hash, rifiuto mismatch), <code>GET /blobs/{sha256}</code> con <code>Range</code>, tus (<code>POST /vaults/{vid}/uploads</code>, <code>PATCH /uploads/{id}</code>) con store S3 e finalizzazione che verifica hash; <code>ref_count</code>.</li><li><code>internal/storage</code>: interfaccia <code>BlobStore</code> (S3 + filesystem per test).</li><li><code>internal/revisions</code>: <code>GET …/revisions</code>, <code>…/revisions/{rev}/content</code>, <code>:restore</code> (nuova revisione che riusa il blob), retention (tutte 30 gg, poi 1/giorno fino a 90) applicata dai job.</li></ul><h3 id="m2-wp2-commit-e-changes" tabindex="-1">M2-WP2 Commit e changes <a class="header-anchor" href="#m2-wp2-commit-e-changes" aria-label="Permalink to &quot;M2-WP2 Commit e changes&quot;">​</a></h3><ul><li><code>internal/sync</code>: <code>POST /vaults/{vid}/commit</code> — per ogni op in ordine, transazione indipendente: ACL (in M2 solo owner), quota (<code>413 QUOTA_EXCEEDED</code>), <code>FILE_TOO_LARGE</code>, <code>PATH_INVALID</code>/<code>PATH_COLLISION</code> (su <code>path_key</code>), <code>base_rev == current_rev</code> altrimenti <code>conflict{REV_CONFLICT,current_rev,current_hash,current_seq}</code>, <code>BLOB_MISSING</code>, <code>file_id</code> client (UUID v7, rifiuto duplicati), <code>UPDATE vaults SET last_seq=last_seq+1 RETURNING</code>, scrittura revisione, aggiornamento <code>files</code>, <code>blobs.ref_count</code>, <code>users.used_bytes</code>, <code>vaults.total_bytes/file_count</code>; <code>move_prefix</code> (solo shared) ; <code>Idempotency-Key</code> + <code>op_id</code> univoco (tabella <code>commit_ops_seen</code> con TTL o unique su <code>file_revisions.op_id</code> → decidere: aggiungere colonna <code>op_id</code> in migrazione, ADR).</li><li><code>GET /vaults/{vid}/changes?since&amp;limit</code> con <code>has_more</code>; <code>410 CURSOR_EXPIRED</code> quando <code>since &lt; compaction_floor</code> (campo <code>vaults.compaction_seq</code>, job di compattazione in M2-WP7).</li><li><code>internal/quota</code>: calcolo quota effettiva, soglie 80/95/100, API <code>/me/usage</code>.</li><li>Test d&#39;integrazione: concorrenza (2 client stesso file → un <code>conflict</code>), quota, collisione case-insensitive, idempotenza.</li></ul><h3 id="m2-wp3-notifiche-realtime" tabindex="-1">M2-WP3 Notifiche realtime <a class="header-anchor" href="#m2-wp3-notifiche-realtime" aria-label="Permalink to &quot;M2-WP3 Notifiche realtime&quot;">​</a></h3><ul><li><code>internal/notify</code>: Postgres <code>LISTEN/NOTIFY</code> canale <code>vault_changed</code> → fan-out in-process; <code>NotifyService.Subscribe</code> (replay da <code>known_seq</code>, chiusura <code>UNAUTHENTICATED</code> a token scaduto), <code>GET /events</code> SSE con <code>Last-Event-ID</code>.</li><li>Desktop <code>sync/transport</code>: client gRPC stream con riconnessione dopo refresh; fallback SSE; polling adattivo 30 s → 5 min.</li></ul><h3 id="m2-wp4-merge-condiviso-shared-go-merge-∥-con-wp1–wp3" tabindex="-1">M2-WP4 Merge condiviso (<code>shared/go/merge</code>) ∥ con WP1–WP3 <a class="header-anchor" href="#m2-wp4-merge-condiviso-shared-go-merge-∥-con-wp1–wp3" aria-label="Permalink to &quot;M2-WP4 Merge condiviso (`shared/go/merge`) ∥ con WP1–WP3&quot;">​</a></h3><ul><li><code>merge/markdown.go</code>: 3-way (<code>base, ours, theirs</code>): frontmatter YAML per chiave (conflitto stessa chiave → remoto vince, locale in copia), corpo diff3 a righe con localizzazione via diff-match-patch; risultato <code>{Merged []byte, Clean bool, Conflicts []Hunk}</code>.</li><li><code>merge/jsonid.go</code>: Excalidraw (per <code>element.id</code>, <code>version</code>/<code>versionNonce</code>, <code>isDeleted</code>, unione <code>files</code>), Canvas (per id nodo/arco, tie-break per tempo server), config JSON LWW per chiave di primo livello.</li><li><code>merge/policy.go</code>: tabella decisionale §3.4.5 (tipo file × stesso/diverso autore × op) → <code>Strategy</code>.</li><li>Fixture <code>shared/conformance/merge/</code> (base/ours/theirs/expected) e test tabellari; copertura ≥ 80 %.</li></ul><h3 id="m2-wp5-cripto-e2ee-shared-go-vaultcrypto-desktop-crypto-∥" tabindex="-1">M2-WP5 Cripto E2EE (<code>shared/go/vaultcrypto</code> + desktop <code>crypto</code>) ∥ <a class="header-anchor" href="#m2-wp5-cripto-e2ee-shared-go-vaultcrypto-desktop-crypto-∥" aria-label="Permalink to &quot;M2-WP5 Cripto E2EE (`shared/go/vaultcrypto` + desktop `crypto`) ∥&quot;">​</a></h3><ul><li><code>vaultcrypto</code>: <code>GenerateVMK</code>, <code>DeriveKEKPassphrase(argon2id, params)</code>, <code>DeriveKEKRecovery(hkdf)</code>, <code>Wrap/Unwrap(AES-GCM)</code>, <code>RecoveryKey</code> encode/decode Base32 con checksum, <code>DeriveSubkeys(VMK)</code> (<code>path-enc</code>, <code>path-key</code>, <code>file</code>), <code>EncryptBlob(w, r, vaultID, fileID)</code>/<code>DecryptBlob</code> a chunk 64 KiB con header <code>NDS1</code> e AAD §3.8.3, <code>EncryptPath</code>/<code>PathKey</code> (<code>enc1:</code>/<code>hmac1:</code>), calibrazione Argon2id sul dispositivo.</li><li>Test vector in <code>shared/conformance/crypto/vectors.json</code> (KDF, wrap, blob a 0/1/2 chunk, path) generati da Go. Per rispettare §3.8.7 (&quot;Go e TS a ogni CI&quot;) si anticipa qui il <strong>core</strong> di <code>packages/vaultcrypto-web</code> (KDF Argon2id via <code>hash-wasm</code>, HKDF/HMAC/AES-GCM via WebCrypto, formato blob e path; nessuna UI) con Vitest che verifica i vettori; M5-WP4 aggiunge solo lo streaming ZIP e la UI.</li><li>Desktop <code>internal/crypto</code>: VMK nel keychain, lock/unlock con timeout, <code>VaultCryptoAPI</code> (§2.5): <code>CreateEncryptedVault</code>, <code>Unlock</code> (ritorna <code>requires_new_passphrase=true</code> quando lo sblocco avviene con recovery key, §3.8.4 p.4), <code>ChangePassphrase</code>, <code>RegenerateRecoveryKey</code>; zxcvbn (frontend) ≥ 3, min 12 caratteri.</li><li>Avviso &quot;disco non cifrato&quot; dove rilevabile (FileVault via <code>fdesetup status</code>, BitLocker via WMI — best effort).</li></ul><h3 id="m2-wp6-sync-engine-desktop" tabindex="-1">M2-WP6 Sync engine desktop <a class="header-anchor" href="#m2-wp6-sync-engine-desktop" aria-label="Permalink to &quot;M2-WP6 Sync engine desktop&quot;">​</a></h3><ul><li><code>internal/sync</code>: schema <code>sync.db</code> (§3.4.3: <code>sync_files</code>, <code>sync_cursor</code>, <code>outbox</code>, <code>conflicts</code>), <code>detect.go</code> (stato da watcher + riconciliazione, rename per hash o <code>file_id</code> da <code>RenameWithLinkUpdate</code>), <code>engine.go</code> (ciclo: pull → applica → push → risolvi; scheduler, pause/resume, backoff con jitter, <code>Retry-After</code>), <code>resolve.go</code> (usa <code>merge</code>, conflict copy <code>&lt;nome&gt; (conflitto &lt;device&gt; &lt;data&gt;).&lt;ext&gt;</code> con <code>conflict_of</code>, limite 5 tentativi → stato <code>conflict</code>), scope <code>.clarae/</code> (§3.4.6), esclusioni, eco per <code>device_id</code>, bootstrap da <code>/tree</code> su <code>CURSOR_EXPIRED</code>, upload grandi via tus.</li><li>Vault privati: cifratura blob/path prima dell&#39;upload, decifratura dopo il download, <code>kind=opaque</code>, nessun <code>move_prefix</code>; hash plaintext in <code>sync.db</code> per evitare re-upload.</li><li>Binding <code>SyncAPI</code> (§2.5) + eventi <code>sync:status</code>, <code>sync:conflict</code>, <code>vault:locked</code>.</li><li>Test: simulatore di 2 client contro cloud in testcontainers (test e2e Go in <code>apps/desktop/internal/sync/e2e_test.go</code>, tag <code>integration</code>): modifica concorrente <code>.md</code> non sovrapposta → merge; sovrapposta → conflict copy; rename vs modifica; delete vs modify; vault privato round-trip.</li></ul><h3 id="m2-wp7-job-e-manutenzione-cloud" tabindex="-1">M2-WP7 Job e manutenzione cloud <a class="header-anchor" href="#m2-wp7-job-e-manutenzione-cloud" aria-label="Permalink to &quot;M2-WP7 Job e manutenzione cloud&quot;">​</a></h3><ul><li><code>internal/jobs</code> (role <code>worker</code>): GC blob (<code>ref_count=0</code> + grace 24 h), riconciliazione <code>used_bytes</code> notturna, purge vault eliminati &gt; 30 gg, retention revisioni, compattazione changelog (finestra configurabile, aggiorna <code>compaction_seq</code>).</li><li><code>GET/PUT /admin/settings/storage</code> rinviato a M5; in M2 i valori arrivano da <code>settings</code> seed.</li></ul><h3 id="m2-wp8-ui-sync" tabindex="-1">M2-WP8 UI sync <a class="header-anchor" href="#m2-wp8-ui-sync" aria-label="Permalink to &quot;M2-WP8 UI sync&quot;">​</a></h3><ul><li><code>sync/</code> frontend: wizard &quot;Collega al cloud&quot; (tipo vault privato/condiviso con testi espliciti, passphrase + robustezza, recovery key con conferma per ri-digitazione, primo upload con progresso/ripresa), sblocco vault bloccato (con passphrase o recovery key; in quest&#39;ultimo caso passo obbligatorio &quot;imposta nuova passphrase&quot; e opzione &quot;rigenera recovery key&quot;), indicatore stato per vault, vista &quot;Risoluzione conflitti&quot; (diff affiancato, Tieni locale/remoto/Unisci/Entrambi), &quot;Cronologia nota&quot; (lista revisioni, diff — decifrato sul client per i privati — e ripristino), dispositivi (lista/revoca via <code>/me/devices</code>), impostazioni sync (intervallo, pausa).</li><li>Sync delle impostazioni utente <code>.clarae/*.json</code> con LWW per chiave.</li></ul><p><strong>Criteri di uscita M2:</strong> scenario a 2 dispositivi (2 istanze desktop con dir dati distinte) converge in entrambi i tipi di vault; nessuna perdita silenziosa (test); p95 <code>changes</code> &lt; 200 ms e <code>commit</code> ≤ 50 op &lt; 500 ms in load test locale (k6 base in <code>services/cloud/test/load/</code>); test vector cripto verdi in Go e TS.</p><hr><h2 id="_8-m3-—-excalidraw-canvas-esito-disegni-nativi-sincronizzati" tabindex="-1">8. M3 — Excalidraw + Canvas (esito: disegni nativi sincronizzati) <a class="header-anchor" href="#_8-m3-—-excalidraw-canvas-esito-disegni-nativi-sincronizzati" aria-label="Permalink to &quot;8. M3 — Excalidraw + Canvas (esito: disegni nativi sincronizzati)&quot;">​</a></h2><blockquote><p><strong>Stato (2026-10-24):</strong> WP1–WP4 implementati (<a href="./adr/0010-drawing-and-canvas-details.html">ADR-0010</a>). Verificati in locale: unit test Go (<code>drawing</code>, <code>canvas</code>, indexer) e frontend, e2e Playwright su mock dei binding (apertura/modifica/salvataggio di un disegno senza richieste di rete, embed, canvas), e2e a due dispositivi per <code>.excalidraw</code> e <code>.canvas</code>. Resta la checklist manuale sul webview reale (<code>docs/qa/m3-drawings-canvas.md</code>).</p></blockquote><h3 id="m3-wp1-excalidraw-frontend-drawing" tabindex="-1">M3-WP1 Excalidraw (frontend <code>drawing/</code>) <a class="header-anchor" href="#m3-wp1-excalidraw-frontend-drawing" aria-label="Permalink to &quot;M3-WP1 Excalidraw (frontend `drawing/`)&quot;">​</a></h3><ul><li>Wrapper <code>@excalidraw/excalidraw</code> con <code>React.lazy</code>, <code>EXCALIDRAW_ASSET_PATH</code> → asset copiati nel bundle (<code>vite</code> plugin di copia), tema app, i18n.</li><li>Tab &quot;Disegno&quot;: apertura <code>.excalidraw</code>, autosave debounce 2 s via <code>WriteNote</code> binario con <code>expectedHash</code>, read-only se permesso <code>viewer</code> (M4) o vault bloccato.</li><li>Comandi: &quot;Nuovo disegno&quot; (palette, inserisce embed se invocato da una nota), &quot;Inserisci disegno&quot;; doppio clic su embed → editor (tab o overlay); export PNG 1x–3x con/senza sfondo, SVG, copia appunti; libreria <code>.clarae/excalidraw-library.json</code>; modalità presentazione/zen.</li><li>Soglia 10 MB per disegno con avviso.</li></ul><h3 id="m3-wp2-supporto-backend-disegni-internal-drawing" tabindex="-1">M3-WP2 Supporto backend disegni (<code>internal/drawing</code>) <a class="header-anchor" href="#m3-wp2-supporto-backend-disegni-internal-drawing" aria-label="Permalink to &quot;M3-WP2 Supporto backend disegni (`internal/drawing`)&quot;">​</a></h3><ul><li>Validazione JSON Excalidraw; estrattore per l&#39;indexer: testo elementi <code>text</code> (FTS) e <code>link</code> degli elementi verso <code>[[Nota]]</code> (archi grafo/backlink con etichetta &quot;Disegno X&quot;).</li><li>Anteprima SVG: generata dal frontend (<code>exportToSvg</code>) e salvata via binding in <code>.clarae/cache/drawings/&lt;hash&gt;.svg</code>; invalidazione per hash; embed <code>![[x.excalidraw|600]]</code> in Live Preview/Reading usa la cache (fallback: render lazy).</li></ul><h3 id="m3-wp3-canvas-json-canvas" tabindex="-1">M3-WP3 Canvas (JSON Canvas) <a class="header-anchor" href="#m3-wp3-canvas-json-canvas" aria-label="Permalink to &quot;M3-WP3 Canvas (JSON Canvas)&quot;">​</a></h3><ul><li><code>internal/canvas</code>: parse/validate <code>.canvas</code> (nodi <code>text|file|link|group</code>, edges), estrattore indexer (testo, link a file).</li><li>Frontend <code>canvas/</code>: editor su <code>&lt;canvas&gt;</code>/SVG con pan/zoom, creazione nodi (testo con mini editor CM6, nota come embed, media, link, gruppo), archi con etichette, selezione/drag/resize, colori preset, undo/redo, autosave; embed <code>![[mappa.canvas]]</code> in nota (render statico).</li></ul><h3 id="m3-wp4-sync-per-id-e-ci-offline" tabindex="-1">M3-WP4 Sync per-id e CI offline <a class="header-anchor" href="#m3-wp4-sync-per-id-e-ci-offline" aria-label="Permalink to &quot;M3-WP4 Sync per-id e CI offline&quot;">​</a></h3><ul><li>Attivazione in <code>sync/resolve.go</code> delle strategie <code>jsonid</code> per <code>.excalidraw</code>/<code>.canvas</code> (stesso utente); test e2e di merge tra 2 dispositivi.</li><li>Test Playwright (Chromium + shim binding) che intercetta le richieste di rete durante apertura di un disegno: <strong>zero richieste esterne</strong> (gate CI); verifica manuale sul webview per OS nella checklist M3.</li></ul><p><strong>Criteri di uscita M3:</strong> creare/embed/modificare/esportare un disegno offline; link da elemento a nota compare nei backlink; ricerca trova testo nel disegno; 2 dispositivi convergono su un disegno modificato in parti diverse.</p><hr><h2 id="_9-m4-—-condivisione-e-gruppi-esito-collaborazione-asincrona" tabindex="-1">9. M4 — Condivisione e gruppi (esito: collaborazione asincrona) <a class="header-anchor" href="#_9-m4-—-condivisione-e-gruppi-esito-collaborazione-asincrona" aria-label="Permalink to &quot;9. M4 — Condivisione e gruppi (esito: collaborazione asincrona)&quot;">​</a></h2><blockquote><p><strong>Stato (2026-10-24):</strong> WP1–WP5 implementati (<a href="./adr/0011-sharing-groups-config-details.html">ADR-0011</a>). Verificati in locale: unit e integrazione del cloud (matrice ACL, scope, eventi, config profile), e2e desktop contro il cloud reale (due utenti: merge, conflict copy per autori diversi, viewer in sola lettura, revoca, manager) e sul mock (inviti, mount, sola lettura, chiavi <code>locked</code>), Web UI con unit test e Playwright. Resta la checklist manuale (<code>docs/qa/m4-sharing.md</code>); la finestra &quot;nuova condivisione&quot; della Web UI e le API admin (M5) non sono incluse.</p></blockquote><h3 id="m4-wp1-gruppi-e-directory-cloud" tabindex="-1">M4-WP1 Gruppi e directory (cloud) <a class="header-anchor" href="#m4-wp1-gruppi-e-directory-cloud" aria-label="Permalink to &quot;M4-WP1 Gruppi e directory (cloud)&quot;">​</a></h3><ul><li>Migrazione <code>0003_groups_sharing.sql</code>: <code>groups</code>, <code>group_members</code>, <code>shares</code>, <code>share_grants</code>, trigger <code>shares_vault_kind_chk</code>, <code>config_profiles</code>, <code>config_assignments</code>.</li><li><code>internal/groups</code>: CRUD (endpoint admin in M5; in M4 API interna + <code>GET /me/groups</code>), <code>GET /directory/users|groups?q=</code> (campi minimi).</li></ul><h3 id="m4-wp2-sharing-e-acl" tabindex="-1">M4-WP2 Sharing e ACL <a class="header-anchor" href="#m4-wp2-sharing-e-acl" aria-label="Permalink to &quot;M4-WP2 Sharing e ACL&quot;">​</a></h3><ul><li><code>internal/sharing</code>: <code>POST /shares</code> (solo <code>kind=shared</code> → <code>409 VAULT_ENCRYPTED</code>), <code>GET/PATCH/DELETE /shares/{id}</code>, grant <code>PUT/DELETE …/grants/{ptype}/{pid}</code>, <code>:accept</code>/<code>:decline</code>, <code>GET /shares?scope=</code>, <code>GET /shared-with-me</code> (mount + <code>scope</code>), scadenza/revoca.</li><li><code>Evaluator.Effective(user, vault, path) Permission</code> (§3.3.2: private → solo owner; owner; grant accettati utente+gruppi su share attivi il cui scope copre il path; massimo), cache per richiesta, invalidazione su modifica share/gruppi.</li><li>Enforcement in <code>sync</code> (changes/blob/commit): <code>scope=share:{id}</code> filtra per prefisso/ACL e trasforma uscita/entrata dal prefisso in <code>delete</code>/<code>create</code>; path relativi alla radice dello share; <code>editor</code> vincolato al prefisso (<code>FORBIDDEN</code>); <code>move_prefix</code> aggiorna <code>shares.path_prefix</code>; <code>SHARE_ROOT_MOVE</code>; <code>404</code> per risorse non autorizzate.</li><li>Eventi <code>ShareChanged</code> (granted/revoked/updated) e <code>VaultChanged</code> ai destinatari.</li><li>Audit per share/grant. Test integrazione ACL (matrice §3.3.2) e scope.</li></ul><h3 id="m4-wp3-config-profile-cloud" tabindex="-1">M4-WP3 Config Profile (cloud) <a class="header-anchor" href="#m4-wp3-config-profile-cloud" aria-label="Permalink to &quot;M4-WP3 Config Profile (cloud)&quot;">​</a></h3><ul><li><code>internal/configprofiles</code>: JSON Schema (<code>api/config-profile.schema.json</code>: feature flag, default editor/aspetto, hotkey, intervallo sync, limite allegati, daily notes, template library, server list), merge effettiva (default prodotto → globale → gruppi per priorità → override utente non <code>locked</code>), <code>GET /config/effective</code> con <code>ETag</code>/<code>If-None-Match</code>, evento <code>ConfigChanged</code>; versioning e rollback (API admin in M5).</li></ul><h3 id="m4-wp4-desktop-mount-condivisione-config" tabindex="-1">M4-WP4 Desktop: mount, condivisione, config <a class="header-anchor" href="#m4-wp4-desktop-mount-condivisione-config" aria-label="Permalink to &quot;M4-WP4 Desktop: mount, condivisione, config&quot;">​</a></h3><ul><li><code>sync/scope.go</code>: mount come vault separato (dir locale <code>&lt;data&gt;/mounts/&lt;share_id&gt;/</code>, <code>sync.db</code> dedicato, cursor per scope), smontaggio su revoca (opzione &quot;mantieni copia scollegata&quot;), mount virtuale &quot;Condivisi con me&quot; per documenti singoli.</li><li>UI: inviti (accetta/rifiuta), dialog &quot;Condividi&quot; (cartella/documento, ricerca utenti/gruppi, livello), elenco condivisioni (mie/con me), badge permesso, read-only per <code>viewer</code> (editor, Excalidraw, canvas).</li><li><code>internal/config</code> + <code>internal/features</code>: scarica config effettiva (ETag, cache offline), applica <code>locked</code> (UI disabilitata con &quot;gestita dall&#39;amministratore&quot;), feature flag che nascondono funzioni; libreria template di gruppo come mount read-only (in M4 solo il montaggio; il consumo dei template arriva con <code>templates</code> in M6-WP3).</li><li>Merge multi-utente: policy &quot;autori diversi e non <code>.md</code> → conflict copy&quot; attiva in <code>resolve.go</code>.</li></ul><h3 id="m4-wp5-web-ui-—-base-e-area-utente" tabindex="-1">M4-WP5 Web UI — base e area utente <a class="header-anchor" href="#m4-wp5-web-ui-—-base-e-area-utente" aria-label="Permalink to &quot;M4-WP5 Web UI — base e area utente&quot;">​</a></h3><ul><li><code>web/</code>: Vite + React, <code>oidc-client-ts</code> PKCE (<code>clarae-web</code>), guardie di ruolo, <code>packages/api-client</code>, <code>packages/ui</code> (design system: tokens, tabelle, form, barra quota).</li><li>Route utente: Spazio utilizzato (<code>/me/usage</code>), I miei vault (tipo, dimensione, file, ultimo sync), Dispositivi, Condivisioni. Download ZIP rinviato a M5.</li><li><code>services/cloud/web-embed</code> con <code>go:embed</code> + fallback SPA; CSP rigida e SRI.</li></ul><blockquote><p><strong>Stato (2026-10-24):</strong> implementato (<a href="./web-ui.html">docs/web-ui.md</a>). Verificati: lint/typecheck/vitest (web, ui), e2e Playwright su API mockata, test Go di <code>web-embed</code>, build di produzione con SRI. Non verificato: login reale contro Keycloak e immagine Docker con la SPA (stack locale non avviabile in questa sessione).</p></blockquote><p><strong>Criteri di uscita M4:</strong> utente A condivide una cartella con un gruppo; B (membro) accetta, vede il mount, modifica (editor) e A riceve; <code>viewer</code> non può scrivere (server e UI); revoca → smontaggio; config profile con chiave <code>locked</code> bloccata nella UI del client; Web UI utente funzionante.</p><hr><h2 id="_10-m5-—-console-admin-ed-export-esito-governance-completa" tabindex="-1">10. M5 — Console admin ed export (esito: governance completa) <a class="header-anchor" href="#_10-m5-—-console-admin-ed-export-esito-governance-completa" aria-label="Permalink to &quot;10. M5 — Console admin ed export (esito: governance completa)&quot;">​</a></h2><blockquote><p><strong>Stato (2026-10-24):</strong> WP1 e WP2 implementati lato cloud e desktop (<a href="./adr/0012-admin-export-details.html">ADR-0012</a>); verificati in locale: integrazione del cloud (admin, sospensione immediata, quota, profili con cronologia, audit, export diretto e a job), client Keycloak anche contro il Keycloak reale del dev stack (<code>KC_LIVE_URL</code>), comando desktop con test. WP3 e WP4 web: vedi sotto. Resta la checklist manuale (<code>docs/qa/m5-admin-export.md</code>).</p></blockquote><h3 id="m5-wp1-api-admin-cloud" tabindex="-1">M5-WP1 API admin (cloud) <a class="header-anchor" href="#m5-wp1-api-admin-cloud" aria-label="Permalink to &quot;M5-WP1 API admin (cloud)&quot;">​</a></h3><ul><li><code>internal/keycloak</code>: client Admin REST (service account, token caching, rotazione segreto), <code>CreateUser</code> con required actions, <code>SetEnabled</code>, <code>LogoutUser</code> (revoca sessioni), <code>GetUserSessions</code>, <code>ResetPassword</code> action, <code>SetRealmRole</code>; test con testcontainers Keycloak.</li><li><code>internal/users</code> admin: <code>/admin/users</code> (lista paginata con filtri), CRUD, <code>:suspend</code>/<code>:activate</code> (Keycloak + <code>users.status</code>), <code>/role</code>, <code>/quota</code> (<code>null</code>=default, <code>-1</code>=illimitata), <code>:reset-password</code>, <code>/vaults</code> (solo metadati), <code>/config/effective</code>.</li><li><code>/admin/groups…</code> (membri, ruolo, config-profiles con priorità), <code>/admin/config-profiles…</code> (incrementa <code>version</code>, cronologia in tabella <code>config_profile_versions</code> — migrazione <code>0005_admin.sql</code>), <code>/admin/settings/storage</code>, <code>/admin/storage/overview</code>, <code>/admin/audit-log</code> (+ export CSV).</li><li>Ogni mutazione → <code>audit_log</code>. Eventi <code>AccountChanged</code> (sospensione, quota).</li></ul><h3 id="m5-wp2-export-zip-cloud" tabindex="-1">M5-WP2 Export ZIP (cloud) <a class="header-anchor" href="#m5-wp2-export-zip-cloud" aria-label="Permalink to &quot;M5-WP2 Export ZIP (cloud)&quot;">​</a></h3><ul><li>Migrazione <code>export_jobs</code>; <code>internal/exports</code>: <code>GET /vaults/{vid}/export.zip</code> streaming (<code>archive/zip</code> con <code>Store</code> per i blob, soglia 512 MB), <code>POST /vaults/{vid}/exports</code> → job (worker) che scrive ZIP su S3 e <code>download_url</code> presigned 24 h; <code>409 VAULT_ENCRYPTED</code> per i privati; esclusione <code>.clarae/</code> device-specific; job <code>expired</code>.</li></ul><h3 id="m5-wp3-web-ui-admin" tabindex="-1">M5-WP3 Web UI admin <a class="header-anchor" href="#m5-wp3-web-ui-admin" aria-label="Permalink to &quot;M5-WP3 Web UI admin&quot;">​</a></h3><ul><li>Route admin: Dashboard storage (totali, top consumer, soglie, trend), Limiti di archiviazione (default globale, override per utente, azioni in blocco), Utenti (tabella, creazione, sospensione, ruolo, reset password, eliminazione, dettaglio con vault/dispositivi/sessioni), Gruppi (CRUD, membri, profili con priorità), Config Profile (editor JSON con validazione schema, anteprima effettiva per utente, cronologia, rollback), Audit log (filtri, CSV).</li><li>WCAG 2.1 AA: navigazione tastiera, label, contrasto (audit in M7).</li></ul><h3 id="m5-wp4-download-zip-utente-e-vaultcrypto-web" tabindex="-1">M5-WP4 Download ZIP utente e <code>vaultcrypto-web</code> <a class="header-anchor" href="#m5-wp4-download-zip-utente-e-vaultcrypto-web" aria-label="Permalink to &quot;M5-WP4 Download ZIP utente e `vaultcrypto-web`&quot;">​</a></h3><ul><li><code>packages/vaultcrypto-web</code>: porting TS del formato §3.8.3 (WebCrypto AES-GCM/HKDF/HMAC, <code>hash-wasm</code> Argon2id), verifica test vector condivisi in CI (Vitest).</li><li>Web UI: vault condiviso → download diretto o job asincrono; vault privato → <code>GET /key-envelopes</code> → passphrase/recovery key nel browser → <code>tree</code> + blob cifrati → decifratura e ZIP in streaming (<code>client-zip</code>/<code>fflate</code> + File System Access API o download stream), avviso &quot;per vault grandi usa il client desktop&quot;.</li><li>Desktop: comando &quot;Esporta vault come ZIP&quot;.</li></ul><p><strong>Criteri di uscita M5:</strong> admin crea un utente (compare in Keycloak), lo sospende (accesso decade entro 30 s anche con token valido), imposta quota (scrittura bloccata a 100 %), assegna profilo a gruppo, legge audit; utente scarica ZIP di un vault condiviso e di uno privato (decifrato nel browser) e i contenuti coincidono con il vault locale.</p><hr><h2 id="_11-m6-—-p1-residui-esito-parita-1-0" tabindex="-1">11. M6 — P1 residui (esito: parità 1.0) <a class="header-anchor" href="#_11-m6-—-p1-residui-esito-parita-1-0" aria-label="Permalink to &quot;11. M6 — P1 residui (esito: parità 1.0)&quot;">​</a></h2><blockquote><p><strong>Stato (2026-10-24):</strong> WP1–WP6 implementati (ADR-0013…0019: grafo, Bases, daily/template/composer, bookmarks/workspaces/preview, importer, history, query/export). Verificati in locale: unit Go con <code>-race</code> e lint, Vitest (290 test), Playwright su mock; benchmark grafo e Bases in <code>docs/qa/m6-graph-benchmark.md</code> e ADR-0014. <strong>Non verificato su webview reale</strong> (hover, stampa PDF, selettori nativi, 30 fps del grafo in WKWebView/WebView2/WebKitGTK): checklist manuale in <code>docs/qa/parita-funzionale-m1.md</code> (sezione M6) e <code>docs/qa/m6-search-export.md</code>. Lacune dichiarate: importer Keep HTML e Apple Notes (P2), &quot;applica template a ogni nuova nota&quot;, <code>pre-sync-overwrite</code> della history non collegato alla sync.</p></blockquote><h3 id="m6-wp1-graph-view" tabindex="-1">M6-WP1 Graph view <a class="header-anchor" href="#m6-wp1-graph-view" aria-label="Permalink to &quot;M6-WP1 Graph view&quot;">​</a></h3><ul><li><code>internal/graph</code>: nodi/archi dall&#39;indice (note, fantasma, allegati opzionali, tag opzionali), filtri (query di ricerca, tag, cartelle, orfani), dati per timelapse (ctime).</li><li>Frontend <code>graph/</code>: rendering WebGL (<code>pixi.js</code> o canvas 2D con fallback), layout force-directed in Web Worker (<code>d3-force</code>), grafo globale e locale (profondità), gruppi colore per query, forze regolabili, hover/click apre nota; obiettivo 10k nodi ≥ 30 fps.</li></ul><h3 id="m6-wp2-bases" tabindex="-1">M6-WP2 Bases <a class="header-anchor" href="#m6-wp2-bases" aria-label="Permalink to &quot;M6-WP2 Bases&quot;">​</a></h3><ul><li><code>internal/bases</code>: parser <code>.base</code> (YAML: viste, filtri, formule, ordinamento), motore di query sulle <code>properties</code> indicizzate, valutatore di formule (sottoinsieme: aritmetica, stringhe, date, <code>if</code>, funzioni su liste), binding <code>BasesAPI</code>.</li><li>Frontend <code>bases/</code>: viste tabella (edit inline delle properties) e card, selettore vista, filtri UI, embed <code>![[x.base]]</code>.</li></ul><h3 id="m6-wp3-daily-notes-unique-notes-template-composer-bookmarks-workspaces" tabindex="-1">M6-WP3 Daily notes, unique notes, template, composer, bookmarks, workspaces <a class="header-anchor" href="#m6-wp3-daily-notes-unique-notes-template-composer-bookmarks-workspaces" aria-label="Permalink to &quot;M6-WP3 Daily notes, unique notes, template, composer, bookmarks, workspaces&quot;">​</a></h3><ul><li><code>internal/templates</code>: variabili <code>{{date:FORMAT}}</code>, <code>{{time}}</code>, <code>{{title}}</code>, cartella template (anche mount di gruppo), daily notes (formato, cartella, template, &quot;apri oggi&quot;, navigazione giorni), unique note creator (prefisso timestamp).</li><li><code>internal/composer</code>: unisci note (append + redirect link), estrai selezione in nuova nota (sostituisce con link).</li><li>Bookmarks (<code>.clarae/bookmarks.json</code>, gruppi, nota/heading/block/ricerca/grafo) con vista sidebar; Workspaces (layout salvati <code>.clarae/workspaces.json</code>).</li><li>Slash commands <code>/</code> nell&#39;editor (riusa il registro comandi); Random note; Page preview (hover con render reading in popover).</li></ul><h3 id="m6-wp4-importer" tabindex="-1">M6-WP4 Importer <a class="header-anchor" href="#m6-wp4-importer" aria-label="Permalink to &quot;M6-WP4 Importer&quot;">​</a></h3><ul><li><code>internal/importer</code>: interfaccia <code>Importer{Detect, Preview, Run}</code> + report; sorgenti: cartella Markdown/HTML (con riscrittura link), Evernote ENEX, Notion (export zip), Roam (JSON), Bear, Google Keep (Takeout), CSV→note; Apple Notes rinviato a P2. UI wizard con anteprima e report.</li></ul><h3 id="m6-wp5-history-locale-e-recovery" tabindex="-1">M6-WP5 History locale e recovery <a class="header-anchor" href="#m6-wp5-history-locale-e-recovery" aria-label="Permalink to &quot;M6-WP5 History locale e recovery&quot;">​</a></h3><ul><li><code>internal/history</code>: snapshot in <code>.clarae/snapshots/</code> ogni 5 min se modificato, retention 7 gg (configurabile), UI &quot;File recovery&quot; (lista, diff, ripristino); integrazione con cronologia cloud (M2) in un&#39;unica vista.</li></ul><h3 id="m6-wp6-embedded-search-export-varie" tabindex="-1">M6-WP6 Embedded search, export, varie <a class="header-anchor" href="#m6-wp6-embedded-search-export-varie" aria-label="Permalink to &quot;M6-WP6 Embedded search, export, varie&quot;">​</a></h3><ul><li>Code block <code>query</code> renderizzato in Live Preview/Reading con risultati live; export PDF (stampa webview con stile reading) e HTML autonomo; impostazioni rimanenti (cestino, cartella allegati, daily notes).</li></ul><p><strong>Criteri di uscita M6:</strong> tutte le righe P1 della matrice §2.2.1 implementate; checklist parità aggiornata; benchmark grafo.</p><hr><h2 id="_12-m7-—-hardening-e-rilascio-1-0" tabindex="-1">12. M7 — Hardening e rilascio 1.0 <a class="header-anchor" href="#_12-m7-—-hardening-e-rilascio-1-0" aria-label="Permalink to &quot;12. M7 — Hardening e rilascio 1.0&quot;">​</a></h2><blockquote><p><strong>Stato (2026-10-27):</strong> WP1–WP4 implementati e verificati in locale (ADR-0020…0023): benchmark e ottimizzazioni (indice 50k ≈ 73 s, ricerca con cache), documenti per audit crittografico e pen test, GDPR (<code>GET /me/export</code>, <code>DELETE /me</code>, purge), scansioni in CI, resilienza (fault injection, drain, prova di ripristino con PITR, chaos sul chart), updater firmato, installer, pipeline di release, chart completo, compose on-premise, accessibilità (axe), i18n, guide utente e admin, dashboard Grafana. <strong>WP5 (release) non è completabile da qui</strong>: firma e notarizzazione, audit e pen test esterni, test manuale cross-OS con screen reader, misure su webview e infrastruttura reali, rebrand e tag. Tutto ciò che resta è in <code>docs/release/v1.0.0-checklist.md</code>; il codice è la candidata <code>1.0.0-rc.1</code> (<code>CHANGELOG.md</code>).</p></blockquote><h3 id="m7-wp1-prestazioni" tabindex="-1">M7-WP1 Prestazioni <a class="header-anchor" href="#m7-wp1-prestazioni" aria-label="Permalink to &quot;M7-WP1 Prestazioni&quot;">​</a></h3><ul><li>Dataset sintetici (50k note, 10k nodi grafo) in CI nightly; benchmark avvio &lt; 3 s, apertura nota &lt; 150 ms, ricerca &lt; 200 ms, indice 50k &lt; 3 min; profiling Go/React; k6 su cloud (1.000 utenti attivi simulati: <code>changes</code>/<code>commit</code>).</li></ul><h3 id="m7-wp2-sicurezza-e-privacy" tabindex="-1">M7-WP2 Sicurezza e privacy <a class="header-anchor" href="#m7-wp2-sicurezza-e-privacy" aria-label="Permalink to &quot;M7-WP2 Sicurezza e privacy&quot;">​</a></h3><ul><li>Pacchetto per audit esterno del design cripto (<code>docs/security/crypto-design.md</code>, test vector, threat model §3.8.1); preparazione pen test (<code>docs/security/pentest-scope.md</code>); CSP/SRI verificati; <code>govulncheck</code>, <code>yarn npm audit</code>, SBOM (syft) in CI; GDPR: <code>GET /me/export</code> (dati account) e cancellazione account con purge (<code>DELETE /me</code> con conferma, job purge) — endpoint non in §3.5, ADR + proposta spec; retention documentata.</li></ul><h3 id="m7-wp2b-resilienza-appendice-a-disponibilita-e-affidabilita-dati" tabindex="-1">M7-WP2b Resilienza (Appendice A: disponibilità e affidabilità dati) <a class="header-anchor" href="#m7-wp2b-resilienza-appendice-a-disponibilita-e-affidabilita-dati" aria-label="Permalink to &quot;M7-WP2b Resilienza (Appendice A: disponibilità e affidabilità dati)&quot;">​</a></h3><ul><li>Fault injection: kill del cloud a metà <code>commit</code> (nessuna revisione parziale, client riprova con idempotenza), crash del client durante <code>WriteAtomic</code> (nessun file parziale), interruzione upload tus e ripresa, perdita di rete durante pull (cursor non avanza), restart PG/MinIO (readiness, backoff).</li><li>Chaos test base sul chart Helm (pod kill, restart rolling) con misura dell&#39;SLO 99,9 % su finestra di test; runbook backup/PITR PG e versioning bucket provati con un restore reale e documentati (<code>docs/runbook/backup-restore.md</code>).</li></ul><h3 id="m7-wp3-distribuzione-e-aggiornamenti" tabindex="-1">M7-WP3 Distribuzione e aggiornamenti <a class="header-anchor" href="#m7-wp3-distribuzione-e-aggiornamenti" aria-label="Permalink to &quot;M7-WP3 Distribuzione e aggiornamenti&quot;">​</a></h3><ul><li><code>internal/updater</code>: canale di update firmato (manifest JSON firmato ed25519, verifica firma, download, applicazione per OS), UI &quot;Aggiornamento disponibile&quot;.</li><li>Installer: NSIS (Windows, firma Authenticode), <code>.dmg</code> notarizzato (macOS), AppImage + <code>.deb</code> (Linux, <code>.desktop</code> con <code>x-scheme-handler/clarae</code>); pipeline release con tag semver; immagini OCI firmate (cosign) + Helm chart completo (HPA, PDB, secret, ingress gRPC/HTTP2) e <code>compose</code> per on-premise.</li></ul><h3 id="m7-wp4-accessibilita-i18n-documentazione" tabindex="-1">M7-WP4 Accessibilità, i18n, documentazione <a class="header-anchor" href="#m7-wp4-accessibilita-i18n-documentazione" aria-label="Permalink to &quot;M7-WP4 Accessibilità, i18n, documentazione&quot;">​</a></h3><ul><li>Audit WCAG 2.1 AA Web UI (axe in Playwright), navigazione tastiera/screen reader del client; revisione traduzioni it/en.</li><li>Docs: guida utente, guida amministratore (installazione, Keycloak, backup/PITR, runbook incidenti, osservabilità con dashboard Grafana), <code>docs/adr/</code> completo, rebrand del nome (eseguito: Clarae notanda).</li></ul><h3 id="m7-wp5-release" tabindex="-1">M7-WP5 Release <a class="header-anchor" href="#m7-wp5-release" aria-label="Permalink to &quot;M7-WP5 Release&quot;">​</a></h3><ul><li>Release candidate, test manuale cross-OS da checklist, fix, tag <code>v1.0.0</code>.</li></ul><p><strong>Post-1.0 (P2, fuori piano):</strong> Audio recorder, Web viewer, Vim mode, CLI, finestre pop-out (processo secondario + IPC), rotazione VMK, Apple Notes importer, format converter. Slides è stato anticipato in M8 (ADR-0027).</p><hr><h2 id="_13-m8-—-revisione-ui-shell-desktop-esito-shell-conforme-al-mockup-28-10-2026" tabindex="-1">13. M8 — Revisione UI shell desktop (esito: shell conforme al mockup 28/10/2026) <a class="header-anchor" href="#_13-m8-—-revisione-ui-shell-desktop-esito-shell-conforme-al-mockup-28-10-2026" aria-label="Permalink to &quot;13. M8 — Revisione UI shell desktop (esito: shell conforme al mockup 28/10/2026)&quot;">​</a></h2><blockquote><p><strong>Stato (2026-10-29):</strong> WP0–WP10 implementati e verificati in locale (<code>task test</code>, lint Go e TS, e2e su mock Wails, build, conformance Go e TS): milestone chiusa lato codice. Restano le verifiche manuali su webview e cloud reali di <code>docs/qa/m8-shell-ui.md</code> e l&#39;aggiornamento dello spec da parte dell&#39;owner (ADR-0026 e ADR-0027 in stato <em>proposta</em>; accettati e recepiti in <code>Specifications.md</code> v1.4, 2026-11-02). In WP2 la tab bar resta per pane (sotto l&#39;header) e non nell&#39;header, perché con gli split ogni pane ha le proprie tab. La tab «Segnalibri» del mockup si chiama <em>Link</em> (link in uscita, backlink e bookmark del vault); <em>Statistiche</em> è completa (WP7) e <em>Slide</em> è completa (WP8). Gli indicatori di stato (permessi, aggiornamenti, sync, inviti, indicizzazione) stanno nel footer della sidebar destra e, a sidebar chiusa, nell&#39;header. <code>note:export-image</code> non è verificato su una webview reale (WKWebView può marcare come «tainted» il canvas con <code>foreignObject</code>): voce da aggiungere a <code>docs/qa/m8-shell-ui.md</code>. Pianificata il 2026-10-28. ADR-0026 (shell) e ADR-0027 (Slides) deviavano dallo spec (<code>statusbar</code>, <code>sidebar/</code>, Slides da P2 a P1): accettati e recepiti in <code>Specifications.md</code> v1.4 (2026-11-02). Piano di dettaglio: <code>.claude/roadmap/progetta-e-pianifica-la-staged-dragon.md</code>. Solo frontend desktop, più un binding Go per le statistiche (WP7).</p></blockquote><p>Ordine: WP0 → WP1 → (WP2 ∥ WP3 ∥ WP4) → WP5 → (WP6 ∥ WP7) → WP8 → WP9 → WP10.</p><h3 id="m8-wp0-adr-e-documenti" tabindex="-1">M8-WP0 ADR e documenti <a class="header-anchor" href="#m8-wp0-adr-e-documenti" aria-label="Permalink to &quot;M8-WP0 ADR e documenti&quot;">​</a></h3><ul><li>ADR-0026 e ADR-0027; indice ADR; questa sezione di roadmap. <code>Specifications.md</code> non si modifica: le modifiche si propongono all&#39;owner.</li></ul><h3 id="m8-wp1-scomposizione-della-shell" tabindex="-1">M8-WP1 Scomposizione della shell <a class="header-anchor" href="#m8-wp1-scomposizione-della-shell" aria-label="Permalink to &quot;M8-WP1 Scomposizione della shell&quot;">​</a></h3><ul><li>Estrazione da <code>app/App.tsx</code> in <code>src/shell/</code> di <code>Header</code>, <code>LeftSidebar</code>, <code>RightSidebar</code>, <code>SidebarTabs</code>, <code>SidebarResizer</code>, <code>StatusBar</code> e <code>useVaultSession</code>, senza cambi funzionali né di DOM/CSS; <code>App.test.tsx</code>, <code>a11y.spec.ts</code> e <code>keyboard.spec.ts</code> restano verdi.</li></ul><h3 id="m8-wp2-header-e-tema" tabindex="-1">M8-WP2 Header e tema <a class="header-anchor" href="#m8-wp2-header-e-tema" aria-label="Permalink to &quot;M8-WP2 Header e tema&quot;">​</a></h3><ul><li>Pulsanti sidebar sinistra/destra e ricerca; tab bar nell&#39;header; switch chiaro/scuro (<code>theme:toggle</code>); set di icone SVG locali al posto dei glifi unicode.</li></ul><h3 id="m8-wp3-ribbon-comandi-rapidi" tabindex="-1">M8-WP3 Ribbon comandi rapidi <a class="header-anchor" href="#m8-wp3-ribbon-comandi-rapidi" aria-label="Permalink to &quot;M8-WP3 Ribbon comandi rapidi&quot;">​</a></h3><ul><li>Barra verticale: nuova cartella, nota, lavagna, disegno, base, separatore, esporta PDF, esporta immagine; nuovi comandi <code>folder:new</code>, <code>separator:insert</code>, <code>note:export-image</code>.</li></ul><h3 id="m8-wp4-sidebar-sinistra" tabindex="-1">M8-WP4 Sidebar sinistra <a class="header-anchor" href="#m8-wp4-sidebar-sinistra" aria-label="Permalink to &quot;M8-WP4 Sidebar sinistra&quot;">​</a></h3><ul><li>Tab <em>File</em> e <em>Struttura</em>; mappatura retrocompatibile dei valori legacy in <code>workspace.json</code>.</li></ul><h3 id="m8-wp5-sidebar-destra-e-footer-di-sync" tabindex="-1">M8-WP5 Sidebar destra e footer di sync <a class="header-anchor" href="#m8-wp5-sidebar-destra-e-footer-di-sync" aria-label="Permalink to &quot;M8-WP5 Sidebar destra e footer di sync&quot;">​</a></h3><ul><li>Tab <em>Proprietà</em>, <em>Tag</em>, <em>Segnalibri</em> (link, backlink, bookmark), <em>ShowSlide</em>, <em>Statistiche</em>; <code>SyncFooter</code> con stato di sync, permessi, aggiornamenti e inviti; eliminazione della status bar.</li></ul><h3 id="m8-wp6-tab-blocco-e-menu-contestuale" tabindex="-1">M8-WP6 Tab: blocco e menu contestuale <a class="header-anchor" href="#m8-wp6-tab-blocco-e-menu-contestuale" aria-label="Permalink to &quot;M8-WP6 Tab: blocco e menu contestuale&quot;">​</a></h3><ul><li><code>Tab.pinned</code> (opzionale) in <code>workspace/layout.ts</code> con <code>parseNode</code> retrocompatibile. Una tab bloccata non si chiude con nessuna azione dell&#39;utente (✕, click centrale, <code>Delete</code>, <code>tab:close</code>, chiusure di massa) e non viene sostituita dalla navigazione (la nota si apre in una tab nuova); si chiude solo se il suo file viene eliminato (<code>closeTab(…, { force: true })</code> in <code>removePath</code>). Le chiusure di massa operano sul pane della tab e non hanno conferma: il blocco è la protezione.</li><li>Menu contestuale: Blocca/Sblocca, Chiudi, Chiudi a destra, Chiudi a sinistra, Chiudi altre, Chiudi tutte (disabilitate se non chiuderebbero nulla), più le voci già presenti; comandi <code>tab:pin</code>, <code>tab:close-right|left|others|all</code>.</li></ul><h3 id="m8-wp7-pannello-statistiche" tabindex="-1">M8-WP7 Pannello Statistiche <a class="header-anchor" href="#m8-wp7-pannello-statistiche" aria-label="Permalink to &quot;M8-WP7 Pannello Statistiche&quot;">​</a></h3><ul><li>Il pannello compone dati già esposti dai binding esistenti, quindi <strong>non serve un nuovo binding Go</strong> (scostamento dal piano iniziale): dimensione e ultima modifica dalla lista file; versioni locali (<code>HistoryAPI.List</code>) e cloud (<code>SyncAPI.History</code>); autore dell&#39;ultima revisione cloud (nome da <code>Mine</code> o dai destinatari della condivisione); destinatari (<code>SharingAPI.VaultShares</code>, filtrati per le condivisioni che coprono la nota), oppure «condiviso da» su un mount e «vault privato» su un vault E2EE; parole, caratteri e titoli dal testo (frontmatter escluso), più cursore e selezione dell&#39;editor. Calcoli puri in <code>sidebar/noteStats.ts</code>.</li><li>Data di creazione: come per il grafo (ADR-0013), proprietà <code>created</code> del frontmatter, altrimenti la prima revisione cloud, altrimenti l&#39;ultima modifica (segnalata con «≈»): il file system non dà un tempo di creazione portabile e una copia sincronizzata mostrerebbe la data del download.</li><li>Sostituisce la vecchia riga di stato dell&#39;editor: le chiavi <code>status.words|chars</code> sono state rimosse.</li></ul><h3 id="m8-wp8-showslide" tabindex="-1">M8-WP8 ShowSlide <a class="header-anchor" href="#m8-wp8-showslide" aria-label="Permalink to &quot;M8-WP8 ShowSlide&quot;">​</a></h3><ul><li>Parser delle slide in TS (<code>packages/markdown/src/slides.ts</code>) e in Go (<code>apps/desktop/internal/parser/slides.go</code>, oggi senza consumatori a runtime) verificati con le stesse fixture <code>shared/conformance/slides/</code> (12 casi: separatori, setext, code fence, math, note, configurazione, slide vuote). Separatore: <code>---</code> dopo una riga vuota; note: righe dopo <code>Note:</code>; configurazione in chiavi piatte <code>slide-transition|theme|progress|numbers|notes</code> (ADR-0027 aggiornato).</li><li>Tab <em>Slide</em>: opzioni scritte nel frontmatter con lo stesso percorso delle Proprietà (disabilitate su vault di sola lettura), pulsanti «Avvia» e «Dalla slide corrente», miniature cliccabili. Presentazione nella stessa finestra (overlay, <code>requestFullscreen</code> dove la webview lo permette): tastiera, transizioni (rispettano <code>prefers-reduced-motion</code>), barra di avanzamento e numeri, vista presentatore con slide successiva, note e timer; comandi <code>slides:start</code> e <code>slides:start-here</code>. Le slide usano la pipeline dell&#39;export (immagini e diagrammi inclusi, nessuna richiesta di rete: verificato in e2e).</li><li>Da verificare su webview reale (checklist <code>docs/qa/m8-shell-ui.md</code>): schermo intero in WKWebView/WebView2/WebKitGTK.</li></ul><h3 id="m8-wp9-footer-sinistro-e-chat" tabindex="-1">M8-WP9 Footer sinistro e chat <a class="header-anchor" href="#m8-wp9-footer-sinistro-e-chat" aria-label="Permalink to &quot;M8-WP9 Footer sinistro e chat&quot;">​</a></h3><ul><li><strong>Selettore vault</strong> in fondo alla sidebar sinistra: nome, numero di note, tipo (privato/condiviso, D-02) e menu con i vault recenti, «Apri un&#39;altra cartella…» e «Chiudi vault»; comando <code>vault:switch</code> (apre la sidebar e il menu). Il cambio (<code>openVaultAt</code> in <code>app/actions.ts</code>) scrive subito note in sospeso e <code>workspace.json</code> del vault che lascia, apre il nuovo, chiude il precedente e azzera lo store solo dopo; riaprire il vault già aperto non fa nulla.</li><li><strong>Impostazioni e account</strong> in fondo al ribbon (visibili anche a sidebar chiusa; senza vault restano nell&#39;header): avatar con le iniziali e menu (account e dispositivi, esci) a sessione attiva, pulsante «Accedi» altrimenti (usa il server già noto o quello predefinito, altrimenti apre le impostazioni cloud; l&#39;OIDC resta nel browser di sistema, D-08), stati «in attesa del browser» e «disconnesso» con «Riconnetti».</li><li><strong>Slot chat ACP</strong> sotto l&#39;editor: campo disabilitato con spiegazione, mostrato solo con la feature <code>chat</code> attiva nel Config Profile; la feature è <strong>spenta per default</strong> (<code>features.Defaults</code> in Go, <code>ProductDefaults</code> e schema del cloud). Nessun codice di protocollo: l&#39;integrazione ACP richiede un ADR dedicato.</li></ul><h3 id="m8-wp10-chiusura-qualita" tabindex="-1">M8-WP10 Chiusura qualità <a class="header-anchor" href="#m8-wp10-chiusura-qualita" aria-label="Permalink to &quot;M8-WP10 Chiusura qualità&quot;">​</a></h3><ul><li>i18n it/en (la parità delle chiavi è un test bloccante), accessibilità: le scansioni axe coprono shell, schede a icona, menu della scheda bloccata e del vault, tab Slide e presentazione (hanno fatto emergere e correggere tre difetti: albero dei segnalibri vuoto, puntina della scheda bloccata dentro la <code>tablist</code>, collisione di classi con la slideshow dei disegni).</li><li>Guida utente: «Il primo vault» riscritto sulla nuova shell, nuovo capitolo «Presentazioni», scorciatoie, accessibilità, condivisione e sincronizzazione senza più la barra di stato; checklist manuale <code>docs/qa/m8-shell-ui.md</code> (export come immagine e schermo intero su webview reali, login OIDC, cloud).</li></ul><p><strong>Criteri di uscita M8:</strong> layout conforme al mockup; comandi del ribbon operativi e presenti in palette; tab bloccabili con menu completo; cambio vault e login/avatar funzionanti; Statistiche e ShowSlide offline; chat visibile ma disabilitata; <code>task ci</code> e <code>task e2e</code> verdi.</p><hr><h2 id="_13-bis-m9-—-workbench-del-vault-nella-web-ui-esito-parita-web-desktop" tabindex="-1">13-bis. M9 — Workbench del vault nella Web UI (esito: parità web/desktop) <a class="header-anchor" href="#_13-bis-m9-—-workbench-del-vault-nella-web-ui-esito-parita-web-desktop" aria-label="Permalink to &quot;13-bis. M9 — Workbench del vault nella Web UI (esito: parità web/desktop)&quot;">​</a></h2><blockquote><p><strong>Stato (2026-11-02):</strong> WP0–WP7 implementati, con i criteri di uscita soddisfatti solo in parte (stato di ogni WP sotto, M9-WP7). ADR-0029 (workbench web, deviazione da A-03) e ADR-0030 (core Go in WASM) accettati dall&#39;owner il 2026-11-02 e recepiti in <code>Specifications.md</code> v1.3 (§1.7, §2.8.3, A-03). Piano di dettaglio: <code>.claude/roadmap/progetta-e-pianifica-gli-glistening-kahan.md</code>.</p></blockquote><p>Decisioni dell&#39;owner:</p><ul><li>la logica del desktop gira nel browser come <strong>core Go compilato in WASM</strong> in un Web Worker, con SQLite-wasm e OPFS;</li><li>i vault privati E2EE sono modificabili anche dal web;</li><li>il web è <strong>online-first con cache locale</strong>, senza PWA.</li></ul><p>Il browser registra un dispositivo <code>web</code> e usa il protocollo di sync esistente: il server resta cieco al contenuto.</p><p>Ordine: WP0 → WP1 (gate go/no-go) → WP2 → WP3 → WP4 → WP5 → WP6 → WP7. WP0 e WP1 possono procedere in parallelo con M10.</p><h3 id="m9-wp0-adr-e-documenti" tabindex="-1">M9-WP0 ADR e documenti <a class="header-anchor" href="#m9-wp0-adr-e-documenti" aria-label="Permalink to &quot;M9-WP0 ADR e documenti&quot;">​</a></h3><ul><li>ADR-0029 e ADR-0030; questa sezione; budget separato del chunk workbench (revisione di ADR-0020); testo proposto per lo spec (A-03, §0.1, §2.8, §4.4, §3.8.1, tabella rischi), che l&#39;owner riporta in <code>Specifications.md</code> (fatto nella v1.3, 2026-11-02).</li></ul><h3 id="m9-wp1-spike-core-wasm-time-boxed" tabindex="-1">M9-WP1 Spike core WASM (time-boxed) <a class="header-anchor" href="#m9-wp1-spike-core-wasm-time-boxed" aria-label="Permalink to &quot;M9-WP1 Spike core WASM (time-boxed)&quot;">​</a></h3><ul><li><code>GOOS=js</code> build di <code>cmd/clarae-core</code> con <code>indexer</code>, <code>search</code>, <code>links</code>, <code>bases</code>, <code>sync</code> e <code>shared/go</code>.</li><li>Driver <code>database/sql</code> su <code>@sqlite.org/sqlite-wasm</code> (<code>opfs-sahpool</code>, FTS5 <code>trigram</code>, migrazioni goose) e VFS OPFS.</li><li>Misure riportate in ADR-0030: dimensione, avvio, indicizzazione 5k note, latenza ricerca, memoria.</li><li>Se un modulo non rientra negli obiettivi, fallback mirato per quel modulo.</li></ul><blockquote><p><strong>Stato (2026-10-29):</strong> spike eseguito <strong>in parte</strong>, con via libera provvisorio (esito in ADR-0030, comandi in <code>docs/perf/wasm-spike.md</code>). Verificato: il core compila per <code>js/wasm</code> (solo <code>modernc.org/sqlite</code> e <code>updater</code> bloccano), 6,4 MB con brotli, SQLite-wasm applica le migrazioni reali con FTS5 <code>trigram</code> (5k note in 1,7 s, ricerca p95 4,4 ms), il parser Go è 4,5× più lento del nativo. <strong>Non verificato</strong>: driver <code>database/sql</code> su sqlite-wasm, VFS OPFS, indicizzazione end-to-end, memoria del core, confronto con il desktop nativo. Questi punti restano in WP2/WP3 e possono ancora cambiare il go/no-go.</p></blockquote><h3 id="m9-wp2-portabilita-del-core-go" tabindex="-1">M9-WP2 Portabilità del core Go <a class="header-anchor" href="#m9-wp2-portabilita-del-core-go" aria-label="Permalink to &quot;M9-WP2 Portabilità del core Go&quot;">​</a></h3><blockquote><p><strong>Stato (2026-10-29):</strong> implementato e provato in Node (ADR-0030, &quot;Esito dell&#39;implementazione&quot;). Tutti i 27 pacchetti di <code>apps/desktop/internal/...</code> passano sotto <code>GOOS=js GOARCH=wasm</code> (<code>task test-wasm</code>, scritto solo in WP3: vedi lì) e il desktop nativo resta verde (<code>go test ./...</code>, <code>golangci-lint</code>). <strong>Deviazione dal piano:</strong> niente interfaccia <code>vfs</code> in Go. Su <code>js</code> il pacchetto <code>os</code> passa da <code>globalThis.fs</code>, che la pagina fornirà sopra OPFS (WP5): evita di migrare circa 60 chiamate in otto pacchetti. <strong>Non verificato:</strong> OPFS e <code>opfs-sahpool</code> in un browser vero, lo stream SSE nel browser, <code>cmd/clarae-core</code> (WP3).</p></blockquote><ul><li>Driver SQL scelto con build tag in <code>internal/store</code>; nuovo <code>internal/sqlitejs</code> (driver <code>database/sql</code> sincrono verso <code>globalThis.__claraeSQLite</code>) e <code>packages/sqlite-bridge</code>; <code>store.Exists</code>/<code>Reset</code> perché i database non stanno nel file system.</li><li>Interfaccia <code>Host</code> in <code>internal/app</code> (<code>internal/shell/host.go</code> per Wails, <code>internal/app/host_native.go</code> e <code>host_web.go</code>); nessun binding importa Wails; <code>isWeb</code> spegne updater, cestino di sistema e watcher.</li><li>Cambi di file senza fsnotify: <code>vault.FS.SetOnChange</code> → <code>watcher.Notify</code>.</li><li>Sessione ospitata in <code>auth</code> (<code>Hosted</code>: token dalla pagina, niente keychain), chiavi dei vault privati in memoria, SSE come canale di notifica (nessun endpoint gRPC annunciato).</li><li><code>SettingsAPI.Info</code> espone <code>platform</code>. Bug trovati dai test su WASM e corretti: <code>sync.ReadMount</code>, colonne <code>TIMESTAMP</code>, <code>updater</code> per <code>js</code>.</li><li>Resta per WP5: blocco per inattività della VMK, shim <code>fs</code> su OPFS, lettura dello stream SSE nel browser.</li><li>Il desktop resta verde a ogni passo.</li></ul><h3 id="m9-wp3-host-rpc-wasm" tabindex="-1">M9-WP3 Host RPC WASM <a class="header-anchor" href="#m9-wp3-host-rpc-wasm" aria-label="Permalink to &quot;M9-WP3 Host RPC WASM&quot;">​</a></h3><blockquote><p><strong>Stato (2026-10-29):</strong> implementato e provato (ADR-0030, &quot;Esito dell&#39;implementazione (M9-WP3)&quot;). <code>internal/rpc</code> (dispatcher con la semantica di Wails), <code>App.Services()</code> come elenco unico dei servizi (usato anche da <code>main.go</code>), <code>cmd/clarae-core</code> con <code>globalThis.__claraeCore</code>, <code>task wasm-core</code> (<strong>6,44 MB con brotli</strong>) e <code>task test-wasm</code>. La parità con <code>wailsjs/go/app/*.d.ts</code> è verificata: 20 servizi, 122 metodi, nessuna eccezione (le funzioni non applicabili al web restano esposte e rispondono con un errore o con lo stato «disattivato»; le nasconde la UI in WP4). <strong>Non verificato:</strong> caricamento in un Web Worker vero. <strong>Correzione:</strong> il target <code>task test-wasm</code>, dato per esistente alla chiusura del WP2, è stato scritto solo ora.</p></blockquote><ul><li><code>cmd/clarae-core</code>: stessi struct dei binding Wails, dispatcher JSON via reflection con la semantica di Wails; gli eventi escono dall&#39;<code>Emit</code> dell&#39;host (<code>__claraeHost.emit</code>), che la pagina inoltra con <code>postMessage</code>.</li><li>Test che ogni metodo di <code>wailsjs/go/app/*.d.ts</code> sia esposto (si salta se i binding non sono generati).</li></ul><h3 id="m9-wp4-frontend-condiviso-packages-workbench" tabindex="-1">M9-WP4 Frontend condiviso <code>packages/workbench</code> <a class="header-anchor" href="#m9-wp4-frontend-condiviso-packages-workbench" aria-label="Permalink to &quot;M9-WP4 Frontend condiviso `packages/workbench`&quot;">​</a></h3><blockquote><p><strong>Stato (2026-10-29):</strong> implementato e verificato (ADR-0029, ADR-0030). Verificati: typecheck dei due pacchetti, 562 test unitari del workbench (554 prima dello spostamento + 8 nuovi), build di produzione (iniziale 1962 kB su 2000 di budget), e2e Playwright del desktop (104 passati, 3 saltati) e della build minificata (42), <code>wails generate module</code> (binding identici, ora in <code>packages/workbench/wailsjs</code>) e <code>task build-desktop</code>. <strong>Non verificato:</strong> il workbench in un browser vero (WP5) e in modalità <code>web</code> dentro Playwright (WP7): la modalità <code>web</code> è coperta solo da test unitari.</p></blockquote><ul><li><code>apps/desktop/frontend/src</code> è ora <code>packages/workbench/src</code> (<code>@clarae/workbench</code>, spostato con <code>git mv</code>: cronologia conservata); <code>wailsjsdir</code> punta a <code>packages/workbench</code>. <code>apps/desktop/frontend</code> ha solo <code>src/main.tsx</code> (chiama <code>mountWorkbench</code>), <code>index.html</code>, lo script di build e gli e2e.</li><li><code>mountWorkbench(root, { kind, onBackToConsole })</code>: l&#39;host dice di che tipo è. <code>kind</code> (<code>desktop</code> per default, <code>web</code>) imposta le capability.</li><li><strong>Build condivisa:</strong> <code>@clarae/workbench/build</code> (<code>packages/workbench/build/esbuild.mjs</code>) esporta plugin, loader, alias e la copia degli asset di Excalidraw; il frontend desktop ci aggiunge entry, HTML, dev server e budget. In WP5 lo userà anche la Web UI.</li><li><strong>Tipi:</strong> <code>workbench</code> e <code>desktop-frontend</code> si controllano ciascuno con il proprio <code>tsc -b</code>; il desktop vede solo la firma pubblica del workbench (<code>src/workbench.d.ts</code>) e non ricompila i sorgenti.</li><li><strong>Capability</strong> (<code>platform/</code>): <code>localFolders</code>, <code>updater</code>, <code>diskEncryptionCheck</code>, <code>nativeWindow</code>. Sul web: niente &quot;Apri cartella&quot; (schermata iniziale, menu del vault), niente sorgenti d&#39;importazione che richiedono una cartella, niente aggiornamenti (dialogo, indicatore, impostazioni, comando), niente avviso sul disco; i link esterni si aprono in una nuova scheda con <code>noopener</code>; lo schermo intero usa solo la Fullscreen API; &quot;Torna alla console&quot; compare nell&#39;intestazione e nella schermata iniziale se l&#39;host lo fornisce.</li><li><strong>Scostamento dal piano:</strong> i dialoghi nativi (salvataggio, stampa, scelta di un file) <strong>non</strong> hanno una sostituzione nel frontend. Passano dai binding Go, e l&#39;<code>Host</code> web (WP2) li trasforma in download, <code>window.print()</code> e selettore di file: la UI non cambia. Resta aperta la scelta di una cartella per l&#39;importer (<code>localFolders</code> falso: sorgenti a cartella nascoste); si potrà riattivare con <code>showDirectoryPicker</code> in WP5.</li></ul><h3 id="m9-wp5-integrazione-in-web" tabindex="-1">M9-WP5 Integrazione in <code>web/</code> <a class="header-anchor" href="#m9-wp5-integrazione-in-web" aria-label="Permalink to &quot;M9-WP5 Integrazione in `web/`&quot;">​</a></h3><blockquote><p><strong>Stato (2026-10-29):</strong> implementato e verificato in un Chromium vero (ADR-0029/0030, <code>docs/web-ui.md</code>). Verificati: lo shim <code>fs</code> su OPFS (9 test in un worker vero), il workbench con il <strong>core WASM reale</strong> (10 test: scrittura, ricerca FTS5 su SQLite <code>opfs-sahpool</code>, backlink, rinomina con riscrittura dei link, storia locale, download dello ZIP, grafo, persistenza al reload, blocco + cancellazione della copia, una scheda sola), la build minificata servita dall&#39;handler Go di produzione con la sua CSP (nessuna violazione, nessuna richiesta esterna, WASM in gzip), 16 test unitari di bridge e inattività, test Go di <code>web-embed</code>, e un&#39;immagine Docker completa (114 MB). Budget: console 611/1000 kB, workbench 2416/2500 kB iniziale e 12774/23000 kB totale, core 7841 kB gzip (limite 8192). <strong>Non verificato:</strong> il flusso con un cloud vero (login OIDC, <code>LinkExisting</code>, sync web ↔ desktop, vault privato con passphrase), l&#39;apertura di un mount (<code>?share=</code>), e Safari/Firefox (solo Chromium).</p></blockquote><p><strong>Deviazioni dal piano</strong> (da confermare):</p><ul><li><p>Il workbench è una <strong>pagina a sé</strong> (<code>workbench.html</code>), non una route lazy della SPA: l&#39;esbuild non separa il CSS dei chunk dinamici e lo stile globale della UI desktop avrebbe toccato la console. Il server la serve per <code>/vaults/:id/open</code> con una CSP dedicata.</p></li><li><p>Il blocco è <strong>uno per browser</strong>, non uno per vault: gli handle sincroni di OPFS e il pool di SQLite sono esclusivi per tutta l&#39;origine.</p></li><li><p>Il budget WASM si misura in <strong>gzip</strong> (7,8 MB), non in brotli (6,4 MB): niente nuove dipendenze Go per il serving; il file <code>.wasm.gz</code> si serve com&#39;è o si decomprime con la libreria standard.</p></li><li><p>Il worker non ha <code>tokens.ts</code>: il token passa dal protocollo dell&#39;host (<code>bridge.ts</code>).</p></li><li><p>Cancellazione della copia in chiaro: <strong>fatta</strong> per blocco e inattività; <strong>non fatta</strong> per il logout e per un &quot;Dimentica questo browser&quot; (resta in WP7).</p></li><li><p>Il blocco per inattività è fisso a 15 minuti: non legge ancora il Config Profile.</p></li><li><p>Pagina <code>workbench.html</code> e <code>web/src/workbench/{main.tsx,launch.ts,bridge.ts,worker.ts,opfs-fs.ts,idle.ts}</code>; &quot;Apri&quot; nella tabella dei vault e nelle condivisioni accettate.</p></li><li><p>esbuild: due pagine, worker a sé, <code>core/*.wasm.gz</code> con hash e SRI verificata dal worker, budget separati; <code>task wasm-core</code>, <code>task web-build</code> (core e binding generati se mancano).</p></li><li><p><code>web-embed</code>: route, CSP del workbench, servizio dei <code>.wasm</code> da <code>.wasm.gz</code>; <code>webembed-serve -dir</code> per provare una build E2E.</p></li><li><p>Dockerfile con gli stage <code>bindings</code> e <code>wasm</code>; CI con binding, core e job <code>wasm-core</code>.</p></li></ul><h3 id="m9-wp6-cloud" tabindex="-1">M9-WP6 Cloud <a class="header-anchor" href="#m9-wp6-cloud" aria-label="Permalink to &quot;M9-WP6 Cloud&quot;">​</a></h3><blockquote><p><strong>Stato (2026-10-29):</strong> implementato. <strong>Scostamento:</strong> il flag si chiama <code>web_workbench</code> (non <code>web.workbench.enabled</code>): le feature del Config Profile sono booleani piatti con underscore (<code>features.*</code>), le chiavi con il punto sono le impostazioni. Il valore predefinito è <em>acceso</em>. Verificati: test di integrazione con PostgreSQL vero (un dispositivo <code>web</code> si registra e si revoca; l&#39;enum OpenAPI e la colonna lo ammettevano già, nessuna migrazione), test dello schema (le due copie identiche, il flag accettato e il tipo errato rifiutato), test Go di <code>features</code> (acceso di default, spegnibile), 2 test web (il pulsante «Apri» c&#39;è e sparisce con il flag spento). <strong>Non verificato:</strong> il rifiuto dell&#39;indirizzo digitato a mano con il flag spento, che richiede un cloud vero (il lancio lo chiede al core con <code>ConfigAPI.Effective</code> e mostra «disattivato dall&#39;amministratore»), e l&#39;effetto per gruppo in un&#39;istanza reale.</p></blockquote><ul><li>Dispositivi con <code>platform: &quot;web&quot;</code>: già previsti dal contratto; coperti da un test di integrazione.</li><li>Feature <code>web_workbench</code> nel Config Profile: <code>api/config-profile.schema.json</code> e la sua copia nel cloud (test di parità), <code>features.Known</code>/<code>Defaults</code> del desktop (che la ignora), console web (<code>useWorkbenchAllowed</code>, nasconde «Apri» in Vault e nelle condivisioni) e lancio del workbench (rifiuta anche l&#39;indirizzo digitato).</li><li>Nessuna nuova API di contenuto.</li></ul><h3 id="m9-wp7-parita-e-qualita" tabindex="-1">M9-WP7 Parità e qualità <a class="header-anchor" href="#m9-wp7-parita-e-qualita" aria-label="Permalink to &quot;M9-WP7 Parità e qualità&quot;">​</a></h3><blockquote><p><strong>Stato (2026-10-29):</strong> implementato; <strong>i criteri di uscita di M9 sono soddisfatti solo in parte</strong> (vedi sotto). Dettaglio e matrice in <a href="./web-workbench-parity.html">web-workbench-parity.md</a> (tabelle generate da <code>scripts/parity.mjs</code>, verificate da <code>task parity</code> in <code>task ci</code>, ADR-0036).</p><p>Verificato: 14 spec dei flussi utente del desktop (<code>workflows</code>, <code>keyboard</code>, <code>editor-toolbar</code>, <code>slides</code>, <code>graph</code>) eseguiti <strong>sul workbench web contro il core vero</strong> (<code>e2e:workbench-ui</code>, <code>E2E_TARGET=web</code>, lo stesso <code>apps/desktop/frontend/e2e/support.ts</code>); e2e contro un <strong>cloud vero</strong> (Keycloak, PostgreSQL, S3: <code>e2e:cloud</code>): login, dispositivo <code>web</code>, una nota passa da un browser all&#39;altro e due modifiche concorrenti alla stessa nota <code>.md</code> si fondono sul client; «Dimentica questo browser» e logout cancellano le copie e i database (<code>forgetThisBrowser</code>, 1 test); un test di regressione dello shim; 81 test e2e web e 14 workbench-ui stabili su più esecuzioni, 104 e2e desktop invariati; sicurezza (build minificata, CSP di produzione).</p><p><strong>Bug veri trovati dalla parità:</strong> (1) due <code>open</code> concorrenti dello stesso file sullo shim OPFS davano EBUSY e il tab restava vuoto (corretto: acquisizione serializzata); (2) il nome del vault mostrava l&#39;id del cloud (ora il core usa il nome del cloud, <code>sync.ReadVaultName</code>).</p><p><strong>Non verificato</strong> (resta in elenco, nessuno è nascosto): desktop nativo ↔ web contro lo stesso cloud (provato web ↔ web: stesso core); copie di conflitto <code>.canvas</code>/<code>.excalidraw</code> dal browser; vault privato nel browser (sblocco, sync cifrata); mount <code>?share=</code>; flag <code>web_workbench</code> spento con un cloud vero; spec di disegno, canvas, condivisione, accessibilità (axe) e prestazioni sul web (usano dati del mock); Safari e Firefox; indicizzazione di vault grandi.</p></blockquote><ul><li>Matrice di parità <code>docs/web-workbench-parity.md</code>: eccezioni dichiarate, cosa è verificato e cosa no, e tabelle generate di 72 comandi (71 sul web) e 122 binding (13 chiamati da un test web contro il core vero: gli altri sono provati solo sotto WASM dai test del core).</li><li>Spec del desktop eseguiti anche sul web con un helper comune (<code>openVault</code> apre un vault sul mock o su una cartella del browser).</li><li>E2E web ↔ cloud vero in <code>web/e2e-cloud</code> (richiede <code>scripts/run-desktop-with-cloud.sh --cloud-only --keep</code> dopo <code>task web-build</code>; suite lenta, non è in <code>task ci</code>).</li><li>Test Go del core sotto <code>GOOS=js</code> (<code>task test-wasm</code>), con <code>scripts/parity.mjs --check</code>; il job CI <code>wasm-core</code> è stato rimosso con <code>ci.yml</code> e oggi entrambi girano in <code>task ci</code> (ADR-0036).</li><li>Sicurezza: blocco e cancellazione (<code>lockAndForget</code>), «Dimentica questo browser» e logout (<code>forgetThisBrowser</code>), CSP e SRI (<code>web/e2e-security</code>).</li></ul><p><strong>Criteri di uscita M9:</strong></p><ul><li>un vault condiviso e uno privato si aprono, si modificano e si sincronizzano dal browser con tutte le funzioni della matrice di parità;</li><li>le modifiche web ↔ desktop si propagano in entrambi i sensi;</li><li><code>task ci</code> verde, con desktop invariato.</li></ul><hr><h2 id="_13-ter-m10-—-pipeline-di-rilascio-esito-installer-e-immagini-pubblicati-da-release-yml" tabindex="-1">13-ter. M10 — Pipeline di rilascio (esito: installer e immagini pubblicati da <code>release.yml</code>) <a class="header-anchor" href="#_13-ter-m10-—-pipeline-di-rilascio-esito-installer-e-immagini-pubblicati-da-release-yml" aria-label="Permalink to &quot;13-ter. M10 — Pipeline di rilascio (esito: installer e immagini pubblicati da `release.yml`)&quot;">​</a></h2><blockquote><p><strong>Stato (2026-10-29):</strong> WP1-WP3 implementati (ADR-0031); <strong>WP4 solo in parte</strong>: un dry run su GitHub (<code>0.0.0-dryrun.3</code>) costruisce gli installer macOS, Windows amd64 e arm64 e Linux amd64 e ha trovato tre difetti, corretti. <strong>Non verificati</strong>: immagine Docker (la build locale è caduta per la rete, il dry run non la include), gate CI nel release, Linux arm64, firme, GHCR, tag RC e avvio degli installer: i criteri di uscita <strong>non sono soddisfatti</strong>. Mancano i certificati di firma: il canale non firmato è attivo, e la firma si accende quando arrivano i segreti. Dettaglio di cosa è verificato e no in ADR-0031.</p><p><strong>Aggiornamento (2026-11-01):</strong> i workflow sono stati ridotti a uno solo. Dalla 1.2.2 <code>release.yml</code> parte da un tag, pubblica immagine multi-arch e chart Helm su GHCR, costruisce gli installer e crea la GitHub Release con <code>SHA256SUMS</code>, <strong>senza firme, cosign, SBOM né attestazioni</strong> e senza eseguire controlli; <code>ci.yml</code> e <code>security.yml</code> sono stati rimossi. Dalla 1.2.3 la matrice desktop è macOS universale (<code>macos-15</code>), Windows amd64 e Linux amd64: Windows arm64 è stato tolto, Linux arm64 non è mai entrato. Le verifiche si fanno in locale con <code>task ci</code> (ADR-0036). I tag dalla 1.1.0 alla 1.2.4 sono stati creati con questa pipeline (voci in <code>CHANGELOG.md</code>); l&#39;esito delle singole run non è registrato qui. I criteri di uscita sotto che parlano di firme e di verifiche sulla push restano non soddisfatti per scelta: firma e verifiche automatiche sono da riattivare (<code>docs/release/secrets.md</code>).</p></blockquote><h3 id="m10-wp1-correzioni-bloccanti" tabindex="-1">M10-WP1 Correzioni bloccanti <a class="header-anchor" href="#m10-wp1-correzioni-bloccanti" aria-label="Permalink to &quot;M10-WP1 Correzioni bloccanti&quot;">​</a></h3><ul><li><code>services/cloud/Dockerfile</code>: <ul><li>niente <code>COPY .yarn</code>, che è ignorato da git;</li><li>cross-compilazione da <code>$BUILDPLATFORM</code> invece di QEMU;</li><li>stage <code>wasm</code> per M9.</li></ul></li><li>Wails CLI installata con <code>scripts/install-wails.sh</code> in <code>ci.yml</code> e <code>release.yml</code> (incompatibilità con Go 1.27); oggi resta solo <code>release.yml</code>.</li><li><code>task build-desktop</code> con <code>-tags webkit2_41</code> su Linux; target <code>docker-build</code> e <code>docker-push</code>.</li></ul><h3 id="m10-wp2-canale-non-firmato" tabindex="-1">M10-WP2 Canale non firmato <a class="header-anchor" href="#m10-wp2-canale-non-firmato" aria-label="Permalink to &quot;M10-WP2 Canale non firmato&quot;">​</a></h3><ul><li>Variabile <code>REQUIRE_SIGNING</code>, default <code>false</code>. Senza segreti, prerelease &quot;unsigned&quot; con avviso nel job summary e nelle note.</li><li>Senza le chiavi del manifest: <code>updater.DisabledByBuild=1</code> e nessun manifest pubblicato.</li><li>Con il certificato Authenticode si firma anche <code>clarae.exe</code>.</li><li>Aggiornamento di <code>docs/release/secrets.md</code> e <code>docs/release/README.md</code>.</li></ul><h3 id="m10-wp3-matrice-e-pubblicazione" tabindex="-1">M10-WP3 Matrice e pubblicazione <a class="header-anchor" href="#m10-wp3-matrice-e-pubblicazione" aria-label="Permalink to &quot;M10-WP3 Matrice e pubblicazione&quot;">​</a></h3><ul><li>Desktop: macOS universal, Windows amd64 e arm64, Linux amd64 e arm64 (<code>.deb</code> + AppImage). Dalla 1.2.3: macOS universale, Windows amd64, Linux amd64.</li><li>Immagini GHCR: semver dai tag (<code>X.Y.Z</code>, più <code>X.Y</code> sulle stabili); cosign, SBOM e provenance tolti nella 1.2.2 (il canale <code>edge</code> da <code>main</code> era già stato tolto nella semplificazione dei workflow).</li><li><code>ci.yml</code> riusabile (<code>workflow_call</code>) come gate dei workflow di rilascio (rimosso nella 1.2.2: il gate è <code>task ci</code> in locale, ADR-0036).</li><li>Una sola GitHub Release per tag, in bozza salvo <code>RELEASE_AUTO_PUBLISH=true</code>.</li><li>Placeholder: <code>ghcr.io/ORG</code> → <code>ghcr.io/e2br</code>; <code>clarae.example</code> → variabili <code>HOMEPAGE_URL</code> e <code>UPDATE_BASE_URL</code>.</li></ul><h3 id="m10-wp4-verifica-reale" tabindex="-1">M10-WP4 Verifica reale <a class="header-anchor" href="#m10-wp4-verifica-reale" aria-label="Permalink to &quot;M10-WP4 Verifica reale&quot;">​</a></h3><ul><li><code>actionlint</code> sui workflow.</li><li>Build multi-arch dell&#39;immagine da un clone pulito.</li><li>Dry run <code>workflow_dispatch</code> su GitHub (serve un <code>gh</code> autenticato).</li><li>Tag <code>v1.1.0-rc.1</code>, poi verifiche: installer avviati sui cinque target; <code>docker run … --version</code>; <code>deploy/compose</code> con <code>/api/v1/readyz</code>.</li><li>Package GHCR reso pubblico.</li><li>Aggiornamento di ADR-0023 (&quot;Verificato e non&quot;).</li></ul><p><strong>Criteri di uscita M10:</strong></p><ul><li>un tag produce in automatico installer per i cinque target e un&#39;immagine multi-arch firmata su GHCR;</li><li>una push su <code>main</code> verifica, costruisce il desktop su tre sistemi e l&#39;immagine (senza pubblicarla) — superato da ADR-0036: nessuna CI sulla push;</li><li>tutto è verificato su una run reale.</li></ul><hr><h2 id="_13-quater-prossimi-passi-post-m10-m11-—-affidabilita-e-parita" tabindex="-1">13-quater. Prossimi passi (post-M10): M11 — Affidabilità e parità <a class="header-anchor" href="#_13-quater-prossimi-passi-post-m10-m11-—-affidabilita-e-parita" aria-label="Permalink to &quot;13-quater. Prossimi passi (post-M10): M11 — Affidabilità e parità&quot;">​</a></h2><p>L&#39;analisi del 2026-11-01 (code review a più revisori su <code>main@70d8c0d</code>, con verifica avversariale dei rilievi alti e medi) ha prodotto un piano a onde. Lo si registra qui come <strong>M11</strong>; le decisioni sono negli ADR 0036–0044, accettati il 2026-11-02 e recepiti in <code>Specifications.md</code> v1.2. Ogni onda si chiude con le verifiche (<code>task ci</code> e le suite lente dell&#39;area) e un check-in con il proprietario. Stato al 2026-11-02:</p><table tabindex="0"><thead><tr><th>Onda</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td>W0 — rete di sicurezza</td><td>ADR-0036; <code>task ci</code> ermetico e completo (typecheck, <code>test-wasm</code>, <code>parity</code>, <code>check-gen</code>, binding obbligatori, tag <code>webkit2_41</code>); <code>parity.mjs --check</code> severo</td><td>fatta; per scelta del proprietario nessun <code>ci.yml</code></td></tr><tr><td>W1 — integrità dei dati nel cloud</td><td>retention con copie di conflitto e <code>compaction_seq</code> (ADR-0038, migrazione 0007), paginazione keyset, validatore senza body binari, lock dei job su un pool dedicato, default di <code>TRUSTED_PROXIES</code>, riconciliazione sotto lock</td><td>fatta; la quota sugli upload dei blob e il <code>PATCH</code> tus senza transazione aperta sono stati chiusi in W8</td></tr><tr><td>W2 — integrità dei dati nel client</td><td>candidati al merge persistenti e quarantena (ADR-0039), pull fermo su vault bloccato, lock per path in <code>vault.FS</code>, «Sovrascrivi» nei conflitti, flush delle modifiche in sospeso al teardown, merge del frontmatter, copia di conflitto prima della sovrascrittura</td><td>fatta</td></tr><tr><td>W3 — sicurezza e host del web</td><td>core come unico timer di blocco, cancellazione della copia su <code>vault:locked</code> con marcatori e overlay, sweep all&#39;avvio, <code>CoreDeadError</code> e limiti di tempo nel bridge, rinnovo del token, <code>persist()</code></td><td>fatta; identità stabile del dispositivo web e capability estese chiuse in W8</td></tr><tr><td>W4 — prestazioni e osservabilità</td><td>metriche e probe del worker, cache e dettagli di <code>/readyz</code>, migrazioni sotto advisory lock, ETag e gzip della Web UI, <code>sizeLimit</code> dello spool; desktop: chiavi dei link, risoluzione incrementale, candidati alla rinomina, ultimo scan persistito, eventi tipizzati</td><td>fatta; strategia del watcher per vault grandi chiusa in W8 (FSEvents, ADR-0044); baseline <code>task perf</code> in <a href="./perf/">perf/README.md</a></td></tr><tr><td>W5 — architettura di parità</td><td>registro delle funzioni e nuovo <code>parity.mjs</code>, <code>Command.requires</code>, client Go generato e contract test, <code>@clarae/cloud-features</code> con <code>CloudPort</code>, ciclo di vita dei vault su console e desktop (ADR-0037)</td><td>fatta (fasi A e B); migrazione di dispositivi, utilizzo e condivisioni, feature flag generati dallo schema e matrice e2e mista chiusi in W8</td></tr><tr><td>W6 — documentazione</td><td>README, <code>CONTRIBUTING.md</code>, <a href="./architecture.html">architecture.md</a>, <a href="./desktop-web-sync.html">desktop-web-sync.md</a>, OpenAPI, CHANGELOG, documenti senza promesse di CI; riscrittura di <a href="./web-ui.html">web-ui.md</a> e capitolo utente sul browser</td><td>fatta</td></tr><tr><td>W7 — bassa priorità</td><td>rilievi di priorità bassa (concorrenza minore, audit e sessioni, crittografia: NFC della passphrase, ADR-0034, azzeramento delle chiavi; supply chain), a lotti</td><td>lotti 1 e 2 fatti; i rilievi bassi rimasti sono stati chiusi in W8</td></tr><tr><td>W8 — punti aperti</td><td>tutti i rilievi rimasti del report (medi e bassi) e i rinvii delle onde precedenti, in otto lotti più due di completamento: quota degli upload, tus, history condivisa, commit, export, ruoli e account (ADR-0041), hub delle notifiche, watcher FSEvents (ADR-0044), path cifrati legati al file (ADR-0042), capability estese e identità del dispositivo web, SRI completa e core WASM più piccolo, <code>cloud-features</code> completo, flag dallo schema, matrice e2e e suite mista, <code>move_prefix</code> lato client (ADR-0040), stato «dispositivo revocato»</td><td>fatta; ADR 0040–0044 accettati il 2026-11-02 (ADR-0041 punto 8 implementato, punto 9 confermato; ADR-0043 implementato nei passi 2–5)</td></tr><tr><td>W9 — ruoli, UI condivisa e spec</td><td>manager che crea condivisioni dentro quella che gestisce (ADR-0041 punto 8), primitive UI condivise tra console e workbench (ADR-0043 passi 2–5), <code>Specifications.md</code> v1.2 con gli ADR 0036–0044, frame della presentazione nei disegni appena aperti</td><td>fatta</td></tr><tr><td>W10 — spec 1.3 e crittografia v2</td><td><code>Specifications.md</code> v1.3 (workbench web, core WASM, Task; ADR 0029, 0030, 0032 accettati); envelope v2 e path <code>enc2</code> attivi per default con migrazione in background (rilascio N+1 di ADR-0034 e ADR-0042); release 1.3.0</td><td>fatta</td></tr><tr><td>W11 — spec 1.4</td><td><code>Specifications.md</code> v1.4 recepisce gli ADR già implementati 0009–0022, 0024, 0026–0028, 0031, 0033 e 0034</td><td>fatta</td></tr><tr><td>W12 — barra di stato</td><td>ADR-0035 accettato, implementato e recepito in <code>Specifications.md</code> v1.5 (2026-11-02): barra di stato compatta facoltativa e spenta per default (<code>appearance.statusBar</code>, <code>app:toggle-status-bar</code>), con test unitari, e2e sul mock e scansione axe</td><td>fatta; release 1.3.1</td></tr></tbody></table><p><strong>Criteri di uscita M11:</strong> <code>task ci</code> verde; suite lente verdi sulle aree toccate (<code>task test-integration</code>, <code>task test-desktop-e2e</code>, <code>task e2e</code>, <code>e2e:workbench-ui</code>, <code>e2e:cloud</code>); ADR 0036–0044 accettati o rivisti dal proprietario e recepiti nello spec (fatto il 2026-11-02: tutti accettati e recepiti in <code>Specifications.md</code> v1.2, Appendice C.4); ogni funzione di gestione dei vault cloud disponibile su console, desktop e workbench secondo il registro.</p><hr><h2 id="_13-quinquies-m12-—-robustezza-e-parita-per-costruzione" tabindex="-1">13-quinquies. M12 — Robustezza e parità per costruzione <a class="header-anchor" href="#_13-quinquies-m12-—-robustezza-e-parita-per-costruzione" aria-label="Permalink to &quot;13-quinquies. M12 — Robustezza e parità per costruzione&quot;">​</a></h2><p>La revisione del 2026-11-02 su <code>main@803b4bc</code> (46 revisori automatici su aree distinte, verifica avversariale di ogni rilievo, critico di completezza con un secondo giro su Bases e template, ciclo di vita dei mount, runtime del cloud ed Helm) ha trovato 134 problemi distinti, nessuno tra quelli già chiusi in M11: 7 di priorità alta, 44 media e 83 bassa. Le decisioni sono in <a href="./adr/0045-parita-per-costruzione.html">ADR-0045</a> (parità per costruzione tra desktop, workbench web e console) e <a href="./adr/0046-bootstrap-server-indietro.html">ADR-0046</a> (bootstrap quando il server è tornato indietro, integra ADR-0022), accettati il 2026-11-02. Ogni onda si chiude con <code>task ci</code> verde, le suite lente dell&#39;area e i commit <code>[M12-Wn.m]</code>.</p><table tabindex="0"><thead><tr><th>Onda</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td>W0 — correzioni urgenti</td><td>DSN di SQLite con <code>#</code> e <code>?</code> nel percorso; logout SSO nel realm di produzione; timeout della sync che non tronca i trasferimenti dei blob; push in streaming; limiti di profondità, memoria e CPU delle espressioni Bases; bootstrap dopo un ripristino PITR del cloud senza perdita delle revisioni recenti (ADR-0046)</td><td>fatta (2026-11-02)</td></tr><tr><td>W1 — integrità del cloud</td><td>GC dei blob e chunk tus, retention dei tombstone, purge dei vault a lotti, indici mancanti, JWKS e gRPC con limiti e timeout, account eliminati, condivisioni derivate e scadute, <code>Idempotency-Key</code>, job di export, probe di Helm, HSTS</td><td>fatta (2026-11-02)</td></tr><tr><td>W2 — integrità del client desktop</td><td>stati della sync (scan, spostamenti, migrazione <code>enc2</code>, risoluzione dei conflitti, quarantena), ciclo di vita dei mount, errori del transport, rinomina senza attesa del ciclo, history, parser lineare, riconciliazione e watcher, importer</td><td>fatta (2026-11-02)</td></tr><tr><td>W3 — workbench e host web</td><td>Error Boundary, Annulla dopo un ricaricamento, canvas, grafo incrementale, incolla allegati, token del client API, export (errori, memoria, download), copie OPFS legate all&#39;account, eliminazione dell&#39;account</td><td>fatta (2026-11-03)</td></tr><tr><td>W4 — gap di parità e regole</td><td>mount sul web (Apri, Mantieni una copia), gate di sblocco, «Dimentica questo browser» senza perdite, capability al posto di <code>kind</code>; prove per superficie nel registro; client tipizzato dell&#39;host web ed eventi generati (ADR-0045 punti 4–5)</td><td>fatta (2026-11-03)</td></tr><tr><td>W5 — parità per costruzione</td><td>capability dal core Go, azioni dichiarative e <code>FeatureId</code> generato, DTO dei binding cloud uguali all&#39;OpenAPI, <code>MountsList</code> in <code>@clarae/cloud-features</code>, politiche nel core (ADR-0045 punti 1–3 e 6–8)</td><td>fatta (2026-11-03)</td></tr><tr><td>W6 — prestazioni</td><td>trasferimenti dei blob in parallelo, quota degli upload senza scansioni, risoluzione dei link incrementale, liste API paginate, code splitting per rotta, core WASM senza moduli desktop; baseline <code>task perf</code> aggiornata</td><td>fatta (2026-11-03); la console resta senza code splitting (SRI del tag, ADR-0029)</td></tr><tr><td>W7 — documentazione</td><td>README, <code>architecture.md</code>, <code>desktop-web-sync.md</code> (procedura end-to-end e contratto degli eventi), <code>web-ui.md</code>, pagina di parità, <code>CONTRIBUTING.md</code>, <code>CLAUDE.md</code>, OpenAPI (403 e 409 del middleware), commenti sul confine desktop/web</td><td>fatta (2026-11-03)</td></tr><tr><td>W8 — priorità bassa</td><td>rilievi bassi non assorbiti dalle onde precedenti, a lotti per area; quelli non corretti restano qui con la motivazione</td><td>fatta (2026-11-03); vedi sotto i punti lasciati aperti</td></tr></tbody></table><p><strong>Criteri di uscita M12:</strong> <code>task ci</code> verde; suite lente verdi sulle aree toccate (<code>task test-integration</code>, <code>task test-desktop-e2e</code>, <code>task test-wasm</code>, <code>task e2e</code>, <code>e2e:workbench-ui</code>, suite mista); nessun rilievo alto o medio aperto; ogni funzione del registro marcata <code>yes</code> sul workbench ha una prova sul core WebAssembly.</p><p><strong>Esito di M12 (2026-11-03).</strong> Criteri di uscita soddisfatti: <code>task ci</code> verde (ora con <code>test-core</code>), suite lente verdi (<code>task test-integration</code>, <code>task test-desktop-e2e</code>, <code>task test-wasm</code>, <code>task e2e</code>, <code>e2e:workbench-ui</code> con 216 spec sul core WASM), nessun rilievo alto o medio aperto, ogni funzione «sì» sul workbench con una prova sul core. Le onde hanno trovato e corretto anche difetti non presenti nella revisione: perdita di una modifica remota parcheggiata durante uno spostamento, ciclo «disconnesso/pronto» della sessione del browser su un token annullato, ricaricamento infinito di <code>/config/effective</code> in errore, pulsante account nel browser, due comandi di Excalidraw attivi senza diritti di modifica.</p><p>Punti lasciati aperti, con la motivazione:</p><ul><li><strong>Code splitting della console:</strong> non fatto. Con lo split i chunk sarebbero verificati solo dove l&#39;import map supporta <code>integrity</code> (non Safari), contro la garanzia di ADR-0029 (tutto il codice della console coperto dall&#39;SRI del tag). Va deciso dal proprietario con un aggiornamento di ADR-0029; il budget della console è rispettato (691/700 kB).</li><li><strong>Mock dei binding:</strong> risoluzione dei link coperta da una fixture condivisa tra Go e mock; grafo, basi e ricerca restano senza fixture (impegno L), e il rischio di divergenza è coperto dalla matrice <code>e2e:workbench-ui</code>, che però non è in <code>task ci</code>: valutare di aggiungerla.</li><li><strong>Live Preview:</strong> <code>scanBlocks</code> legge ancora l&#39;intero documento per il frontmatter a ogni transazione; è il prossimo intervento sulle note molto lunghe.</li><li><strong>Query duplicate:</strong> cinque copie restano tra <code>sync</code>/<code>sharing</code> e <code>notify</code>/<code>sharing</code> per evitare cicli di import (ADR-0033); un test le vuole identiche.</li><li><strong>Liste paginate:</strong> il cambio di forma di <code>/shares</code> e <code>/shared-with-me</code> richiede di aggiornare i desktop prima del cloud (CHANGELOG, «Compatibilità»).</li><li><strong>Specifica:</strong> ADR-0046 devia da <code>Specifications.md</code> §3.4.4 e introduce <code>since_id</code>; ADR-0045 e ADR-0046 vanno recepiti dal proprietario.</li></ul><h2 id="_13-sexies-m13-—-apertura-dei-file-per-tipo-e-presentazioni-marp" tabindex="-1">13-sexies. M13 — Apertura dei file per tipo e presentazioni Marp <a class="header-anchor" href="#_13-sexies-m13-—-apertura-dei-file-per-tipo-e-presentazioni-marp" aria-label="Permalink to &quot;13-sexies. M13 — Apertura dei file per tipo e presentazioni Marp&quot;">​</a></h2><p>Due richieste del 2026-11-03. I file che l&#39;app non mostra devono aprirsi con l&#39;applicazione del sistema sul desktop e scaricarsi nel browser. Servono inoltre le presentazioni <a href="https://marp.app/" target="_blank" rel="noreferrer">Marp</a> in file <code>.marp</code>, con editor e anteprima affiancati ed export. La decisione è <a href="./adr/0047-apertura-file-per-tipo-e-presentazioni-marp.html">ADR-0047</a>, accettato il 2026-11-03: devia da <code>Specifications.md</code> (§2.2.1, §3.4.5, §3.4.6) e supera in parte l&#39;alternativa «file di slide dedicati» di ADR-0027. Ogni onda si chiude con <code>task ci</code> verde e i commit <code>[M13-Wn.m]</code>.</p><table tabindex="0"><thead><tr><th>Onda</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td>W1.1 — decisione</td><td>ADR-0047: routing di apertura per tipo, <code>.marp</code> come Markdown per il core, Marp entro V-02 (solo temi integrati, niente CSS dell&#39;autore, Shadow DOM), offline, export HTML/PDF e PPTX rinviato</td><td>fatta (2026-11-03)</td></tr><tr><td>W1.2 — Fase 1, apertura per tipo</td><td>capability <code>openWithSystemApp</code>, <code>Host.OpenPath</code>/<code>RevealPath</code>, binding <code>OpenWithSystemApp</code>, <code>RevealInFolder</code> e <code>DownloadFile</code>; eseguibili mai aperti (<code>pathrules.IsExecutable</code>); router <code>openFile</code> agganciato a <code>openNote</code>; dialog «Apertura File» nel browser; icone per tipo e menu dell&#39;explorer; e2e sul mock e sul core WASM</td><td>fatta (2026-11-03)</td></tr><tr><td>W1.3 — Fase 2, presentazioni Marp</td><td><code>KindOf(&quot;.marp&quot;) = md</code> (unione a 3 vie, indice, link); <code>@marp-team/marp-core</code> 5.0.2 in un chunk lazy; sanitizzazione dedicata; vista divisa con anteprima live in Shadow DOM, slide del cursore, presentazione; comandi <code>marp:*</code>, export HTML e PDF, PPTX non ancora disponibile; flag <code>presentations</code> del Config Profile; e2e sul mock e sul core WASM, senza rete</td><td>fatta (2026-11-03)</td></tr></tbody></table><p><strong>Punti lasciati aperti:</strong></p><ul><li><strong>Export PPTX:</strong> non disponibile. Marp CLI lo produce con un Chromium headless, che non c&#39;è né in Wails né nel browser.</li><li><strong>Da verificare su un&#39;app reale:</strong> l&#39;apertura con l&#39;app del sistema, la stampa in PDF con <code>@page</code> della dimensione della slide nella webview di macOS e il tutto schermo in Wails. I test usano un host finto.</li><li><strong>Embed <code>![[deck.marp]]</code> in una nota:</strong> mostra il segnaposto, non la prima slide.</li><li><strong>Bundle iniziale del desktop:</strong> 1979 kB su 2000. Marp ne è fuori, ma il margine è stretto.</li><li><strong>Specifica:</strong> ADR-0047 va recepito dal proprietario.</li></ul><h2 id="_13-septies-m14-—-presentazioni-marp-come-i-disegni-tab-slideshow-tutto-schermo-export-nel-ribbon-e-pptx" tabindex="-1">13-septies. M14 — Presentazioni Marp come i disegni: tab SlideShow, tutto schermo, export nel ribbon e PPTX <a class="header-anchor" href="#_13-septies-m14-—-presentazioni-marp-come-i-disegni-tab-slideshow-tutto-schermo-export-nel-ribbon-e-pptx" aria-label="Permalink to &quot;13-septies. M14 — Presentazioni Marp come i disegni: tab SlideShow, tutto schermo, export nel ribbon e PPTX&quot;">​</a></h2><p>Richiesta del 2026-11-05. Un <code>.marp</code> si apre in un editor a tutta larghezza, senza vista divisa. Il tab SlideShow offre le stesse funzioni dei disegni, con presentazione a tutto schermo. Gli export HTML, PDF e PPTX (modificabile, con pptxgenjs) sono nel ribbon, per tipo di file attivo. La decisione è <a href="./adr/0048-presentazioni-marp-slideshow-ribbon-pptx.html">ADR-0048</a>, accettato il 2026-11-05. Devia da <code>Specifications.md</code> come ADR-0047 e supera in parte ADR-0047 (vista divisa e PPTX). Ogni onda si chiude con i commit <code>[M14-Wn.m]</code>; il controllo finale è <code>task ci</code> verde.</p><p><strong>Stato: fatta (2026-11-05).</strong></p><table tabindex="0"><thead><tr><th>Onda</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td>W1 — ADR e roadmap</td><td>ADR-0048 (accettato il 2026-11-05), ADR-0047 «parzialmente superata da ADR-0048», indice, questa sezione</td><td>fatto</td></tr><tr><td>W2 — Go: formato PPTX nell&#39;export</td><td><code>exportFormats</code> in <code>bindings_export.go</code>: MIME PPTX → <code>.pptx</code>; la validazione apre lo ZIP e richiede <code>[Content_Types].xml</code> e <code>ppt/presentation.xml</code>, <code>MaxBinaryBytes</code> invariato; test (valido, senza voci, non ZIP, troppo grande); verifica anche con <code>GOOS=js GOARCH=wasm</code>; binding invariati, niente <code>task gen</code></td><td>fatto</td></tr><tr><td>W3 — Frontend: editor, modello, SlideShow</td><td>editor a tutta larghezza (via <code>SplitHandle</code>, <code>MarpPane</code>, <code>presenter.ts</code>, CSS <code>.marp-split*</code>; fix <code>.mode-toggle[hidden]</code>); modulo puro <code>marp/slides.ts</code> (slide, <code>hidden</code>, note, frontmatter, riordino per blocchi) con transazioni di CodeMirror; store e controller; <code>MarpSlidesPanel</code> (barra, impostazioni, card, miniature, note); overlay <code>MarpShow</code> con gli stessi tasti e loop dei disegni</td><td>fatto</td></tr><tr><td>W4 — Frontend: ribbon ed export PPTX</td><td>gruppo export del ribbon per tipo di file; comandi <code>drawing:export-png/svg/pdf</code>; correzione di <code>note:export-pdf</code>; <code>marp/pptx.ts</code> con <code>pptxgenjs</code> a versione esatta, lazy; slide escluse saltate anche in HTML e PDF; voci di parità <code>presentations</code> e <code>drawing.export</code>, poi <code>task gen</code> e <code>task parity</code></td><td>fatto</td></tr><tr><td>W5 — Verifica, revisione, documenti</td><td><code>reviewer</code> sul diff (undo senza perdita di testo, <code>---</code> in codice e frontmatter, sanificazione miniature, niente <code>style</code> inline, pptxgenjs offline e senza <code>eval</code>, esclusioni nei tre export); <code>qa-engineer</code> (<code>task typecheck</code>, vitest, <code>task test-wasm</code>, <code>task parity</code>, e2e, <code>task e2e-matrix -- marp</code>, <code>task ci</code>); CHANGELOG, guida utente, pagina di parità</td><td>fatto</td></tr></tbody></table><p><strong>Criteri di uscita M14:</strong> ADR-0048 accettato; nessuna vista divisa e nessun pulsante di modalità su un <code>.marp</code>; il tab SlideShow permette riordino, esclusione, note e presentazione con undo nell&#39;editor; la presentazione a tutto schermo risponde a tasti, loop ed Esc; il ribbon mostra gli export del tipo di file attivo; il PPTX è valido, con testo modificabile e note, ed è scaricato dal workbench web; le slide escluse non compaiono negli export; nessuna richiesta di rete; <code>task ci</code> verde, <code>task e2e-matrix -- marp drawing-export</code> verde.</p><p><strong>Esito (2026-11-05):</strong> tutte le onde sono fatte. In W5 il <code>reviewer</code> ha fatto tre revisioni del diff, l&#39;ultima senza rilievi gravi o medi; <code>task ci</code> è verde (2026-11-05), come gli e2e desktop sui mock dei binding, la matrice sul core WASM nel browser e il bundle di produzione. CHANGELOG (<em>Unreleased</em>), guida utente, guida admin (flag <code>presentations</code>) e pagina di parità sono aggiornati. ADR-0048 è accettato e ADR-0047 è parzialmente superata.</p><p><strong>Ancora da verificare:</strong></p><ul><li>prova manuale del PPTX aprendolo in PowerPoint e in Keynote (testo modificabile, note, resa del tema);</li><li><code>task test-desktop-e2e</code> (sync a due dispositivi contro il cloud reale) non è stato eseguito.</li></ul><p><strong>Follow-up a bassa priorità:</strong></p><ul><li>la riscrittura di una nota su più righe (spostata in fondo alla slide) può lasciare nel sorgente una riga di soli spazi o una riga vuota in più: solo estetico;</li><li>caso stretto: una nota scritta entro 300 ms da una modifica nell&#39;editor si perde se si cambia scheda entro 600 ms (il salvataggio della nota è differito di 600 ms, la pubblicazione dello stato dell&#39;editor di 300 ms).</li></ul><p><strong>Punti da tenere d&#39;occhio:</strong></p><ul><li><strong>Compatibilità:</strong> un client ≤ 1.3.3 vede <code>&lt;!-- clarae: hidden --&gt;</code> come una nota e mostra la slide (riportato nel CHANGELOG, <em>Unreleased</em>).</li><li><strong>Tema nel PPTX:</strong> approssimato; da verificare aprendo il file in PowerPoint o Keynote.</li><li><strong>Specifica:</strong> ADR-0047 e ADR-0048 vanno recepiti insieme dal proprietario.</li></ul><h2 id="_13-octies-m15-—-migrazione-a-wails-v3" tabindex="-1">13-octies. M15 — Migrazione a Wails v3 <a class="header-anchor" href="#_13-octies-m15-—-migrazione-a-wails-v3" aria-label="Permalink to &quot;13-octies. M15 — Migrazione a Wails v3&quot;">​</a></h2><p>Richiesta del 2026-11-10: passare il client desktop a Wails v3 mantenendo tutte le funzioni esistenti (solo parità: niente pop-out, niente updater integrato di v3). La decisione è <a href="./adr/0051-wails-v3.html">ADR-0051</a>, in stato <strong>proposta</strong> (non accettata, subordinata all&#39;esito dello spike B-W0). Devia da <code>Specifications.md</code> (V-07 <code>:59</code>, A-03 <code>:68</code>, D-07 <code>:1920</code>, §4.5 <code>:1857</code>, §4.2 <code>:1726</code>, C.2 <code>:1944</code>): lo spec non viene toccato, lo aggiorna l&#39;owner. Il piano (due progetti, una critica avversariale e il piano approvato) non è versionato. Ogni onda si chiude con <code>task ci</code> verde e i commit <code>[M15-Wn.m]</code>, su richiesta.</p><p><strong>Stato: in corso (2026-11-11).</strong> B-W0 eseguito (esito: GO con condizioni); B-W1…B-W7 fatte, B-W4b compresa, con gli esiti nella tabella (macOS provato, Windows come cross-build, Linux non provato); B-W8: parte automatica eseguita, matrice manuale da eseguire su Windows, Linux e macOS Intel; B-W9: revisione finale eseguita, con verdetto Fail per due rilievi medi di processo e di QA (base del rollback e percorso di aggiornamento reale assente dalla matrice), non per regressioni del codice; <strong>entrambi chiusi il 2026-11-11 dalle decisioni dell&#39;owner</strong>, vedi «Esito della revisione finale di B-W9». L&#39;ADR-0051 resta in proposta. <strong>Nessun rollback a Wails v2</strong> (decisione dell&#39;owner, 2026-11-11): in caso di problemi gravi si corregge in avanti su v3. <strong>Criterio di aggiornamento:</strong> installazione manuale sopra la 1.3.4 su ogni sistema operativo, perché le build pubblicate non hanno l&#39;updater; l&#39;updater si prova solo per build con chiave. Ordine consigliato: M15 per prima. Il piano prevedeva B-W2 e B-W3 su v2, rilasciabili da sole; i commit sono richiesti a fine ondata, dopo <code>task ci</code> verde, su un ramo dedicato e non su <code>main</code>, e nessuna onda è ancora committata. Il margine sul bundle iniziale del desktop era di 8 kB (misurato il 2026-11-11 a interruttore Milkdown spento: 1992 su 2000 kB; acceso: 1375 kB; workbench web: 2492 su 2500 spento, 1916 acceso) ed era condiviso con M16: nessuna delle due parti poteva aggiungere peso all&#39;entry. <strong>Dal 2026-11-12 (A-W9 di M16) l&#39;interruttore non c&#39;è più e l&#39;entry desktop è di 1376 kB su 2000: il margine è di circa 624 kB</strong> (web workbench 1925 su 2500).</p><table tabindex="0"><thead><tr><th>Onda</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td>B-W0 — Spike</td><td>Ramo usa e getta, sui tre sistemi operativi (desktop-core-developer, frontend-developer, qa-engineer): <code>main.go</code> v3, <code>CoreBridge</code>, shim, build a mano. Criteri go/no-go sotto</td><td>eseguito, esito: GO con condizioni (macOS: nessun bloccante; export oltre 64 MiB fallisce, runtime oltre il budget, prove manuali su Windows e Linux da fare); decisione all&#39;owner</td></tr><tr><td>B-W1 — ADR e roadmap</td><td>ADR-0051 in proposta con gli esiti dello spike; questa sezione; indice ADR (docs-writer)</td><td>fatto (in attesa di accettazione degli ADR); esiti dello spike riportati in ADR-0051</td></tr><tr><td>B-W2 — Generatore dei binding, ancora su v2</td><td><code>internal/app/gen/bindings</code> con output byte-identico a <code>wails generate module</code>; Taskfile; stage 1 del Dockerfile cloud senza CLI Wails; v2 portata a 2.17.1 (fix di sicurezza Linux). Uscita: <code>diff -r</code> vuoto contro <code>wails generate module</code>; <code>task ci</code> e <code>task docker-build</code> verdi senza CLI Wails</td><td>fatto</td></tr><tr><td>B-W3 — Estrazione della shell, ancora su v2</td><td><code>internal/shell</code> con host e <code>closeGuard</code> testabile; <code>OnSecondInstance([]string)</code>. Uscita: <code>go list -deps ./internal/app</code> senza <code>wailsapp</code>; <code>task ci</code> verde</td><td>fatto (2026-11-11): <code>internal/shell</code> con host e <code>closeGuard</code>; <code>go list -deps ./internal/app</code> senza <code>wailsapp</code>; la revisione ha fatto correggere il watcher del guard e una gara su <code>a.ctx</code></td></tr><tr><td>B-W4 — Passaggio a v3, lato Go</td><td><code>CoreBridge</code>, guard su hook <code>WindowClosing</code> e <code>ShouldQuit</code>, context nostro, ID single-instance per Linux, menu, logger dedicato, listener URL solo su macOS. Uscita: <code>go test -race</code> verde; test d&#39;architettura; build sui tre OS</td><td>fatto (2026-11-11), con <code>CoreBridge</code>, guard, ID <code>dev.clarae.desktop.i&lt;16 hex&gt;</code>, menu solo su macOS, <code>UIRuntimeLogger</code>, annullamento dei dialoghi su Windows tradotto in percorso vuoto, filtro degli errori di binding nel log, controllo dei tag di build all&#39;avvio. <code>go test -race</code> verde; build macOS e Windows; Linux solo type-check (<code>CGO_ENABLED=0 -tags production,purego</code>), la build <code>gtk3</code> non è mai stata eseguita</td></tr><tr><td>B-W4b — Trasporto proprio (condizionale)</td><td>Solo se B-W0 conferma il tetto di 64 MiB del trasporto HTTP di v3: trasporto sul canale nativo dei messaggi verso lo stesso dispatcher. Uscita: export HTML da 200 MiB e chiamata pendente di 3 minuti riusciti</td><td>fatta (2026-11-11), con una scelta diversa dal piano: upload a chunk su <code>/clarae/upload/&lt;id&gt;</code> dell&#39;asset server (soglia 32 MiB di JSON, tetto 320 MiB, solo RAM), non un trasporto sul canale nativo. Esito su macOS in un WKWebView reale: 65 MiB in 0,63 s, 200 MiB in 2,0 s, 250 MiB in 3,1 s con checksum corretto; chiamata da 3 minuti con altre 8 in corso risolte. WebView2 e WebKitGTK non provati</td></tr><tr><td>B-W5 — Shim desktop</td><td><code>apps/desktop/frontend/src/wailsHost.ts</code> con drop-guard e segnale di pronto. Uscita: vitest nuovi; e2e desktop-mock e web-core invariati e verdi; budget secondo ADR</td><td>fatto (2026-11-11): <code>wailsHost.ts</code> su <code>@wailsio/runtime</code> 3.1.0 in un chunk a parte (57 kB, 17,6 kB gzip), 33 test vitest, binario v3 reale provato su macOS (deep link a freddo e a caldo, chiusura in 0,12 s). Bundle iniziale desktop 1990 kB su 2000. <code>location.reload()</code> e drop vero nel binario reale non provati</td></tr><tr><td>B-W6 — Build e dev</td><td><code>scripts/build-desktop-bin.sh</code>, <code>wails3 tool watcher</code>, controllo versioni in <code>task lint</code>. Uscita: <code>task dev-desktop</code> e <code>task build-desktop</code> sui tre OS; albero pulito</td><td>fatto per macOS (2026-11-11): <code>task build-desktop</code> e <code>task dev-desktop</code> verificati; controllo delle versioni in <code>task lint</code> (<code>lint-wails-versions</code>); Windows solo cross-build; Linux (<code>gtk3</code>) non verificato. La correzione della revisione: <code>--dev</code> passa <code>main.Version=dev</code>, readiness HTTP del watcher, <code>SKIP_FRONTEND</code> solo con <code>1</code></td></tr><tr><td>B-W7 — Rilascio</td><td><code>render-assets</code>, syso, bootstrapper, <code>.app</code>, <code>release.yml</code>, controllo dei tag di build. Uscita: stessi nomi di artefatto; aggiornamento nei due versi su canale di staging</td><td>fatto su macOS e come cross-build Windows (2026-11-11): <code>render-assets.go</code> al posto di <code>nsis-render.go</code>, bootstrapper WebView2 da <code>wails3</code> con pin dell&#39;hash, <code>check-build-tags.sh</code>, <code>.dmg</code> con gli stessi nomi di prima; <code>LSMinimumSystemVersion</code> da 10.13 a 13.0 (ADR-0051). Aggiornamento nei due versi su canale di staging: <strong>non eseguito</strong> (procedura in <code>docs/qa/m15-wails3-matrice.md</code> §3); Linux e <code>release.yml</code> su runner vero non provati</td></tr><tr><td>B-W8 — QA</td><td>Matrice per OS in <code>docs/qa/</code> e smoke scriptato del binario reale. Uscita: zero P0 e P1</td><td><strong>parte automatica eseguita (2026-11-11), matrice manuale da eseguire</strong>: suite di integrazione, sync a due dispositivi ed e2e verdi, <code>task e2e-matrix</code> verde al rilancio isolato (il primo giro ebbe 4 falli d&#39;ambiente), smoke scriptato del binario v3 su macOS ok; Windows, Linux e macOS Intel non provati, nessuna riga manuale spuntata. Dettagli sotto</td></tr><tr><td>B-W9 — Revisione e documenti</td><td>Sicurezza, licenza del codice portato da v2, CHANGELOG. Uscita: <code>task ci</code> verde; <code>rg wails/v2</code> vuoto</td><td><strong>revisione finale eseguita (2026-11-11)</strong>, verdetto Fail per due rilievi medi (rollback, percorso di aggiornamento), chiusi dalle decisioni dell&#39;owner del 2026-11-11 (nessun rollback a v2; installazione manuale sopra la 1.3.4); sicurezza e licenze del codice portato da v2 senza rilievi; uscita non raggiunta: <code>task ci</code> non rieseguito dalla catena e <code>rg wails/v2</code> non vuoto. Dettagli sotto</td></tr></tbody></table><p><strong>Esito dello spike B-W0 (2026-11-10, Wails v3.1.0, solo macOS).</strong> Raccomandazione: <strong>GO con condizioni</strong>. Per criterio (dettaglio e misure in <a href="./adr/0051-wails-v3.html">ADR-0051</a>): 1 parziale (trasporto: <code>CoreBridge</code>, conflitto e panic ok; manca la UI vera, B-W5); 2 passa su macOS (40/40 su quattro gesti di chiusura); 3 non verificabile qui; 4 premessa confermata (ID attuale rifiutato da D-Bus in 614 casi su 1000, ID <code>dev.clarae.desktop.i&lt;16 hex&gt;</code> accettato 1000/1000; test su Linux non eseguibile); 5 parziale (drop-guard su <code>window</code> riporta <code>dropEffect</code> a <code>copy</code>); 6 passa su macOS (struttura; <code>Menu.Set</code> solo su macOS); 7 passa con <code>Options.Logger</code> a Warn minimo (<code>DisableLogging</code> da solo non basta); <strong>8 fallisce</strong> per <code>SaveHTML</code> oltre 64 MiB (65 e 200 MiB falliscono, 63 MiB passa), quindi B-W4b è attiva; 9 passa su macOS con la riserva che <code>frame-src &#39;none&#39;</code> non copre gli iframe <code>srcdoc</code> e <code>about:blank</code>; 10 parziale (proxy su <code>127.0.0.1:5173</code> e ricarica SSE ok); 11 e 12 non verificabili qui. <strong>Il runtime <code>@wailsio/runtime</code> pesa 25-57 kB</strong>: con 1979 kB di oggi porta l&#39;iniziale a 2004-2035 kB contro 2000, quindi serve un <code>import()</code> dinamico, <code>/wails/runtime.js</code> servito da Go o un nuovo limite in un ADR. Condizioni per il GO: B-W4b (o limite di export dichiarato), runtime fuori dall&#39;entry, prove manuali su macOS, Windows e Linux (chiusura 20 volte per OS, <code>clarae://</code> a freddo e a caldo, drop reale, dialoghi, single-instance su Ubuntu 22.04 e 24.04, installazione manuale sopra la 1.3.4 su ogni sistema operativo; l&#39;aggiornamento via updater su staging solo per build con chiave; nessun ritorno a v2).</p><p><strong>Criteri go/no-go di B-W0.</strong> GO solo se passano tutti.</p><ol><li>Senza modifiche a <code>packages/workbench</code>: apertura vault, modifica, salvataggio, eventi; <code>errorCode(e) === &#39;conflict&#39;</code> su un conflitto reale.</li><li>Chiusura con modifica non salvata (pulsante, Cmd+Q, Alt+F4, Quit dall&#39;updater): file scritto 20 volte su 20 per OS, <code>app:before-close</code> emesso una sola volta, processo terminato entro 5 s.</li><li><code>clarae://</code> a freddo e a caldo e callback OIDC: 10 su 10 per OS.</li><li>Single-instance su Ubuntu 22.04 e 24.04 con 50 data dir casuali.</li><li>Drop di un PNG da Finder, Explorer e Nautilus nell&#39;editor e su Excalidraw; rilascio fuori zona senza navigazione.</li><li>Menu esatto su macOS, nessuna barra altrove.</li><li>Nessun segreto nel log a livello debug.</li><li><code>SaveHTML</code> a 65 e 200 MiB, <code>SaveAttachment</code> da 32 MB, una chiamata pendente 3 minuti con altre 8 in corso.</li><li>CSP di produzione invariata, zero violazioni; un iframe iniettato non carica.</li><li>Dev con ricarica di Go e UI su <code>127.0.0.1:5173</code>.</li><li>Aggiornamento 1.3.4 → v3 tramite l&#39;updater, su canale di staging. Criterio rivisto il 2026-11-11: per M15 vale l&#39;installazione manuale sopra la 1.3.4 su ogni sistema operativo (le build pubblicate non hanno l&#39;updater); l&#39;updater si prova solo per build con chiave.</li><li>macOS: titlebar trascinabile, scorciatoie di modifica, About, fullscreen, stampa. Dialoghi di file e cartella sui tre OS.</li></ol><p>No-go su chiusura, deep link, aggiornamento, single-instance o drop senza rimedio in due giorni: si resta su v2.17.1 e si tengono B-W2 e B-W3. Regola del piano per lo spike, che ha dato GO con condizioni: dal 2026-11-11 non esiste più un ritorno a v2 (vedi «Nessun rollback» sotto).</p><p><strong>Nessun rollback a v2</strong> (decisione dell&#39;owner, 2026-11-11). In caso di problemi gravi, cioè un P0 della matrice (perdita dati alla chiusura, login o deep link rotti, installazione sopra la 1.3.4 fallita, crash all&#39;avvio), si corregge in avanti su v3 con una nuova versione. Non si prepara né si prova un rilascio v2 di ritorno, e non servono un ramo o un tag di appoggio.</p><p><strong>Assunzioni adottate</strong> (da confermare con ADR-0051; se una cambia, cambiano le onde indicate): il runtime JS di v3 (circa 60 kB) resta fuori dal conteggio «initial» del bundle, come il runtime iniettato di v2 (B-W0, B-W5); l&#39;export HTML fino a 256 MiB è una funzione esistente e va mantenuta, con l&#39;onda B-W4b se lo spike conferma il tetto di 64 MiB (B-W0, B-W4b); le prove di aggiornamento via updater, necessarie solo per build con chiave, usano una 1.3.4 ricostruita con chiave e URL di staging (B-W0, B-W7); non c&#39;è rollback a v2 (decisione dell&#39;owner, 2026-11-11).</p><p><strong>Cambia per l&#39;utente:</strong> su macOS e Linux l&#39;elenco degli strumenti recenti di Excalidraw si azzera una volta (l&#39;origine passa da <code>wails://wails</code> a <code>wails://localhost</code>); il minimo di macOS dichiarato passa da 10.13 a 13 (il linker di Go 1.27 compila per macOS 13; la 1.3.4 dichiarava 10.13 su Intel e 11.0 su Apple Silicon, senza una prova di avvio sotto macOS 13); una chiamata a un binding che va in panic ora viene rifiutata, in v2 non si risolveva mai. Il resto resta com&#39;è, con voce nella matrice di QA.</p><p><strong>Criteri di uscita M15:</strong> ADR-0051 accettato; spike B-W0 con esito GO su tutti i criteri; binding generati senza la CLI Wails con output identico a v2; <code>internal/app</code> senza dipendenza da Wails; chiusura con modifica non salvata, <code>clarae://</code>, single-instance e drop di file verificati sui tre OS; installazione manuale sopra la 1.3.4 provata su ogni sistema operativo (l&#39;aggiornamento via updater solo per build con chiave); stessi nomi di artefatto e stessi installer; nessun segreto nel log a livello debug e CSP di produzione invariata; zero P0 e P1 nella matrice di QA; <code>task ci</code> verde e <code>rg wails/v2</code> vuoto.</p><p><strong>Stato dei criteri di uscita M15 (2026-11-11):</strong></p><ul><li>ADR-0051 accettato: <strong>no</strong> (proposta).</li><li>Spike B-W0: GO con condizioni; condizioni soddisfatte: B-W4b (upload a chunk) e runtime fuori dall&#39;entry (chunk dinamico); le prove manuali sono state fatte solo su macOS.</li><li>Binding generati senza la CLI Wails con output identico a v2 (B-W2): sì; <code>internal/app</code> senza dipendenza da Wails: sì (<code>go list -deps</code>).</li><li>Chiusura con modifica non salvata, <code>clarae://</code>, single-instance e drop di file sui tre OS: <strong>solo macOS</strong> (chiusura, deep link e single-instance con il binario reale; drop con test sintetici); Windows e Linux non provati.</li><li>Installazione manuale sopra la 1.3.4 su ogni sistema operativo (criterio di aggiornamento, decisione dell&#39;owner del 2026-11-11): <strong>non eseguita</strong> (<code>docs/qa/m15-wails3-matrice.md</code> §1.1, nessuna riga spuntata). Le build pubblicate non hanno l&#39;aggiornamento automatico (<code>.github/workflows/release.yml:112</code> imposta <code>ALLOW_UNSIGNED_UPDATES</code> senza chiave pubblica; <code>README.md:29-30</code>: «le nuove versioni si installano a mano»); l&#39;aggiornamento via updater (§3 della matrice) resta da provare solo per build con chiave. Nessun rollback a v2.</li><li>Stessi nomi di artefatto e stessi installer: sì su macOS (<code>.dmg</code>) e come cross-build Windows (<code>render-assets</code> identico a <code>nsis-render</code> per <code>wails_tools.nsh</code>); Linux non provato.</li><li>Nessun segreto nel log a livello debug e CSP di produzione invariata: sì (logger a Warn con test e smoke del binario; <code>cspMiddleware</code> invariato).</li><li>Zero P0 e P1 nella matrice di QA: <strong>matrice manuale non eseguita</strong>; la parte automatica di B-W8 (2026-11-11) è verde, con un solo giro fallito per un problema d&#39;ambiente.</li><li><code>task ci</code> verde e <code>rg wails/v2</code> vuoto: <strong>no</strong>; <code>task ci</code> non è stato rieseguito dalle catene di QA e di revisione. <code>deploy/PINS.md</code> ora cita <code>wails/v2</code> solo per vietarlo; restano il binario versionato <code>apps/desktop/desktop</code> (la rimozione si decide al momento dei commit: non è stato cancellato) e le citazioni legittime nel generatore dei binding (attribuzione del codice portato da v2, <code>regen-golden.sh</code>) e nei documenti.</li></ul><p><strong>Esito di B-W8, parte automatica (2026-11-11).</strong> Mac in alimentazione di rete, Docker 29.9.3, suite lunghe sotto <code>caffeinate -i</code>.</p><table tabindex="0"><thead><tr><th>Prova</th><th>Esito</th><th>Conteggi</th><th>Durata</th></tr></thead><tbody><tr><td><code>task test-integration</code></td><td>verde</td><td><code>test/integration</code> ok</td><td>2 min 16 s</td></tr><tr><td><code>task test-desktop-e2e</code></td><td>verde</td><td><code>internal/sync</code> e <code>internal/sync/transport</code> ok</td><td>3 min 49 s</td></tr><tr><td><code>task e2e</code></td><td>verde</td><td>127 + 43 + 94 = 264 passati, 36 saltati (solo desktop-mock)</td><td>3 min 24 s</td></tr><tr><td><code>task e2e-matrix</code>, primo giro</td><td>4 falli d&#39;ambiente</td><td>245 passati, 4 falliti, 77 saltati</td><td>11 min 15 s</td></tr><tr><td><code>task e2e-matrix -- drawing-wp5 drawing-embed --repeat-each=3</code></td><td>verde</td><td>114 passati, 0 falliti, 6 saltati</td><td>8 min 24 s</td></tr></tbody></table><ul><li><strong>Fallo del primo giro:</strong> <code>drawing-wp5.spec.ts:79</code> e <code>:93</code> su desktop-mock, <code>drawing-embed.spec.ts:105</code> e <code>:125</code> su web-core, tutti con <code>browserContext.close: ENOENT</code> su un file di traccia sotto <code>.dev/e2e-matrix/5199-5176/test-results/</code>, mai un&#39;asserzione: un altro <code>e2e:workbench-ui</code> girava sulla stessa macchina. Classificato come ambiente; il rilancio isolato è pulito. <strong>Non verificata:</strong> la matrice intera in un giro pulito, a macchina libera: da rifare.</li><li><strong>Smoke del binario v3</strong> (macOS universale, versione <code>1.3.5-qa</code>, build di 17 s con cache calda): avvio in 1,4 s; seconda istanza con la stessa data dir e <code>clarae://open?…</code> inoltra l&#39;URL e termina con codice 0 in 0,6 s; con un&#39;altra data dir convive; SIGTERM chiude entrambi i processi in 0,15 s, senza processi residui; <code>check-build-tags.sh</code> ok su x86_64 e arm64; <code>go version -m</code>: <code>-tags=production</code>, <code>-trimpath=true</code>, <code>CGO_ENABLED=1</code>, Go 1.27.4, nessuna traccia di <code>mcp</code>, <code>server</code> e <code>devtools</code>, porta 9099 non in ascolto; 129.624.928 byte contro 127.936.608 della 1.3.4 installata (+1,3%, entrambe universali); il <code>.dmg</code> non è stato costruito.</li><li><strong>Non verificato:</strong> l&#39;apertura effettiva della nota da deep link (nello smoke non c&#39;era un vault), la chiusura con nota sporca, Windows, Linux e macOS Intel; restano a mano finestra nativa, drop dei file, dialoghi e l&#39;installazione manuale sopra la 1.3.4. Esiti nel dettaglio in <code>docs/qa/m15-wails3-matrice.md</code>, sezione «Esiti automatici (2026-11-11)».</li></ul><p><strong>Esito della revisione finale di B-W9 (2026-11-11): Fail.</strong> Il codice della Parte B regge (identità dell&#39;installazione invariata, dati di WebView2 e data dir invariati, licenze <code>LICENSE-wails.txt</code> e <code>LICENSE-typescriptify.txt</code> presenti, nessun segreto, nessun test indebolito). Rilievi:</p><ol><li><strong>Media, processo: il rollback v3 → v2 punta a un commit che non esiste. Chiuso dalla decisione dell&#39;owner (2026-11-11): nessun rollback a v2</strong>, i problemi gravi si correggono in avanti su v3. Il fatto resta vero (<code>git log v1.3.4..HEAD</code> contiene solo <code>2451abb</code> e <code>bd9efc3</code>: B-W2…B-W9, la Parte A e Go 1.27.4 sono non committati, sullo stesso albero di <code>main</code>) ma non serve più una base di rollback. I commit sono richiesti a fine ondata, dopo <code>task ci</code> verde, su un ramo dedicato e non su <code>main</code>.</li><li><strong>Media, test-gap: la matrice provava solo l&#39;aggiornamento via updater, assente dalle build pubblicate. Chiuso dalla decisione dell&#39;owner (2026-11-11):</strong> il criterio di aggiornamento di M15 è l&#39;installazione manuale sopra la 1.3.4 su ogni sistema operativo (NSIS sopra la 1.3.4 con la stessa <code>UNINST_KEY</code> e <code>InstallDir</code>, <code>.app</code> trascinata sulla vecchia, <code>apt install</code> del <code>.deb</code>): <code>docs/qa/m15-wails3-matrice.md</code> §1.1, <strong>da eseguire</strong> (nessuna riga spuntata). L&#39;aggiornamento via updater (§3) resta da provare solo per build con chiave.</li><li>Bassa: in §3.3 della matrice l&#39;installer Windows (<code>clarae-amd64-installer.exe</code>) non è rinominato e <code>classify</code> (<code>tools/release/main.go:64-67</code>) lo scarta in silenzio; la matrice (§3.3) ora ha il passo di rinomina, come in <code>release.yml</code>.</li><li>Bassa: la matrice (<code>:98</code>) dice che su macOS il trasporto è il «canale nativo dei messaggi»; B-W4b ha scelto l&#39;upload a blocchi sull&#39;asset server; la frase della matrice è allineata all&#39;ADR.</li><li>Bassa: <code>scripts/build-desktop-bin.sh:121-128</code> ereditava <code>CLARAE_LIVE_ENGINE</code> (rimossa il 2026-11-12, A-W9 di M16), <code>CLARAE_AI</code>, <code>CLARAE_COLLAB</code> e <code>CLARAE_E2E</code> dall&#39;ambiente: un rilascio da una shell che le esporta sarebbe uscito con Milkdown o con il mock dei binding. <strong>Chiuso in W8 (catena della build):</strong> <code>build-desktop-bin.sh --release</code> e <code>release/build-desktop.sh --release</code> (che <code>task release-desktop</code> passa sempre), <code>task web-build</code> e il Dockerfile del cloud eseguono <code>scripts/release/check-editor-switches.sh</code>, che rifiuta le quattro variabili e anche <code>CLARAE_DIST</code>, e <code>scripts/release/check-dist.sh</code>, che cerca Milkdown e il mock dei binding nel <code>dist</code> costruito (dal 2026-11-12 cerca la collaborazione, <code>y-prosemirror</code>, e il mock, e pretende il chunk di Milkdown: Milkdown è il Live di ogni build). Non è agganciata a <code>task ci</code>, che non costruisce nessun <code>dist</code>: sta nelle build di rilascio. La build Docker non è provata sotto <code>docker build</code>.</li><li>Bassa: restavano riferimenti a v2 in <code>apps/desktop/internal/app/services_test.go:47</code> (<code>wails.json</code>), <code>cmd/clarae-core/core_js.go:98</code> e <code>doc.go:40</code>, <code>web/src/workbench/bridge.ts:72</code> (OnDomReady di Wails), <code>deploy/PINS.md:46</code> e <code>docs/qa/m15-wails3-matrice.md:15</code> (log in uno scratchpad di sessione). <strong>Chiuso in W8:</strong> i commenti sono riscritti (<code>App.Startup</code>/<code>DomReady</code>/<code>Shutdown</code>, <code>Lifecycle.Start</code>/<code>Stop</code>, generatore <code>internal/app/gen/bindings</code>), <code>deploy/PINS.md</code> prescrive <code>wails/v3</code> con pin esatto e vieta <code>wails/v2</code>, e la matrice non rimanda più a uno scratchpad.</li></ol><p>Eseguiti dalla revisione: <code>go test -race</code> di <code>internal/shell</code>, <code>internal/platform</code>, <code>internal/telemetry</code>, <code>internal/rpc</code>, <code>build/</code> e del package principale; <code>go vet</code> per <code>GOOS=windows</code> e per <code>GOOS=js GOARCH=wasm</code>; <code>go list -deps</code> senza <code>wailsapp</code> per <code>internal/app</code>, <code>cmd/clarae-core</code> e il generatore dei binding; generatore con <code>-check</code>; <code>go mod tidy -diff</code>; <code>install-wails.sh --check-pins</code> e <code>--check</code>; <code>bash -n</code> sugli 8 script. <strong>Non rieseguiti:</strong> vitest dello shim, <code>task ci</code>, <code>task parity</code>, <code>task docker-build</code>, e2e, build Linux con <code>gtk3</code>, Windows reale, Mac Intel, <code>release.yml</code> su un runner, qualunque aggiornamento reale.</p><p><strong>Decisioni dell&#39;owner (2026-11-11) e stato (B-W9).</strong> Decise: nessun rollback a v2; criterio di aggiornamento di M15 = installazione manuale sopra la 1.3.4. Fatte: <code>.go-version</code> è ora <code>go1.27.4</code>, allineato a <code>apps/desktop/go.mod</code> e agli altri moduli; l&#39;avviso per chi è su macOS 12 (serve macOS 13: <code>LSMinimumSystemVersion</code> <code>13.0.0</code> in <code>apps/desktop/build/darwin/Info.plist</code>) è nelle note di compatibilità del CHANGELOG, sezione <em>Unreleased</em>; <code>CLAUDE.md</code> è aggiornato nei fatti diventati falsi (Wails v3.1.0, <code>task dev-desktop</code> con <code>wails3 tool watcher</code>, binding da <code>internal/app/gen/bindings</code>), e il vincolo «Wails v2» è segnalato come in revisione con ADR-0051 in proposta. <strong>Ancora da decidere, al momento dei commit:</strong> la rimozione del binario versionato <code>apps/desktop/desktop</code> (5 MB, M0; non cancellato), che blocca <code>rg wails/v2</code> vuoto. <strong>Da tenere d&#39;occhio:</strong> il filtro dei log (<code>UIRuntimeLogger</code>) dipende dal testo di Wails 3.1.0 e va ricontrollato a ogni aggiornamento.</p><p><strong>Punti da tenere d&#39;occhio:</strong> issue aperte upstream sulla chiusura (6368, 6375, 6570) e sui dialoghi di file (6355, 6558); minor settimanali di v3 (pin esatti, superficie Wails in pochi file); budget del bundle; <code>golangci-lint</code> e <code>govulncheck</code> con il tag <code>gtk3</code> su Linux; specifica da aggiornare dall&#39;owner (V-07, A-03, D-07, §4.2, §4.5, C.2).</p><h2 id="_13-nonies-m16-—-editor-live-su-milkdown" tabindex="-1">13-nonies. M16 — Editor Live su Milkdown <a class="header-anchor" href="#_13-nonies-m16-—-editor-live-su-milkdown" aria-label="Permalink to &quot;13-nonies. M16 — Editor Live su Milkdown&quot;">​</a></h2><p>Richiesta del 2026-11-10: usare Milkdown (Crepe) come editor Markdown, con tutte le feature di Crepe più emoji con asset locali, highlight, automd, upload, diff e streaming; collaborazione (Yjs) integrata e spenta; AI implementata ma inattiva; tutte le funzioni esistenti mantenute. Milkdown sostituisce Live Preview; Source resta su CodeMirror 6 (i <code>.marp</code> restano in Source) e Reading è invariata. Le decisioni sono <a href="./adr/0049-editor-live-milkdown.html">ADR-0049</a> (editor; supera in parte ADR-0004) e <a href="./adr/0050-ai-inattiva-e-collab-spento.html">ADR-0050</a> (AI e collaborazione spente), ADR-0049 <strong>accettato il 2026-11-12</strong> (decisione dell&#39;owner, vedi A-W9), ADR-0050 in stato <strong>proposta</strong>. Deviano da <code>Specifications.md</code> (§2.3.1–§2.3.3 <code>:414</code>, <code>:419-429</code>, <code>:431-440</code>, §3.4.2 <code>:1084</code>, §4.2 <code>:1746-1748</code> e <code>:1769</code>, §2.6.6 <code>:579</code>): lo spec non viene toccato, lo aggiorna l&#39;owner. Il piano non è versionato. Ogni onda si chiude con <code>task ci</code> verde e i commit <code>[M16-Wn.m]</code>, su richiesta.</p><p><strong>Stato: in corso (2026-11-12): A-W9 fatta.</strong> <strong>Decisione dell&#39;owner del 2026-11-12: Milkdown è l&#39;unico motore Live e il predefinito, senza attendere le prove manuali di A-W8</strong> (IME, spellcheck e lettori di schermo sulle tre WebView): l&#39;interruttore <code>CLARAE_LIVE_ENGINE</code> e il CodeMirror Live Preview sono rimossi (vedi «Esito di A-W9»); le prove manuali restano <strong>da fare</strong> e non sono passate. A-W0 eseguito (esito: NO-GO alla lettera del piano; lo spike raccomandava GO con condizioni, ora attuate); A-W1…A-W7 fatte, con gli esiti nella tabella; A-W8 (cancello di parità): <strong>parte automatica eseguita, prove manuali non fatte</strong> (IME, spellcheck, lettori di schermo, incolla da app esterne, note reali grandi, shell v3) <strong>e della decisione dell&#39;owner sul default</strong>. Stato dopo W8 (2026-11-11): la causa seria della caccia differenziale (task con primo paragrafo vuoto seguito da un blocco) e le cause 2, 3 e 4 sono corrette, e l&#39;accessibilità del Live di Milkdown (liste, contrasto, nome delle caselle) è corretta, ciascuna con un test che fallisce senza la correzione; i due rilievi della revisione W8 (la casella di un task nato da un bullet nascosta ai lettori di schermo; un <code>%%</code> incollato nell&#39;etichetta di un wikilink) sono stati corretti in W9, e la caccia di W9 e la revisione di W9 hanno trovato altre divergenze, corrette in W10 (vedi «Stato dopo W9 e W10»); restano aperte le cause 6 e 7, il titolo con <code>[[^1]](url)</code> e i casi non seri della caccia di W9 (vedi «Esito del cancello A-W8»). <strong>Fase di consolidamento avviata il 2026-11-12:</strong> chiusi i tre casi seri della revisione di W10 (vedi «Consolidamento») e fatto il passo <code>[M16-UX1]</code>, che porta Live all&#39;esperienza del playground di Crepe (vedi «Consolidamento, passo <code>[M16-UX1]</code>»). <strong>La caccia differenziale non è esaurita:</strong> ogni giro ha chiuso le divergenze trovate e ne ha trovate di nuove in sequenze meno comuni. Decisione dell&#39;owner del 2026-11-11 (<strong>superata il 2026-11-12</strong>): Milkdown sarebbe rimasto dietro l&#39;interruttore di build fino alle prove manuali (IME, spellcheck e lettori di schermo su WKWebView, WebView2 e WebKitGTK; apertura delle note grandi), e A-W9 sarebbe rimasta in attesa; il 2026-11-12 l&#39;owner ha deciso di invertire il default e rimuovere il vecchio Live senza quelle prove. La revisione finale della Parte A (2026-11-11) è <strong>Pass con riserve</strong>: nessun rilievo alto o medio, sei bassi. Dal 2026-11-12 <strong>ogni build ha Live su Milkdown</strong>; Source resta CodeMirror 6 e Reading è invariata; AI e collaborazione sono implementate e inattive. L&#39;ADR-0049 è accettato (non ancora recepito nello spec); l&#39;ADR-0050 resta in proposta. In parallelo a M15, da subito: A-W0 (spike), A-W1 (ADR) e A-W2 (refactor sul solo CodeMirror) toccano file disgiunti dalla Parte B. Vincoli fra le parti: A-W6 (servizio AI nel core Go) parte dopo B-W2, così <code>AIAPI</code> passa dal nuovo generatore dei binding una volta sola; A-W8 (cancello di parità con IME e spellcheck sulle tre WebView) si esegue sulla shell v3, cioè dopo B-W8. Il margine sul bundle iniziale era di 7 kB dopo <code>[M16-UX1]</code> (1993 su 2000 kB sul desktop, 2493 su 2500 sul web, a interruttore spento: erano 21 kB di partenza, 8 kB prima del passo) ed era condiviso con M15; con A-W9 l&#39;entry desktop è di 1376 kB e il margine è di circa 624 kB (web workbench 1925 su 2500).</p><table tabindex="0"><thead><tr><th>Onda</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td>A-W0 — Spike</td><td>Ramo usa e getta (frontend-developer, qa-engineer; decide il reviewer). Criteri go/no-go sotto</td><td>eseguito, esito: NO-GO alla lettera del piano (criteri 1, 2, 5 falliscono; 4 e 6 passano con configurazione); decisione all&#39;owner</td></tr><tr><td>A-W1 — ADR e roadmap</td><td>ADR-0049 e ADR-0050 in proposta; questa sezione; indice ADR (docs-writer). Uscita: indice aggiornato, spec intatto</td><td>fatto (in attesa di accettazione degli ADR); esiti dello spike riportati in ADR-0049</td></tr><tr><td>A-W2 — Maniglia sul solo CodeMirror</td><td><code>editor/handle.ts</code>, <code>editor/types.ts</code>, adattatore CM; 13 consumer migrati; <code>scanInline</code> esportato; voci slash a id di comando; <code>SourceEdit</code>. Uscita: suite di contratto verde su CM; ESLint vieta <code>@codemirror/*</code> fuori da <code>editor/source</code>; e2e invariati</td><td>fatto con deviazioni (vedi sotto)</td></tr><tr><td>A-W3 — Fedeltà e OFM senza UI</td><td>Busta, tabella, composizione, nodi raw, override dei nodi upstream, <code>conformance.test.ts</code>, corpus in <code>shared/conformance/roundtrip/</code>, <code>.prettierignore</code>. Uscita: invariante di escape e criteri di round-trip bloccanti in <code>task conformance</code></td><td>fatto (2026-11-11): busta, tabella, composizione, nodi <code>raw</code>, override dei nodi upstream, corpus di 1075 file e <code>conformance.test.ts</code>. Cancello A rimisurato: C1 1074/1074, C1-edit 35041/35041, C2 4266/4267 (99,98%), C3 1074/1074, C4 0 sporchi. Resta una divergenza nota (fence non chiusa in una voce con <code>%%</code>)</td></tr><tr><td>A-W4 — <code>MilkdownEditor</code> dietro interruttore di build</td><td>Reload esterno, sola lettura, hotkey, cambio modalità con spina CM, guardia di ripiego. Uscita: suite di contratto verde sui due adattatori; bundle iniziale entro budget su desktop e web</td><td>fatto (2026-11-11): <code>MilkdownEditor</code> dietro <code>CLARAE_LIVE_ENGINE=milkdown</code> (interruttore rimosso in A-W9), con ripiego su Source e reload esterno rifiutato che non perde più la modifica. Entry desktop 1992 su 2000 kB, web 2492 su 2500: nessun limite alzato</td></tr><tr><td>A-W5a — Viste e link</td><td>Wikilink, embed, callout, math, mermaid, query, tag, clic con Mod/Alt, hover. Uscita: le righe di parità toccate hanno un test verde su desktop-mock e web-core con motore Milkdown</td><td>fatto (2026-11-11): wikilink, embed, immagini, callout con fold, math, mermaid, query, tag, commenti, HTML, Mod+clic e hover; e2e <code>live-views</code> su desktop-mock e web-core</td></tr><tr><td>A-W5b — Input</td><td>Completamenti, slash (con le voci <code>insert</code> a caret ancora da convertire in comandi), incolla, drop con posizione mappata, upload, automd, emoji locali, autoPair, casella dei task, <strong>riordino delle voci di lista (Alt+↑/↓)</strong>. Uscita: come A-W5a</td><td>fatto (2026-11-11): completamenti, slash, incolla e drop con allegati, autoPair, task, riordino Alt+↑/↓, input rule OFM. <code>plugin-automd</code> non incluso (rompe nodi OFM); e2e <code>live-input</code></td></tr><tr><td>A-W5c — Cornice</td><td>Toolbar, <code>FindBar</code>, vai a riga, fold dei heading <strong>e delle voci di lista, dei blockquote, dei code block e delle tabelle</strong> (oggi in Live ripiegabili con <code>foldGutter</code>), impostazioni, highlight del codice (non con <code>plugin-highlight</code>, inapplicabile ai code block di Crepe). Uscita: come A-W5a</td><td>fatto (2026-11-11): ricerca propria, vai a riga, fold di heading, voci, quote, code block e tabelle, impostazioni dinamiche, colori dei code block, comandi <code>editor:find</code> e <code>editor:goto-line</code>. <code>prosemirror-search</code> non usato, TopBar di Crepe spenta; e2e <code>live-frame</code>, <code>editor-find</code></td></tr><tr><td>A-W6 — AI inattiva</td><td>In parallelo a A-W5 e dopo B-W2 (desktop-core-developer, frontend-developer, cloud-developer). Uscita: test Go «zero richieste» verdi; <code>task parity</code> e <code>task check-gen</code> verdi; core WASM entro 8192 kB</td><td>fatto (2026-11-11): <code>internal/ai</code>, <code>AIAPI</code>, eventi, flag nello schema, stub <code>js</code>, fail-closed sui vault privati, redazione della chiave prima del taglio; <code>attachAi</code> collegato dietro l&#39;interruttore. Core WASM 7.040 kB gzip su 8192. <code>task check-gen</code> è fragile se il repository cambia durante l&#39;esecuzione</td></tr><tr><td>A-W7 — Collab spento</td><td>Uscita: un profilo con <code>collab: true</code> non carica il chunk</td><td>fatto (2026-11-11): chunk <code>collab</code> dietro costante di build, flag e provider registrato (nessuno); plugin <code>liveCollab</code> che lo sostituisce con uno stub nelle build senza costante; test di convergenza su due <code>Y.Doc</code> e e2e <code>live-collab</code></td></tr><tr><td>A-W8 — Cancello di parità</td><td>Sulla shell v3: perf, axe, prova manuale di IME e spellcheck sulle tre WebView; poi Milkdown diventa il default. Uscita: <code>task ci</code> e <code>task e2e-matrix</code> verdi sui due motori; verdetto Pass</td><td><strong>parte automatica eseguita (2026-11-11), in attesa delle prove manuali e della decisione dell&#39;owner sul default.</strong> Matrice e2e sui due motori, budget, <code>live:metrics</code>, soglia <code>LIVE_MAX</code>, rete e CSP: passano; prestazioni: nessun criterio violato, con l&#39;apertura circa 10 volte più lenta di CodeMirror (2,5 s a 200 kB); accessibilità: <strong>NON PASS</strong> (corretta in W8 e W9); verdetto Pass non dato. Dettagli sotto. <strong>Decisione dell&#39;owner del 2026-11-12: default Milkdown senza le prove manuali, che restano da fare</strong></td></tr><tr><td>A-W9 — Rimozione del vecchio Live</td><td><code>livePreview.ts</code>, <code>blockWidgets.ts</code>, <code>widgets.ts</code>, <code>callouts.ts</code>, <code>query/widget.ts</code>, selettori <code>.cm-lp-*</code> e interruttore; <code>features.yaml</code>, CHANGELOG (frontend-developer, docs-writer). Uscita: <code>task ci</code> verde; bundle misurato e annotato in roadmap</td><td><strong>fatto (2026-11-12), per decisione dell&#39;owner, senza le prove manuali di A-W8.</strong> Interruttore, <code>livePreview.ts</code>, <code>blockWidgets.ts</code>, <code>widgets.ts</code>, <code>callouts.ts</code>, <code>query/widget.ts</code>, <code>livePreviewContext</code> e i selettori <code>.cm-lp-*</code> rimossi; <code>editor/source/</code> raccoglie i moduli solo-CodeMirror; Twemoji credita CC-BY in «Informazioni» e nel README. Bundle: desktop 1376/18368 kB (limiti 2000/23000), web workbench 1925/16414 (2500/23000), console 698/700, core WASM 7103 kB gzip su 8192. <code>task ci</code> verde (dichiarato). Dettagli in «Esito di A-W9»</td></tr></tbody></table><p><strong>Esito dello spike A-W0 (2026-11-10, Milkdown/Crepe 7.23.0, corpus di 914 file).</strong> <strong>Alla lettera del piano è un NO-GO</strong>: i criteri 1, 2 e 5 falliscono, 4 e 6 passano con una configurazione precisa; la decisione di procedere spetta all&#39;owner (lo spike raccomanda GO con condizioni). Per criterio (misure in <a href="./adr/0049-editor-live-milkdown.html">ADR-0049</a>): 1 <strong>fallisce</strong> (con tutti i blocchi sporchi <code>extract()</code> uguale su 797/914, 87%, e HTML di Reading su 846/914, 93%; strato di conservazione e prototipo OFM rozzi); 2 <strong>fallisce</strong> sul totale (≤1 riga nell&#39;83,9% di 4283 casi contro il 95%) e passa sul sottoinsieme senza blocchi «raw» (99,1%); 3 passa (dieci giri idempotenti in 910/914); 4 fallisce di default (<code>trailing</code> aggiunge un paragrafo vuoto nel 36,9% dei documenti) e <strong>passa</strong> con <code>trailingConfig.shouldAppend = () =&gt; false</code> (0/236); 5 <strong>fallisce</strong> (iniziale desktop 2012 kB su 2000, web 2565 su 2500; il CSS lazy di Crepe non è collegato dal desktop); 6 fallisce di default (Twemoji da <code>cdn.jsdelivr.net</code>) e <strong>passa</strong> con svg locali; 7 passa con configurazione (icone con <code>aria-label</code>, <code>buildTopBar</code>: 0 violazioni axe sulla TopBar); 8 passa per la meccanica DOM (il cablaggio a <code>commandForEvent</code> non è provato); 9 passa con due shim per jsdom; 10 non verificabile qui (nessun IME né WKWebView). Condizioni per un eventuale GO: blocchi raw in A-W3 e nuova misura (100% di <code>extract</code> e HTML uguali sul corpus non avversario, ≥95% a ≤1 riga); configurazione di <code>trailing</code>, <code>tablePipeAlign: false</code>, <code>remark-emoji</code> escluso, override di image-block e Latex, Twemoji locale; budget alzato (desktop +12 kB, web +65 kB) o entry tagliata; TopBar solo con icone etichettate; prova IME su WKWebView prima di A-W8. <code>plugin-highlight</code> non si applica ai code block di Crepe e va scartato.</p><p><strong>A-W2 — fatto con deviazioni accettate dalla revisione.</strong> La maniglia, l&#39;adattatore CodeMirror e la suite di contratto ci sono; il refactor è puro. Due uscite sono soddisfatte solo in parte (deviazioni accettate dalla revisione) e sono registrate qui:</p><ul><li><strong>Regola ESLint con eccezioni.</strong> <code>@codemirror/*</code> e <code>@lezer/*</code> sono vietati fuori da <code>editor/source</code>, ma <code>eslint.config.js</code> (<code>engineExempt</code>) esenta 15 file, di cui due fuori da <code>editor/</code> (<code>slash/slash.ts</code>, <code>query/widget.ts</code>); <code>no-restricted-imports</code> non intercetta gli <code>import()</code> dinamici. <strong>Le eccezioni si tolgono in A-W9</strong>, con la rimozione del vecchio Live (o si spostano in <code>editor/source</code>). <strong>Fatto in A-W9 (2026-11-12):</strong> <code>engineExempt</code> in <code>eslint.config.js</code> si riduce a <code>packages/workbench/src/editor/source/**</code>; i 15 file esentati sono stati cancellati o spostati lì.</li><li><strong>Slash.</strong> Solo le voci <code>h1</code>, <code>h2</code> e <code>h3</code> sono già comandi (<code>exec</code>); le voci <code>insert</code> con caret <code>|</code> (callout, code, table e simili) restano come sono <strong>fino ad A-W5b</strong>.</li></ul><p><strong>Criteri go/no-go di A-W0.</strong> Corpus: esempi CommonMark e GFM, casi OFM, seme del vault demo (va estratto da <code>seed_demo_vault</code>, <code>scripts/lib.sh:128</code>), varianti CRLF e BOM.</p><ol><li>Con tutti i blocchi forzati sporchi, <code>extract()</code> e l&#39;HTML di <code>reading/render.ts</code> sono identici prima e dopo.</li><li>Località a righe: un carattere inserito dà un diff di al più una riga in almeno il 95% dei casi; la spunta di un task in una lista annidata di 200 voci dà una riga.</li><li>Dieci giri di round-trip sono idempotenti.</li><li>Nessun blocco diventa sporco senza input: caricamento, hover, clic sul fold, apertura dei tooltip.</li><li>Bundle desktop e web entro budget con tutti i chunk.</li><li>Zero violazioni della CSP di produzione e zero richieste esterne.</li><li>Nomi accessibili e i18n del chrome di Crepe.</li><li>Le hotkey arrivano a <code>commandForEvent</code> anche da code block, cella di tabella e tooltip.</li><li>L&#39;editor si monta in jsdom (<code>App.test.tsx:74</code> lo richiede); una sola istanza di <code>@codemirror/state</code>, <code>katex</code>, <code>vue</code>.</li><li>Prova di IME su WKWebView.</li></ol><p>No-go su 1, 2, 4 o 6: l&#39;intervento si ferma e si torna all&#39;owner con i dati.</p><p><strong>Assunzioni adottate</strong> (da confermare con gli ADR; se una cambia, cambiano le onde indicate): la TopBar di Crepe non ha nomi accessibili, i18n né undo/redo, quindi <code>EditorToolbar</code> resta la barra accessibile in entrambe le modalità; la TopBar si accende solo se lo spike la rende accessibile e tradotta con <code>buildTopBar</code>, e una <code>yarn patch</code> di Crepe richiede il consenso dell&#39;owner (A-W0, A-W5c); AI e collab hanno un doppio cancello, flag del Config Profile e costante di build, e nelle build rilasciate non sono accendibili senza una nuova release (A-W6, A-W7); numeri di riga, multi-cursore e selezione rettangolare restano solo in Source, la ricerca in Live cerca il testo reso e la colonna in barra di stato è approssimata dentro il blocco (A-W5c, ADR-0049).</p><p><strong>Cambia per l&#39;utente</strong> (dal 2026-11-12, per tutti: Milkdown è l&#39;unico motore Live; elenco completo in ADR-0049 §9, che ora comprende anche Invio e Shift+Invio, Tab, gli atomi raw non modificabili, <code>[[x</code> non chiuso, il math in linea, il popup slash proprio e la rinumerazione delle liste): la sintassi sulla riga attiva è sostituita dal WYSIWYG (wikilink ed embed mostrano il sorgente quando il cursore è dentro); numeri di riga, multi-cursore, selezione rettangolare, match della selezione, parentesi abbinate, riga attiva e completamento dei nomi di property solo in Source; l&#39;undo non attraversa Live↔Source; i documenti oltre la soglia si aprono in Source con avviso; il primo Live aperto carica un chunk lazy; i code block di Live sono nel carattere a spaziatura fissa e con meno margine interno; la ricerca nella nota è quella di Live (testo reso, con espressioni regolari) e il pannello di ricerca di CodeMirror c&#39;è solo in Source; la colonna in barra di stato è approssimata dentro il blocco; i file CRLF migliorano (i blocchi non toccati conservano CRLF).</p><p><strong>Criteri di uscita M16:</strong> ADR-0049 e ADR-0050 accettati; spike A-W0 con esito GO; un <code>.md</code> aperto e salvato senza modifiche resta byte-identico, e la modifica di un blocco cambia solo le righe del blocco (invariante di escape, località e idempotenza bloccanti in <code>task conformance</code>); ogni riga di parità toccata ha un test verde su desktop-mock e web-core con motore Milkdown; con il flag <code>ai</code> spento, con vault privato o con <code>collab</code> senza provider non parte alcuna richiesta di rete e nessun chunk AI o collab viene caricato; bundle iniziale e totale entro budget su desktop e web, core WASM entro 8192 kB; verdetto Pass del cancello A-W8 (IME e spellcheck sulle tre WebView); <code>task ci</code> e <code>task e2e-matrix</code> verdi sui due motori; vecchio Live rimosso in A-W9. <strong>Stato al 2026-11-12:</strong> vedi sotto; il verdetto Pass di A-W8 non è stato dato e l&#39;owner ha deciso di procedere comunque.</p><p><strong>Stato dei criteri di uscita M16 (2026-11-11):</strong></p><ul><li>ADR-0049 e ADR-0050 accettati: <strong>ADR-0049 sì, il 2026-11-12</strong> (decisione dell&#39;owner, senza le prove manuali di A-W8; non ancora recepito in <code>Specifications.md</code>); <strong>ADR-0050 no</strong> (proposta).</li><li>Spike A-W0: alla lettera NO-GO; le condizioni per il GO sono attuate (blocchi raw e rimisura; <code>trailing</code>, <code>tablePipeAlign</code>, <code>remark-emoji</code> escluso, override di image-block e Latex, Twemoji locale; entry tagliata senza alzare i limiti; TopBar spenta) <strong>tranne la prova IME su WKWebView</strong>, ancora da fare.</li><li>Un <code>.md</code> aperto e salvato senza modifiche resta byte-identico, e la modifica di un blocco cambia solo le righe del blocco: misurato il 2026-11-11 su 1075 file con <code>live:metrics</code> (rieseguito in A-W8, 9 test passati in 146 s, stessi numeri; il fuzz su 4 semi casuali dà 17 divergenze su circa 88.000 modifiche, 99,98%, identiche al cancello A, e 0 su 65.554 con 3 semi «reali»; la caccia differenziale di A-W8 ha però trovato divergenze nuove nei percorsi di modifica che il cancello non misura, vedi sotto) (C1 1074/1074, C1-edit 35041/35041, C2 4266/4267, C3 1074/1074, C4 0 sporchi), e i criteri sono asserzioni di <code>conformance.test.ts</code>; <code>task conformance</code> intero non è stato rieseguito dalla catena di documentazione.</li><li>Righe di parità toccate con un test verde su desktop-mock e web-core con motore Milkdown: sì. <code>task e2e-matrix</code> con <code>CLARAE_LIVE_ENGINE=milkdown</code> ha dato 313 passati, 0 falliti, 13 saltati (11,6 min); con l&#39;interruttore spento 249 passati, 0 falliti, 77 saltati (10,8 min; i 64 saltati in più sono gli spec <code>live-*</code>). Il primo giro con l&#39;interruttore spento fu invalidato da un problema d&#39;ambiente (69 <code>ENOENT</code> per una cartella di risultati cancellata da un processo concorrente) e rilanciato con porte proprie.</li><li>Con il flag <code>ai</code> spento, con vault privato o con <code>collab</code> senza provider non parte alcuna richiesta e nessun chunk AI o collab viene caricato: sì (test Go «zero richieste», <code>ai/wiring.test.ts</code>, <code>collab/wiring.test.ts</code>, e2e <code>live-ai</code> e <code>live-collab</code>); build con <code>CLARAE_AI=1</code> e chunk realmente caricato non provata.</li><li>Bundle iniziale e totale entro budget, core WASM entro 8192 kB: sì, rimisurato in A-W8 (desktop 1992/15998 kB spento e 1375/18304 acceso; web workbench 2492/14041 spento e 1916/16350 acceso; console 698 su 700; core 7102 kB gzip; sqlite 398 su 1536; limiti non alzati). Con le tre variabili spente la build predefinita non contiene Milkdown, ProseMirror, Yjs né il frontend AI (revisione finale A).</li><li>Cancello A-W8: <strong>parte automatica eseguita, verdetto Pass non dato.</strong> Passano matrice sui due motori, budget, metriche, soglia <code>LIVE_MAX</code>, rete e CSP; l&#39;accessibilità era NON PASS (liste) ed è stata corretta in W8 (<code>a11y.spec</code> su una nota ricca, chiaro e scuro, 26/26 con l&#39;interruttore acceso; i due rilievi della revisione W8 sono stati corretti in W9); IME, spellcheck, lettori di schermo e le WebView reali sono da provare a mano sulla shell v3. <code>task ci</code> non è stato rieseguito dalle catene di QA e di revisione (oggi non prova il motore Milkdown). Vecchio Live rimosso (A-W9): <strong>fatto il 2026-11-12</strong>, per decisione dell&#39;owner e senza le prove manuali (restano da fare).</li></ul><p><strong>Esito del cancello A-W8, parte automatica (2026-11-11).</strong> Condizioni: Mac in alimentazione di rete, carico macchina 11–55 per altri agenti in esecuzione (le prestazioni sono indicative), solo Chromium headless contro mock e core WASM. <strong>Nessuna WebView reale e nessuna shell v3: NON VERIFICATO.</strong></p><ul><li><strong>Matrice e2e:</strong> 313 passati, 0 falliti, 13 saltati con Milkdown acceso; 249 passati, 0 falliti, 77 saltati con l&#39;interruttore spento (dettagli nello stato dei criteri sopra).</li><li><strong>Prestazioni</strong> (spec scratch con due ripetizioni per cella; il campionamento a due frame quantizza i valori a circa 16 e 33 ms; <code>ui-perf.spec</code> non distingue i due motori):</li></ul><table tabindex="0"><thead><tr><th>Nota</th><th>Apertura CodeMirror</th><th>Apertura Milkdown</th><th>p50 / p95 CodeMirror (ms)</th><th>p50 / p95 Milkdown (ms)</th></tr></thead><tbody><tr><td>5 kB</td><td>0,15–0,18 s</td><td>0,93–0,96 s</td><td>25 / 33</td><td>17–19 / 31–32</td></tr><tr><td>200 kB</td><td>0,23–0,24 s</td><td><strong>2,53–2,56 s</strong></td><td>26–27 / 32–34</td><td>17–19 / 31–33</td></tr><tr><td>130 kB, circa 2.900 blocchi</td><td>0,14 s</td><td>2,07–2,12 s</td><td>26 / 33</td><td>17 / 31</td></tr><tr><td>300 kB, 160 kB a blocchi, 1 MB</td><td>0,14–0,54 s</td><td>Source con avviso, 0,44–0,47 s</td><td>25–27 / 32–34</td><td>26 / 33</td></tr></tbody></table><p>Oltre <code>LIVE_MAX</code> le note da 300 kB e 1 MB cadono in Source («more than 250,000 characters») e quella da 160 kB a blocchi anche («more than 3,000 blocks»); la digitazione arriva a destinazione in tutte le celle. La latenza di digitazione è pari o migliore di CodeMirror. <strong>L&#39;apertura costa circa 0,8 s di avvio a freddo (chunk lazy) e circa 10 volte CodeMirror a 200 kB</strong>; <code>limits.ts</code> dichiara soglie che tengono l&#39;apertura «near a second»: da rivalutare o da rimisurare a macchina scarica. Con <code>ui-perf.spec</code> del repository (5 kB): CodeMirror apertura 156 ms, p50 25,1, p95 32,8; Milkdown 568 ms, p50 17,1, p95 30,7. <code>fileChanges.perf</code>: 3/3 passati (indipendente dal motore, gira in jsdom).</p><ul><li><strong>Accessibilità: NON PASS al momento della misura, corretta in W8 (i due rilievi della revisione W8 sono stati corretti in W9).</strong> <code>a11y.spec</code> con interruttore acceso passa (24/24, 0 violazioni) ma scansiona una nota vuota ed esclude <code>.cm-content</code>. Su una nota ricca (liste, task, callout, tabella, code, math, embed; chiaro e scuro), confrontata con CodeMirror a <code>.cm-content</code> incluso:</li></ul><table tabindex="0"><thead><tr><th>Gravità</th><th>Regola</th><th>Elemento</th><th>Rispetto a CodeMirror</th></tr></thead><tbody><tr><td>serious</td><td><code>list</code> (4 elementi)</td><td><code>ul</code>/<code>ol</code> con <code>li</code> dentro <code>div.milkdown-list-item-block</code></td><td>nuova</td></tr><tr><td>serious</td><td><code>listitem</code></td><td><code>.milkdown-list-item-block &gt; li</code></td><td>nuova</td></tr><tr><td>serious</td><td><code>color-contrast</code> 1,36:1 (chiaro), 1,52:1 (scuro)</td><td><code>.ordered.label.milkdown-icon</code> (numeri delle liste ordinate)</td><td>nuova</td></tr><tr><td>serious</td><td><code>color-contrast</code> 4,13 chiaro / 3,07 scuro</td><td><code>span[data-ofm=&quot;tag&quot;]</code></td><td>come CodeMirror (<code>.cm-lp-tag</code>, stessi token)</td></tr><tr><td>serious</td><td><code>color-contrast</code> 3,43 scuro</td><td>wikilink e link esterni</td><td>come CodeMirror</td></tr></tbody></table><p>Milkdown risolve <code>aria-toggle-field-name</code> sulla casella dei task (CodeMirror l&#39;ha ancora); <code>scrollable-region-focusable</code> e <code>page-has-heading-one</code> sono solo in CodeMirror; best-practice sul Live di Milkdown: 0. <strong>Proposta:</strong> estendere <code>a11y.spec</code> a una nota ricca in Live senza escludere <code>.ProseMirror</code>; correggere la struttura delle liste (ruoli ARIA o override del nodo) e il colore dell&#39;etichetta con un token <code>--crepe-*</code>, in <code>packages/workbench/src/editor/live/</code>. <strong>Dopo W8:</strong> fatto, con <code>input/listSemantics.ts</code> (il blocco della voce prende <code>role=listitem</code> e il <code>li</code> interno <code>role=none</code>; bullet e numeri sono <code>aria-hidden</code>, le caselle dei task restano caselle), il colore delle etichette sul token <code>--crepe-color-on-surface-variant</code> e un test di <code>a11y.spec</code> su una nota ricca con <code>.ProseMirror</code> incluso (senza le correzioni fallisce con <code>list</code>, <code>listitem</code> e <code>color-contrast</code>; con le correzioni 0 violazioni; la nota di prova non ha tag né link, il cui contrasto è uguale a CodeMirror). La casella ha ora il nome «Task: testo». <strong>In corso:</strong> <code>listSemantics.ts</code> calcola <code>aria-hidden</code> solo sulle voci senza ruolo, quindi una voce che da bullet diventa task (digitando <code>[ ] </code>) tiene la casella nascosta ai lettori di schermo e il glifo di un task tornato bullet resta esposto; la correzione ricalcola l&#39;attributo a ogni aggiornamento della voce, con un test e2e che trasforma un bullet in task.</p><ul><li><p><strong>Rete e CSP:</strong> <code>workbench-csp</code> 5/5 (verifica solo l&#39;avvio). Su una nota con emoji, immagini locali e remote, html, code, math e mermaid, e con picker emoji, slash, find e toolbar, l&#39;unica richiesta fuori dall&#39;origine è <code>https://example.com/remote.png</code>, bloccata da <code>img-src &#39;self&#39; data: blob:</code> come con CodeMirror; l&#39;emoji arriva da <code>/emoji/svg/1f600.svg</code>; zero errori di pagina. <code>live-ai</code> e <code>live-collab</code> passano nella matrice accesa. Non eseguiti <code>csp.spec</code> ed <code>excalidraw-offline</code>; la CSP della shell Wails reale non è verificata.</p></li><li><p><strong>Caccia differenziale sull&#39;editor montato (jsdom):</strong> 195.642 sequenze di input (181.976 hanno modificato il documento) su 423 documenti (conformance, demo, cases, varianti CRLF e BOM) e sui 651 esempi CommonMark non avversari, in due passate con semi 1 e 2. Il percorso di modifica concorda con la serializzazione forzata: <strong>1 divergenza su 195k</strong> (un file con doppio BOM, dove sbaglia la serializzazione forzata, non la modifica); Live → Source → Live non produce mai un testo diverso; l&#39;undo completo ripristina i byte originali. Divergenze nuove, per causa:</p><ol><li><strong>Task con primo paragrafo vuoto seguito da un blocco</strong> (la più seria). Input minimo <code>- [ ] a\\n- [x] b\\n</code>, caret all&#39;inizio del testo del primo task, incolla <code>- x\\n- y</code>: il testo scritto diventa <code>-\\n[ ] - x\\n - y\\n a\\n- [x] b\\n</code>. La casella finisce su una riga non indentata, il task perde lo stato, il contenuto esce dalla lista e la riapertura in Live è rifiutata (la nota resta in Source); nei file CRLF la riscrittura allargata toglie i <code>#</code> finali dei titoli intatti. Il cancello non la vede perché modifica e serializzazione forzata coincidono. 249 dei 275 rifiuti di riapertura e circa 300 casi <code>E:tasks</code>. Causa esatta non isolata: <code>fidelity/compose.ts</code> (<code>forcedBlock</code>, <code>composeContainer</code> per <code>list_item</code> con <code>checked</code>, <code>windowIsSound</code>).</li><li>Spazio iniziale prima di un nodo OFM (<code>[[a]] text</code> con quattro spazi o <code>\\t</code> all&#39;inizio): Reading lo rende come <code>&lt;pre&gt;&lt;code&gt;</code>, <code>extract()</code> perde link e tag, alla riapertura il blocco diventa <code>raw_block</code>.</li><li><code>%%</code> o <code>$$</code> digitati nell&#39;etichetta di un wikilink (<code>[[a%%b]]</code>): <code>extract()</code> legge 0 link e il commento aperto inghiotte il resto del file; Invio nell&#39;etichetta spezza il nodo o ne crea uno vuoto.</li><li>Titolo che contiene un raw inline (incolla di un URL o <code>[^1]</code> in <code>## Title</code>): testo corretto, ma alla riapertura il titolo diventa <code>raw_block</code>.</li><li>Minore: un <code>hr</code> identico a un altro cambia marcatore (<code>---</code> diventa <code>***</code>, il nuovo prende <code>---</code>).</li><li>Minore: il redo non riproduce la modifica nelle tabelle (96 casi, incolla di blocchi in una cella: compare una riga vuota in più).</li><li>Minore: le righe fratelle sono riscritte in liste con indentazione irregolare (circa 276 casi, quasi tutti negli esempi CommonMark 295, 310 e 312). <strong>Stato dopo W8 (2026-11-11).</strong> Corrette, ciascuna con un test che fallisce senza la correzione: la causa 1 (il primo paragrafo con testo diventa la testa del task e i blocchi precedenti lo seguono; un task con testo vuoto e altri blocchi è scritto senza casella), la 2 (il primo spazio o tab davanti a un nodo OFM è scritto <code>&amp;#x20;</code> o <code>&amp;#x9;</code>), la 3 (il carattere che formerebbe <code>%%</code>, <code>$$</code> o <code>[</code> nell&#39;etichetta di un wikilink non viene digitato; Invio nell&#39;etichetta porta il caret fuori dal nodo) e la 4 (nei titoli non si scrivono <code>\\[^label]</code> né <code>\\:</code>). Sul seme 1 le riaperture rifiutate passano da 274 a 0. La causa 5 non è un bug: con <code>---</code> in prima riga e un secondo <code>---</code> sotto i due sarebbero frontmatter, quindi il primo diventa <code>***</code> di proposito (un test lo documenta). <strong>Non corrette:</strong> la causa 6 (l&#39;incolla con selezione su più celle spezza la tabella, e il redo passa da <code>fixTables</code>: serve lavoro sul plugin delle tabelle), la 7 (compare solo quando un incolla o uno split aggiunge blocchi a una voce con marcatore irregolare, per esempio <code>1. foo</code> diventa <code>1. foo</code>: serve lavoro in <code>compose.ts</code>) e l&#39;escape del backtick in <code>extract()</code>, che va corretto in Go e in TS insieme (il parser Go ha lo stesso comportamento, <code>parser.go:538</code>; a divergere è Reading). <strong>Chiusi in W9</strong> (vedi «Stato dopo W9 e W10»): la guardia sul <code>%%</code> non copriva l&#39;incolla (un <code>%%</code> incollato nell&#39;etichetta di <code>[[ab</code> produceva <code>see [[abx]]%%y end</code> e inghiottiva il resto della nota) e la casella di un task nato da un bullet restava <code>aria-hidden</code>. <strong>Scelte da confermare:</strong> un task con il solo stato e altri blocchi è scritto <code>-</code> e lo stato si perde, e togliere <code>\\[^1]</code> nei titoli può cambiare la semantica se la nota ha la definizione <code>[^1]:</code>.</li></ol><p><strong>Stato dopo W9 e W10 (2026-11-11).</strong> In W9 sono stati corretti, ciascuno con un test che fallisce senza la correzione: la casella di un task spezzato con Invio dopo la prima riga (restava fuori dal marcatore), l&#39;incolla nell&#39;etichetta di un wikilink (segue le regole della digitazione), <code>[^1]</code> e punteggiatura a fine enfasi nei titoli, gli item vuoti annidati in liste larghe, <code>$$</code> in un blocco math, Invio su un intervallo che attraversa blocchi (lanciava un <code>TypeError</code>) e l&#39;<code>aria-hidden</code> della casella di un bullet diventato task. La caccia indipendente di W9 (33.000 sequenze sui task e 46.612 sulle famiglie nuove, semi 5 e 6) e la revisione di W9 hanno trovato altro, corretto in W10, sempre con un test che fallisce senza la correzione (verificato per mutazione): Maiusc+Invio seguito da un incolla in un task (167 riaperture rifiutate: la casella finiva fuori dal marcatore), il delimitatore <code>)</code> negli elenchi ordinati dentro i task (le caselle perdevano lo stato in serializzazione), l&#39;incolla di HTML con blocchi nell&#39;etichetta o nel target di un wikilink (il link spariva dall&#39;indice) e lo <code>spread</code> di un item con la testa svuotata (la lista che segue si perdeva in silenzio). <code>live:metrics</code> resta identico al baseline (C1-edit 35.041/35.041, C2 non avversario 99,98%, C3 1074/1074, C4 a 0). Vitest del workbench: 156 file passati e 1 saltato, 2143 test passati e 46 saltati; non sono stati eseguiti Playwright, <code>task parity</code>, la matrice e2e né Wails reale.</p><p><strong>La caccia differenziale non è esaurita.</strong> Ogni giro (A-W3, W7, W8, W9, W10) ha chiuso le divergenze trovate e ne ha trovate di nuove in sequenze meno comuni; dopo W10 non è stata rieseguita una caccia completa. <strong>Divergenze note ancora aperte:</strong> la causa 6 (redo nelle tabelle dopo l&#39;incolla di blocchi in una cella; in W8 il volume era raddoppiato, 228 casi) e la causa 7 (indentazione irregolare e riscrittura delle righe fratelle nelle liste); il titolo con <code>[[^1]](url)</code>, che alla riapertura diventa <code>raw_block</code>; i casi non seri della caccia di W9 (nota riaperta come un unico <code>raw_block</code> con un item vuoto seguito da un blocco o con un task che contiene <code>[^1]</code>; il nuovo task dopo Invio a fine di un task spuntato nasce <code>[x]</code>; l&#39;incolla di un blocco nell&#39;ultimo item di un callout aggiunge una riga <code>&gt;</code> vuota fuori dal blocco toccato; l&#39;incolla di HTML in una cella spezza la tabella e l&#39;undo non la ripristina, 2 casi); l&#39;escape del backtick in <code>extract()</code>; dalla revisione di W10, il caso non serio dei due a-capo duri di fila che producono un <code>\\</code> letterale (i tre casi seri di quella revisione sono chiusi: vedi «Consolidamento»). Scelta da confermare: <code> **b.**c</code> si salva <code>**b.**&amp;#x63;</code>, con un riferimento di carattere che l&#39;utente non ha scritto. Nota: Maiusc+Invio in un task seguito da un incolla non conserva più l&#39;a-capo iniziale. <strong>Conclusione:</strong> prima di rendere Milkdown il default servono, oltre alle prove manuali dell&#39;owner, una fase di consolidamento dedicata e una caccia fino a esaurimento.</p><p><strong>Consolidamento, primo passo (2026-11-12): chiusi i tre casi seri della revisione di W10.</strong> Voce larga con la testa svuotata seguita da una tabella o da una citazione e poi da un paragrafo (il paragrafo finiva nella tabella o nella citazione); incolla di lista o tabella a metà del testo di una voce stretta (il testo che segue finiva nell&#39;ultima voce incollata o in una riga); Maiusc+Invio due volte e incolla di <code>---</code> (la voce diventava un titolo setext e il task spariva). Causa comune: una voce modificata è riscritta per intero dal serializzatore, che fra i figli di una voce stretta non mette righe bianche nemmeno dove CommonMark legge due blocchi come uno; la rete <code>checked()</code> prendeva per buona quell&#39;uscita. Correzioni: <code>narrowJoin</code> e <code>ruleHandler</code> in <code>kit.ts</code>, <code>replaceWithBlocks</code> in <code>input/paste.ts</code>; <code>mendTaskHeads</code> non rende più larga la voce davanti a una regola. Deviazioni nuove in ADR-0049 §9, scelte dall&#39;owner: una regola subito sotto il testo di una voce stretta si scrive <code>***</code>; un incolla di blocchi a metà riga toglie gli spazi iniziali del testo che segue. Del primo caso resta il limite già noto: la voce senza testo che comincia con la tabella o la citazione si riapre come <code>raw_block</code>. Prove: <code>input/tightItems.test.ts</code> (16 test sull&#39;editor montato) e 4 test in <code>overrides.test.ts</code>, compreso un test di neutralità sui 1075 file del corpus (la nuova regola non scatta mai su un file letto); verificato per mutazione (8, 10 e 6 test falliti senza ciascuna correzione). Vitest del workbench: 157 file passati e 1 saltato, 2163 test passati e 46 saltati; <code>live:metrics</code> identico al baseline; <code>tsc</code>, eslint e prettier puliti. <strong>Non eseguiti:</strong> <code>task ci</code>, gli e2e Playwright, <code>task parity</code> e una nuova caccia differenziale, che resta il passo successivo del consolidamento.</p><p><strong>Consolidamento, passo <code>[M16-UX1]</code> (2026-11-12): l&#39;esperienza del playground di Crepe.</strong> Richiesta dell&#39;owner del 2026-11-12: Live con Milkdown deve avere l&#39;esperienza di <a href="https://milkdown.dev/playground" target="_blank" rel="noreferrer">https://milkdown.dev/playground</a>. Il motore restava dietro <code>CLARAE_LIVE_ENGINE</code>, spento di default: non era visibile all&#39;utente e il passo non aveva una riga nel CHANGELOG (dal 2026-11-12 è visibile a tutti: vedi A-W9 e il CHANGELOG, sezione <em>Unreleased</em>). Il passo aggiunge, in <code>packages/workbench/src/editor/live/chrome/</code> (<code>handle.ts</code>, <code>index.ts</code>, <code>toolbar.ts</code>, <code>shortcuts.ts</code>, <code>icons.ts</code>, <code>chrome.css</code>), in <code>input/suggest.ts</code> e <code>input/slashLook.ts</code> e in <code>theme.css</code> (righe nuove in ADR-0049 §9):</p><ul><li><strong>Maniglia dei blocchi:</strong> un «+» che aggiunge un blocco vuoto sotto e apre lì il popup slash (con <code>slashCommands</code> spento aggiunge solo il blocco), e una presa che trascina il blocco. È costruita sul plugin dei blocchi <code>@milkdown/kit/plugin/block</code>, non sulla funzione <code>blockEdit</code> di Crepe (scartata: menu slash in Vue senza traduzione e maniglia senza nomi). Solo per il puntatore: i pulsanti non sono nell&#39;ordine di tabulazione, hanno un nome per i lettori di schermo e il «+» risponde anche a un clic senza puntatore; gli equivalenti da tastiera sono <code>/</code> e Alt+↑/↓. Nascosta nei pane stretti (sotto 420 px), in sola lettura e dentro tabelle e citazioni.</li><li><strong>Barra sulla selezione</strong> (grassetto, corsivo, barrato, evidenziato, codice, formula in linea, link) con le scorciatoie del registro dei comandi e senza il pulsante AI: la barra di Crepe lanciava un&#39;eccezione leggendo la configurazione dell&#39;AI, quindi <code>attachAi</code> (<code>ai/feature.ts</code>) toglie il flag <code>ai</code> da <code>FeaturesCtx</code>; l&#39;AI resta inattiva (ADR-0050). <strong>Tooltip dei link</strong> solo sui link Markdown (copia, modifica, rimuovi; i wikilink restano con Mod+clic e anteprima; l&#39;avviso di copia è una regione <code>aria-live</code>). <strong>Segnaposto</strong> nel blocco vuoto con il caret (non in tabelle, code block, liste e sola lettura; il testo segue <code>slashCommands</code>).</li><li><strong>Popup slash</strong> con i gruppi Testo, Elenchi, Avanzati e Vault e un&#39;icona per voce, con le etichette senza «/» in Live (Source resta con «/Heading 1»), stesse voci e stesse regole di Source. <strong>Margini più larghi</strong> guidati da <code>data-size</code> (<code>wide</code>, <code>compact</code>, <code>narrow</code>), scritto da un <code>ResizeObserver</code> (non una container query: <code>contain</code> romperebbe il popup slash, che è <code>position: fixed</code>); con <code>readableWidth</code> la riga di testo è di 712 px e il <code>.ProseMirror</code> arriva a 880 px in un pane largo.</li><li><strong>Difetto di fedeltà trovato lungo il passo</strong>, riproducibile prima con Alt+↑: spostare un blocco oltre una regola orizzontale faceva sparire la regola e duplicava il blocco. Corretto in <code>fidelity/compose.ts</code> (guardia sulla regola; blocchi appaiati alle voci del file per identità e poi per posizione, con l&#39;indentazione del posto). <strong>Residui noti, non corretti:</strong> spostare l&#39;ultima di due liste adiacenti con marcatori diversi può scambiare i loro marcatori; una lista dentro una finestra riscritta può normalizzare <code>* x</code> in <code>* x</code>. Corretta anche un&#39;attesa vecchia di <code>live-input.spec.ts</code> (<code>***</code> sotto una voce stretta, dal passo precedente, fee031b).</li><li><strong>Bundle</strong> (build, kB): desktop a interruttore spento 1993 iniziale (era 1992, margine 7) e 15999 totale; acceso 1375 iniziale e 18387 totale; chunk <code>MilkdownEditor</code> 389,2 (era 337,2: circa 52 kB di JS) e CSS circa +10; web workbench spento 2493 iniziale e 14042 totale. Limiti non alzati (2000/23000 desktop, 2500/23000 web).</li><li><strong>Prove:</strong> vitest del workbench 2196 passati e 46 saltati; Playwright con Milkdown su desktop-mock 72 passati (<code>live-chrome</code>, <code>live-input</code>, <code>live-frame</code>, <code>a11y</code>, <code>live-views</code>, <code>editor-toolbar</code>); <code>e2e:workbench-ui</code> 128 passati su desktop-mock e web-core. Il registro di parità (<code>editor.formatting</code>) ha le prove nuove (<code>chrome.test.ts</code>, <code>live-chrome.spec.ts</code>). <strong>Non eseguiti:</strong> Wails reale e le tre WebView (WKWebView, WebView2, WebKitGTK), un lettore di schermo vero, <code>task ci</code> intero e una nuova caccia differenziale. ADR-0049 aggiornato (§6, §9, accessibilità, alternative, conseguenze, §12), ancora in proposta.</li></ul><p>Fuori dal perimetro dell&#39;editor: <code>extract()</code> TS ignora il backtick con escape (il testo <code>\\`[[a]] #t</code> ha 0 link e 0 tag, mentre Reading li rende) e l&#39;editor scrive quell&#39;escape alla digitazione di un backtick; il parser Go è NON VERIFICATO. <strong>NON VERIFICATO nella caccia:</strong> Backspace e Invio nativi del browser (emulati con i comandi di ProseMirror), il code block CodeMirror, il Go,<code>task ci</code>.</p></li><li><p><strong>Revisione finale della Parte A: Pass con riserve.</strong> Rilievi bassi: (R1) nessun controllo automatico tiene Milkdown, AI e collab fuori dalle build predefinite e di rilascio (nessuno tra <code>Taskfile.yml</code>, <code>scripts/</code>, <code>release.yml</code> e <code>services/cloud/Dockerfile</code> cita <code>CLARAE_LIVE_ENGINE</code>, <code>CLARAE_AI</code>, <code>CLARAE_COLLAB</code>; il budget non lo coglie): <strong>chiuso in W8</strong> con <code>scripts/release/check-editor-switches.sh</code> e <code>check-dist.sh</code> nelle build di rilascio (vedi M15, rilievo 5 di B-W9); <strong>cambiate in A-W9</strong>: la prima non elenca più <code>CLARAE_LIVE_ENGINE</code>, la seconda cerca <code>y-prosemirror</code> e il mock dei binding e pretende <code>assets/MilkdownEditor-*.js</code>; (R2) il pulsante Tabella della toolbar ora inserisce la tabella intera (a HEAD perdeva il primo <code>|</code>) e non era nel CHANGELOG (ora sì); (R3) le prove di <code>editor.ai</code> ed <code>editor.collab</code> in <code>shared/parity/features.yaml</code> non erano quelle di ADR-0050 §7: corretto il 2026-11-11 (<code>ai/wiring.test.ts</code> e <code>live-ai.spec.ts</code> per <code>editor.ai</code>; <code>collab/collab.test.ts</code>, <code>converge.test.ts</code>, <code>wiring.test.ts</code> e <code>live-collab.spec.ts</code> per <code>editor.collab</code>), <code>task parity</code> verde; (R4) il commento di <code>copyTwemojiAssets</code> in <code>packages/workbench/build/esbuild.mjs</code> dichiara un&#39;attribuzione CC-BY nel JS spedito che la build non contiene: sta solo in <code>emoji/ATTRIBUTION.txt</code>, accanto alle immagini, e nel commento del sorgente <code>chunks/emoji.ts</code> (che la minificazione non spedisce); il commento è stato corretto in W8 (dice che l&#39;attribuzione sta in <code>emoji/ATTRIBUTION.txt</code>, scritto accanto alle immagini e copiato solo con l&#39;interruttore acceso, e che la build predefinita non copia nulla); la riga in «Informazioni» o nel README restava da scrivere prima di accendere l&#39;interruttore: <strong>fatto in A-W9</strong> (riga «Licenze» in «Informazioni» e sezione «Attribuzioni» del README; <code>emoji/ATTRIBUTION.txt</code> in ogni build); (R5) <code>linkLazyStyles</code> non collega mai nulla (0 fogli collegati, 7 saltati a interruttore spento e 9 a acceso) e dipendeva dalla cartella di lavoro: in W8 le build hanno <code>absWorkingDir</code> e il commento dice che oggi non collega nulla e resta come rete di sicurezza; tenerlo o toglierlo resta da decidere; <code>CLARAE_DIST</code> accetta ora anche percorsi assoluti; (R6) documenti non aggiornati (corretti da questa ondata di documentazione: ADR-0049 §7, ADR-0050 e il margine di 8 kB qui sopra).</p></li></ul><p><strong>Esito di A-W9 (2026-11-12): Milkdown è l&#39;unico motore Live.</strong> Decisione dell&#39;owner, senza attendere le prove manuali di A-W8. Verificato sull&#39;albero di lavoro non committato (<code>git diff HEAD</code>); i numeri di build e di test sono quelli dichiarati dall&#39;implementatore.</p><ul><li><strong>Rimosso:</strong> il plugin <code>liveEngine</code> e <code>CLARAE_LIVE_ENGINE</code> (esbuild del workbench, script di build di desktop e web; aggiornati i commenti del Taskfile e del Dockerfile del cloud); <code>livePreview.ts</code>, <code>blockWidgets.ts</code>, <code>widgets.ts</code>, <code>callouts.ts</code>, <code>query/widget.ts</code> con i loro test; il <code>Facet</code> <code>livePreviewContext</code>; i selettori <code>.cm-lp-*</code>, <code>.cm-wikilink*</code> e <code>.cm-callout*</code>.</li><li><strong>Cambiato:</strong> <code>NoteEditor.live.tsx</code> è <code>NoteEditor.tsx</code>; <code>editor/Editor.tsx</code> è <code>editor/source/SourceEditor.tsx</code> (Source a modalità fissa, senza <code>Compartment</code>: il disegno di ADR-0004 è superato, ADR-0004 passa a «superata in parte»); <code>blockState</code>, <code>sourceMode</code>, <code>commands</code>, <code>completions</code>, <code>external</code>, <code>paste</code>, <code>slash</code> e la metà CodeMirror di <code>stats</code> stanno in <code>editor/source/</code>; <code>engineExempt</code> di ESLint è ridotta a <code>editor/source/**</code>; le regole CSS <code>.editor-host .cm-*</code> valgono solo per Source; i code block di Live sono nel carattere a spaziatura fissa e con meno margine interno.</li><li><strong>Guardie di rilascio:</strong> <code>check-editor-switches.sh</code> non elenca più <code>CLARAE_LIVE_ENGINE</code>; <code>check-dist.sh</code> non rifiuta più Milkdown, mantiene i controlli su <code>y-prosemirror</code> (collaborazione) e sul mock dei binding e pretende <code>assets/MilkdownEditor-*.js</code>.</li><li><strong>Twemoji (CC-BY 4.0):</strong> <code>copyTwemojiAssets</code> copia le immagini in ogni build; attribuzione in «Informazioni» (riga «Licenze», <code>settings.licenses</code> e <code>settings.twemojiAttribution</code>), in <code>emoji/ATTRIBUTION.txt</code> e nel README.</li><li><strong>Bundle</strong> (kB, iniziale/totale): desktop 1376/18368 (limiti 2000/23000); web workbench 1925/16414 (2500/23000); console 698/700; core WebAssembly 7103 kB gzip su 8192. Limiti non alzati. L&#39;entry desktop scende da 1993 a 1376 kB.</li><li><strong>Prove (dichiarate):</strong> vitest del workbench 2180 passati e 46 saltati; <code>task e2e</code> desktop 179 passati e 4 saltati, desktop-prod 43, console web 94; <code>task e2e-matrix</code> 353 passati, 13 saltati, 0 falliti; <code>task ci</code> con uscita 0. La suite non ha più il confronto fra due motori.</li><li><strong>Non eseguito:</strong> Wails reale, WKWebView, WebView2, WebKitGTK, lettori di schermo, IME.</li></ul><p><strong>Prove che deve fare una persona (erano «prima del default Milkdown»; dal 2026-11-12 sono seguiti aperti, perché il default è stato deciso senza):</strong></p><ol><li><strong>IME</strong> su WKWebView (macOS), WebView2 (Windows) e WebKitGTK (Linux): giapponese, cinese e coreano; composizione in paragrafi, liste, citazioni, callout, celle di tabella e code block; accenti morti; Invio e Backspace durante la composizione; hotkey con <code>isComposing</code>.</li><li><strong>Spellcheck</strong> sulle tre WebView: sottolineature, menu contestuale, correzione senza perdere cursore o selezione.</li><li><strong>Lettori di schermo:</strong> VoiceOver, NVDA, Orca; annuncio di liste e numero di voci, casella dei task, callout, tabelle, wikilink, toolbar e menu slash, focus fra Live e Source.</li><li><strong>Incolla da app esterne</strong> (Word, browser, altri editor di note, Notes): HTML, immagini e allegati, tabelle, file in drag and drop.</li><li><strong>Note reali grandi dell&#39;utente:</strong> tempo di apertura percepito, scorrimento, comportamento alla soglia <code>LIVE_MAX</code>.</li><li><strong>Matrice e CSP reali sulla shell v3.</strong></li></ol><p><strong>Da decidere dall&#39;owner (stato al 2026-11-12):</strong> aggiornare <code>Specifications.md</code> (§2.3.x, §2.6.6, §3.4.2, §4.2, matrice delle funzioni) e accettare ADR-0050; quando fare le prove manuali che restano da fare (sopra) e cosa fare se una fallisce (nessun motore di ripiego: l&#39;interruttore non c&#39;è più, si corregge in avanti); se accettare l&#39;apertura 10 volte più lenta (2,5 s a 200 kB nella misura di A-W8, in Chromium headless) o tagliare <code>LIVE_MAX</code>; come chiudere le cause 6 e 7 della caccia e l&#39;escape del backtick (Go e TS insieme); le due scelte dell&#39;editor in W8 (task con il solo stato scritto <code>-</code>, <code>\\[^1]</code> tolto nei titoli); tenere o togliere <code>linkLazyStyles</code> (R5). <strong>Risolti il 2026-11-12:</strong> il default (Milkdown, senza attendere le prove manuali) e la rimozione del vecchio Live (A-W9); dove mostrare l&#39;attribuzione Twemoji (R4: «Informazioni» e README); chi paga la prossima aggiunta all&#39;entry (non c&#39;è più il problema: margine di circa 624 kB). Chiusi in W8: l&#39;accessibilità delle liste, la causa 1 della caccia, la guardia di rilascio sugli interruttori di build (R1 della revisione A e rilievo 5 della revisione B) e AI N3 (<code>InfoStrict</code> restituisce l&#39;errore della tabella meta, e il predicato «vault privato» di <code>bindings_ai.go</code> risponde <code>true</code> se la lettura fallisce; <code>Info</code> non cambia). Prima di attivare AI e collab: le etichette AI di Crepe sono solo in inglese e collab e conservazione per identità restano incompatibili (le caselle dei task, prima tutte «Task», ora si chiamano «Task: testo»).</p><p><strong>Punti da tenere d&#39;occhio:</strong> un blocco modificato può essere riscritto in forma diversa (marcatore, escape, indentazione) con hunk più larghi nel diff3; prestazioni sui documenti grandi (ProseMirror non virtualizza il DOM, soglia <code>LIVE_MAX</code> con ripiego su Source); instabilità upstream (bug di Milkdown sugli autolink, <code>prosemirror-search</code> archiviato, API di Crepe e TopBar); IME, spellcheck e accessibilità sulle tre WebView non ancora verificati (e ora senza un motore di ripiego); eccezione di Vue (via Crepe) rispetto a <code>Specifications.md:1769</code>, da far confermare all&#39;owner; specifica da aggiornare dall&#39;owner.</p><hr><h2 id="_13-decies-m17-—-rebrand-a-«clarae-notanda»" tabindex="-1">13-decies. M17 — Rebrand a «Clarae notanda» <a class="header-anchor" href="#_13-decies-m17-—-rebrand-a-«clarae-notanda»" aria-label="Permalink to &quot;13-decies. M17 — Rebrand a «Clarae notanda»&quot;">​</a></h2><p>Richiesta del 2026-11-13: il prodotto passa da «MemoBrain Notes» a <strong>«Clarae notanda»</strong>, con il payoff «Your knowledge, carefully preserved in its clarity.», un logo ricavato da <code>assets/clarae.png</code> e la palette Deep Navy <code>#102B3A</code>, Teal <code>#159992</code>, Mint <code>#72C9BD</code>, Mist <code>#E9F0EF</code>, White <code>#FFFFFF</code> su desktop e console web. Le funzionalità non cambiano. La decisione è <a href="./adr/0052-rebrand-clarae-notanda.html">ADR-0052</a>, in stato <strong>proposta</strong>: devia da <code>Specifications.md</code> (nome del prodotto, cartella <code>.memobrain/</code>, schema URL, realm e client OIDC, gRPC, chiave Excalidraw) e lo spec non viene toccato: lo aggiorna l&#39;owner, a partire dalla sezione «Sostituzioni da riportare in <code>Specifications.md</code>» dell&#39;ADR. Il piano (approvato dall&#39;owner il 2026-11-13) non è versionato. Il nome compare in 925 file su 2274 (circa 4.350 occorrenze, 41 percorsi) ed è scritto anche in dati persistiti (vault, keychain, storage del browser, realm Keycloak, bucket, advisory lock), quindi il rename non è solo meccanico: vale la regola di «migrazione automatica» dell&#39;ADR, con tre classi di ciò che resta <code>memobrain</code> (congelato: le etichette crittografiche dei vault; legacy transitorio: i percorsi di compatibilità con una release di rimozione; storico).</p><p><strong>Stato: eseguita (2026-11-13), versione 1.5.0, pubblicata come 1.5.1.</strong> Il tag <code>v1.5.0</code> non ha prodotto una release: la build dell&#39;immagine del cloud si è fermata sul budget del bundle della console (704 kB su 700) e il push del chart su GHCR sul tag del manifest appena caricato; la 1.5.1 corregge entrambi e aggiunge a <code>task ci</code> la build di produzione della Web UI (<code>web-budget</code>). Le onde F0, F1, C1…C9, B1…B7, F4, F5 e F6 sono fatte sul ramo <code>rebrand/clarae</code>, con un commit per work package e la sigla <code>[M17-…]</code> (autore Efrem Ropelato, senza <code>Co-Authored-By</code>). <code>task ci</code> è verde sull&#39;albero completo e il tag è <code>v1.5.0</code>. <strong>La versione è 1.5.0, non 2.0.0 come diceva il piano</strong> (decisione dell&#39;owner, recepita dal commit <code>[M17-F6]</code>): la <strong>1.5</strong> è questa release (rename e compatibilità), la <strong>1.6</strong> accende <code>features.config_dir_v2</code> e toglie i doppi advisory lock e la doppia immagine, la <strong>2.0</strong> rimuove il resto della compatibilità con la 1.x. <strong>Aggiornamento 2026-11-15:</strong> le rimozioni previste per la 1.6 passano alla <strong>1.7</strong> (vedi «Release di rimozione» più sotto e M18). L&#39;ADR-0052 resta in stato <strong>proposta</strong>: lo accetta l&#39;owner, che aggiorna anche <code>Specifications.md</code>. <strong>Ordine seguito:</strong> F0 → F1 → (F2 ‖ F3 ‖ F4 ‖ F5) → F6.</p><table tabindex="0"><thead><tr><th>Onda</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td>F0 — Preparazione (ancora con il nome vecchio)</td><td>ADR-0052 e questa sezione. Indurimento della release: <code>UPDATER_PKG</code> di <code>scripts/release/build-desktop.sh</code> derivato con <code>go list ./internal/updater</code> e <code>TestLdflagsProbe</code> (<code>apps/desktop/internal/updater/ldflags_test.go</code>, con <code>TestLdflagsReachThePackage</code> che lo tiene onesto) eseguito dallo script con gli stessi <code>-ldflags</code> prima del build (prima un path sbagliato non dava errore e il binario si fidava della chiave di sviluppo). <code>TestDepguardPackagesExist</code> in <code>services/cloud/internal/db/ownership_test.go</code> (ogni <code>pkg:</code> di <code>.golangci.yml</code> esiste sotto il module path reale, e ogni pacchetto sqlc ha la sua regola)</td><td><strong>fatta (2026-11-13)</strong>: commit <code>[M17-F0]</code></td></tr><tr><td>F1 — Rename meccanico e guardia permanente</td><td><code>scripts/rebrand/allowlist.tsv</code> (<code>classe ⇥ pathspec ⇥ regex ⇥ motivo</code>; classi <code>frozen</code>, <code>legacy</code>, <code>fixture</code>, <code>history</code>, <code>external</code>, più <code>tool</code> per gli script del rename), <code>scripts/rebrand/rename.mjs</code> (la sostituzione sensibile al casing, in un solo passaggio, che salta allowlist e file generati) pilotato da <code>scripts/rebrand/run.sh</code> (che rigenera il codice generato). Guardia <code>scripts/rebrand/check.mjs</code> con <code>lib.test.mjs</code> e task <code>lint-brand</code> come primo passo di <code>task lint</code>: fallisce su ogni riga o percorso col nome vecchio fuori allowlist <strong>e</strong> su ogni voce dell&#39;allowlist che non corrisponde più a nulla. Rimosso il task <code>rename-module</code> (non copriva i <code>go.mod</code> dei moduli, il pacchetto proto e lo script di rilascio). Il payoff non passa dal rename meccanico (va in F4)</td><td><strong>fatta (2026-11-13)</strong>: tre commit <code>[M17-F1]</code> (regole e guardia, passo meccanico su 860 file, correzione di un test che dipendeva dalla lunghezza del vecchio nome); <code>task ci</code> verde sull&#39;ultimo. L&#39;allowlist ha oggi 84 righe, due delle quali aggiunte in F6 per le guide che devono nominare i nomi della 1.x; l&#39;esito della «verifica inversa» del piano (la sostituzione al contrario ridà il commit padre) non è registrato qui</td></tr><tr><td>F2 / C1 — Regole di path a doppio nome</td><td><code>ConfigDir</code>, <code>LegacyConfigDirs</code>, <code>IsConfigPath</code>, <code>ConfigRel</code>, <code>TmpPrefix</code>, <code>IsTmpName</code> in <code>shared/go/pathrules/pathrules.go</code>; <code>IsExcluded</code> vale per entrambe le cartelle e per entrambi i prefissi dei temporanei; <code>syncproto.KindOf</code> dà <code>KindConfig</code> a tutte e due; <code>vault</code>, <code>watcher</code>, <code>history</code>, <code>templates</code> e <code>e2e-device</code> usano gli helper; <code>CleanStaleTemp</code> toglie anche un residuo della 1.4.0. Costanti TS generate in <code>platform/vaultPaths.gen.ts</code> (da <code>app/gen/capabilities</code>, quindi da <code>task gen</code>) e <code>platform/vaultPaths.ts</code>, al posto delle sei stringhe ripetute nella UI</td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-C1]</code> (core) e <code>[M17-C1]</code> (UI)</td></tr><tr><td>F2 / C2 — Migrazione della parte locale</td><td>Nuovo <code>internal/vaultdir</code>: <code>Ensure(root)</code> sposta <code>index.db*</code>, <code>sync.db*</code>, <code>cache/</code>, <code>snapshots/</code>, <code>workspace*.json</code> (tutto ciò che <code>IsExcluded</code> dice di non sincronizzare) alla prima apertura del vault, una rinomina atomica per elemento, ripetibile e ripristinabile dopo un crash, vince <code>.clarae</code>, mai cancellazioni; <code>vaultdir.DB</code> è l&#39;unico modo di costruire il path di <code>index.db</code> e <code>sync.db</code> (vault aperti e cartelle dei mount). Un vault non collegato adotta anche le impostazioni (<code>AdoptSettings</code>). <strong>Nel browser</strong> le chiavi dei database nel pool SQLite non si rinominano (<code>vaultdir/dbpath_js.go</code>): un profilo 1.x tiene le sue</td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-C2]</code>, con matrice di test (solo vecchio, solo nuovo, entrambi, crash dopo ogni rinomina, journal, concorrenza, link simbolico, WAL non scritto)</td></tr><tr><td>F2 / C3 — Impostazioni sincronizzate</td><td><code>vault.FS.ReadConfig</code>/<code>WriteConfig</code> (legge in <code>.clarae/</code>, poi nella cartella vecchia, poi di nuovo in <code>.clarae/</code>; scrive dove il file già si trova; un file nuovo va nella cartella vecchia finché il vault è collegato e lo spostamento è spento), <code>MoveConfig</code>, <code>SetConfigPolicy</code>; spostamento differito <code>sync/configmigrate.go</code> dietro <code>features.config_dir_v2</code> (schema, <code>app/managed.go</code>, <code>Manager.SetConfigDirV2</code>): a fine ciclo, un file alla volta, stesso id e stessa cronologia, <code>base_rev</code> al ciclo successivo, nulla di sovrascritto. Guardia in pull e bootstrap (<code>sync/pull.go</code>, <code>skipExcluded</code>) che non scrive un path escluso. <strong>Fuori dal piano:</strong> <code>vault.FS.ShelveConfig</code>, chiamata da <code>Manager.Link</code> e <code>LinkExisting</code> finché il flag è spento, rimette nella cartella vecchia le impostazioni che un vault non collegato aveva adottato, perché un client 1.x del vault cloud non le vedrebbe; i callback di modifica girano fuori dai lock delle impostazioni</td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-C3]</code> (due commit), test di risolutore, scritture concorrenti durante uno spostamento, regole e crash dello spostamento, guardia in pull (verificata per mutazione)</td></tr><tr><td>F2 / C4 — Formati dei file</td><td><code>.excalidraw</code> scrive <code>clarae</code> e legge entrambe le chiavi (<code>customData.clarae ?? .memobrain</code>), elemento per elemento solo quando uno strumento lo riscrive, e le impostazioni del disegno nel file al salvataggio (<code>drawing/meta.ts</code>, <code>DrawingEditor.tsx</code>); Marp legge <code>clarae|memobrain: hidden</code> e <code>clarae-loop ?? memobrain-loop</code> (idem <code>-notes</code>), scrive i nuovi, un&#39;impostazione impostata toglie la vecchia nella stessa modifica (<code>marp/slides.ts</code>). Le fixture di merge nel formato vecchio restano (classe <code>fixture</code>); aggiunte <code>excalidraw-settings-key</code> (chiave nuova) e <code>excalidraw-settings-key-both-names</code></td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-C4]</code> (tre commit). Nessuna conversione in blocco, quindi <strong>nessuna release di rimozione</strong> per questi due formati</td></tr><tr><td>F2 / C5 — Dati locali</td><td><code>ResolveDataDir</code> (<code>platform/datadir.go</code>): cartella dati <code>MemoBrain Notes</code> → <code>Clarae notanda</code> al primo avvio, con sonda di quiete sull&#39;<code>app.db</code> vecchio (<code>busy_timeout(0)</code> e <code>journal_mode=DELETE</code>: SQLite rifiuta se un&#39;altra connessione è aperta, quindi si riconosce un&#39;istanza 1.x qualunque sia il suo id), rinomina atomica, <code>app.db</code> per ultimo, nulla di sovrascritto; un&#39;istanza vecchia in esecuzione o una rinomina rifiutata ferma l&#39;avvio con un dialogo (<code>shell.ShowStartupError</code>); riscrittura dei <code>recent_vaults.path</code>; log <code>memobrain*</code> rinominati. <code>internal/ossecret</code>: lettura dal servizio vecchio del portachiavi con copia nel nuovo, scrittura nel nuovo e rimozione del vecchio, <code>Delete</code> su tutti (usata da auth, crittografia e AI). Variabili <code>DATA_DIR</code>, <code>UPDATES</code>, <code>AUTH_REDIRECT</code>, <code>DEFAULT_SERVER_URL</code> via <code>envcompat</code>. Windows: profilo WebView2 in <code>&lt;cartella dati&gt;\\webview</code> e profilo vecchio spostato (<code>platform/legacy.go</code>); macOS: avviso nel log se <code>/Applications/MemoBrain Notes.app</code> esiste. Bundle id <code>dev.clarae.desktop</code></td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-C5]</code> (due commit); sonda provata con una seconda connessione e con un secondo processo. <strong>Non provati su macchine reali:</strong> il dialogo, la rinomina rifiutata su Windows, il portachiavi vero (i test usano un portachiavi finto), lo spostamento del profilo WebView2</td></tr><tr><td>F2 / C6 — Schema URL</td><td><code>Scheme</code> <code>clarae</code>, <code>LegacySchemes</code> <code>memobrain</code>: <code>ParseSchemeURL</code> e <code>FindSchemeURL</code> accettano entrambi (<code>platform/urls.go</code>), <code>build/project.json</code> e <code>clarae.desktop</code> li registrano entrambi; redirect OIDC con ricaduta sul vecchio URI se il realm rifiuta il nuovo (<code>auth/auth.go</code>, riusa <code>redirectRejected</code>)</td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-C6]</code>, <code>assets_test.go</code> fissa la registrazione di entrambi</td></tr><tr><td>F2 / C7 — Browser</td><td><code>web/src/workbench/legacyNames.ts</code> (unico posto che nomina i nomi della 1.4, fissati da <code>legacyNames.test.ts</code>); <code>migrate.ts</code> sposta una cartella OPFS in modo ripristinabile (<code>FileSystemHandle.move</code> se c&#39;è, altrimenti copia, confronto, marker scritto per ultimo, poi rimozione); <code>accounts/&lt;chiave vecchia&gt;</code> → <code>accounts/&lt;chiave nuova&gt;</code>, marker (unione delle due chiavi, vince la voce con modifiche), <code>device.ts</code> (copia IndexedDB vecchio → nuovo), preferenze in lettura doppia; la pagina prende <strong>entrambi</strong> i Web Lock in ordine fisso e parla e ascolta su entrambi i canali. <strong>Correzione <code>[M17-C7]</code> finale:</strong> la cartella dati del core nel browser e le chiavi dei database nel pool SQLite <strong>non si spostano</strong> per un profilo 1.x (<code>storage.ts</code> <code>dataDirOf</code>, <code>vaultdir/dbpath_js.go</code>), perché il pool non rinomina e una copia non è atomica; un profilo nuovo usa i nomi nuovi</td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-C7]</code> (due commit); test su finti OPFS (con e senza <code>move</code>, disco pieno) e IndexedDB, e uno spec Playwright (<code>web/e2e/migration.spec.ts</code>) contro OPFS e IndexedDB veri</td></tr><tr><td>F2 / C8 — Rinomine libere</td><td>MIME del drag and drop, User-Agent, testo e nome del file della chiave di recupero, global <code>__clarae*</code>: rinominati senza alias nel passo F1; i tipi di dato del drag and drop hanno ora una costante ciascuno in <code>util/dragTypes.ts</code></td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-F1]</code> e <code>[M17-C8]</code></td></tr><tr><td>F2 / C9 — E2E a due dispositivi</td><td><code>apps/desktop/internal/sync/e2e_configdir_test.go</code>: flag spento (un client nuovo e uno 1.x, simulato scrivendo la cartella vecchia sul disco, si scambiano <code>editor.json</code> e <code>hotkeys.json</code> nei due versi e il server non ha nulla col nome nuovo), flag acceso (spostamento offline sui due client con convergenza su id e cronologia, senza copie), ricreazione dal client vecchio, vault privato con <code>sync.db</code> piantato sotto i due nomi (l&#39;altro dispositivo non lo scrive), mount della 1.x sotto <code>mounts/</code> migrato alla lettura, e il caso dell&#39;impostazione che passa nella cartella vecchia al collegamento</td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-C9]</code> (due commit). Il client 1.x è simulato, non è un&#39;app 1.4.0</td></tr><tr><td>F3 / B1 — OIDC</td><td><code>nameDefaults(issuer)</code>: un issuer che finisce in <code>/realms/memobrain</code> tiene audience, AZP, client, realm, bucket e namespace delle metriche della 1.x, altrimenti <code>clarae-*</code>; una variabile esplicita vince; <code>Config.LegacyNames</code> e la riga di log <code>names in use</code>. <code>OIDC_ADMIN_ROLES</code> (default <code>clarae-admin,memobrain-admin</code>): <code>auth.RoleFromRealmRoles</code>, <code>users.NewService</code>, <code>keycloak.Config.AdminRoles</code>; <code>SetAdmin</code> assegna il primo ruolo che il realm ha e toglie tutti quelli posseduti. <code>NewS3</code> rifiuta di partire (<code>ErrLegacyBucket</code>) se il bucket di default manca ma esiste quello vecchio. Realm <code>realm-clarae.json</code> (dev e prod) con entrambi i redirect e nome <code>${KC_REALM:clarae}</code>; <code>useAdminAccess</code> accetta i due ruoli</td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-B1]</code></td></tr><tr><td>F3 / B2 — gRPC</td><td><code>api/proto/clarae/v1</code> è il contratto nuovo (<code>shared/go/notifyv1</code>); <code>api/proto/memobrain/v1</code> resta come proto legacy (<code>shared/go/notifyv1legacy</code>; la cartella resta <code>memobrain/v1</code> perché <code>buf lint</code> lega cartella e package). <code>grpcserver</code>: il flusso passa a <code>notifyServer.serve</code>, chiamato da entrambi i servizi (autenticazione, replay, chiusura e limiti invariati); un test confronta i descrittori dei due proto. Route dell&#39;Ingress per entrambi (<code>ingress.grpc.legacyPath</code>). Il client nuovo contro un cloud vecchio ricade sull&#39;SSE</td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-B2]</code></td></tr><tr><td>F3 / B3 — Variabili d&#39;ambiente</td><td><code>shared/go/envcompat</code> (<code>CLARAE_X</code> vince, <code>MEMOBRAIN_X</code> vale con un avviso): cinque variabili lette a runtime (quattro del desktop, <code>ALLOW_PLACEHOLDER_SECRETS</code> del cloud) e cinque di Compose (<code>HOST</code>, <code>SITE</code>, <code>IMAGE</code>, <code>VERSION</code>, <code>ALLOW_PLACEHOLDER_SECRETS</code>, con interpolazione annidata); rename secco per le variabili di test, perf e build</td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-B3]</code> (due commit)</td></tr><tr><td>F3 / B4 — Dati dell&#39;installazione</td><td>Advisory lock <code>clarae.*</code> (<code>db.AdvisoryLockKeys</code>): ogni transazione prende il lock <code>memobrain.*</code> <strong>prima</strong> e quello nuovo poi, sempre in quest&#39;ordine; test d&#39;integrazione che fa da pod 1.4. <code>METRICS_NAMESPACE</code> (validato) o, in sua assenza, il namespace del realm. In Compose <code>COMPOSE_PROJECT_NAME</code>, <code>POSTGRES_USER</code>, <code>POSTGRES_DB</code> e <code>KC_REALM</code> obbligatori e senza default; <code>s3-init</code> crea i bucket con lo stesso criterio del servizio e rifiuta come lui</td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-B4]</code> e <code>[M17-B3]</code>; il test di integrazione dei lock è in <code>services/cloud/test/integration</code> e va in <code>task test-integration</code></td></tr><tr><td>F3 / B5 — Helm e immagine</td><td>Chart <code>clarae</code> con <code>nameOverride</code>/<code>fullnameOverride</code> (<code>_helpers.tpl</code>); <code>ci/values-legacy.yaml</code> in <code>task helm-check</code>, che asserisce nomi e selector della 1.x con <code>nameOverride: memobrain</code>; <code>values.yaml</code> senza i default che portano il nome (li decide il binario), <code>ingress.grpc.legacyPath</code>; <code>release.yml</code> pubblica l&#39;immagine anche come <code>memobrain-cloud</code> (seconda voce <code>images:</code>, da togliere nella 1.6)</td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-B5]</code>; <code>task helm-check</code> e <code>task docker-build</code> non sono registrati qui come rieseguiti</td></tr><tr><td>F3 / B6 — Installer e artefatti desktop</td><td>NSIS (<code>project.nsi</code>, macro <code>clarae.removeLegacyInstall</code>) rimuove la vecchia installazione senza eseguirne il disinstallatore (cancellerebbe il profilo WebView2); app in esecuzione: nuovo tentativo o annulla, installazione silenziosa ferma con codice 5; <code>nfpm.yaml</code> con <code>replaces</code> e <code>conflicts: [memobrain]</code>; prefisso degli artefatti e contesto di firma del manifest rinominati (<code>tools/release/main.go</code>, <code>shared/go/updatemanifest/manifest.go</code>, <code>apps/desktop/internal/updater/key.go</code>); <code>installer_legacy_test.go</code></td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-B6]</code>, con asserzioni sullo script e compilazione con <code>makensis</code> dove c&#39;è (altrimenti il test è saltato). <strong>L&#39;installer non è mai stato eseguito su Windows</strong>, né è stato provato un <code>.deb</code> sopra il pacchetto vecchio</td></tr><tr><td>F3 / B7 — Guida e nota di rilascio</td><td><code>docs/admin-guide/migrazione-clarae.md</code> (quattro righe da aggiungere ai <code>.env</code> di Compose, redirect <code>clarae://</code> sui realm esistenti, upgrade Helm in-place, metriche, rollback, verifica finale) con rimandi da <code>README.md</code> e <code>backup-upgrade.md</code> della guida admin; la nota di rilascio è la sezione 1.5.0 del CHANGELOG</td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-B7]</code> (guida) e <code>[M17-F6]</code> (nota di rilascio)</td></tr><tr><td>F4 — Marchio</td><td>Ridisegno vettoriale del marchio (tre forme) in <code>assets/brand/</code> (<code>mark.svg</code>, <code>mark-on-dark.svg</code>, <code>icon.svg</code>, <code>safari-pinned-tab.svg</code>); <code>scripts/brand/gen-brand-assets.py</code> riscritto a partire dagli SVG (nome, payoff e palette come costanti, <code>rsvg-convert</code> e Pillow), con icone, favicon, manifest, banner e social preview rigenerati. Payoff con la chiave i18n <code>app.tagline</code> (stesso testo in <code>en</code> e <code>it</code>). Componente <code>BrandMark</code> in <code>packages/ui</code>. Rimossi <code>assets/logo.png</code> e <code>assets/image.png</code>; <code>assets/clarae.png</code> resta come sorgente; <code>assets/brand/README.md</code></td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-F4]</code>. <strong>Non risulta registrata</strong> l&#39;approvazione dell&#39;owner sul ridisegno del marchio (il checkpoint del piano) né un controllo a occhio delle icone su macOS (Dock, Finder)</td></tr><tr><td>F5 — Stile dell&#39;interfaccia</td><td>Primitive <code>--brand-*</code> in <code>packages/ui/src/tokens.css</code> come unica fonte dei token della console (<code>--nd-*</code>), del workbench (<code>packages/workbench/src/styles/tokens.css</code>) e degli overlay di <code>web/src/workbench/shell.css</code>; <code>--accent</code> (testo e pieni, tonalità più scura) e <code>--accent-bright</code> (ciò che non è testo) al posto del <code>--accent-fill</code> ipotizzato dal piano; <code>DEFAULT_ACCENT</code> unico (<code>state/settings.ts</code>), con il violetto della 1.x salvato letto come «nessuna scelta»; <code>BackgroundColour</code>, <code>theme-color</code>, <code>mask-icon</code> e manifest; <code>--bg-primary</code> (usato nel canvas, mai definito) è <code>--bg</code>. Non cambiano callout, preset di canvas e grafo, palette di Excalidraw, temi di Mermaid e Marp. <code>tokens.contrast.test.ts</code>: contrasto ≥ 4,5:1 sulle coppie testo/superficie nei due temi</td><td><strong>fatta (2026-11-13)</strong>: <code>[M17-F5]</code>. L&#39;esito di axe (<code>a11y.spec.ts</code>) sui due temi non è registrato qui</td></tr><tr><td>F6 — Documentazione</td><td>CHANGELOG (sezione 1.5.0), questa sezione, ADR-0052 (stato di esecuzione, release di rimozione, browser, ciò che resta non provato), guida utente (<em>Aggiornare dalla 1.x</em>), <code>docs/web-ui.md</code>, <code>docs/desktop-web-sync.md</code>, <code>docs/dev-setup.md</code>, <code>docs/architecture.md</code>, README, CONTRIBUTING, <code>docs/admin-guide/profili-quote-audit.md</code>, <code>docs/qa/a11y-*.md</code>; commit <code>[M17-F6]</code> con i riferimenti di versione e le release di rimozione nei motivi dell&#39;allowlist. <code>Specifications.md</code> resta all&#39;owner</td><td><strong>fatta (2026-11-13)</strong>. <code>CLAUDE.md</code> e <code>docs/qa/i18n-glossary.md</code> non sono toccati da questo passo</td></tr></tbody></table><p><strong>Criteri di uscita M17</strong> (dalla verifica del piano), con l&#39;esito registrato:</p><ul><li><code>task ci</code> verde dopo F1 e dopo ogni work package; <code>task lint-brand</code> senza righe fuori allowlist e senza voci dell&#39;allowlist inutili. <strong>F1 verde (<code>[M17-F1]</code>); <code>lint-brand</code> passa (84 righe nell&#39;allowlist); <code>task ci</code> verde sull&#39;albero completo del 2026-11-13, documentazione compresa, prima del tag.</strong></li><li><code>task test-integration</code> (realm rinominato), <code>task test-desktop-e2e</code> (casi C9), <code>task test-wasm</code>, <code>task e2e</code>, <code>yarn workspace @clarae/web run e2e:workbench-ui</code>, <code>task helm-check</code> (con <code>ci/values-legacy.yaml</code>), <code>task docker-build</code> e <code>task release-tool</code>: <strong>eseguiti sull&#39;albero completo il 2026-11-13, tutti verdi: <code>test-integration</code>, <code>test-desktop-e2e</code>, <code>test-wasm</code> (dentro <code>task ci</code>), <code>task e2e</code> (desktop 179 test con 4 saltati, bundle di produzione 43, console 97), <code>helm-check</code> e <code>release-tool</code>. Non eseguito: <code>e2e:workbench-ui</code> (la matrice sul core WASM nel browser; solo <code>workbench.spec</code>, <code>migration.spec</code> e <code>device.spec</code> durante C7). <code>docker-build</code> non era stato eseguito prima del tag <code>v1.5.0</code> ed è lì che la release si è fermata; per la 1.5.1 l&#39;immagine è stata costruita in locale e <code>task ci</code> ne ripete il controllo dei budget (<code>web-budget</code>).</strong></li><li><strong>Migrazione reale</strong> (copia di una cartella dati e di un vault creati con la 1.4.0, avvio della build nuova, vault, bookmark, sessione e chiavi dei vault E2EE presenti senza reinserire nulla): <strong>non fatta</strong>. Coperta da test con portachiavi finto e cartelle costruite dai test.</li><li><strong>Convivenza</strong> (cloud nuovo con realm vecchio, client 1.4.0 e client nuovo sullo stesso vault, <code>scripts/run-desktop-with-cloud.sh --two-devices</code>): <strong>non fatta con un&#39;app 1.4.0 vera</strong>; coperta dai casi C9, che simulano il client vecchio, e dai test del cloud con il realm della 1.x.</li><li><strong>Aspetto</strong> (<code>task run-desktop</code> e console in chiaro e scuro, axe, icone su macOS, favicon e PWA): le scansioni axe passano in chiaro e scuro su desktop e console (dentro <code>task e2e</code>) e il contrasto è imposto da <code>tokens.contrast.test.ts</code>; gli screenshot dei due temi sono stati guardati durante F5, il marchio è stato approvato dall&#39;owner sulla tavola di confronto. <strong>Non controllati a occhio:</strong> le icone nel Dock e nel Finder, la favicon e la PWA installata.</li></ul><p><strong>Agenti:</strong> F0 e F6 → <code>docs-writer</code>; F1 direttamente; F2 → <code>desktop-core-developer</code> e poi <code>frontend-developer</code> (dopo <code>task gen</code>); F3 → <code>cloud-developer</code>; F4 e F5 → <code>frontend-developer</code>; a fine fase <code>reviewer</code> e <code>qa-engineer</code>.</p><p><strong>Punti aperti e limiti accettati:</strong></p><ul><li><strong>Prove manuali su sistemi operativi reali, da fare e non registrate:</strong> dialogo «chiudi la vecchia app» e sonda su un&#39;istanza 1.x vera (macOS, Windows, Linux); installer Windows sopra una 1.x, con l&#39;app aperta e in modalità silenziosa; <code>.deb</code> sopra il pacchetto vecchio; AppImage; gli schemi <code>clarae://</code> e della 1.x a freddo e a caldo e accesso OIDC contro un realm della 1.x; portachiavi vero di ogni sistema; profilo WebView2 spostato su Windows; <strong>su macOS e Linux il codice non sposta il profilo del WebView della 1.x</strong>, quindi ciò che il WebView tiene per sé (per esempio l&#39;elenco degli strumenti recenti di Excalidraw) può ripartire vuoto; profilo del browser di una 1.4 reale (spec Playwright e unit test coprono la migrazione, non un profilo vecchio di mesi); icone nel Dock e nel Finder, favicon e PWA.</li><li><strong>Decisioni lasciate all&#39;owner:</strong> accettare l&#39;ADR-0052 e aggiornare <code>Specifications.md</code> (elenco delle sostituzioni nell&#39;ADR); confermare il ridisegno del marchio; fissare una release di rimozione per la lettura dei file <code>.excalidraw</code> e delle presentazioni della 1.x, per il formato della 1.3 dello storage del browser e per i percorsi che oggi dicono «finché esistono» (non c&#39;è una conversione in blocco); caricare a mano la social preview (<code>assets/brand/README.md</code>).</li><li><strong>Release di rimozione dei percorsi legacy (fissate in F6, come nelle righe dell&#39;allowlist):</strong> <strong>1.6</strong> per gli advisory lock col nome vecchio, l&#39;immagine pubblicata anche con il nome vecchio e il default di <code>features.config_dir_v2</code> (che diventa acceso); <strong>2.0</strong> per tutto il resto della compatibilità con la 1.x (variabili d&#39;ambiente, portachiavi, cartella dati, schema URL e redirect, cartelle di configurazione e di staging, nomi del browser, default del realm della 1.x, ruolo amministratore, servizio gRPC, <code>nameOverride</code>). L&#39;elenco puntuale, riga per riga, è <code>scripts/rebrand/allowlist.tsv</code> e la tabella di rimozione di <code>docs/admin-guide/migrazione-clarae.md</code>. <strong>Aggiornamento 2026-11-15 (decisione dell&#39;owner):</strong> le tre rimozioni indicate per la <strong>1.6</strong> (advisory lock col nome vecchio, immagine pubblicata anche col nome vecchio, default acceso di <code>features.config_dir_v2</code>) passano alla <strong>1.7</strong>; la 1.6.0 non le tocca. <strong>Eseguite nella 1.7.0</strong> (M19, §13-duodecies). La 2.0 non cambia.</li><li><strong>Font del logo:</strong> il carattere della tavola <code>assets/clarae.png</code> non è identificabile con certezza; i banner usano il font di sistema, come lo script di oggi, e nell&#39;app restano gli stack di sistema (deve funzionare offline).</li><li><strong>Non automatizzabile:</strong> l&#39;installazione della 1.5.0 su ogni macchina (nessun client ha l&#39;updater attivo) e la rimozione a mano della vecchia app su macOS e del vecchio AppImage; sui realm Keycloak esistenti l&#39;aggiunta del redirect <code>clarae://auth/callback</code> al client desktop (finché manca, il client ricade sul vecchio); nei <code>.env</code> di Compose esistenti quattro righe da aggiungere.</li><li><strong>Limiti con «rinomina tutto»:</strong> un disegno toccato dal client nuovo non ha più formule modificabili né ordine delle diapositive su un client 1.4.0, e una presentazione toccata mostra le slide escluse e ignora «ricomincia alla fine» e le note del relatore; nei merge concorrenti di un <code>.excalidraw</code> possono restare entrambe le chiavi (il client nuovo le legge tutte e due). Un client 1.4.0 non trova lo stato di sync di un vault già aperto dalla 1.5 sullo stesso dispositivo: il ritorno alla 1.4.0 su quel dispositivo non è previsto.</li><li><strong>Manifest di update e chiave di sviluppo:</strong> si rinominano (fatto in B6). Nessuna delle otto release pubblicate (da v1.2.3 a v1.4.0) ha un <code>manifest.json</code> né l&#39;updater attivo (<code>ALLOW_UNSIGNED_UPDATES: &#39;1&#39;</code> nel <code>release.yml</code> di ogni tag), e il repository non ha né la variabile <code>UPDATE_PUBLIC_KEY</code> né segreti di firma (verificato il 2026-11-13).</li><li><strong>Specifica:</strong> ADR-0052 va accettato e recepito dall&#39;owner (elenco delle sostituzioni nell&#39;ADR).</li></ul><hr><h2 id="_13-undecies-m18-—-shell-piu-morbida-stato-vuoto-navigazione-dei-disegni-grafo-3d-applicazioni" tabindex="-1">13-undecies. M18 — Shell più morbida, stato vuoto, navigazione dei disegni, Grafo 3D, Applicazioni <a class="header-anchor" href="#_13-undecies-m18-—-shell-piu-morbida-stato-vuoto-navigazione-dei-disegni-grafo-3d-applicazioni" aria-label="Permalink to &quot;13-undecies. M18 — Shell più morbida, stato vuoto, navigazione dei disegni, Grafo 3D, Applicazioni&quot;">​</a></h2><p>Richiesta del 2026-11-15 (schizzo dell&#39;owner), in cinque punti più una revisione dell&#39;editor dei disegni: (1) angoli arrotondati nel layout, con le schede raccordate al contenuto; (2) stato vuoto della zona centrale con i comandi di creazione, in stile editor di note; (3) vista <strong>Grafo 3D</strong> dei link del vault con <code>3d-force-graph</code> e icone per tipo di documento, raggiungibile dal ribbon; (4) <strong>applicazioni</strong>: un URL registrato che si apre in un browser interno dentro una tab; (5) nel footer di Excalidraw, zoom sugli oggetti selezionati e mini-mappa; (6) miglioramenti e correttivi dell&#39;editor dei disegni (venti debolezze confermate, una con perdita di dati). Le decisioni scritte finora sono <a href="./adr/0053-navigazione-dei-disegni.html">ADR-0053</a> (navigazione dei disegni) e <a href="./adr/0054-editor-dei-disegni-merge-undo-ricarica-libreria-ricerca.html">ADR-0054</a> (editor dei disegni; emenda ADR-0010), entrambi <strong>accettati</strong> il 2026-11-15 (M20, §13-terdecies) e recepiti in <code>Specifications.md</code> v1.6 (ADR-0054 devia da §3.4.5 e §3.4.6). Il grafo 3D ha <a href="./adr/0055-grafo-3d.html">ADR-0055</a>, <strong>accettato</strong> e recepito (aggiunta a ADR-0013 e allo spec: §2.2.1, Appendice A, §3.4.6, §4.2); le applicazioni hanno <a href="./adr/0056-applicazioni-in-vista-nativa.html">ADR-0056</a>, <strong>accettato</strong> e recepito (anticipa il Web viewer da P2: §2.2.1, §2.6.6, §3.7, §4.2, Appendici B e C.2 dello spec; non tocca «una sola finestra» né la CSP). <strong>Aggiornamento M20:</strong> dove i paragrafi e le righe seguenti dicono «proposta» o «a cura dell&#39;owner» è lo stato del momento in cui furono scritti, e dove citano il grafo a due livelli, il driver solo macOS, il selettore rapido che cerca solo le note o il file <code>graph3d-csp.spec.ts</code> è segnata la modifica della 1.7.1. Il piano non è versionato.</p><p><strong>Stato: eseguita in parte (2026-11-15), versione 1.6.0.</strong> Fatte le tracce <strong>A</strong>, <strong>B</strong> e <strong>C</strong> (C1…C7) e conclusi i due spike <strong>D0</strong> ed <strong>E0</strong>, che <strong>non sono fusi</strong> (programmi usa-e-getta, nessun codice nel prodotto). <strong>Le tracce D (Grafo 3D) ed E (Applicazioni) non sono implementate:</strong> D1…D9 ed E1…E5 sono da fare, con le decisioni aperte qui sotto. Il tag è <code>v1.6.0</code> (decisione dell&#39;owner); le rimozioni di compatibilità che M17 fissava alla 1.6 passano alla <strong>1.7</strong>. <strong>Ordine seguito:</strong> A → B → C1…C7 nel checkout principale, gli spike D0 ed E0 in parallelo dall&#39;inizio perché decidono go/no-go e soglie; poi, quando si farà, D1…D9 ed E1…E5 (il Go va prima della UI: Go → <code>task gen</code> → frontend → prove → docs). Regola per ogni funzione nuova: voce in <code>shared/parity/features.yaml</code> → <code>task gen</code> → comando con <code>feature</code> e <code>requires</code> → binding → prove per superficie → <code>task parity</code> (<code>docs/desktop-web-sync.md</code>).</p><p><strong>Aggiornamento (2026-11-15, dopo la 1.6.0): la traccia D (Grafo 3D) è fatta, D1…D9, ed è nella 1.7.0.</strong> È committata su <code>main</code> (D1 <code>f806b6f</code>, D <code>c832455</code>, documenti <code>98b2dd1</code>) e <strong><code>task ci</code> completo è verde su quell&#39;albero</strong> (2026-11-15; budget stampati: console <code>initial 697 kB (limit 700)</code>, workbench <code>initial 1950 kB (limit 2500), total 17298 kB (limit 23000)</code>). ADR-0055 è stato accettato il 2026-11-15 (M20). <strong>Dopo la revisione del codice</strong> sono stati corretti, con una prova e2e ciascuno: nel livello a punti un solo click apriva il nodo (ora lo seleziona); nel livello a sprite un nodo nascosto dal timelapse si poteva cliccare e trascinare (ora no); la selezione restava riferita al grafo precedente dopo un aggiornamento; la texture dell&#39;anello di selezione non veniva rilasciata al cambio di tema; dopo un download fallito del chunk 3D, riscegliere il 3D ora lo riscarica. <strong>Resta non provato</strong> sulla WebView reale del desktop (WKWebView, WebView2, WebKitGTK), su GPU integrate, su Windows e Linux e su vault reali; le prove sono vitest, test Go, e2e in Chromium (mock dei binding e core WASM) e la prova di CSP sul web. Lo stato della traccia E (Applicazioni) è nel paragrafo seguente. Il paragrafo precedente descrive lo stato alla 1.6.0 e non si riscrive.</p><p><strong>Aggiornamento (2026-11-15, nella 1.7.0): la traccia E (Applicazioni) è fatta, E1…E5, ed è nella 1.7.0.</strong> È committata con le sigle <code>[M18-E1-E2]</code>, <code>[M18-E3-E4]</code> e <code>[M18-E5]</code> e fusa in <code>main</code>. <strong><code>task ci</code> completo è verde con le applicazioni dentro</strong> (2026-11-15; budget stampati: console <code>initial 697 kB (limit 700)</code>, workbench <code>initial 1996 kB (limit 2500), total 17344 kB (limit 23000)</code>; <code>task parity</code>: 96 funzioni, 203 comandi, 155 binding). ADR-0056 è stato accettato il 2026-11-15 (M20). <strong>Il flag <code>features.web_viewer</code> resta spento di default finché la matrice manuale <a href="./qa/m18-webview-matrice.html"><code>docs/qa/m18-webview-matrice.md</code></a> non è eseguita</strong> (nessun caso lo è). <strong>Eseguito:</strong> test Go di <code>internal/webview</code>, <code>internal/app</code>, <code>internal/shell</code> e <code>internal/sync</code> con <code>-race</code>; <code>go vet</code> per <code>GOOS=js</code>, <code>GOOS=windows CGO_ENABLED=0</code> e <code>GOOS=linux</code>; <code>task lint-go</code> con 0 rilievi; <code>task test-wasm</code>; <code>task gen</code> e <code>task check-gen</code>; <strong>la prova del driver su un Mac reale</strong> (<code>task test-nativeview</code>, macOS 27.2.1, arm64: 14 prove su 14); vitest del workbench (2.475 test, 115 nella cartella <code>webapp</code>), <code>task lint-ts</code>, <code>task parity</code> (96 funzioni, 203 comandi, 155 binding), e2e <code>webapp.spec.ts</code> (17 casi) sul mock dei binding e, per ciò che non richiede la vista incorporata, sul core WASM, e a11y; quattro prove di mutazione sul frontend (indirizzo non http accettato, testo della pagina reso come markup, vista sotto un dialogo, conferma dell&#39;origine saltata) fanno fallire i test. <strong>Dopo una revisione del frontend</strong> sono stati corretti altri rilievi, ciascuno con un test: una vista che finiva di aprirsi dopo che la scheda era stata lasciata restava disegnata sopra l&#39;altra scheda; la pagina poteva prendere la tastiera da un altro pannello; un trascinamento non concluso poteva lasciare le viste nascoste; dopo il blocco del vault l&#39;applicazione non si riapriva senza chiudere la scheda; gli eventi della vista arrivati prima della risposta di <code>Open</code> andavano persi; <code>F2</code> e i comandi dell&#39;editor non sono più riservati sopra una pagina. <strong>Dopo una revisione di sicurezza del core</strong> sono stati corretti otto rilievi, ciascuno con un test (i due confermati: la regola della rete privata restava accesa per tutta la vita di una vista aperta su un host privato; una vista aperta mentre il vault si chiudeva restava orfana). <strong>Non provato:</strong> nulla del frontend sulla finestra reale del desktop (posizionamento della vista sopra l&#39;HTML, bounds con lo zoom dell&#39;app diverso da 100%, sfarfallio nel nascondere e mostrare, fuoco da tastiera, sonda <code>elementsFromPoint</code> su <code>WKWebView</code>, trascinamento di una scheda sopra la vista); nella prova del driver, tastiera e mouse reali, camera e microfono, NTLM e certificato client, macOS precedente alla 14 e il limite di viste; Windows e Linux a runtime.</p><p><strong>Decisioni dell&#39;owner</strong></p><ul><li><strong>Browser delle applicazioni:</strong> webview nativa sovrapposta alla tab, solo desktop; sul web si apre una scheda del browser.</li><li><strong>Grafo 3D:</strong> interruttore 2D/3D dentro la vista grafo esistente.</li><li><strong>Angoli:</strong> schede arrotondate con raccordo concavo e angolo tra area centrale e sidebar; niente pannelli «a carta».</li><li><strong>Zoom nel footer:</strong> con selezione inquadra quella, senza selezione inquadra tutto il disegno.</li><li><strong>Sessioni delle applicazioni:</strong> persistenti per vault, locali al dispositivo, fuori dal vault.</li><li><strong>Piattaforme delle applicazioni:</strong> driver acceso <strong>solo macOS</strong>; su Windows e Linux la capability <code>embeddedBrowser</code> è spenta e l&#39;applicazione si apre nel browser di sistema (nessun driver GTK). <strong>Aggiornamento 1.7.1 (decisione dell&#39;owner):</strong> il driver Windows, una copia ridotta del binding WebView2 interno di Wails, entra nel codice <strong>compilato e spento</strong> finché non è provato su Windows; la capability resta macOS; Linux nessun driver.</li><li><strong>User agent delle applicazioni:</strong> simile a Safari.</li><li><strong>Schede in secondo piano:</strong> una vista nascosta ha i timer rallentati dal motore web; è accettato, non si tiene viva.</li><li><strong>Rilascio della traccia E:</strong> la 1.7.0 include le applicazioni, con il flag spento di default finché la matrice manuale non è eseguita.</li><li><strong>Rilascio:</strong> il tag è <code>v1.6.0</code>; le rimozioni di M17 per la 1.6 passano alla 1.7.</li></ul><table tabindex="0"><thead><tr><th>Traccia</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td>A — Angoli arrotondati</td><td>Scala <code>--radius-xs</code> … <code>--radius-pill</code> nel workbench (<code>packages/workbench/src/styles/tokens.css</code>; la console non cambia, <code>--radius</code> resta come alias); schede con angoli superiori arrotondati e raccordo concavo verso il contenuto (<code>style.css</code>); indicatore della scheda attiva in alto; corpo del pannello con angoli superiori arrotondati; raccordi nascosti in <code>forced-colors</code></td><td><strong>fatta (2026-11-15)</strong>. Verifica visiva con screenshot nei due temi e in split, non con snapshot automatici (<code>docs/qa/m8-shell-ui.md</code>)</td></tr><tr><td>B — Stato vuoto con comandi</td><td><code>workspace/EmptyPane.tsx</code>: un pannello senza schede offre <em>Nuova nota</em>, <em>Nuova lavagna</em>, <em>Nuovo disegno</em>, <em>Nuova presentazione</em> e il selettore rapido, con la scorciatoia effettiva; voce nascosta se il comando non è disponibile o il flag è spento, disabilitata su vault in sola lettura; il clic porta il fuoco sul pannello prima di eseguire il comando. Nessun comando nuovo: estende la voce <code>workspace.layout</code></td><td><strong>fatta (2026-11-15)</strong>. La voce per le applicazioni (<code>app:new</code>) ora c&#39;è (traccia E), nascosta con il flag <code>features.web_viewer</code> spento</td></tr><tr><td>C1 — Ciclo di vita del disegno</td><td>File reso invalido dall&#39;esterno non sovrascritto (<code>useNoteDocument</code> con <code>accept</code>, stato <code>rejected</code>, banner con la sola scelta «Sovrascrivi»); ricarica esterna che applica sfondo e griglia e aggiorna lo Slideshow senza riscrivere il file; <code>captureUpdate</code> esplicito (un&#39;azione è un passo di annullamento); scena non più serializzata a ogni <code>onChange</code>, firma a hash, <code>onChange</code> e <code>initialData</code> stabili (ADR-0054, punti 1-3)</td><td><strong>fatta (2026-11-15)</strong></td></tr><tr><td>C2 — Zoom sulla selezione</td><td>Due pulsanti accanto al controllo di zoom (<code>drawing/NavigationTools.tsx</code>). <strong>Deviazione dal piano:</strong> lo slot <code>&lt;Footer&gt;</code> del fork non è reso nel layout «tray» (quello di un disegno modificabile), quindi il gruppo è flottante, ancorato all&#39;isola dello zoom misurandola (dipende dalle classi <code>.zoom-actions</code>, <code>.Island</code>, <code>.App-bottom-bar</code> del fork); <code>drawing:zoom-to-fit-selected</code> esce dalle azioni di scena (funziona in sola lettura e senza <code>drawing_actions</code>); la barra inferiore del layout «tray», che il fork non conta nei margini di un fit, la misuriamo noi (<code>viewport.ts</code>, <code>bottomBarInset</code>). ADR-0053</td><td><strong>fatta (2026-11-15)</strong></td></tr><tr><td>C3 — Mini-mappa</td><td><code>drawing/Minimap.tsx</code> (resa semplificata su canvas 2D, moduli puri <code>drawing/minimap/</code>), clic, trascinamento, frecce e Home; nascosta in Zen, in presentazione e con il menu degli stili aperto; stato per dispositivo (<code>localStorage</code>, <code>drawing/uiPrefs.ts</code>); comando <code>drawing:toggle-minimap</code>; voce di parità <code>drawing.navigation</code>. ADR-0053</td><td><strong>fatta (2026-11-15)</strong></td></tr><tr><td>C4 — Due pannelli sullo stesso disegno</td><td><code>getSceneController()</code> sceglie l&#39;editor del pannello a fuoco; lo store dello Slideshow ha un proprietario; drop e dialoghi vanno all&#39;editor da cui partono</td><td><strong>fatta (2026-11-15)</strong></td></tr><tr><td>C5 — Merge nell&#39;editor</td><td><code>VaultAPI.MergeEdit</code>: merge a tre vie con <code>shared/go/merge</code> di modifiche non salvate e nuova versione su disco, al posto del banner; attesa fino a 20 s della fine di un gesto; pulsante «Tieni entrambe». Regola D-04: <code>sync.db</code> registra l&#39;autore della revisione di testa (migrazione <code>0004_head_author.sql</code>, <code>Manager.SameAuthorOnDisk</code>): su un vault condiviso un disegno si fonde solo se la versione su disco è dello stesso utente; le righe preesistenti non hanno autore e contano come «altro autore». ADR-0054, punti 4-6</td><td><strong>fatta (2026-11-15)</strong></td></tr><tr><td>C6 — Prestazioni</td><td>Auto-export 15 s dopo l&#39;ultimo salvataggio e alla chiusura (<code>export/autoExport.ts</code>); <code>DrawingAPI.Preview(vault, path, variant)</code> calcola l&#39;hash nel core (<code>ReadPreview</code> rimosso): un embed con anteprima in cache non rilegge il disegno e più embed condividono lettura e resa; soglie a 8 MB (non più indicizzato) e 10 MB (lento) misurate in byte sul file salvato</td><td><strong>fatta (2026-11-15)</strong></td></tr><tr><td>C7 — Rifinitura</td><td>Tema «Sistema» seguito a caldo; anteprime per tema (<code>&lt;hash&gt;.svg</code> e <code>&lt;hash&gt;.dark.svg</code>) con gli embed ricaricati al cambio di tema; potatura di <code>.clarae/cache/drawings/</code> all&#39;apertura del vault; libreria di forme con store condiviso e merge <strong>per id</strong> nella sync (strategia <code>library-by-id</code>, 13 fixture <code>library-*</code>); ricerca nei disegni su <code>originalText</code> e TeX delle formule, con la migrazione dell&#39;indice <code>0005_reindex_drawings.sql</code>. I tombstone degli elementi cancellati <strong>non</strong> si potano. ADR-0054, punti 9-14</td><td><strong>fatta (2026-11-15)</strong></td></tr><tr><td>D0 — Spike Grafo 3D (<code>3d-force-graph</code>)</td><td>Dipendenze pinnate, build desktop e web, CSP di produzione, WebGL, misure a 3.000 nodi su Apple M4. Esito: <strong>sì con tre condizioni</strong> — link in un unico <code>LineSegments</code> (con i link di serie 19 fps in orbita a 3.000 nodi), layout in un worker con forze alleggerite, tetto iniziale di 5.000 nodi; chunk di 793 kB caricato solo quando serve (totali 19,2 MB sul desktop e 17,2 MB sul web, su un budget di 23), zero <code>eval</code> con gli alias di <code>ngraph.*</code> e <code>three/webgpu</code>, CSP di produzione rispettata, contesto WebGL rilasciato</td><td><strong>concluso (2026-11-15), non fuso</strong>: il prototipo non è nel prodotto, le misure grezze sono in <a href="./qa/graph-3d-spike-d0/"><code>docs/qa/graph-3d-spike-d0/</code></a>. <strong>Non misurati:</strong> hardware più lento e la WebView reale di Wails</td></tr><tr><td>D1…D9 — Grafo 3D</td><td>D1 nodi <code>drawing</code>, <code>canvas</code> e <code>base</code> in <code>graph.Build</code> (disegni e lavagne sono anche sorgenti di link, una base solo destinazione) e opzione <code>ShowDocuments</code>; D2 <code>task gen</code>, mock e grafo 2D incrementale; D3 divisione di <code>GraphView.tsx</code> in guscio comune, <code>Graph2D</code> e <code>Graph3D</code> in un chunk lazy; D4-D6 superficie 3D (orbita, focus, icone per tipo di documento su <code>CanvasTexture</code>, <strong>due livelli di dettaglio nella 1.7.0, non i tre del piano</strong>: sprite fino a 2.000 nodi e un <code>Points</code> per aspetto oltre, perché lo spike misurava sprite e sfere come oggetti separati e costavano lo stesso, e il livello che cambiava le cose era quello a punti; <strong>tre nella 1.7.1</strong> (M20-S4): sprite fino a 1.000 nodi, solidi istanziati (un <code>InstancedMesh</code> per forma) da 1.001 a 2.000, punti oltre; layout nel worker con <code>d3-force-3d</code>; ripiego al 2D senza WebGL2, rilascio del contesto, colori dai token, <code>prefers-reduced-motion</code>); D7 comandi <code>graph:open-3d</code> e <code>graph:toggle-3d</code>, pulsante nel ribbon e voce di parità <code>graph.3d</code>; D8-D9 e2e <code>graph-3d.spec.ts</code>, prova di CSP (<code>web/e2e-security/graph3d-csp.spec.ts</code> nella 1.7.0, dalla 1.7.1 dentro <code>web/e2e-security/workbench-csp.spec.ts</code>), controllo di build <code>noRuntimeCode</code> e benchmark in <a href="./qa/graph-3d-benchmark.html"><code>docs/qa/graph-3d-benchmark.md</code></a>. ADR-0055</td><td><strong>fatta e nella 1.7.0 (2026-11-15)</strong>, committata su <code>main</code>; <code>task ci</code> verde. Misurato su Apple M4 e Chromium headless (60 fps in orbita con Metal fino a 5.000 nodi; 19…29 fps con rasterizzatore software). <strong>Non provato</strong> sulla WebView reale, su GPU integrate, su Windows e Linux, né su vault reali</td></tr><tr><td>E0 — Spike webview nativa in una tab</td><td>Programma usa-e-getta, solo API pubbliche di Wails (<code>NativeWindow()</code> e <code>InvokeSync</code>). Esito per sistema: <strong>macOS sì</strong> (eseguito: un sito con <code>X-Frame-Options: DENY</code> caricato, bounds entro 1 pt, isolamento, scorciatoie riservate, 200 cicli di apertura e chiusura senza crash); <strong>Windows sì condizionato</strong> a una copia ridotta del binding WebView2 interno di Wails (compilato, mai eseguito; stima 4-6 giorni); <strong>Linux no per ora</strong> (compilato in un container, mai eseguito)</td><td><strong>concluso (2026-11-15), non fuso</strong>: programma usa-e-getta, nessun codice nel prodotto; i log non sono conservati e le sue misure sono state ripetute dalla prova del driver (<code>task test-nativeview</code>)</td></tr><tr><td>E1…E5 — Applicazioni</td><td>E1 core Go (<code>internal/webview</code>: <code>Driver</code>, <code>Manager</code>, <code>Fake</code>, <code>ValidateURL</code>), binding <code>WebViewAPI</code> (13 metodi, con risposta <code>webview-unavailable</code> sul core WASM), dieci eventi <code>webview:*</code>, capability <code>embeddedBrowser</code> (campo <code>DesktopOS</code> di <code>CapabilitySpec</code>: dipende dal sistema operativo a runtime); E2 driver acceso <strong>solo per macOS</strong> (<code>internal/shell/nativeview</code>, <code>WKWebView</code> figlio della stessa finestra, cgo); su Windows e Linux capability spenta (<strong>1.7.1:</strong> su Windows c&#39;è un driver compilato e spento, su Linux nessuno); prova a mano con <code>task test-nativeview</code>; E3 file <code>.webapp</code> nel vault (<code>{&quot;version&quot;:1,&quot;url&quot;:&quot;https://…&quot;}</code>) e comandi <code>app:*</code>, conferma alla prima apertura di un&#39;origine; E4 <code>BrowserView</code> con barra e gestore unico delle viste (<code>webapp/nativeViews.ts</code>: bounds come frazioni del viewport, vista sempre sopra l&#39;HTML con sonda <code>elementsFromPoint</code>, inoltro delle scorciatoie riservate); E5 matrice di QA per sistema operativo <a href="./qa/m18-webview-matrice.html"><code>docs/qa/m18-webview-matrice.md</code></a> (scritta, nessun caso eseguito), guide, voci di parità <code>webapp</code> e <code>webapp.embedded</code> (quest&#39;ultima <code>exception</code> sul workbench), <a href="./adr/0056-applicazioni-in-vista-nativa.html">ADR-0056</a></td><td><strong>fatta (2026-11-15)</strong>, nella 1.7.0, <code>task ci</code> verde. Il flag <code>features.web_viewer</code> resta <code>false</code> finché la matrice di QA non è eseguita. <strong>1.7.1:</strong> il selettore rapido trova i <code>.webapp</code>, una pulizia in background cancella i dati di sessione dei vault che non esistono più, il driver Windows è nel codice e spento (§13-terdecies). <strong>Non provato</strong> sulla finestra reale: il frontend (vedi il paragrafo di aggiornamento sopra)</td></tr></tbody></table><p><strong>Decisioni (per D ed E)</strong></p><ul><li><strong>Windows e Linux: decise dal proprietario.</strong> Driver acceso solo macOS; su Windows e Linux la capability è spenta e l&#39;applicazione si apre nel browser di sistema. Nella 1.7.0 non si copiava il binding WebView2 interno di Wails (condizione dello spike E0) e non c&#39;è un driver GTK. <strong>Aggiornamento 1.7.1:</strong> il proprietario ha deciso di includere il driver Windows, compilato ma spento finché non è provato su Windows (§13-terdecies); Linux resta senza driver; si riprende se e quando si vorrà un browser incorporato anche lì.</li><li><strong>User agent della webview</strong> delle applicazioni: <strong>deciso</strong>, simile a Safari (una vista nuova che non si presenta come un browser noto è trattata peggio da alcuni siti).</li><li><strong>Schede in secondo piano: deciso.</strong> Una vista nativa nascosta ha i timer rallentati dal motore web (misurato su macOS nello spike E0), quindi chat e riproduzione rallentano quando la scheda non è attiva; è accettato e la vista non si tiene viva.</li><li><strong>Grafo 3D:</strong> le tre condizioni di D0 e il tetto di 5.000 nodi sono assunti da ADR-0055 (in proposta); i livelli di dettaglio erano due nella 1.7.0 e <strong>sono tre dalla 1.7.1</strong> (solidi istanziati da 1.001 a 2.000 nodi, §13-terdecies). Restano da fare la misura sulla WebView reale (<code>task run-desktop</code>) e su hardware più lento, e l&#39;accettazione dell&#39;ADR da parte dell&#39;owner; il tetto si alza solo dopo quelle misure.</li></ul><p><strong>Criteri di uscita della parte eseguita</strong> (esito registrato)</p><ul><li>Prove eseguite sull&#39;albero non committato del 2026-11-15: vitest sulle aree toccate; test Go dei pacchetti toccati; <code>task test-wasm</code>; <code>task conformance</code> (con le 13 fixture <code>library-*</code>); e2e Playwright dei disegni sul mock dei binding e, per gli spec nuovi, sul core WASM nel browser; <code>task parity</code>. <strong><code>task ci</code> completo è verde</strong> sullo stesso albero (2026-11-15), dopo due correzioni: sei occorrenze del vecchio nome nel Go nuovo (due test passati alla costante <code>LegacyConfigDir</code>, due righe <code>legacy</code> in più nell&#39;allowlist) e un rilievo <code>unparam</code> di <code>golangci-lint</code> introdotto dal test nuovo sull&#39;autore della revisione (<code>head_author_test.go</code>, corretto nel test). Le suite lente (integrazione del cloud, matrice e2e completa) non sono state eseguite per intero.</li><li>Un test preesistente è instabile sotto carico: <code>packages/workbench/src/workspace/marpNotesTabSwitch.test.tsx</code> fallisce a volte quando gira insieme agli altri, anche sul codice precedente (3 volte su 6 nello stesso gruppo), e passa da solo.</li><li><strong>Non provato:</strong> il posizionamento del gruppo di zoom e la mini-mappa su una WebView reale (WKWebView, WebView2, WebKitGTK); la fusione nell&#39;editor su un vault condiviso con due utenti reali; il ritorno alla 1.5 sullo stesso dispositivo dopo le migrazioni di <code>sync.db</code> e <code>index.db</code>.</li><li><strong>Specifica:</strong> ADR-0053 e ADR-0054 sono stati accettati e recepiti in <code>Specifications.md</code> v1.6 (M20, 2026-11-15).</li><li><strong>Traccia D (nella 1.7.0):</strong> <a href="./adr/0055-grafo-3d.html">ADR-0055</a> è stato accettato e recepito in <code>Specifications.md</code> v1.6 (§2.2.1, Appendice A, §3.4.6, §4.2; M20). <code>task ci</code> è verde sull&#39;albero rilasciato (2026-11-15). <strong>Da fare:</strong> la verifica manuale con <code>task run-desktop</code> (grafo 3D su un vault con qualche migliaio di note, apertura e chiusura ripetute, nessun avviso sui contesti WebGL).</li><li><strong>Traccia E (nella 1.7.0):</strong> <a href="./adr/0056-applicazioni-in-vista-nativa.html">ADR-0056</a> è stato accettato e recepito in <code>Specifications.md</code> v1.6 (§2.2.1, Appendice B, C.2, §2.6.6, §3.7, §4.2, C.4 e i formati del vault; M20). <strong>Da fare:</strong> la matrice manuale <a href="./qa/m18-webview-matrice.html"><code>docs/qa/m18-webview-matrice.md</code></a> su macOS (14 o successivo, e 13), la verifica del ripiego su Windows e Linux e del workbench web, poi la decisione di accendere il flag di default; e un <code>task ci</code> completo registrato con le applicazioni dentro. Il codice nativo dell&#39;applicazione desktop non è provato dal solo <code>task ci</code>: la prova del driver è a mano, <code>task test-nativeview</code>.</li><li><strong>Prove manuali (1.7.1):</strong> l&#39;ordine, i comandi per preparare l&#39;ambiente (anche con il cloud e il profilo con <code>features.web_viewer</code>), le misure del grafo 3D sulla finestra reale e il registro degli esiti sono nel runbook <a href="./qa/verifica-manuale-1.7.html"><code>docs/qa/verifica-manuale-1.7.md</code></a>. Nessuna prova è ancora eseguita.</li></ul><hr><h2 id="_13-duodecies-m19-—-versione-1-7-0-rimozioni-di-compatibilita" tabindex="-1">13-duodecies. M19 — Versione 1.7.0: rimozioni di compatibilità <a class="header-anchor" href="#_13-duodecies-m19-—-versione-1-7-0-rimozioni-di-compatibilita" aria-label="Permalink to &quot;13-duodecies. M19 — Versione 1.7.0: rimozioni di compatibilità&quot;">​</a></h2><p>Le tre rimozioni di compatibilità con la 1.x che M17 fissava alla 1.6 e che l&#39;owner ha spostato alla 1.7 (decisione del 2026-11-15, <a href="./adr/0052-rebrand-clarae-notanda.html">ADR-0052</a>). Insieme alle rimozioni, la 1.7.0 porta il grafo 3D e le applicazioni di M18 (tracce D ed E, §13-undecies). Sigle dei commit: <code>[M19-R1]</code>, <code>[M19-R2]</code>, <code>[M19-R3]</code>, <code>[M19]</code>.</p><p><strong>Stato: eseguita (2026-11-15), versione 1.7.0.</strong> Il resto della compatibilità con la 1.x resta alla 2.0, come nella tabella di <a href="./admin-guide/migrazione-clarae.html"><code>docs/admin-guide/migrazione-clarae.md</code></a>.</p><table tabindex="0"><thead><tr><th>Sessione</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td>R1 — Advisory lock</td><td><code>AdvisoryLockKeys</code> (<code>services/cloud/internal/db/locks.go</code>) restituisce solo <code>clarae.&lt;tipo&gt;:&lt;id&gt;</code> (blob, quota degli upload, export); nelle linee 1.5 e 1.6 prendeva prima il nome della 1.x e poi quello nuovo. <strong>Vincolo operativo:</strong> un pod 1.4 o precedente non deve mai girare insieme a un pod 1.7 o successivo sullo stesso database; da 1.4 o precedente si passa per la 1.5 o la 1.6. Il ritorno alla 1.4.0 è possibile solo senza pod 1.7 in esecuzione</td><td><strong>fatta</strong>. Test: <code>locks_test.go</code>; <code>test/integration/advisory_lock_test.go</code> sostituisce il test che simulava un pod 1.4</td></tr><tr><td>R2 — Immagine</td><td><code>.github/workflows/release.yml</code> pubblica solo <code>ghcr.io/&lt;owner&gt;/clarae-cloud</code>; non esiste un tag 1.7.x con il nome della 1.x (i tag 1.5 e 1.6 con il nome vecchio restano nel registry). Chi ha le variabili dell&#39;immagine del Compose (<code>CLARAE_IMAGE</code>, o quella della 1.x) o <code>image.repository</code> di Helm che puntano all&#39;immagine con il nome della 1.x la cambia in <code>clarae-cloud</code> prima della 1.7</td><td><strong>fatta</strong>. <strong>Il workflow non è stato eseguito</strong> (serve un tag pubblicato): riletto e analizzato come YAML, <code>actionlint</code> non installato</td></tr><tr><td>R3 — <code>config_dir_v2</code></td><td><code>features.config_dir_v2</code> è <code>true</code> per default (<code>api/config-profile.schema.json</code>, generati rigenerati): il motore di sync sposta le impostazioni sincronizzate dei vault collegati nella cartella <code>.clarae/</code>. <strong>Correzione collegata:</strong> lo spostamento parte solo dopo aver letto un profilo del server, fresco o in cache (<code>configDirV2Enabled</code> in <code>apps/desktop/internal/app/managed.go</code>, test <code>TestConfigDirV2FromProfile</code>). Un cloud 1.7 distribuisce <code>true</code>, uno 1.5 o 1.6 <code>false</code></td><td><strong>fatta</strong>. <strong>Limite noto, non corretto:</strong> passando nella stessa sessione a un altro server con la cache fresca, il valore del server precedente vale fino al refresh successivo</td></tr></tbody></table><p><strong>Per chi amministra</strong> (ordine in <code>migrazione-clarae.md</code>, «Aggiornare alla 1.7»): aggiornare prima ogni dispositivo dei vault collegati, poi i riferimenti all&#39;immagine, mai un pod 1.4 con un pod 1.7, poi il cloud. Per non spostare le impostazioni: <code>&quot;features&quot;: {&quot;config_dir_v2&quot;: false}</code> nel profilo e toglierlo quando tutti i dispositivi sono aggiornati. Un dispositivo 1.4 rimasto sul vault dopo lo spostamento ricrea le impostazioni che non trova nella cartella vecchia: due copie con id diversi, da riconciliare a mano (il motore non sposta un file se nella cartella nuova c&#39;è già quel nome, quindi non si perdono dati).</p><p><strong>Criteri di uscita</strong> (esito registrato)</p><ul><li><strong>Eseguito:</strong> <code>task gen</code> e <code>task check-gen</code>; test Go di sync, app, vault e features (compreso <code>TestAdminGuideDocumentsEveryKey</code>); test del cloud dei pacchetti toccati; sottoinsieme dei test d&#39;integrazione su lock, blob, tus, quota ed export con Docker (verde); <code>task test-wasm</code>; vitest di workbench e web; <code>golangci-lint</code> con 0 rilievi. <code>task ci</code> completo è verde sull&#39;albero del grafo 3D (traccia D) del 2026-11-15; non è registrato qui un <code>task ci</code> ripetuto sull&#39;albero con le rimozioni.</li><li><strong>Non eseguito al momento della 1.7.0:</strong> l&#39;intera <code>task test-integration</code> e il workflow di release (R2). <strong>Aggiornamento:</strong> <code>task test-integration</code> è verde sull&#39;albero della 1.7.1 (M20); il workflow di release con la modifica di R2 è stato eseguito dal push del tag <code>v1.7.0</code> (2026-11-15, 14:21 UTC, esito positivo, 13 minuti) e ha pubblicato la release «Clarae notanda 1.7.0».</li><li><strong>Anche nella 1.7.0:</strong> la traccia E di M18 (applicazioni in una scheda, vista nativa su macOS, <code>features.web_viewer</code> spento di default): stato e prove in §13-undecies. Non è registrato qui un <code>task ci</code> ripetuto sull&#39;albero con le applicazioni e le rimozioni insieme.</li></ul><hr><h2 id="_13-terdecies-m20-—-versione-1-7-1-chiusura-dei-sospesi-di-m18" tabindex="-1">13-terdecies. M20 — Versione 1.7.1: chiusura dei sospesi di M18 <a class="header-anchor" href="#_13-terdecies-m20-—-versione-1-7-1-chiusura-dei-sospesi-di-m18" aria-label="Permalink to &quot;13-terdecies. M20 — Versione 1.7.1: chiusura dei sospesi di M18&quot;">​</a></h2><p>Piano del 2026-11-15 (non versionato). Parte da <code>main</code> = <code>v1.7.0</code>, che il piano credeva solo locale: <code>main</code> e il tag <code>v1.7.0</code> erano invece già stati pubblicati (push del 2026-11-15, 14:21 UTC, non fatto da questa sessione), con la release «Clarae notanda 1.7.0»; le tredici voci rimaste dopo la 1.7.0 (suite complete, prove manuali, livello intermedio del grafo 3D, selettore rapido, dati di sessione, driver Windows, ADR e spec, push). Sigle dei commit: <code>[M20-S1]</code> … <code>[M20-S7]</code>, autore Efrem Ropelato, senza <code>Co-Authored-By</code>. Il lavoro delle sessioni S2…S6 è nel working tree, <strong>non ancora committato</strong> (i commit sono di S7), e <strong>la revisione del codice della 1.7.1 è in corso</strong> al momento di questa scrittura: può portare piccole correzioni, e la roadmap non ne descrive i dettagli.</p><p><strong>Stato: eseguita in parte (2026-11-15), versione 1.7.1 non ancora rilasciata.</strong> Fatte le sessioni S1…S6; S7 (rilascio) da fare.</p><p><strong>Decisioni dell&#39;owner</strong></p><ul><li><strong>ADR e spec (voce 10):</strong> gli ADR 0053, 0054, 0055 e 0056 sono accettati e <code>Specifications.md</code> è aggiornato dagli elenchi in fondo agli ADR, per richiesta esplicita (in deroga alla regola che vieta di modificarlo in automatico). Lo spec passa alla <strong>v1.6</strong>.</li><li><strong>Push (voce 12):</strong> solo alla fine, con <code>task ci</code> verde: <code>main</code> e il tag <code>v1.7.1</code>; conferma finale prima del push. (<code>v1.7.0</code> risultava già pubblicato: vedi sopra.)</li><li><strong>Prove manuali e misure su finestra reale (voci 2, 3, 11):</strong> le esegue l&#39;owner; si preparano strumenti e istruzioni (runbook <a href="./qa/verifica-manuale-1.7.html"><code>docs/qa/verifica-manuale-1.7.md</code></a>).</li><li><strong><code>features.web_viewer</code> (voce 9):</strong> resta <strong>spento di default</strong>: la matrice manuale non è eseguita.</li><li><strong>Livelli di dettaglio del 3D (voce 4):</strong> livello intermedio istanziato (<code>InstancedMesh</code> per tipo) tra sprite e punti, con misura prima e dopo; se non migliorava si toglieva e si scriveva. Migliora: resta.</li><li><strong>Windows e Linux (voce 5):</strong> driver Windows (copia ridotta del binding WebView2) compilato ma spento finché non è provato su Windows; Linux nessun driver.</li><li><strong>Dati di sessione (voce 6):</strong> la deviazione dal piano resta e si registra (ora accettata con ADR-0056); si aggiunge la pulizia degli archivi dei vault che non esistono più.</li></ul><table tabindex="0"><thead><tr><th>Sessione</th><th>Voci</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td>S1 — Suite complete</td><td>1, 13</td><td>Le suite lente sulla base <code>v1.7.0</code>, in un worktree; poi la correzione di ciò che falliva</td><td><strong>fatta (2026-11-15)</strong>, macchina molto carica: <code>e2e:security</code> 11/11; <code>task test-integration</code> verde; <code>e2e-desktop-prod</code> 44/44; <code>e2e-web</code> 97/97; <code>e2e-desktop</code> 235 passati e 1 fallito (contesti WebGL del grafo 3D, oltre il timeout di 30 s); matrice 442 passati e 4 falliti al primo giro, tutti in <code>graph-3d.spec.ts</code>, poi verdi rilanciati. <code>graph-3d.spec.ts</code> stabilizzato (S4)</td></tr><tr><td>S2 — Selettore rapido e archivi</td><td>7, 6</td><td>Il selettore rapido trova le applicazioni (<code>.webapp</code>), le lavagne, le basi e i disegni (<code>links.SuggestFiles</code>, <code>QuickSwitcher.tsx</code>), con il tipo letto dai lettori di schermo; un file di un altro tipo con lo stesso nome non nasconde «Crea nota». Pulizia in background, dopo l&#39;avvio, dei dati di sessione delle applicazioni dei vault che non esistono più (<code>webviews_sweep.go</code>): mai per un vault solo chiuso, su un disco non montato o in un punto di mount non montato (cartella madre vuota); ricontrollo prima di cancellare. File in <code>.trash/</code> e nelle cartelle nascoste fuori dal selettore e dai suggerimenti dei wikilink; «Crea nota» tolta anche da una presentazione <code>.marp</code> omonima</td><td><strong>fatta (2026-11-15)</strong>, nel working tree. Provata da vitest, test Go ed e2e in Chromium</td></tr><tr><td>S3 — Driver Windows spento</td><td>5</td><td><code>internal/shell/nativeview</code> per Windows su una copia ridotta e corretta del binding WebView2 di Wails v3.1.0 (<code>webview2/</code>, con <code>LICENSE</code> e <code>NOTICE</code>), compilata per amd64 e arm64 con CGO spento (<code>task ci</code> ha il passo <code>vet-windows</code>); si accende solo con <code>CLARAE_WEBVIEW2_EXPERIMENTAL=1</code>, e anche così la capability <code>embeddedBrowser</code> resta solo macOS</td><td><strong>fatta (2026-11-15)</strong>, nel working tree. <strong>Mai eseguito su Windows</strong>; verificato davvero spento dalla revisione</td></tr><tr><td>S4 — Livello intermedio</td><td>4, 8</td><td>Sprite fino a 1.000 nodi, solidi istanziati da 1.001 a 2.000, punti oltre; sette forme; legenda con la forma; trascinamento fino a 2.000; la presa di un nodo si chiude se il grafo cambia e i controlli della camera restano attivi. Prova CSP del 3D dentro <code>workbench-csp.spec.ts</code>; benchmark con <code>CLARAE_GRAPH3D_KINDS=mixed</code> e <code>CLARAE_GRAPH3D_LOD</code></td><td><strong>fatta (2026-11-15)</strong>, nel working tree. Misure su Chromium e una macchina carica (Metal: 8 draw call e 0,1 ms di CPU per frame contro 0,9 e 1,8 ms degli sprite; software a 2.000 nodi 11,3 / 27,3 fps contro 9,3 / 18,0): <a href="./qa/graph-3d-benchmark.html"><code>graph-3d-benchmark.md</code></a>. Non visto sulla finestra reale</td></tr><tr><td>S5 — Verifica manuale</td><td>2, 3, 11</td><td>Runbook unico per l&#39;owner: avvio con il cloud e il profilo con <code>features.web_viewer</code>, vault grandi per il 3D, ordine delle checklist, dove registrare gli esiti</td><td><strong>fatta (2026-11-15)</strong>: <a href="./qa/verifica-manuale-1.7.html"><code>docs/qa/verifica-manuale-1.7.md</code></a>, completato con le novità della 1.7.1. <strong>Nessuna prova è eseguita.</strong> Le soglie che propone (≥ 30 fps in orbita a 5.000 nodi, nessun avviso WebGL dopo dieci aperture e chiusure, matrice macOS 14 o successivo senza P0 e P1) sono <strong>proposte non fissate dall&#39;owner</strong></td></tr><tr><td>S6 — Spec e ADR</td><td>10, 9</td><td>ADR 0053…0056 accettati e recepiti, <code>Specifications.md</code> v1.6, ADR-0055 e ADR-0056 aggiornati (tre livelli, selettore rapido, pulizia degli archivi, driver Windows spento, <code>web_viewer</code> spento di default), guide, matrice M4/M42 e sottosezione del driver Windows</td><td><strong>fatta (2026-11-15)</strong></td></tr><tr><td>S7 — Rilascio</td><td>12</td><td>Versione 1.7.1, CHANGELOG, <code>task ci</code>, suite complete ripetute sull&#39;albero della 1.7.1, commit per sessione, tag <code>v1.7.1</code>, conferma, push</td><td><strong>fatta (2026-11-15)</strong>: <code>task ci</code> e suite complete verdi (esito sotto), tag <code>v1.7.1</code>; push in attesa della conferma dell&#39;owner</td></tr></tbody></table><p><strong>Revisione del codice (2026-11-15):</strong> due rilievi medi (pulizia su un punto di mount non montato; controlli della camera spenti dopo un aggiornamento del grafo) e quattro bassi (indicizzazione di un test della pulizia, ricontrollo prima di cancellare, file nascosti nel selettore, «Crea nota» con una presentazione omonima, <code>task ci</code> che non compilava il codice Windows), tutti corretti con un test ciascuno.</p><p><strong>Per chi amministra:</strong> nessuna migrazione e nessun cambio di contratto. Il cloud non cambia; i client si installano a mano. La pulizia dei dati di sessione parte da sola al primo avvio dopo l&#39;aggiornamento e riguarda solo vault che non esistono più con certezza (guida <a href="./admin-guide/profili-quote-audit.html#applicazioni-note-per-chi-amministra">profili, quote e audit</a>). <code>features.web_viewer</code> resta spento di default.</p><p><strong>Criteri di uscita</strong> (esito da registrare in S7)</p><ul><li><strong>Eseguito (S1):</strong> le suite complete su <code>v1.7.0</code> (tabella sopra).</li><li><strong>Eseguito sull&#39;albero della 1.7.1 (2026-11-15):</strong> <code>task ci</code> completo verde; <code>e2e-desktop</code> 244 passati, <code>e2e-desktop-prod</code> 44, <code>e2e-web</code> 97, <code>e2e:security</code> 11, <code>task test-integration</code> verde, matrice 462 passati e 1 fallito (un test di <code>drawing.spec.ts</code> su web-core, poi 60 su 60 rilanciato), nel giro precedente 463 su 463. Prima del tag la matrice ha trovato un difetto preesistente del fuoco (la ricerca della libreria di Excalidraw toglieva il fuoco alla palette), corretto in <code>packages/ui/src/focus.ts</code>.</li><li><strong>Non provato:</strong> nulla delle novità sulla finestra reale del desktop (livello a solidi, selettore rapido, pulizia dei dati di sessione); il driver Windows mai eseguito su Windows; le misure del 3D su una macchina carica e un grafo sintetico; la matrice delle applicazioni e le prove manuali del runbook.</li><li><strong>Specifica:</strong> fatta in S6 (<code>Specifications.md</code> v1.6). Non recepiti ADR-0023 e ADR-0045…0052, che restano all&#39;owner; lo spec dice ancora Wails v2 e la nomenclatura della 1.x del prodotto e della cartella di configurazione (ADR-0052 non è recepito).</li></ul><hr><h2 id="_13-quaterdecies-m21-—-correttivi-dello-schizzo-del-2026-11-15" tabindex="-1">13-quaterdecies. M21 — Correttivi dello schizzo del 2026-11-15 <a class="header-anchor" href="#_13-quaterdecies-m21-—-correttivi-dello-schizzo-del-2026-11-15" aria-label="Permalink to &quot;13-quaterdecies. M21 — Correttivi dello schizzo del 2026-11-15&quot;">​</a></h2><p>Richiesta dell&#39;owner del 2026-11-15 (schizzo annotato): <strong>dodici punti</strong>, tra difetti e richieste, su console web, desktop, cloud e workbench. L&#39;analisi del codice ha trovato per quasi tutti una causa precisa e ha cambiato il perimetro in tre punti. <strong>Applicazioni (10):</strong> esistono già (ADR-0056) e sono invisibili perché <code>features.web_viewer</code> è spento di default; mancano solo il pulsante nell&#39;esploratore e il nome senza <code>.webapp</code>, e l&#39;owner ha deciso di accendere il flag. <strong>Audit (7):</strong> nessuna migrazione e nessun job cancella <code>audit_log</code> (la sola <code>UPDATE</code> è l&#39;anonimizzazione dell&#39;account, <code>privacy.sql</code>); la causa probabile è un database ricreato durante l&#39;aggiornamento di E2BR (Helm, namespace <code>clarae</code> contro quello con il nome della 1.x di <code>Upgrade.md</code>). <strong>E2BR esegue la 1.5.1:</strong> con un cloud 1.5 o 1.6 <code>features.config_dir_v2</code> arriva spento e le impostazioni restano nella cartella di configurazione della 1.x (punto 9); le correzioni arrivano con la nuova versione, e l&#39;aggiornamento di E2BR si fa con la procedura dell&#39;Onda F.</p><p>Le deviazioni dallo spec sono registrate in cinque ADR, <strong>accettati dall&#39;owner il 2026-11-16</strong> e <strong>recepiti</strong> in <code>Specifications.md</code> v1.7 il 2026-11-16 (su richiesta dell&#39;owner, secondo <a href="./spec-v1.7-proposta.html"><code>docs/spec-v1.7-proposta.md</code></a>): <a href="./adr/0057-identita-dispositivo-desktop-hostname.html">ADR-0057</a> (dispositivo desktop per hostname e revoca al logout, punto 6), <a href="./adr/0058-logout-completo-da-keycloak.html">ADR-0058</a> (logout completo da Keycloak, punto 5), <a href="./adr/0059-pulizia-cartella-configurazione-legacy-e-zip-coerente.html">ADR-0059</a> (pulizia della cartella di configurazione legacy e ZIP coerente, punto 9; emenda ADR-0052) <a href="./adr/0060-web-viewer-acceso-di-default.html">ADR-0060</a> (<code>features.web_viewer</code> acceso di default, punto 10; emenda ADR-0056) e <a href="./adr/0061-budget-iniziale-console-720.html">ADR-0061</a> (budget iniziale della console a 720 kB; emenda ADR-0020). Nessun commit senza richiesta esplicita dell&#39;owner.</p><p><strong>Stato: implementata (2026-11-16), committata per sessione M21-S1…S8 e rilasciata come versione 1.7.2 (tag <code>v1.7.2</code>); prove manuali da fare; ADR accettati e recepiti nello spec v1.7 il 2026-11-16 ([M21-S9]).</strong> Versione decisa dall&#39;owner: 1.7.2, con una migrazione del cloud (<code>0016</code>). ADR 0057…0061 scritti in <em>proposta</em> e <strong>accettati dall&#39;owner il 2026-11-16</strong> (con ADR-0052, il rebrand); preparata la proposta di recepimento <a href="./spec-v1.7-proposta.html"><code>docs/spec-v1.7-proposta.md</code></a> (spec v1.7, con la nomenclatura <em>Clarae notanda</em>). <strong><code>Specifications.md</code> è alla v1.7</strong>, applicata su richiesta esplicita dell&#39;owner, con la nomenclatura <em>Clarae notanda</em> in tutto lo spec. La documentazione di chiusura (CHANGELOG [1.7.2], guide, runbook <a href="./qa/m21-correttivi.html"><code>docs/qa/m21-correttivi.md</code></a>) è scritta. <strong>Nulla è provato su una finestra reale, su un Keycloak vero o su E2BR.</strong></p><p><strong>Decisioni dell&#39;owner</strong></p><ul><li><strong>Applicazioni (punto 10):</strong> <code>features.web_viewer</code> <strong>acceso di default</strong> (ADR-0060). Sul desktop la vista integrata resta solo su macOS; altrove c&#39;è la scheda «Apri nel browser».</li><li><strong>Dispositivi (punto 6):</strong> il dispositivo desktop è identificato dall&#39;hostname (ADR-0057); due macchine con lo stesso hostname e la stessa piattaforma si fondono in un solo dispositivo.</li><li><strong>Audit (punto 7):</strong> le interrogazioni di diagnosi su E2BR sono <strong>un compito dell&#39;owner</strong>, non partono in automatico (vedi l&#39;Onda F). Un eventuale <code>pg_dump</code> del vecchio database e il suo ripristino si pianificano con l&#39;owner.</li><li><strong>Spec:</strong> non si modifica in automatico. Il 2026-11-16 l&#39;owner accetta gli ADR 0057…0061 e ADR-0052 e chiede esplicitamente di applicare <code>docs/spec-v1.7-proposta.md</code>: lo spec è alla v1.7 ([M21-S9]).</li></ul><p><strong>Scostamenti dal piano, scoperti implementando</strong> (scritti negli ADR e nel CHANGELOG)</p><ul><li><strong>Nessuna nuova registrazione automatica del dispositivo</strong> (ADR-0057, punto 7): il piano prevedeva di ripetere la registrazione al primo <code>commit</code> rifiutato per <code>device_id</code> sconosciuto o revocato. Non è implementata: renderebbe una revoca dalla console annullabile dal computer stesso, contro §1.7. Resta il pulsante «Registra di nuovo questo dispositivo», che riattiva la stessa riga grazie all&#39;upsert. Il punto aperto dell&#39;ADR è risolto in questo senso, e l&#39;owner lo ha confermato accettando l&#39;ADR (2026-11-16).</li><li><strong><code>POST /me/devices</code> risponde sempre <code>201</code></strong>, anche quando riattiva una riga (il contratto non ha altri codici di successo).</li><li><strong>Logout desktop: prima la sessione, poi la revoca del token</strong> (ADR-0058, punto 7): Keycloak identifica la sessione dal token di rinnovo, che dopo la revoca non basta più. Il marcatore dell&#39;uscita è il file <code>auth-logged-out</code> nella cartella dati, non una voce di <code>auth.json</code>.</li><li><strong>Pulizia della cartella legacy: file identico cancellato, file diverso nel cestino</strong> anche per le righe sincronizzate (<code>RemoveShadowedConfig</code>), e snapshot diversi lasciati dove sono, non cancellati (ADR-0059).</li><li><strong>Azione dell&#39;esploratore nel registro di parità:</strong> è la stessa funzione di <code>app:new</code> ed è descritta nella nota della voce <code>webapp</code>; non ha un id proprio, e la prova <code>FileExplorer.webapp.test.tsx</code> non è tra le prove elencate della voce (da decidere se aggiungerla).</li><li><strong><code>DB_EXPECT_INITIALIZED</code> anche con Compose:</strong> dopo la revisione del codice <code>deploy/compose/compose.yaml</code> inoltra la variabile (<code>.env.example</code> ha la riga commentata); i valori di k3d la tengono a <code>&#39;false&#39;</code>.</li><li><strong>Correzioni della revisione:</strong> l&#39;uscita della console si completa anche se la revoca dei token fallisce; lo ZIP privato esporta la copia legacy sana se quella in <code>.clarae/</code> non si può esportare; l&#39;uscita del desktop con un token scaduto non riavvia la sync; la riga <code>database state</code> non ritarda l&#39;ascolto.</li><li><strong>Passo 0 della diagnosi del logout non fatto:</strong> la causa del rientro senza password su E2BR non è accertata (ADR-0058).</li></ul><h3 id="onde-e-work-package" tabindex="-1">Onde e work package <a class="header-anchor" href="#onde-e-work-package" aria-label="Permalink to &quot;Onde e work package&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Onda</th><th>Punti</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td><strong>0 — ADR</strong></td><td>5, 6, 9, 10</td><td>ADR 0057…0060 (poi anche 0061, il budget della console) e questa sezione della roadmap; accettati il 2026-11-16</td><td><strong>fatta (2026-11-15)</strong>: ADR in stato <em>proposta</em></td></tr><tr><td><strong>A — UI della console e presentazioni</strong></td><td>1, 2, 3, 8, 4</td><td><strong>1.</strong> «Scarica ZIP» uniforme: <code>PrivateExport</code> (<code>web/src/pages/VaultExport.tsx</code>) usa <code>vaultExport.download</code> come testo visibile; l&#39;<code>aria-label</code> <code>downloadPrivateAria</code> resta; si toglie <code>vaultExport.downloadPrivate</code> da <code>it.json</code> e <code>en.json</code>; si aggiornano <code>docs/user-guide/import-export.md</code> e <code>docs/qa/m5-admin-export.md</code>. <strong>2.</strong> La modale «Scarica &lt;vault&gt;» va a capo: la causa è <code>.mbcf td { white-space: nowrap }</code> ereditato dal <code>Dialog</code> montato in una cella; correzione in <code>.nd-dialog</code> (<code>packages/ui/src/components.css</code>: <code>white-space: normal; overflow-wrap: anywhere; overflow-x: hidden</code>). <strong>3.</strong> Amministrazione a tutta larghezza con il menu a sinistra: <code>app__main--wide</code> sulle rotte <code>/admin/*</code> (<code>web/src/layout/Shell.tsx</code>, <code>web/src/app.css</code>). <strong>8.</strong> La percentuale per vault è rispetto alla <strong>quota dell&#39;utente</strong> (<code>UsagePanel.shareOf</code>), «—» con quota illimitata, tooltip «rispetto al tuo limite di N GB»; vale anche sul desktop, che usa lo stesso componente. <strong>4.</strong> Presentazione Marp a tutto schermo: il polyfill <code>@marp-team/marpit-svg-polyfill</code> non è mai applicato (<code>script: false</code> in <code>marp/engine.ts</code>; bug WebKit 23113 con <code>&lt;section&gt;</code> in <code>&lt;foreignObject&gt;</code>) e il <code>&lt;div&gt;</code> anonimo di <code>MarpShow.tsx</code> spezza la catena <code>height:100%</code>; si applica il polyfill in <code>MarpShow</code> e nelle miniature, si dà al wrapper <code>class=&quot;marp-body&quot;</code> e <code>SHOW_CSS</code> centra l&#39;SVG</td><td><strong>implementata (2026-11-16)</strong>, nel working tree. Polyfill di Marp solo dove il difetto c&#39;è (presentazione e miniature); progetto WebKit di Playwright opzionale (<code>E2E_WEBKIT=1</code>). <strong>Da provare su macOS</strong> (P1…P3 del runbook)</td></tr><tr><td><strong>B — Excalidraw: testo che scompare, oggetti fermi</strong></td><td>11, 12</td><td>Il fork <code>@zsviczian/excalidraw</code> richiede un host (<code>attachInlineLinkSuggester</code> lancia un errore di host non configurato e <code>textWysiwyg</code> lo chiama prima di inserire la textarea): <code>editingTextElement</code> resta impostato, il testo non si vede (11) e il trascinamento resta disabilitato (12). Si crea <code>packages/workbench/src/drawing/excalidrawHost.ts</code>, con <code>protocolVersion: 2</code> e i default del pacchetto stock, registrato una sola volta all&#39;import lazy e prima del primo mount (<code>DrawingEditor.tsx</code>, <code>ExcalidrawIsland.tsx</code>). Verifica successiva: il gestore del fuoco delle modali (<code>packages/ui/src/focus.ts</code>) non deve togliere il fuoco alla textarea mentre è aperto un selettore del fork. <strong>Prioritaria: blocca l&#39;editing</strong></td><td><strong>implementata (2026-11-16)</strong>, nel working tree: <code>excalidrawHost.ts</code> registrato al caricamento del motore; il gestore del fuoco esclude il widget (<code>.excalidraw</code>). <strong>Da provare su macOS</strong> (E1…E5)</td></tr><tr><td><strong>C — Dispositivi e logout</strong> (cloud, core desktop, frontend)</td><td>6, 5</td><td><strong>6 (ADR-0057).</strong> Cloud: migrazione <code>0016_device_hostname.sql</code> (colonna <code>hostname</code>, deduplica senza cancellare righe, indice unico parziale <code>(user_id, platform, hostname)</code>), query <code>UpsertDesktopDevice</code>, <code>users.Service.RegisterDevice</code> con upsert per le piattaforme desktop (per <code>web</code> resta com&#39;è), descrizione di <code>DeviceRegistration</code> e <code>POST /me/devices</code> in <code>api/openapi.yaml</code>. Desktop: <code>Logout</code> revoca il dispositivo prima di cancellare la sessione, una sola nuova registrazione su <code>device_id</code> sconosciuto o revocato, <code>CLARAE_DEVICE_NAME</code> per i test e per due istanze sullo stesso computer (<code>scripts/run-desktop-with-cloud.sh --two-devices</code> e i test di <code>task test-desktop-e2e</code>). <strong>5 (ADR-0058).</strong> Console: <code>revokeTokensOnSignout</code>, <code>signOut</code> con <code>id_token_hint</code>, <code>client_id</code> e <code>post_logout_redirect_uri = ${origin}/signed-out</code>, pagina pubblica <code>/signed-out</code> senza login automatico, <code>prompt=login</code> dopo un&#39;uscita esplicita, estensione di <code>realm_test.go</code>. Desktop: revoca dal <code>revocation_endpoint</code> della discovery con controllo dello status, logout back-channel su <code>end_session_endpoint</code>, <code>prompt=login</code> al login successivo. <strong>Passo 0, diagnosi:</strong> riprodurre sullo stack e verificare il client <code>clarae-web</code> nel realm attivo di E2BR (<code>--import-realm</code> non sovrascrive un realm esistente); registrare la causa nell&#39;ADR-0058</td><td><strong>implementata (2026-11-16)</strong>, nel working tree. Con gli scostamenti sopra (nessuna nuova registrazione automatica; ordine sessione → revoca). <strong>Da provare contro Keycloak</strong> (L1…L5, D1…D5); passo 0 non fatto</td></tr><tr><td><strong>D — Cartelle di configurazione allineate</strong> (core desktop, cloud, frontend)</td><td>9</td><td>ADR-0059. <code>vaultdir.CleanupLegacy</code> all&#39;apertura del vault dopo <code>Ensure</code>, una volta per versione dell&#39;app (marcatore locale escluso dalla sync): cancella le voci solo locali che <code>.clarae/</code> ha già (<code>sync.db*</code> solo se il database aperto è quello di <code>.clarae/</code>), sposta gli snapshot senza collisione, manda nel cestino del vault la copia legacy delle impostazioni di un vault non collegato in collisione, rimuove la cartella vuota. <code>sync/configmigrate.go</code>: delete della riga legacy pulita quando <code>.clarae/&lt;nome&gt;</code> esiste (la revisione resta nello storico, D-04; vale solo con <code>config_dir_v2</code> acceso, cioè con un cloud ≥ 1.7). ZIP coerente: <code>writeZip</code> (<code>services/cloud/internal/export/service.go</code>) e l&#39;export privato nel browser (<code>packages/vaultcrypto-web/src/export.ts</code>) riscrivono i path della cartella legacy in quelli di <code>.clarae/</code>, con precedenza a <code>.clarae/</code> in caso di collisione. Righe nuove di classe <code>legacy</code> in <code>scripts/rebrand/allowlist.tsv</code> (rimozione alla 2.0)</td><td><strong>implementata (2026-11-16)</strong>, nel working tree. La parte sincronizzata richiede un cloud ≥ 1.7. <strong>Da provare su un vault reale</strong> (Z1…Z7)</td></tr><tr><td><strong>E — Applicazioni</strong> (frontend)</td><td>10</td><td>ADR-0060. <code>features.web_viewer</code> con default <code>true</code> nello schema <code>api/config-profile.schema.json</code>, poi <code>task gen</code>; test e tabella della guida admin allineati. <code>FileExplorer.tsx</code>: pulsante «Nuova applicazione» nella barra, voce nei due menu contestuali, stessa condizione di <code>app:new</code> (<code>canEditWebapps</code>). <code>display()</code> dell&#39;esploratore e <code>label</code> di <code>TabBar.tsx</code> tolgono anche <code>.webapp</code> (helper <code>nameOf</code> spostato in <code>webapp/model.ts</code>). Azione registrata sotto la voce <code>webapp</code> di <code>shared/parity/features.yaml</code>, poi <code>task parity</code>. Già presenti, da provare negli e2e: apertura nella scheda dopo il salvataggio e al clic, modifica dell&#39;indirizzo con la scheda che si aggiorna</td><td><strong>implementata (2026-11-16)</strong>, nel working tree. <strong>Da provare sulla finestra reale</strong> (W1…W4; la matrice M18 resta da eseguire)</td></tr><tr><td><strong>F — Registro di audit persistente</strong> (cloud, docs, operazioni)</td><td>7</td><td><strong>Diagnosi su E2BR, a cura dell&#39;owner (non automatica):</strong> vedi sotto. <strong>Hardening nel repo:</strong> (1) test sulle migrazioni (accanto a <code>internal/db/ownership_test.go</code>): nessuna migrazione contiene <code>DROP</code>, <code>TRUNCATE</code> o <code>DELETE</code> su <code>audit_log</code> <strong>nelle sezioni <code>+goose Up</code></strong> (la sezione <code>Down</code> di <code>0001_core.sql</code> ha un <code>DROP TABLE audit_log</code>, e <code>0005</code> e <code>0010</code> hanno <code>DROP INDEX</code> su di esso: il test non deve leggerle); (2) guardia all&#39;avvio: con <code>DB_EXPECT_INITIALIZED=true</code> il cloud rifiuta di creare lo schema su un database vuoto (goose versione 0) ed esce con un errore chiaro, il chart <code>deploy/helm</code> espone il valore e lo imposta quando <code>.Release.IsUpgrade</code>; (3) log all&#39;avvio con la versione dello schema, il numero di righe di audit e la data della prima; (4) <code>deploy/k3d/deps.yaml</code>: Postgres da <code>emptyDir</code> a un PVC; (5) guida admin (aggiornamento): stesso namespace, release, PVC e <code>COMPOSE_PROJECT_NAME</code>, <code>pg_dump</code> prima di ogni aggiornamento; riscrittura di <code>.claude/deploy/Upgrade.md</code> (locale, non versionato) per il namespace <code>clarae</code>, con il backup</td><td><strong>implementata (2026-11-16)</strong>, nel working tree (guardia, log, test, PVC k3d, guida admin); <code>.claude/deploy/Upgrade.md</code> riscritto (locale). <strong>Diagnosi su E2BR: dell&#39;owner, non fatta</strong> (A1…A5)</td></tr><tr><td><strong>Chiusura</strong></td><td>tutti</td><td>CHANGELOG 1.7.2, guide (utente e admin: Applicazioni non più «spento di default», chiavi del Config Profile, aggiornamento), casi nel runbook QA (<code>docs/qa/</code>), <code>task ci</code> verde, revisione del diff con l&#39;agente reviewer; poi l&#39;aggiornamento di E2BR</td><td>documentazione <strong>fatta (2026-11-16)</strong>: CHANGELOG [1.7.2], guide, runbook; revisione del codice fatta (correzioni sotto). <strong><code>task ci</code>: l&#39;esito è nel CHANGELOG [1.7.2], paragrafo «Verificato»</strong>; poi l&#39;aggiornamento di E2BR</td></tr></tbody></table><p><strong>Compito dell&#39;owner, non automatico: diagnosi dell&#39;audit su E2BR (solo lettura).</strong> Servono a capire se il database è stato ricreato e se il vecchio esiste ancora:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> version_id, tstamp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> goose_db_version </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> min</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">at</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> audit_log;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> min</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(created_at) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users;</span></span></code></pre></div><p>e <code>kubectl get pvc -A</code>, per sapere se esiste ancora il volume del namespace con il nome della 1.x. Se il vecchio database esiste, si recupera con <code>pg_dump</code> e un ripristino pianificato con l&#39;owner: <strong>non si fa in automatico</strong>. Il risultato va registrato in questa sezione.</p><p><strong>Per chi amministra:</strong> E2BR si aggiorna alla nuova versione <strong>dopo</strong> il backup (<code>pg_dump</code>) e con la guardia dell&#39;Onda F attiva, nello stesso namespace, release e volume dell&#39;installazione corrente (<a href="./admin-guide/backup-upgrade.html#aggiornare-senza-perdere-il-database">guida</a>; la procedura di E2BR sta nel file locale non versionato <code>.claude/deploy/Upgrade.md</code>). La migrazione <code>0016</code> <strong>revoca i dispositivi desktop duplicati</strong>, lasciando attivo il più recente. <code>features.web_viewer</code> è acceso di default: chi non vuole le applicazioni lo spegne dal profilo. Con un cloud 1.5 o 1.6 (E2BR oggi) la parte sincronizzata della correzione del punto 9 non ha effetto: <code>config_dir_v2</code> arriva spento. Un realm Keycloak già importato non cambia da solo con la nuova versione: <code>post.logout.redirect.uris</code> del client web si controlla dalla console di Keycloak (ADR-0058).</p><p><strong>Criteri di uscita</strong></p><ul><li><strong>Per onda:</strong> vitest e <code>go test -race</code> mirati (comandi di <code>CLAUDE.md</code>), poi <code>task gen</code> e <code>task parity</code> dove cambiano flag, azioni o API.</li><li><strong>Integrazione e due dispositivi:</strong> <code>task test-integration</code> (dispositivi, export, migrazioni, guardia, aggiornamento di un database con dati di audit da 0015 a 0016 senza perdere righe) e <code>task test-desktop-e2e</code> (logout e login senza duplicati, sync a due dispositivi con <code>CLARAE_DEVICE_NAME</code>).</li><li><strong>Interfaccia:</strong> <code>task e2e</code> e <code>yarn workspace @clarae/web run e2e:workbench-ui</code> (Excalidraw testo e trascinamento, Marp anche su webkit, Applicazioni, modale, amministrazione a tutta larghezza).</li><li><strong>QA manuale su macOS</strong> con <code>scripts/run-desktop-with-cloud.sh</code>: modificare un testo in un disegno e spostare oggetti; presentazione Marp a tutto schermo; Esci (web e desktop) chiede la password al rientro; logout e login senza dispositivi doppi; vault con la cartella di configurazione legacy ripulita e ZIP con la sola <code>.clarae/</code>.</li><li><strong>Documentazione:</strong> i casi nuovi nel runbook QA (<code>docs/qa/</code>).</li><li><strong>Chiusura:</strong> <code>task ci</code> verde, poi una revisione del diff con l&#39;agente reviewer; aggiornamento di E2BR dopo il backup e con la guardia attiva.</li><li><strong>Esito (2026-11-16):</strong> codice e documentazione di chiusura fatti; <strong>non registrati qui</strong> gli esiti di <code>task ci</code>, <code>task test-integration</code>, <code>task test-desktop-e2e</code> e della matrice e2e su questo albero. Le prove automatiche di ogni onda sono elencate nel CHANGELOG [1.7.2] (<em>Build e sviluppo</em>).</li><li><strong>Resta manuale:</strong> i casi di <a href="./qa/m21-correttivi.html"><code>docs/qa/m21-correttivi.md</code></a> su macOS (presentazione, disegni, applicazioni), su un Keycloak vero (uscita da console e desktop, dispositivi) e su E2BR (aggiornamento con backup, controllo del client <code>clarae-web</code>, <code>database state</code>).</li><li><strong>Rilascio:</strong> versione <strong>1.7.2</strong>, tag <code>v1.7.2</code> (CHANGELOG <code>## [1.7.2] - 2026-11-16</code>). Il push lo fa l&#39;owner.</li><li><strong>Fuori da M21 (resta all&#39;owner):</strong> la diagnosi dell&#39;audit su E2BR e l&#39;eventuale ripristino del vecchio database. ADR-0056 e ADR-0020 portano già le note degli emendamenti di ADR-0060 e ADR-0061.</li></ul><hr><h2 id="_13-quindecies-m22-—-applicazioni-integrate-su-windows-e-linux-nomi-dei-file-senza-estensione" tabindex="-1">13-quindecies. M22 — Applicazioni integrate su Windows e Linux; nomi dei file senza estensione <a class="header-anchor" href="#_13-quindecies-m22-—-applicazioni-integrate-su-windows-e-linux-nomi-dei-file-senza-estensione" aria-label="Permalink to &quot;13-quindecies. M22 — Applicazioni integrate su Windows e Linux; nomi dei file senza estensione&quot;">​</a></h2><p>Richiesta dell&#39;owner del 2026-11-19 (schizzo annotato), in due punti. <strong>(1) Applicazioni dentro Clarae anche su Windows e Linux.</strong> Al commit <code>db1b9d6a</code> la vista integrata (ADR-0056) è accesa solo su macOS: <code>CapEmbeddedBrowser</code> ha <code>DesktopOS: {&quot;darwin&quot;}</code> (<code>apps/desktop/internal/app/capabilities.go:114</code>). Su Windows c&#39;è un driver WebView2 completo ma <strong>spento</strong> (<code>internal/shell/nativeview/driver_windows.go</code>, interruttore <code>CLARAE_WEBVIEW2_EXPERIMENTAL=1</code>, mai eseguito); su Linux <strong>nessun driver</strong> (<code>driver_other.go</code>). Le due piattaforme mostrano la scheda «Apri nel browser» (<code>webapp/BrowserView.tsx:67-74</code>). <strong>(2) Estensioni nascoste per tutti i file supportati e visibili solo per i non supportati; la rinomina non mostra né permette di cambiare l&#39;estensione.</strong> Al commit <code>db1b9d6a</code> l&#39;esploratore toglie solo <code>.md</code> e <code>.webapp</code> (<code>sidebar/FileExplorer.tsx</code>, <code>display</code>), una trentina di punti hanno ognuno la propria espressione regolare, e la rinomina preriempie il prompt con l&#39;estensione e non la ricolloca: per un <code>.excalidraw</code> si perde il tipo del file.</p><p>Le deviazioni dallo spec sono in due ADR, <strong>accettati dall&#39;owner il 2026-11-20</strong> (con ADR-0051, accettato lo stesso giorno: opzione A della proposta di spec v1.8): <a href="./adr/0062-vista-integrata-windows-linux.html">ADR-0062</a> (vista integrata su Windows e Linux con ripiego automatico e <code>CLARAE_WEBVIEW=off</code>; emenda ADR-0056 e ADR-0060; devia da §2.2.1, §2.6.6, §3.7, §4.2 e C.2) e <a href="./adr/0063-nomi-file-senza-estensione.html">ADR-0063</a> (nomi senza estensione e rinomina che la conserva; integra ADR-0047; non devia dallo spec). <code>Specifications.md</code> è alla <strong>v1.8 dal 2026-11-20</strong>, che li recepisce (proposta <a href="./spec-v1.8-proposta.html"><code>spec-v1.8-proposta.md</code></a>, sezioni 3 e 4, come storia). Nessun commit senza richiesta esplicita dell&#39;owner.</p><p><strong>Stato (2026-11-20): implementata, committata per sessione M22-S1…S4 e rilasciata come versione 1.7.3 (tag <code>v1.7.3</code>); ADR 0062 e 0063 accettati dall&#39;owner il 2026-11-20 e recepiti in <code>Specifications.md</code> v1.8 (2026-11-20); prove manuali dell&#39;owner da fare.</strong> <code>task ci</code> verde sull&#39;albero di M22 (835 s, esiti nel CHANGELOG [1.7.3], paragrafo «Verificato»); il push del tag lo fa l&#39;owner. Nulla è provato su una finestra reale di Windows o di Linux: il driver Linux ha solo i 14 test live sotto Xvfb (X11) con la sandbox di WebKit accesa, riportati verdi su arm64 dagli sviluppatori (l&#39;amd64 non è eseguibile su un Mac arm64: l&#39;emulatore non ha seccomp, e il vecchio esito amd64 era senza sandbox e non vale più). <strong>La revisione del diff con l&#39;agente <code>reviewer</code> è stata fatta, con esito Fail: i cinque rilievi sono corretti nel working tree</strong> (sandbox di WebKit obbligatoria, frame sconosciuti, cancellazione di uno store, vincolo di build, selettori con etichette uguali) e la documentazione è allineata.</p><p><strong>Decisioni dell&#39;owner (2026-11-19)</strong></p><ul><li><strong>Vista integrata accesa di default su Windows e Linux, con ripiego automatico</strong> a «Apri nel browser» se driver o runtime falliscono, e una variabile per spegnerla (<code>CLARAE_WEBVIEW=off</code>). Le prove reali le fa l&#39;owner con la matrice QA (<a href="./qa/m18-webview-matrice.html"><code>m18-webview-matrice.md</code></a>).</li><li><strong>«Supportato» è tutto ciò che si apre in una scheda di Clarae</strong> (<code>openTarget(path) === &#39;in-app&#39;</code>, <code>packages/workbench/src/embeds/media.ts:90</code>): note, presentazioni Marp, disegni, lavagne, basi, applicazioni, immagini, PDF, audio e video. L&#39;estensione resta visibile solo per i file che si aprono con l&#39;applicazione del sistema.</li></ul><p><strong>Punto da correggere, scoperto scrivendo l&#39;ADR, corretto nell&#39;Onda B</strong> (ADR-0062, «Stato del ripiego prima di M22»): un errore di <code>Driver.Create</code> diventa <code>ErrDriver</code> (<code>apps/desktop/internal/webview/manager.go:229-231</code>) e il binding lo traduce in <code>webview-failed</code> (<code>bindings_webview.go:208-210</code>), mentre <code>BrowserView.tsx:205</code> ripiega sul riquadro solo per <code>webview-unavailable</code> e <code>webview-disabled</code>; inoltre un <code>Create</code> fallito non marca il driver come non disponibile (<code>Manager.driver()</code>, <code>manager.go:143-169</code>). Il ripiego automatico richiedeva quindi una modifica del core, non solo la capability: è nell&#39;Onda B (<code>webview.ErrPlatformUnavailable</code>, <code>Manager.markUnavailable</code>).</p><h3 id="onde-e-work-package-1" tabindex="-1">Onde e work package <a class="header-anchor" href="#onde-e-work-package-1" aria-label="Permalink to &quot;Onde e work package&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Onda</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td><strong>0 — ADR e roadmap</strong></td><td>ADR-0062 e ADR-0063 in <em>proposta</em> (poi <strong>accettati il 2026-11-20</strong>); note di emendamento in ADR-0056, ADR-0060 e ADR-0047; indice degli ADR; questa sezione</td><td><strong>fatta (2026-11-19)</strong>; ADR accettati il 2026-11-20</td></tr><tr><td><strong>A — Nomi senza estensione</strong></td><td><strong>Implementata (2026-11-19), nel working tree.</strong> Solo TypeScript, nessuna modifica Go. Helper unico <code>splitName</code>/<code>displayName</code> in <code>embeds/media.ts</code> (caso legacy <code>X.excalidraw.md</code>) e, <strong>in più del piano</strong>, <code>displayPath</code> (cartella + nome senza estensione) per le intestazioni delle viste, la finestra di recupero, la cronologia, la conferma del cestino, i collegamenti inversi e i selettori <code>dialog.pick</code>; il selettore delle immagini dei disegni non mostra più l&#39;estensione. Applicato a esploratore (riga e ordinamento, con l&#39;estensione come spareggio), schede, grafo, pannelli dei collegamenti (quello dei link non toglie più l&#39;estensione ai file non supportati), segnalibri, embed e anteprime, esportazione, presentazioni Marp. <code>promptRename(entry)</code> e la funzione pura <code>renameTarget</code> in <code>app/actions.ts</code> per menu, F2 e <code>note:rename</code>: prompt con il solo nome, estensione originale ricollocata, estensione uguale non raddoppiata, <strong>nome sempre rifilato</strong> (anche per cartelle e file non supportati). Invariati il testo dei link, i tooltip, il selettore rapido e la ricerca. Test: <code>media.test.ts</code>, <code>rename.test.ts</code> (nuovo) e i test aggiornati di esploratore, schede, segnalibri, embed, anteprime e <code>webapp/model</code>; e2e aggiornati e un caso nuovo in <code>keyboard.spec.ts</code> (F2 su un disegno conserva <code>.excalidraw</code>)</td><td><strong>implementata</strong>, da provare a mano</td></tr><tr><td><strong>B — Windows acceso</strong></td><td><strong>Implementata (2026-11-19), nel working tree.</strong> <code>Supported</code> è una costante <code>true</code> (non una variabile: così la pulizia <code>webviews_sweep</code> non dimentica le righe di cui non ha cancellato i dati quando le viste sono spente); a decidere sono <code>New</code> (<code>nil</code> con <code>CLARAE_WEBVIEW=off</code>, senza finestra, senza runtime o senza cartella dati) e <code>Create</code>. <code>CLARAE_WEBVIEW=off</code> in <code>switch.go</code>, senza build tag, condiviso col driver Linux (maiuscole e spazi ai lati ignorati; macOS non la legge); <code>datafolders.go</code> raccoglie la cartella dei dati comune ai due driver. <code>nativeview.New(win, dataDir)</code> e <code>shell.Host.SetDataDir</code>. Pre-controllo <code>loader.RuntimeInstalled()</code>. <strong>Ripiego:</strong> sentinella <code>webview.ErrPlatformUnavailable</code> → <code>webview-unavailable</code>; se nessuna vista è mai stata creata nella sessione il <code>Manager</code> spegne il driver (<code>Available()</code> falso, la capability <code>embeddedBrowser</code> risulta falsa). <code>DesktopOS</code> con <code>darwin</code>, <code>windows</code> e <code>linux</code>; <code>capabilities_test.go</code>, <code>driver_windows_test.go</code>, <code>manager_test.go</code>, <code>bindings_webview_test.go</code>, <code>switch_test.go</code>, <code>datafolders_test.go</code>; <code>task gen</code> e <code>task vet-windows</code></td><td><strong>implementata</strong>, Windows non provato a runtime</td></tr><tr><td><strong>C — Driver Linux WebKitGTK</strong></td><td><strong>Implementata (2026-11-19), nel working tree.</strong> <code>driver_linux.go</code>, <code>guest_linux.c</code>, <code>guest_linux.h</code> e <code>testhooks_linux.go</code> con cgo (<code>gtk+-3.0</code>, <code>webkit2gtk-4.1</code>), tag <code>linux &amp;&amp; cgo &amp;&amp; gtk3 &amp;&amp; !android &amp;&amp; !server &amp;&amp; !purego</code> (GTK 4 e <code>purego</code>: nessun driver). <strong>Scostamenti dal piano:</strong> (1) l&#39;innesto non usa un <code>GtkFixed</code> con <code>size-allocate</code>: la web view di Wails passa in un <code>GtkOverlay</code> nel <code>webview-box</code> e gli ospiti sono figli dell&#39;overlay, posizionati dal segnale <code>get-child-position</code> (bordi arrotondati, mai sotto 1 pixel); la gerarchia attesa è controllata e, se diversa, <code>Create</code> fallisce come indisponibile; (2) il frame di una navigazione è <strong>in parte sconosciuto</strong>: WebKitGTK non dà l&#39;identità del frame, quindi <code>about:</code>, <code>blob:</code> e <code>data:</code> sono <code>FrameSub</code> e il resto è <code>FrameUnknown</code> (nuovi <code>webview.FrameKind</code>, <code>FramePolicy</code>, <code>MainFrameNotice</code> e l&#39;interfaccia opzionale <code>FrameAwareDriver</code>, solo Linux); il <code>Manager</code> applica le regole del frame principale senza scrivere <code>curPrivate</code> (che si aggiorna da <code>notify::uri</code>), con <code>MainFrame:false</code>, e rifiuta un redirect verso un host privato dopo una navigazione sconosciuta verso un host pubblico (<code>pendingPublic</code>) e un iframe privato da una pagina pubblica; (3) il selettore di file è annullato e segnalato; (4) user agent di WebKitGTK, senza il suffisso <code>Version/</code>; (5) <strong>sandbox di WebKit obbligatoria</strong> (<code>webkit_web_context_set_sandbox_enabled(TRUE)</code>): <code>sandboxProblem()</code> (variabile <code>WEBKIT_DISABLE_SANDBOX_THIS_IS_DANGEROUS</code> impostata, <code>bwrap</code> assente, sonda di avvio che replica gli argomenti di WebKit) fa rispondere indisponibile e vale il ripiego; rischio residuo: un avvio del web process che fallisce dopo una sonda riuscita fa abortire l&#39;app (<code>g_error</code> in <code>readPIDFromPeer</code>); Flatpak e Snap non provati; (6) durante la cancellazione di uno store una <code>Open</code> dello stesso vault fallisce con un errore ritentabile (<code>webview-failed</code>, non il ripiego) e <code>onCleared</code> non conferma se nel frattempo ci sono viste; (7) il vincolo di build è anche su <code>guest_linux.c</code> e <code>guest_linux.h</code>, e <code>vet.sh</code> fa <code>go list</code> su sei combinazioni di tag e di cgo. Sessioni per vault in <code>&lt;dataDir&gt;/webapps/&lt;store&gt;/{data,cache}</code> con cookie in SQLite, contesti vivi fino a <code>RemoveData</code> o all&#39;uscita; <code>WEBKIT_*</code> dell&#39;ambiente rispettate; WebKitGTK ≥ 2.40. <strong><code>task vet-linux</code></strong> (in <code>task ci</code>, dopo <code>vet-windows</code>; <code>LINUX_ARCH=arm64</code> per un Mac Apple silicon) e <strong><code>task test-nativeview-linux</code></strong> (a mano, Xvfb; <code>RUN</code>, <code>NO_MENU</code>, <code>CLARAE_NATIVEVIEW_CFLAGS</code>; container con <code>--cap-add SYS_ADMIN --cap-add NET_ADMIN</code>, seccomp e systempaths non confinati, o <code>--privileged</code>; su Mac arm64 serve <code>LINUX_ARCH=arm64</code>): 14 test live verdi su arm64 con la sandbox accesa (riportato). <strong>Non provati:</strong> Wayland reale, GPU reale, clic reali, Flatpak, Snap, amd64 con la sandbox</td><td><strong>implementata</strong>, Linux provato solo sotto Xvfb (arm64)</td></tr><tr><td><strong>D — Chiusura</strong></td><td><strong>Documentazione fatta (2026-11-19):</strong> voce <code>webapp.embedded</code> di <code>shared/parity/features.yaml</code> («macOS, Windows e Linux», prove nuove) e <code>task parity</code> (registro rigenerato); ADR-0062 (differenze dichiarate) e ADR-0063 (<code>displayPath</code>, nome rifilato); guide utente e admin (tre sistemi, requisiti WebView2 ≥ 1.0.2210.55 e WebKitGTK ≥ 2.40, <code>CLARAE_WEBVIEW=off</code>, ripiego, nomi e rinomina); <code>docs/dev-setup.md</code>, <code>docs/desktop-web-sync.md</code>; CHANGELOG <em>Unreleased</em>; <code>docs/qa/m18-webview-matrice.md</code> §2-§3 (Windows senza interruttore, Linux su X11, Wayland e GPU reale, ripiego e <code>CLARAE_WEBVIEW=off</code>); runbook <a href="./qa/m22-nomi-file-e-applicazioni.html"><code>docs/qa/m22-nomi-file-e-applicazioni.md</code></a>. <strong>In corso:</strong> <code>task ci</code> e la revisione del diff con l&#39;agente <code>reviewer</code></td><td><strong>documentazione fatta</strong>; <code>task ci</code> e revisione in corso</td></tr></tbody></table><p><strong>Per chi amministra</strong> (quando le onde B e C saranno rilasciate): <code>features.web_viewer</code> resta acceso di default; chi non vuole la vista integrata sui computer Windows e Linux imposta <code>CLARAE_WEBVIEW=off</code> nell&#39;ambiente del client (vale solo <code>off</code>; macOS non la legge), o spegne il flag dal profilo. Requisiti: WebView2 Runtime ≥ 1.0.2210.55 su Windows; su Linux <code>webkit2gtk-4.1</code> ≥ 2.40 e <strong>bubblewrap (<code>bwrap</code>) funzionante</strong> (la sandbox di WebKit è obbligatoria: in un container o con i namespace utente spenti la vista non parte); senza, le applicazioni si aprono nel browser di sistema. Guida: <a href="./admin-guide/profili-quote-audit.html#applicazioni-note-per-chi-amministra">profili, quote e audit</a>.</p><p><strong>Criteri di uscita</strong></p><ul><li><strong>Onda A:</strong> <code>yarn workspace @clarae/workbench exec vitest run src/embeds src/sidebar src/workspace src/app</code>, poi <code>task e2e</code> e <code>yarn workspace @clarae/web run e2e:workbench-ui</code> (la stessa UI sul core WASM).</li><li><strong>Onde B e C:</strong> <code>cd apps/desktop &amp;&amp; go test -race ./internal/app/... ./internal/webview/... ./internal/shell/...</code>, <code>task vet-windows</code>, <code>task vet-linux</code>, <code>task gen</code> e <code>task check-gen</code>, <code>task parity</code>.</li><li><strong>Finale:</strong> <code>task ci</code> verde; revisione del diff con l&#39;agente <code>reviewer</code>.</li><li><strong>Manuale, a carico dell&#39;owner</strong> (casi in <a href="./qa/m22-nomi-file-e-applicazioni.html"><code>docs/qa/m22-nomi-file-e-applicazioni.md</code></a> e <a href="./qa/m18-webview-matrice.html"><code>docs/qa/m18-webview-matrice.md</code></a>): su macOS l&#39;esploratore mostra <code>Desktop_UI</code>, <code>SlideClarae</code> e <code>SATAP</code> senza estensione e F2 non mostra né cambia l&#39;estensione; su Windows (WebView2) e su Linux (GNOME Wayland e X11) un <code>.webapp</code> si apre nella scheda con barra, i cookie restano dopo il riavvio, la vista segue il ridimensionamento e la palette la nasconde; con <code>CLARAE_WEBVIEW=off</code> o con il runtime mancante appare «Apri nel browser».</li><li><strong>Decisioni dell&#39;owner a fine milestone:</strong> ADR-0062 e ADR-0063 <strong>accettati il 2026-11-20</strong> e <strong>recepiti in <code>Specifications.md</code> v1.8</strong> (2026-11-20), insieme a ADR-0051 (opzione A).</li></ul><p><strong>Rischi</strong></p><ul><li><strong>I driver di Windows e Linux non sono mai stati eseguiti</strong> prima delle prove dell&#39;owner: li limitano il ripiego automatico, <code>CLARAE_WEBVIEW=off</code> e il flag del profilo. Un difetto che non fa fallire <code>Create</code> (posizione, fuoco, sfarfallio) non è coperto dal ripiego.</li><li><strong>L&#39;innesto GTK sposta un widget di Wails:</strong> dipende dalla gerarchia di Wails v3.1.0 (<code>pkg/application/linux_cgo_gtk3.go</code>, <code>windowNew</code>); un aggiornamento di Wails va ricontrollato (<code>task test-nativeview-linux</code> e controllo della gerarchia, con ripiego).</li><li><strong>Frame in parte sconosciuto su Linux</strong> (WebKitGTK non dà l&#39;identità del frame): le regole del frame principale sono le più severe, quindi si sbaglia dalla parte del rifiuto; non scrive <code>curPrivate</code> (ADR-0062 punto 13).</li><li><strong>Sandbox di WebKit su Linux:</strong> serve <code>bwrap</code> funzionante; senza, o in un container, vale il ripiego. Un avvio del web process che fallisce dopo una sonda riuscita fa abortire l&#39;app (nessun ripiego); Flatpak e Snap non sono provati.</li><li><strong>Il ripiego richiedeva una modifica del core</strong> (fatta, Onda B): senza di essa un runtime mancante darebbe <code>webview-failed</code> e non il riquadro «Apri nel browser». Non è provata su una macchina senza il runtime.</li><li><strong>Nomi senza estensione:</strong> due file con lo stesso nome e tipi diversi si distinguono solo dall&#39;icona e dal tooltip; la rinomina non può più cambiare il tipo di un file supportato (limite dichiarato in ADR-0063).</li></ul><hr><h2 id="_13-sedecies-m23-—-terminale-integrato-ancorabile-e-sganciabile" tabindex="-1">13-sedecies. M23 — Terminale integrato, ancorabile e sganciabile <a class="header-anchor" href="#_13-sedecies-m23-—-terminale-integrato-ancorabile-e-sganciabile" aria-label="Permalink to &quot;13-sedecies. M23 — Terminale integrato, ancorabile e sganciabile&quot;">​</a></h2><p>Richiesta dell&#39;owner del 2026-11-20 (schizzo annotato e requisiti). Un pulsante nella ribbon, subito sopra le Impostazioni, apre un <strong>pannello terminale</strong> con più tab, ognuno con la propria shell, con la cartella di lavoro nella radice del vault aperto (la home se non c&#39;è un vault). Il pannello sta in basso (default), a sinistra o a destra, è ridimensionabile e ricorda la posizione. Un pulsante all&#39;estrema destra della barra dei tab lo <strong>sgancia in una finestra separata del sistema</strong> e lo riaggancia, <strong>senza riavviare le shell</strong>. Chiudere un tab, la finestra separata o l&#39;app termina i processi, senza orfani.</p><p>Stato del codice prima di M23: nessun terminale, nessuna libreria PTY (<code>github.com/creack/pty</code> è solo una dipendenza transitiva, nel <code>go.sum</code> di <code>apps/desktop</code>, e nessun pacchetto la importa), nessun <code>@xterm/*</code>; una sola finestra (<code>apps/desktop/main.go:146</code>); gli eventi Wails vanno sempre a tutte le finestre (<code>apps/desktop/internal/shell/host.go:121</code>); il layout del workbench è solo l&#39;area dell&#39;editor; la CSP del desktop ha <code>connect-src &#39;self&#39;</code> (<code>apps/desktop/internal/app/csp_prod.go:14</code>), quindi l&#39;I/O passa da binding ed eventi e non da un WebSocket.</p><p>La deviazione dallo spec (una seconda finestra, solo per il terminale; un&#39;architettura «chiusa» che ora lancia una shell dell&#39;utente) è in <strong><a href="./adr/0064-terminale-integrato-e-finestra-separata.html">ADR-0064</a>, accettato dall&#39;owner il 2026-11-20</strong>; emenda ADR-0051 («niente pop-out»), <strong>accettato anch&#39;esso il 2026-11-20</strong> (opzione A). <code>Specifications.md</code> è alla <strong>v1.8 dal 2026-11-20</strong>, che li recepisce (proposta <a href="./spec-v1.8-proposta.html"><code>spec-v1.8-proposta.md</code></a>, sezione 5, come storia) e dichiara M23 «1.8.0» (il tag seguirà). Nessun commit senza richiesta esplicita dell&#39;owner.</p><p><strong>Stato (2026-11-20): implementata, committata per sessione M23-S1…S4 e rilasciata come versione 1.8.0 (tag <code>v1.8.0</code>); ADR 0051 e 0062–0064 accettati e recepiti in <code>Specifications.md</code> v1.8; prove manuali dell&#39;owner da fare.</strong> <code>task ci</code> verde (559 s) e <code>task e2e</code> verde (413 passati), esiti nel CHANGELOG [1.8.0], paragrafo «Verificato»; la revisione con l&#39;agente <code>reviewer</code> ha dato esito Fail e tutti i rilievi sono corretti. Il push del tag lo fa l&#39;owner. Stato precedente, per la cronaca: Onda 0 fatta (ADR-0064, accettato il 2026-11-20, e questa sezione). Onde A, B e C implementate (2026-11-20), nel working tree (non committate). Onda D: documentazione fatta (guida utente, nota in guida admin, README, <code>desktop-web-sync.md</code>, <code>architecture.md</code>, <code>dev-setup.md</code>, runbook, CHANGELOG, proposta di spec); <strong>revisione con l&#39;agente <code>reviewer</code>: esito Fail, i rilievi sono corretti nel working tree (elencati sotto); <code>task ci</code> in corso.</strong> Nulla del terminale è provato su una finestra reale, e ConPTY e Job Object non sono mai stati eseguiti (solo <code>task vet-windows</code>).</p><p><strong>Scostamenti rispetto al piano e all&#39;ADR (implementazione)</strong></p><ul><li><strong><code>Kill</code> esteso alla sessione.</strong> Oltre a <code>SIGKILL</code> al gruppo del leader, su Unix il core uccide anche gli altri processi della sessione (i job di una shell interattiva stanno in gruppi propri, e quelli con <code>nohup</code> ignorano <code>SIGHUP</code>): <code>members_darwin.go</code> e <code>members_linux.go</code> li elencano. Nessun processo di una scheda sopravvive alla sua chiusura.</li><li><strong>Campo <code>reason</code> di <code>terminal:exit</code></strong> (<code>exited</code>, <code>closed</code>, <code>read-only</code>, <code>window-closed</code>), come in ADR-0064, decisione 10: il frontend decide con quello se chiudere la scheda (<code>exit</code> con codice 0, chiusura richiesta, finestra chiusa) o lasciarla con il codice.</li><li><strong><code>TerminalAPI.CanOpen(vaultId)</code></strong> (non nel piano): dice se <code>Open</code> partirebbe e serve a disabilitare il pulsante; <code>SyncAPI.Info.readOnly</code> dice lo stesso.</li><li><strong><code>vaultId</code> nella sessione</strong> (<code>TerminalSession.vaultId</code>): il core sa a quale vault appartiene una shell, per chiuderla quando il vault diventa di sola lettura (<code>Manager.CloseVault</code>, hook <code>Hooks.ReadOnly</code> del <code>sync.Manager</code>) e per aprire una scheda nuova della finestra separata nel vault della scheda in primo piano.</li><li><strong>Alias <code>Backquote</code>.</strong> Il tasto a sinistra del <code>1</code> si riconosce prima dal carattere e poi dalla posizione fisica (<code>combosFromEvent</code> in <code>commands/hotkeys.ts</code>; su macOS anche <code>IntlBackslash</code>, perché una tastiera ISO riporta il tasto in alto a sinistra così e <code>&lt;&gt;</code> come <code>Backquote</code>): le scorciatoie del terminale sono <code>Ctrl+` </code>, <code>Ctrl+Maiusc+` </code> su tutti i sistemi (anche macOS, dove <code>Cmd+` </code> resta al sistema). <strong>Conflitto noto:</strong> con il layout italiano su Windows e Linux, fuori dal terminale e con una nota aperta, <code>Ctrl+\\</code> esegue <code>pane:split-right</code> (il carattere ha la precedenza); dentro xterm un tasto riservato va all&#39;app solo se il comando scelto è <code>terminal:*</code> o la palette, quindi <code>Ctrl+\\</code> resta alla shell; <em>Impostazioni → Scorciatoie</em> non lo segnala.</li><li><strong>Finestra separata e vault.</strong> Una scheda nuova nella finestra separata usa il vault della scheda in primo piano (la finestra non conosce vault); <code>terminal:toggle</code> nella finestra separata riaggancia, e nella principale con il pannello sganciato porta la finestra in primo piano.</li><li><strong>Chiusura della principale.</strong> Il gancio di chiusura della finestra principale chiude anche quella del terminale (<code>main.go</code>), e <code>Lifecycle.CloseWindowsOnStop</code> la chiude all&#39;uscita, con un&#39;attesa massima di 500 ms.</li><li><strong>Limite noto: un mount già chiuso che diventa di sola lettura non chiude le sessioni aperte in lui.</strong></li><li><strong>Licenze controllate</strong> (decisione 17 di ADR-0064): <code>@xterm/xterm</code> 6.0.0, <code>@xterm/addon-fit</code> 0.11.0, <code>@xterm/addon-web-links</code> 0.12.0 e <code>github.com/creack/pty</code> v1.1.24 sono MIT. I tre <code>@xterm/*</code> sono fissati esatti in <code>package.json</code> (come dice ADR-0064).</li><li><strong>Licenze in <em>Impostazioni → Informazioni → Licenze</em>: fatte</strong> (<code>settings.terminalAttribution</code> sul desktop, <code>settings.terminalAttributionWeb</code> nel workbench web, dove c&#39;è xterm.js ma non creack/pty); anche il <code>README.md</code>.</li><li><strong>Rilievi della revisione (esito Fail), corretti nel working tree:</strong> i collegamenti OSC 8 si aprono solo con <code>openExternal</code> (<code>linkHandler</code> in <code>terminal/instances.ts</code>); la copertura dei vault privati bloccati deriva da <code>SyncAPI.Info(id).locked</code> e non dalla fase di sync; l&#39;alias fisico vale per <code>Backquote</code> e, su macOS, <code>IntlBackslash</code>; dentro il terminale un tasto riservato va all&#39;app solo se il comando scelto è <code>terminal:*</code> o la palette; la finestra separata usa le scorciatoie del vault della scheda in primo piano e ha il titolo localizzato; un tab di una sessione già terminata alla risposta di <code>Open</code> nasce segnato come terminato (o sparisce se l&#39;uscita è pulita); versioni <code>@xterm/*</code> esatte.</li></ul><p><strong>Decisioni dell&#39;owner (2026-11-20)</strong></p><ul><li><strong>Nessun flag</strong> del Config Profile: il terminale è sempre disponibile sul desktop. Conseguenza dichiarata: un amministratore non può spegnerlo.</li><li><strong><code>cwd</code> = radice del vault aperto</strong>; la home se non c&#39;è un vault. Il frontend passa un <code>vaultId</code>, mai un percorso.</li><li><strong>Sola lettura: il terminale non si apre.</strong> Per i vault in sola lettura (lettore di un mount o condivisione revocata: <code>sync.Manager.ReadOnly</code>, <code>apps/desktop/internal/sync/mounts.go:229</code>) il pulsante è disabilitato e il core rifiuta l&#39;apertura con l&#39;errore <code>terminal-read-only</code>; le sessioni aperte in un vault che diventa di sola lettura si chiudono con motivo <code>read-only</code>. Sostituisce la decisione presa all&#39;inizio della giornata («cwd nella radice anche per i mount in sola lettura»). <strong>Resta dichiarato</strong> che una shell aperta in un vault scrivibile può modificare file fuori dalle regole dell&#39;app (altri vault, <code>.clarae/</code>, qualunque file dell&#39;utente): il terminale non è un confine di sicurezza.</li><li><strong>Finestra separata vera</strong>: seconda finestra Wails v3 nello stesso processo, solo per il terminale; le sessioni vivono nel core e sopravvivono allo sgancio e al riaggancio (snapshot con <code>seq</code>). Deviazione da A-03, dalla riga «Finestre separate (pop-out)» e da ADR-0051.</li><li><strong>Workbench web senza terminale</strong>: eccezione di parità (il browser non può avviare processi; capability <code>terminal</code> falsa).</li><li>La shell parte <strong>solo da un gesto dell&#39;utente</strong> (ADR-0047): mai da un file del vault, da un link o da un deep link.</li></ul><h3 id="onde-e-work-package-2" tabindex="-1">Onde e work package <a class="header-anchor" href="#onde-e-work-package-2" aria-label="Permalink to &quot;Onde e work package&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Onda</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td><strong>0 — ADR e roadmap</strong></td><td>ADR-0064 in <em>proposta</em> (poi <strong>accettato il 2026-11-20</strong>); nota di emendamento in ADR-0051 (punto «niente pop-out»); indice degli ADR; questa sezione</td><td><strong>fatta (2026-11-20)</strong>; ADR accettato il 2026-11-20</td></tr><tr><td><strong>A — Core Go: sessioni PTY</strong></td><td>Pacchetto <code>apps/desktop/internal/terminal/</code> (escluso da WASM con <code>//go:build !js</code>): <code>pty_unix.go</code> su <code>creack/pty</code> (shell <code>$SHELL -l</code>, ripiego <code>/bin/zsh</code>, <code>/bin/bash</code>, <code>/bin/sh</code>; <code>Setsid</code> e <code>Setctty</code>) e <code>pty_windows.go</code> con ConPTY (<code>pwsh.exe</code>, <code>powershell.exe</code>, <code>%ComSpec%</code>) e <strong>Job Object con <code>KILL_ON_JOB_CLOSE</code></strong>. <code>Manager</code> con sessioni <code>{id, cwd, pty, process, ring buffer da 2 MiB, seq}</code>, limite di 16 sessioni, lettura coalescente (circa 16 ms o 32 KiB) → evento <code>terminal:output {id, seq, data}</code>; <code>terminal:exit {id, code, reason}</code>. Chiusura: <code>SIGHUP</code> al gruppo e <code>SIGKILL</code> dopo 1 s (Unix), <code>ClosePseudoConsole</code> e chiusura del job (Windows); <code>Shutdown()</code> entro il watchdog di 3 s (<code>shell/lifecycle.go:15</code>), chiamato per primo in <code>App.Shutdown</code> (<code>internal/app/app.go:237</code>). Binding <code>TerminalAPI</code> (<code>internal/app/bindings_terminal.go</code>: <code>Open</code>, <code>Write</code>, <code>Resize</code>, <code>Close</code>, <code>List</code>, <code>Snapshot</code>, <code>Dock</code>, <code>Undock</code>, <code>State</code>) con il rifiuto <code>terminal-read-only</code> e la chiusura delle sessioni di un vault che diventa di sola lettura; stub WASM <code>bindings_terminal_js.go</code> (<code>terminal-unavailable</code>). Capability <code>terminal</code> (desktop su macOS, Windows e Linux; web falsa), voce <code>terminal</code> in <code>shared/parity/features.yaml</code>, eventi in <code>events_registry.go</code>, <code>task gen</code>. <code>//nolint:gosec</code> motivato su G204</td><td><strong>implementata (2026-11-20), nel working tree</strong></td></tr><tr><td><strong>B — Finestra separata</strong></td><td><code>Host.OpenTerminalWindow()</code> e <code>CloseTerminalWindow()</code> (finestra Wails v3 <code>terminal</code>, pagina <code>/terminal.html</code>); stato <code>docked</code> o <code>detached</code> nel <code>Manager</code>, evento <code>terminal:layout {mode}</code>; <code>Undock()</code> apre la finestra, <code>Dock()</code> la chiude <strong>senza</strong> chiudere le sessioni. Chiusura dal sistema della finestra separata: termina tutte le sessioni e torna a <code>docked</code> con il pannello chiuso, senza passare dal <code>CloseGuard</code> (<code>shell/close.go</code>); uscita dell&#39;app: <code>Lifecycle.Stop</code> chiude sessioni e finestra. Disegna solo chi possiede il pannello; al cambio, <code>Snapshot</code> e scarto degli eventi con <code>seq</code> minore o uguale. Vault privato bloccato: la finestra separata si copre; i tasti nel terminale contano come attività (<code>api.crypto.activity</code>)</td><td><strong>implementata (2026-11-20), nel working tree</strong></td></tr><tr><td><strong>C — Frontend</strong></td><td>Dipendenze <code>@xterm/xterm</code>, <code>@xterm/addon-fit</code>, <code>@xterm/addon-web-links</code> (lazy, budget iniziale invariato). <code>packages/workbench/src/terminal/</code>: <code>TerminalPanel</code> (tab con <code>+</code> e <code>×</code>, selettore Basso/Sinistra/Destra, pulsante Sgancia/Aggancia all&#39;estrema destra), <code>TerminalView</code> (un xterm per tab, tasti riservati dell&#39;app, tema dai token, link con <code>openExternal</code>), <code>model.ts</code>. Layout con pannello in basso, a sinistra o a destra, splitter con <code>role=&quot;separator&quot;</code>; preferenze per dispositivo in <code>localStorage</code> (<code>clarae.terminal.dock</code>). Pulsante <code>terminal:toggle</code> in ribbon sopra le Impostazioni, <code>aria-pressed</code>, <strong>disabilitato con un vault in sola lettura</strong>, nascosto dove la capability manca; icona <code>terminal</code>. Comandi <code>terminal:toggle</code> (<code>Ctrl-` </code>), <code>terminal:new-tab</code>, <code>terminal:close-tab</code>, <code>terminal:undock</code>, <code>terminal:dock</code> con <code>feature</code> e <code>requires</code>; i18n it/en. Entry <code>apps/desktop/frontend/src/terminal.tsx</code> e <code>terminal.html</code> per la finestra separata. Mock dei binding con un <code>TerminalAPI</code> finto</td><td><strong>implementata (2026-11-20), nel working tree</strong></td></tr><tr><td><strong>D — Chiusura</strong> (docs, QA, revisione, <code>ci</code>)</td><td>Guida utente (terminale, scorciatoie, finestra separata, vault in sola lettura, shell fuori dalle regole dell&#39;app), CHANGELOG <em>Unreleased</em>, licenze (<code>README.md</code> e Impostazioni › Informazioni › Licenze, ADR-0049), runbook <code>docs/qa/m23-terminale.md</code> (macOS, Windows, Linux: shell, <code>cwd</code>, tab, sgancio e aggancio con output conservato, vault in sola lettura, chiusure senza orfani con <code>ps</code> e Task Manager, uscita dell&#39;app), registro di parità, revisione con l&#39;agente <code>reviewer</code>, <code>task ci</code></td><td><strong>documentazione fatta (2026-11-20)</strong>; revisione e <code>task ci</code> in corso</td></tr></tbody></table><p><strong>Criteri di uscita</strong></p><ul><li><strong>Onda A:</strong> <code>cd apps/desktop &amp;&amp; go test -race ./internal/terminal/... ./internal/app/...</code> (con <code>/bin/sh</code> reale: apertura, <code>cwd</code>, eco, resize, <code>Snapshot</code> e <code>seq</code>, rifiuto <code>terminal-read-only</code>, chiusura di un vault che diventa di sola lettura, chiusura del tab e di tutto con verifica che il gruppo di processi non esista più, figlio in background ucciso, limite di sessioni, <code>Shutdown</code> entro 3 s); <code>task vet-windows</code> (ConPTY e Job Object), <code>task vet-linux</code>, vet con <code>GOOS=js GOARCH=wasm</code> (stub); <code>task gen</code> e <code>task parity</code>.</li><li><strong>Onde B e C:</strong> vitest (modello dei tab, preferenze di ancoraggio, pulsante della ribbon anche disabilitato, tasti), <code>task e2e</code> sul mock (apertura dalla ribbon, <code>+</code> e <code>×</code>, l&#39;ultimo tab chiude il pannello, cambio di posizione persistente, sgancio e aggancio simulati con ridisegno dallo snapshot); sul web il pulsante non c&#39;è.</li><li><strong>Finale:</strong> <code>task ci</code> verde; revisione del diff con l&#39;agente <code>reviewer</code>.</li><li><strong>Manuale, a carico dell&#39;owner</strong> (<a href="./qa/m23-terminale.html"><code>docs/qa/m23-terminale.md</code></a>, scritto): su macOS, Windows e Linux la shell parte nella radice del vault; cambiando vault i nuovi tab partono nel nuovo percorso; con un vault in sola lettura il pulsante è disabilitato; lo sgancio con <code>top</code> in esecuzione continua e il riaggancio conserva l&#39;output; la chiusura della finestra separata e dell&#39;app non lascia processi orfani.</li><li><strong>Decisione dell&#39;owner a fine milestone:</strong> ADR-0064 <strong>accettato il 2026-11-20</strong> (licenze di <code>creack/pty</code> e <code>@xterm/*</code> controllate il 2026-11-20: MIT). Lo spec v1.8 è applicato (2026-11-20, con ADR-0051, opzione A). <strong>Seguito (deriva dello spec, non corretta):</strong> <code>Specifications.md:1903</code> cita ancora il tag di build <code>webkit2_41</code> (di Wails v2); la build Linux usa <code>gtk3</code>.</li></ul><p><strong>Rischi</strong></p><ul><li><strong>Seconda finestra mai usata nel prodotto:</strong> chiusure, fuoco ed eventi doppi (mitigati da <code>mode</code> e <code>seq</code>); su Linux la finestra separata non ospita viste native (non serve).</li><li><strong>Throughput degli eventi di Wails</strong> (coda per finestra, payload grandi con una richiesta): mitigato dalla coalescenza; da misurare con output massivo (<code>yes</code>, <code>cat</code> di file grandi).</li><li><strong>ConPTY e Job Object non provati su Windows</strong> fino al runbook dell&#39;owner: si compilano (<code>task vet-windows</code>) ma non girano su una macchina vera.</li><li><strong>Il terminale esegue qualunque comando dell&#39;utente e non è un confine di sicurezza:</strong> nei vault scrivibili una shell può modificare file fuori dalle regole dell&#39;app (altri vault, <code>.clarae/</code>, mount aperti come cartella). La sola lettura è rispettata solo per l&#39;apertura nel vault della sessione (<code>terminal-read-only</code>); è dichiarato in ADR-0064 e nella guida.</li><li><strong>Nessun flag:</strong> un amministratore non può spegnere il terminale (decisione dell&#39;owner); un eventuale <code>features.terminal</code> sarebbe un nuovo ADR.</li><li><strong>Dipendenza da ADR-0051:</strong> la seconda finestra richiede Wails v3, già nel codice (dalla 1.4.0) e <strong>ADR-0051 accettato il 2026-11-20</strong> (opzione A, recepito nello spec v1.8), ma senza matrice manuale su Windows e Linux (B-W8, <code>docs/qa/m15-wails3-matrice.md</code>): il rischio resta, dichiarato.</li></ul><hr><h2 id="_13-septendecies-m24-—-carattere-del-terminale" tabindex="-1">13-septendecies. M24 — Carattere del terminale <a class="header-anchor" href="#_13-septendecies-m24-—-carattere-del-terminale" aria-label="Permalink to &quot;13-septendecies. M24 — Carattere del terminale&quot;">​</a></h2><p>Richiesta dell&#39;owner del 2026-11-20, dopo il tag v1.8.0. In <em>Impostazioni → Aspetto</em> ci sono i campi <strong>«Carattere del terminale»</strong>, con default <strong><code>MesloLGS NF</code></strong> (un Nerd Font con le icone dei prompt di shell), e <strong>«Dimensione del carattere del terminale»</strong>, default <strong>13</strong> px, perché il carattere a spaziatura fissa del sistema non le mostra. Lavoro piccolo, sopra M23; nessuna deviazione dallo spec e nessun ADR (vedi sotto).</p><p><strong>Decisioni dell&#39;owner e fatti (verificati sul codice)</strong></p><ul><li>Salvato in <code>appearance.json</code> <strong>del vault</strong>, come il carattere dell&#39;interfaccia (<code>terminalFont</code> in <code>packages/workbench/src/state/settings.ts</code>, default <code>DEFAULT_TERMINAL_FONT</code>); <strong>non</strong> nel Config Profile, nessun flag. Il file è tra quelli sincronizzati «per utente» (<code>Specifications.md</code>, §3.4.6): lo stesso nome arriva agli altri dispositivi dell&#39;utente, dove il carattere va installato.</li><li>Vuoto → default. Il valore è un <strong>solo nome di famiglia</strong> (<code>cleanFamily</code> in <code>terminal/theme.ts</code>: tolti i caratteri non ammessi, al massimo 64), tra virgolette e seguito dal ripiego <code>ui-monospace, Menlo, Consolas, &quot;DejaVu Sans Mono&quot;, monospace</code> (<code>xtermFontFamily</code>).</li><li><strong>Dimensione:</strong> <code>terminalFontSize</code> in <code>appearance.json</code>, da 8 a 32 (<code>TERMINAL_FONT_SIZE_MIN</code> e <code>_MAX</code>), default 13 (<code>DEFAULT_TERMINAL_FONT_SIZE</code>); <code>terminalFontSizeOf</code> arrotonda e riporta a 13 un valore non valido o fuori intervallo (anche al caricamento delle impostazioni); il campo numerico di Impostazioni tiene il valore nell&#39;intervallo.</li><li><strong>Il font non è incluso nell&#39;app:</strong> se non è installato vale il ripiego.</li><li>I terminali aperti si aggiornano subito, per carattere e dimensione (<code>fontScreens(setting, size)</code> in <code>terminal/instances.ts</code>, chiamata da <code>TerminalPanel</code>) e, dopo il caricamento del font (<code>fontReady</code>, attesa al massimo 1,5 s), lo schermo si misura di nuovo (<code>fit</code>) e il PTY riceve il nuovo numero di colonne e righe (<code>Resize</code>).</li><li>La finestra separata usa le impostazioni del vault della scheda in primo piano (senza vault, 13 e il carattere predefinito). <strong>Nel workbench web i due campi non compaiono</strong> (<code>can(&#39;terminal&#39;)</code> in <code>SettingsPanel.tsx</code>).</li></ul><p><strong>Stato (2026-11-20): implementata, committata per sessione M24-S1…S2 e rilasciata come versione 1.8.1 (tag <code>v1.8.1</code>, M24-S3); prove manuali dell&#39;owner da fare (T20…T27).</strong> <code>task ci</code> verde (1306 s, dopo due esecuzioni fermate dal carico della macchina in test non toccati) e <code>task e2e</code> verde; esiti nel CHANGELOG [1.8.1]. Il push del tag lo fa l&#39;owner.</p><table tabindex="0"><thead><tr><th>Sessione</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td><strong>M24-S1</strong></td><td>Impostazioni <code>terminalFont</code> e <code>terminalFontSize</code> in <code>appearance.json</code>, due campi in <em>Impostazioni → Aspetto</em> solo sul desktop (chiavi i18n <code>settings.terminalFont</code>, <code>settings.terminalFontHint</code> e <code>settings.terminalFontSize</code>), <code>cleanFamily</code>, <code>xtermFontFamily</code>, <code>terminalFontSizeOf</code>, <code>fontReady</code>, <code>fontScreens</code>; test vitest</td><td><strong>implementata (2026-11-20), nel working tree</strong></td></tr><tr><td><strong>M24-S2</strong></td><td>Documentazione: guida del terminale e di <em>Impostazioni</em>, runbook <a href="./qa/m23-terminale.html"><code>qa/m23-terminale.md</code></a> (sezione 8, T20…T27), CHANGELOG <em>Unreleased</em>, questa sezione</td><td><strong>fatta (2026-11-20)</strong></td></tr><tr><td><strong>M24-S3</strong></td><td>Rilascio <strong>1.8.1</strong> (versione, note di rilascio dal CHANGELOG, tag a cura dell&#39;owner)</td><td>da fare</td></tr></tbody></table><p><strong>Criteri di uscita:</strong> <code>task ci</code> verde; manuale a carico dell&#39;owner (T20…T27): rendering con <code>MesloLGS NF</code> installato e non installato su una finestra reale, cambio di carattere e di dimensione con un terminale aperto, ridimensionamento della shell dopo il cambio, valori fuori intervallo, finestra separata.</p><p><strong>ADR e spec: nessuna modifica.</strong> ADR-0064 e lo spec v1.8 non parlano del carattere del terminale; la scelta non li contraddice. ADR-0064 fissa per dispositivo (<code>localStorage</code>) solo posizione e dimensione del pannello, mentre il carattere è un&#39;impostazione dell&#39;aspetto del vault, come quello dell&#39;interfaccia. V-02 («nessun CSS personalizzato») non è toccato: il valore è un solo nome di famiglia depurato, non CSS. Se l&#39;owner vuole che il campo sia per dispositivo, o un elenco di caratteri, sarebbe una nuova decisione.</p><p><strong>Rischi</strong></p><ul><li><strong>Rendering con il font vero non provato su una finestra reale</strong> (misura delle celle, caricamento ritardato, Windows e Linux): runbook T20…T27.</li><li><strong>Il nome sincronizzato</strong> arriva a dispositivi dove il font non è installato: vale il ripiego, senza errori.</li></ul><hr><h2 id="_13-octodecies-m25-—-presenza-in-tempo-reale-sui-vault-condivisi" tabindex="-1">13-octodecies. M25 — Presenza in tempo reale sui vault condivisi <a class="header-anchor" href="#_13-octodecies-m25-—-presenza-in-tempo-reale-sui-vault-condivisi" aria-label="Permalink to &quot;13-octodecies. M25 — Presenza in tempo reale sui vault condivisi&quot;">​</a></h2><p>Richiesta dell&#39;owner del 2026-11-20, dopo il tag v1.8.1. Nella barra dell&#39;esploratore, al posto del pulsante «Nuova applicazione», gli <strong>avatar degli altri utenti</strong> che hanno aperto lo stesso file; sopra il documento, i loro <strong>cursori live</strong> (puntatore con etichetta col nome). Solo <strong>vault condivisi</strong>. Non è co-editing: il merge resta sul client e <a href="./adr/0050-ai-inattiva-e-collab-spento.html">ADR-0050</a> resta com&#39;è. Rilascio <strong>1.8.2</strong>. Decisione: <a href="./adr/0065-presenza-in-tempo-reale.html">ADR-0065</a> (<strong>accettato dall&#39;owner il 2026-11-20</strong>).</p><p><strong>Decisioni dell&#39;owner (2026-11-20)</strong></p><ul><li><code>features.presence</code> <strong>acceso di default</strong>, spegnibile dal Config Profile.</li><li>Componenti <strong>propri</strong> <code>Avatar</code> e <code>AvatarGroup</code> in <code>@clarae/ui</code>: niente MUI (CSP della console, token, budget).</li><li>Trasporto <strong>WebSocket</strong> <code>GET /api/v1/presence</code> (rotta esterna come <code>/events</code>, token nel primo frame) e <strong>PostgreSQL <code>LISTEN/NOTIFY</code></strong> tra le repliche, con coalescenza.</li><li>Nelle note il cursore è il <strong>puntatore ancorato al testo</strong> (riga e colonna); nei disegni e nei canvas, coordinate di scena.</li><li>Stanze <code>(vault cloud, file_id)</code>; identità timbrata dal server; autorizzazione per file al <code>join</code>, ricontrollata su revoca e sospensione; nessuna persistenza, nessun audit, nessun log per frame.</li><li>Il comando <code>app:new</code> resta in ribbon, menu contestuali, palette e stato vuoto; il pulsante dell&#39;esploratore (<code>FileExplorer.tsx:483-495</code>) sparisce (emenda ADR-0060).</li></ul><p><strong>Stato (2026-11-21): implementata, committata per sessione M25-S1…S5 e rilasciata come versione 1.8.2 (tag <code>v1.8.2</code>, M25-S6); revisione: Pass con riserve (4 rilievi bassi corretti); <code>task ci</code>, <code>task e2e</code>, matrice e <code>task test-integration</code> verdi (esiti nel CHANGELOG [1.8.2]). Nessuna prova con più utenti reali: runbook <code>docs/qa/m25-presenza.md</code> a carico dell&#39;owner.</strong></p><table tabindex="0"><thead><tr><th>Onda</th><th>Sessione</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td><strong>0</strong></td><td>M25-S1</td><td>ADR-0065 (con note di emendamento in ADR-0060 e ADR-0050 e riga nell&#39;indice) e questa sezione</td><td><strong>fatta (2026-11-20), ADR accettato</strong></td></tr><tr><td><strong>A</strong></td><td>M25-S2</td><td>Cloud: modulo <code>internal/presence</code> (hub delle stanze, WebSocket, autenticazione, limiti, PG NOTIFY, drain), flag <code>features.presence</code> nello schema, in <code>shared/go/features</code> e nella guida admin, rotta esterna in OpenAPI, Caddy e Helm (timeout), test unitari e di integrazione con due «repliche»</td><td>implementata; scostamento: niente metriche Prometheus della presenza</td></tr><tr><td><strong>B</strong></td><td>M25-S3</td><td>Core (desktop e <code>GOOS=js</code>): client WebSocket, mappatura <code>vaultId/path</code> → <code>(vault cloud, file_id)</code> dallo stato di sync (anche mount), <code>PresenceAPI</code>, eventi, capability, stub, <code>task gen</code>, test con un server finto</td><td>implementata</td></tr><tr><td><strong>C</strong></td><td>M25-S4</td><td>Frontend: <code>Avatar</code>/<code>AvatarGroup</code> in <code>@clarae/ui</code>, <code>presence/</code> nel workbench (<code>getUserColor</code>, avatar nella barra dell&#39;esploratore, overlay dei cursori, adattatori per note, disegni e canvas), rimozione del pulsante, test, e2e, registro di parità</td><td>implementata; scostamento: il cursore delle note segue il <code>pointermove</code>, non il caret</td></tr><tr><td><strong>D</strong></td><td>M25-S5</td><td>Chiusura: guide, runbook <code>qa/m25-presenza.md</code>, CHANGELOG, data-retention, revisione, <code>task ci</code> e <code>task test-integration</code>, rilascio <strong>1.8.2</strong></td><td>documentazione fatta; revisione e <code>task ci</code> in corso; <code>task test-integration</code> e rilascio 1.8.2 da fare</td></tr></tbody></table><p><strong>Criteri di uscita:</strong> <code>task ci</code> e <code>task test-integration</code> verdi; test dell&#39;hub (autorizzazione per file, revoca, limiti, fan-out tra due hub); <code>task parity</code> con la voce <code>presence</code> provata sul core WASM; e2e con gli avatar al posto del pulsante e la pulizia alla chiusura; flag spento = nessuna connessione; guide, runbook e CHANGELOG aggiornati; <strong>rilascio 1.8.2</strong> (versione, note di rilascio, tag <code>v1.8.2</code> a cura dell&#39;owner); manuale a carico dell&#39;owner con due utenti (desktop e web).</p><p><strong>Spec:</strong> <code>Specifications.md</code> <strong>v1.9 applicato il 2026-11-20</strong> (con i punti facoltativi): <a href="./spec-v1.9-proposta.html"><code>spec-v1.9-proposta.md</code></a> resta come storia; A-05, §2.6.4, D-04, V-01, §3.7, §2.6.6, C.2 e C.4 recepiscono ADR-0065.</p><p><strong>Rischi</strong></p><ul><li><strong>Carico di PostgreSQL <code>NOTIFY</code></strong> con molti utenti nella stessa stanza: coalescenza ~15 Hz e invio solo con membri su altre repliche; da misurare.</li><li><strong>Privacy:</strong> nome e posizione visibili agli altri utenti del file; nulla viene salvato; il flag è spegnibile dall&#39;amministratore. Aggiornare <code>security/data-retention.md</code>.</li><li><strong>Ingress e timeout:</strong> proxy e bilanciatori devono ammettere l&#39;upgrade WebSocket e non chiudere le connessioni inattive prima del <code>ping</code>; la CSP <code>connect-src &#39;self&#39;</code> va provata con <code>wss:</code> nei tre browser.</li><li><strong>Nessuna prova reale con più utenti</strong> durante lo sviluppo: i test usano un server finto e due «repliche» sullo stesso PostgreSQL; il manuale resta a carico dell&#39;owner.</li></ul><hr><h2 id="_13-novodecies-m26-—-cartelle-dei-sistemi-di-versione-fuori-dal-sync-ed-elenco-dei-file-non-inviati" tabindex="-1">13-novodecies. M26 — Cartelle dei sistemi di versione fuori dal sync ed elenco dei file non inviati <a class="header-anchor" href="#_13-novodecies-m26-—-cartelle-dei-sistemi-di-versione-fuori-dal-sync-ed-elenco-dei-file-non-inviati" aria-label="Permalink to &quot;13-novodecies. M26 — Cartelle dei sistemi di versione fuori dal sync ed elenco dei file non inviati&quot;">​</a></h2><p>Richiesta dell&#39;owner del 2026-11-21, dopo il tag v1.8.2. Clarae esclude <strong>sempre</strong> dalla sincronizzazione le cartelle dei sistemi di versione e mostra in Impostazioni › Sincronizzazione l&#39;<strong>elenco dei file non inviati con il motivo</strong>. Decisione: <a href="./adr/0066-vcs-esclusi-e-file-non-inviati.html">ADR-0066</a> (<strong>accettato dall&#39;owner il 2026-11-21</strong>).</p><p><strong>Decisioni dell&#39;owner (2026-11-21)</strong></p><ul><li>Cartelle escluse: <code>.git</code>, <code>.hg</code>, <code>.svn</code>, <code>.bzr</code>, <code>.jj</code> (cartella o file, a qualunque profondità, senza distinzione di maiuscole); <code>CVS</code> e <code>_darcs</code> no.</li><li>I file VCS <strong>già nel cloud restano</strong>: il client li dimentica in <code>sync.db</code> senza inviare cancellazioni, così un dispositivo ancora su 1.8.x non perde la propria <code>.git</code>. Contano nella quota (D-03); nessuna pulizia automatica.</li></ul><p><strong>Stato (2026-11-21): ADR-0066 accettato; M26-S1…S3 fatte e committate per sessione, rilasciate nella versione 1.8.3 (tag <code>v1.8.3</code>). Il rilascio contiene la regola delle cartelle VCS, la dimenticanza delle righe escluse senza cancellazioni e l&#39;elenco dei file non inviati nel core e nei binding (<code>SyncAPI.Unsent</code>/<code>RetryUnsent</code>, <code>Status.unsent</code>). Restano da fare il blocco «File non inviati» nell&#39;interfaccia (M26-S4), le guide, la revisione e l&#39;e2e a due dispositivi contro il cloud reale (M26-S5).</strong></p><table tabindex="0"><thead><tr><th>Onda</th><th>Sessione</th><th>Agente</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td><strong>0</strong></td><td>M26-S1</td><td>docs-writer</td><td>ADR-0066, riga nell&#39;indice e questa sezione</td><td><strong>fatta (2026-11-21), ADR accettato</strong></td></tr><tr><td><strong>A</strong></td><td>M26-S2</td><td>desktop-core-developer</td><td><code>shared/go/pathrules</code>: <code>VCSDirs</code>, <code>ExclusionReason</code>, <code>IsExcluded</code> sopra di essa; test a tabella (annidati, file <code>.git</code>, maiuscole, <code>.gitignore</code> e <code>.github/</code> non esclusi); test d&#39;integrazione del cloud: commit <code>.git/config</code> in un vault condiviso → <code>PATH_INVALID</code></td><td>fatta (2026-11-21); in più <code>move_prefix</code> del cloud rifiuta una destinazione esclusa</td></tr><tr><td><strong>B</strong></td><td>M26-S3</td><td>desktop-core-developer</td><td><code>apps/desktop/internal/sync</code>: righe escluse dimenticate (avvio e scan, senza delete), <code>vault.FS.WalkReport</code>, <code>park</code> con codici e <code>classifyLastError</code>, <code>unsent.go</code> (<code>Unsent</code>, <code>RetryUnsent</code>), <code>Status.unsent</code>, binding <code>SyncAPI.Unsent</code>/<code>SyncAPI.RetryUnsent</code>, <code>task gen</code>; test di scan, push, unsent, e2e a due dispositivi, <code>task test-wasm</code></td><td>fatta (2026-11-21); scostamenti: niente e2e a due dispositivi con testcontainers (un cloud 1.8.3 rifiuta i path <code>.git</code> nei vault condivisi, quindi non si può preparare lo stato «già sincronizzato»: lo copre il test con il remote finto), voce <code>sync.unsent</code> nel registro di parità come <code>partial</code> fino a M26-S4</td></tr><tr><td><strong>C</strong></td><td>M26-S4</td><td>frontend-developer</td><td><code>settings/SyncUnsent.tsx</code> in <code>SyncSection.tsx</code>, azione <code>sync:retry-unsent</code>, i18n <code>sync.unsent.*</code>, voce <code>sync.unsent</code> nel registro di parità, mock dei binding, vitest</td><td>da fare</td></tr><tr><td><strong>D</strong></td><td>M26-S5</td><td>docs-writer, reviewer, qa-engineer</td><td><code>user-guide/sync-cloud.md</code> e <code>risoluzione-problemi.md</code>, CHANGELOG Unreleased, stato di questa sezione, revisione avversariale, <code>task ci</code>, <code>task test-integration</code>, <code>task test-desktop-e2e</code></td><td>da fare</td></tr></tbody></table><p><strong>Criteri di uscita:</strong> <code>task ci</code>, <code>task test-integration</code> e <code>task test-desktop-e2e</code> verdi; un vault con <code>.git/</code> non manda nulla della cartella nel cloud e non la indicizza; un <code>sync.db</code> con righe <code>.git/…</code> già sincronizzate le dimentica senza inviare cancellazioni (il file resta nel cloud, l&#39;altro dispositivo non lo scrive); file oltre il limite, rifiuti del server, nomi non validi e symlink compaiono nell&#39;elenco con il motivo, e «Riprova» rimette in coda i parcheggiati; <code>task parity</code> con la voce <code>sync.unsent</code> provata sul core WASM; guide e CHANGELOG aggiornati.</p><p><strong>Spec:</strong> ADR-0066 devia da §3.4.2, §3.4.3 e §3.4.4 A; le righe da aggiornare sono nella sezione «Conseguenze» dell&#39;ADR (a cura dell&#39;owner).</p><p><strong>Rischi</strong></p><ul><li><strong>Client 1.8.x:</strong> su un vault privato continuano a scambiarsi la <code>.git</code> tra loro; su un vault condiviso i loro invii VCS sono rifiutati e parcheggiati. Nessuna perdita, ma conviene aggiornare tutti i dispositivi.</li><li><strong>Quota:</strong> le copie VCS già nel cloud restano conteggiate finché non le toglie qualcuno.</li><li><strong>Codici in <code>last_error</code>:</strong> le righe scritte dalle versioni precedenti hanno testo libero; <code>classifyLastError</code> deve riconoscerle (test con i messaggi storici).</li></ul><h2 id="_13-vicies-m27-—-sito-della-documentazione-su-github-pages" tabindex="-1">13-vicies. M27 — Sito della documentazione su GitHub Pages <a class="header-anchor" href="#_13-vicies-m27-—-sito-della-documentazione-su-github-pages" aria-label="Permalink to &quot;13-vicies. M27 — Sito della documentazione su GitHub Pages&quot;">​</a></h2><p>Richiesta dell&#39;owner del 2026-11-23, dopo il tag v1.8.3. <code>docs/</code> riceve un indice (<code>docs/index.md</code>) e diventa un sito statico in <code>docs_html/</code>, pubblicato sul branch <code>gh-pages</code> per GitHub Pages da un task locale e da un workflow su ogni push su <code>main</code>. Decisione: <a href="./adr/0067-sito-documentazione-github-pages.html">ADR-0067</a> (proposta; eccezione ad ADR-0036, che voleva <code>release.yml</code> come unico workflow).</p><p><strong>Stato (2026-11-23): M27-S1…S4 fatte e committate per sessione, rilasciate come versione 1.8.4 (tag <code>v1.8.4</code>, M27-S5). Nessuna modifica al prodotto. <code>task ci</code> verde (745 s). Restano all&#39;owner: l&#39;accettazione di ADR-0067, l&#39;aggiornamento di <code>Specifications.md</code> (§6 e Appendice C) e l&#39;attivazione di Pages sul branch <code>gh-pages</code>; il workflow <code>docs.yml</code> non è ancora stato eseguito su GitHub.</strong></p><table tabindex="0"><thead><tr><th>Onda</th><th>Sessione</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td><strong>0</strong></td><td>M27-S1</td><td>ADR-0067 e riga nell&#39;indice degli ADR</td><td>fatta (2026-11-23), ADR in stato <em>proposta</em></td></tr><tr><td><strong>A</strong></td><td>M27-S2</td><td><code>docs/index.md</code>: introduzione al progetto e indice di tutti i documenti di <code>docs/</code> per pubblico</td><td>fatta (2026-11-23); link e copertura verificati (90 link, 70 documenti)</td></tr><tr><td><strong>B</strong></td><td>M27-S3</td><td>VitePress 1.6 (<code>docs/.vitepress/config.mjs</code>): barra laterale da <code>index.md</code>, <code>README.md</code> come indice di cartella, link fuori dal sito verso GitHub, codice inline protetto da Vue, <code>.nojekyll</code>; <code>task docs-build</code>, <code>docs-dev</code>, <code>docs-preview</code>; <code>docs_html/</code> ignorata</td><td>fatta (2026-11-23); 340 link interni del sito verificati; corretto un <code>&lt;vault&gt;</code> nella roadmap che rompeva il build</td></tr><tr><td><strong>C</strong></td><td>M27-S4</td><td><code>scripts/docs-publish.sh</code> (commit con indice temporaneo sopra <code>gh-pages</code>, fast-forward, nessun commit se il sito non cambia), <code>task docs-publish</code>, workflow <code>.github/workflows/docs.yml</code>, guide di sviluppo e di rilascio</td><td>fatta (2026-11-23); script provato contro un remote locale (prima pubblicazione, invariata, modificata, dry run)</td></tr><tr><td><strong>D</strong></td><td>M27-S5</td><td>Versione 1.8.4: contratto, stub, esempio Compose, perimetro del pentest, CHANGELOG e questa sezione</td><td>fatta (2026-11-23)</td></tr></tbody></table><p><strong>Criteri di uscita:</strong> <code>task docs-build</code> senza link interrotti; <code>task docs-publish DOCS_DRY_RUN=1</code> prepara il commit; il workflow <code>docs.yml</code> pubblica <code>gh-pages</code> al primo push su <code>main</code> che tocca <code>docs/</code>, e il sito risponde su <code>https://&lt;owner&gt;.github.io/Clarae/</code>.</p><p><strong>Rischi</strong></p><ul><li><strong>Pagine come template Vue:</strong> un tag HTML non chiuso nel testo di un documento rompe il build del sito; va provato con <code>task docs-build</code> quando si scrivono documenti.</li><li><strong>Repository privato:</strong> GitHub Pages richiede un piano a pagamento.</li></ul><h2 id="_13-unvicies-m28-—-riferimenti-a-prodotti-di-terze-parti-rimossi" tabindex="-1">13-unvicies. M28 — Riferimenti a prodotti di terze parti rimossi <a class="header-anchor" href="#_13-unvicies-m28-—-riferimenti-a-prodotti-di-terze-parti-rimossi" aria-label="Permalink to &quot;13-unvicies. M28 — Riferimenti a prodotti di terze parti rimossi&quot;">​</a></h2><p>Richiesta dell&#39;owner del 2026-11-23, dopo il tag v1.8.4: togliere dal repository ogni riferimento all&#39;editor di note a cui il prodotto si ispirava, anche nei documenti storici e in <code>Specifications.md</code> (modifica autorizzata esplicitamente dall&#39;owner). La compatibilità resta descritta con formule neutre: «file Markdown ordinari, apribili anche da altri editor», «formato JSON Canvas», «plugin Excalidraw di terze parti», «Markdown esteso (OFM)».</p><p><strong>Stato (2026-11-23): M28-S1…S4 fatte e committate per sessione, non rilasciate. <code>task ci</code> verde (571 s) e gli e2e Playwright dei disegni toccati (19 test). Restano solo gli identificatori e i percorsi esportati dal fork di Excalidraw (<code>packages/workbench/src/drawing/excalidrawHost.ts</code>, <code>scripts/excalidraw-exports.json</code>, <code>build/esbuild.mjs</code>), che non si possono rinominare. La storia dei commit non è stata riscritta.</strong></p><table tabindex="0"><thead><tr><th>Onda</th><th>Sessione</th><th>Contenuto</th><th>Stato</th></tr></thead><tbody><tr><td><strong>A</strong></td><td>M28-S1</td><td>Core Go del desktop e <code>shared/</code>: commenti e messaggi, convertitore dei disegni <code>.excalidraw.md</code> rinominato in <code>ConvertLegacyMD</code>, schema di link dell&#39;editor tolto dalla regex degli URL dei disegni (nuovo <code>TestInURLStringSchemes</code>), fixture della cartella nascosta dell&#39;importer in <code>.editor/</code></td><td>fatta (2026-11-23)</td></tr><tr><td><strong>B</strong></td><td>M28-S2</td><td>Workbench e frontend: commenti, test, testi i18n della conversione dei disegni <code>.excalidraw.md</code> (solo i valori), spec e2e <code>drawing-extra-tools.spec.ts</code>, registro di parità e file generati</td><td>fatta (2026-11-23)</td></tr><tr><td><strong>C</strong></td><td>M28-S3</td><td><code>Specifications.md</code>, README, architettura, indice della documentazione, guide utente, checklist QA (<code>qa/parita-funzionale-m1.md</code>), prestazioni e checklist di rilascio</td><td>fatta (2026-11-23)</td></tr><tr><td><strong>D</strong></td><td>M28-S4</td><td>Documenti storici: ADR (<code>0028-excalidraw-fork.md</code>), CHANGELOG dei rilasci passati, roadmap, proposta dello spec 1.2; questa sezione</td><td>fatta (2026-11-23)</td></tr></tbody></table><p><strong>Rischi</strong></p><ul><li>I nomi dei file rinominati (<code>docs/adr/0028-excalidraw-fork.md</code>, <code>docs/qa/parita-funzionale-m1.md</code>) cambiano i link esterni a quei documenti.</li><li>Il tag <code>v1.8.4</code>, non ancora pubblicato, punta a un commit precedente a questa milestone.</li></ul><hr><h2 id="_14-trasversale-test-e-verifica" tabindex="-1">14. Trasversale: test e verifica <a class="header-anchor" href="#_14-trasversale-test-e-verifica" aria-label="Permalink to &quot;14. Trasversale: test e verifica&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Livello</th><th>Strumento</th><th>Dove</th></tr></thead><tbody><tr><td>Unit Go</td><td><code>go test -race ./...</code> (tabelle per parser, pathrules, merge, vaultcrypto, search)</td><td>tutti i moduli</td></tr><tr><td>Conformance</td><td>fixture <code>shared/conformance/{markdown,merge,crypto}</code> eseguite da Go e TS</td><td><code>task conformance</code></td></tr><tr><td>Integrazione cloud</td><td>testcontainers (PG, MinIO, Keycloak)</td><td><code>services/cloud/test/integration</code>, <code>task test-integration</code></td></tr><tr><td>Contratto</td><td>richieste e risposte del client validate contro <code>openapi.yaml</code></td><td><code>apps/desktop/internal/sync/transport/contract_test.go</code></td></tr><tr><td>E2E sync</td><td>2 engine desktop contro cloud in container</td><td><code>apps/desktop/internal/sync/e2e_test.go</code></td></tr><tr><td>Frontend</td><td>Vitest (unit/componenti), Playwright sul mock dei binding e su Web UI</td><td><code>packages/*/src</code>, <code>apps/desktop/frontend/e2e</code>, <code>web/e2e</code></td></tr><tr><td>Prestazioni</td><td>benchmark Go (<code>-bench</code>), k6, dataset sintetici</td><td>a mano (<code>task perf</code>, <code>task perf-check</code>)</td></tr><tr><td>Sicurezza</td><td>govulncheck, yarn npm audit, test CSP/no-network (SBOM da riattivare)</td><td><code>task vuln</code> in <code>task ci</code>; e2e di sicurezza a mano</td></tr></tbody></table><p>Verifica end-to-end di ogni milestone = i &quot;Criteri di uscita&quot; sopra, eseguiti con <code>task ci</code> + scenario manuale documentato in <code>docs/qa/m&lt;N&gt;-checklist.md</code>.</p><hr><h2 id="_15-primi-passi-operativi-subito-dopo-l-approvazione" tabindex="-1">15. Primi passi operativi (subito dopo l&#39;approvazione) <a class="header-anchor" href="#_15-primi-passi-operativi-subito-dopo-l-approvazione" aria-label="Permalink to &quot;15. Primi passi operativi (subito dopo l&#39;approvazione)&quot;">​</a></h2><ol><li>M0-WP0 scaffolding + <code>docs/roadmap.md</code> (questo piano) + aggiornamento <code>CLAUDE.md</code> con i comandi.</li><li>SPIKE-01, -02, -03, -05 (SPIKE-04 all&#39;inizio di M1) con ADR.</li><li>M0-WP1 → WP2 → WP3/WP4 (cloud+Keycloak) → WP5 → WP6 → WP7.</li><li>Decisioni ancora aperte: hosting (il module path resta <code>clarae</code>, licenza MIT già decisa); scelta <code>op_id</code> persistito (M2-WP2); libreria rendering grafo (M6).</li></ol>',446)])])}const g=o(d,[["render",c]]);export{m as __pageData,g as default};
